calls_in_full_run run_cred_proc_maps_positive_control     || die "5.9.9.Fa: run_cred_proc_maps_positive_control определён, но не вызывается из full_run() — шаг не исполнится (находка №112)"
grep -q '\^/proc/\[0-9\]+/(task/\[0-9\]+/)?(maps|mem|environ)\$' rules/credential-access.yaml     || die "5.9.9.Fa: numeric-PID предикат отсутствует в rules/credential-access.yaml — правка №107 не в дереве"
go test -count=1 -v ./internal/correlator/ -run 'TestP1_17_CredProcMapsMassRead_NumericPID|TestP1_17_ProcSelfNarrowingIsRuleLocal' 2>&1     | grep -E '^(=== RUN|--- |ok|FAIL)' | sed 's/^/  /'
go test -count=1 ./internal/correlator/ -run 'TestP1_17_CredProcMapsMassRead_NumericPID|TestP1_17_ProcSelfNarrowingIsRuleLocal' >/dev/null 2>&1     || die "5.9.9.Fa: юнит-тесты красные — либо сужение не доказано как не-ослепление, либо нарушен запрет волны (/proc/self у owasp_web_sensitive_file_read)"
echo "  ок: шаг вызывается из full_run(), оба юнит-теста зелёные"

# Волна 5.9.9.F.2. Правок правил в ней нет, поэтому сторожа здесь другие:
# они охраняют не «сужение != ослепление», а «пункт волны вообще способен
# исполниться». Каждый из трёх ловит ровно тот класс дефекта, который уже
# случался с этой волной на ревью: шаг написан, но не вызывается; режим
# удалён, но вернулся; продуктовая правка откачена частично.
echo "--- преflight: шаг 5.9.9.F.2b присутствует в цепочке (№125) ---"
grep -q "^run_cpu_pressure_control()" $SETUP/attacks/run-all-attacks.sh \
    || die "5.9.9.F.2b: run_cpu_pressure_control отсутствует в run-all-attacks.sh — крит. 14 останется в SKIP четвёртый замер подряд, приёмка SKIP=0 недостижима"
calls_outside_menu run_cpu_pressure_control \
    || die "5.9.9.F.2b: run_cpu_pressure_control вызывается только из interactive_mode — на замере шаг не исполнится (находка №112)"
grep -q -- '--cpu-pressure-control' $SETUP/attacks/run-all-attacks.sh \
    || die "5.9.9.F.2b: ветки --cpu-pressure-control нет в main() — шаг [9.7/14] ниже не сможет его позвать"
# Маркер шага обязан искаться ПО МАСКЕ: шаг идёт вне окна замера, отдельным
# вызовом со своим TIMESTAMP, и поиск по TIMESTAMP основного прогона не
# нашёл бы его никогда (ревизия исполнения волны, Р2).
grep -q 'cpu_pressure_control_marker=$(latest_marker' $SETUP/attacks/run-gate.sh \
    || die "5.9.9.F.2b: run-gate.sh ищет маркер cpu-pressure-control не по маске — крит. 14 не увидит исполнившийся шаг (ревизия волны, Р2)"
echo "  ок: шаг определён, вызывается своей веткой main(), маркер ищется по маске"

echo "--- преflight: режим drop контроля счётности не вернулся (5.9.9.F.2a, №123) ---"
# Ищется ИСПОЛНЯЕМАЯ строка, а не любое вхождение: имя переменной осталось в
# комментарии run-all-attacks.sh, объясняющем, почему режим удалён, — и это
# правильное место для него.
grep -vE '^[[:space:]]*#' $SETUP/attacks/run-all-attacks.sh | grep -q 'COUNTING_CONTROL_DROP_N' \
    && die "5.9.9.F.2a: COUNTING_CONTROL_DROP_N вернулся в исполняемый код run-all-attacks.sh — режим drop не переполняет кольцо и никогда не переполнял (находка №123), его половину тождества несёт крит. 22"
grep -qE '^for c20_mode in idle; do$' $SETUP/attacks/run-gate.sh \
    || die "5.9.9.F.2a: секция 20 run-gate.sh перебирает не только idle — режим drop удалён волной, его SKIP был одним из четырёх, которые эта волна снимает"
grep -q 'formula="${4:-legacy}"' $SETUP/attacks/run-gate.sh \
    || die "5.9.9.F.2a: counting_control_residual без параметра formula — крит. 22 считает старым асимметричным допуском, который проходит любой результат (находка №124)"
echo "  ок: режим drop удалён, крит. 22 считает замкнутым тождеством"

# ============================ ВОЛНА 5.9.9.F.3 ============================
# Три продуктовых пункта (3a/3b/3c) и четыре измерительных. Сторожа ниже
# охраняют РАЗНОЕ, и это различие существенно:
#   - у продуктовых проверяется, что правка ЛЕЖИТ В ДЕРЕВЕ и что её
#     юнит-половина зелёная. Живая половина (правило не ослепло) стоит
#     ниже, шагом [9.6/14], и её здесь заменить нечем;
#   - у измерительных проверяется, что механизм СПОСОБЕН упасть.
# Определения помощников стоят ЗДЕСЬ, до первого сторожа волны, а не
# перед сторожем 3b: сторож 3a ниже зовёт rule_condition() раньше, и при
# определении ниже по файлу bash печатал "command not found", а `|| die`
# превращал это в ЛОЖНЫЙ СТОП «правка не в дереве» на правленом дереве
# (предпрогон №2.9.9.F.3, 10:08 UTC).
#
# Интервальные квантификаторы ({0,4}) здесь НЕ используются намеренно:
# awk на стенде — mawk, и полагаться на их поддержку значит получить сторож,
# который молча ничего не матчит. Отступы в rules/*.yaml фиксированы: ключи
# правила — четыре пробела, вложенность условия — шесть и больше.
rule_condition() {
    sed -n "/id: $1/,/^  - id:/p" "$2" | awk '
        /^    (condition|condition_group):/ { inc=1 }
        /^    (severity|action|tags|exceptions|enrichment|labels|name|description):/ { inc=0 }
        inc && !/^[[:space:]]*#/'
}
rule_meta() {
    sed -n "/id: $1/,/^  - id:/p" "$2" | grep -E '^    (severity|event_type|action):'
}
# Ревизия волны 5.9.9.F.3 (2026-08-26): у сторожа 3c ниже rule_condition()
# давал ЛОЖНОЕ ПАДЕНИЕ. Структурный признак песочницы живёт в блоке
# exceptions:, а rule_condition() ровно на строке `exceptions:` выключает
# печать — то есть сторож искал признак в единственном месте, где его по
# устройству правила быть не может, и на правленом дереве давал f3c_hit=0.
# rule_predicate() — это то, что обещал (но нигде не определял) комментарий
# сторожа 3b: тело правила без name:/description: и их свёрнутых
# продолжений, то есть условия, метаданные И исключения.
rule_predicate() {
    sed -n "/id: $1/,/^  - id:/p" "$2" | awk '
        /^    (condition|condition_group|severity|action|tags|event_type|exceptions|enrichment|labels):/ { inc=1 }
        /^    (name|description):/ { inc=0 }
        inc && !/^[[:space:]]*#/'
}

echo "--- преflight: 5.9.9.F.3a — rootkit_hidden_dir_dev заякорен и не видит штатные ноды /dev (№131) ---"
grep -q 'id: rootkit_hidden_dir_dev' rules/rootkit-detection.yaml \
    || die "5.9.9.F.3a: правило rootkit_hidden_dir_dev исчезло из rules/rootkit-detection.yaml — удаление вместо сужения приёмкой волны не является"
# Якорь ищется в УСЛОВИИ (rule_condition выше), а не в теле правила: тело
# содержит и имя, и описание, и tags — сторож по телу дал бы ложный пропуск,
# как это и случилось при первой редакции сторожа 3b.
rule_condition rootkit_hidden_dir_dev rules/rootkit-detection.yaml | grep -qE '\^/dev/' \
    || die "5.9.9.F.3a: regex rootkit_hidden_dir_dev не заякорен (^) в условии — /dev/ продолжит матчиться подстрокой внутри /tmp/namespace-dev-*/dev/mqueue (находка №131), правка не в дереве"
sed -n '/id: rootkit_hidden_dir_dev/,/^  - id:/p' rules/rootkit-detection.yaml | grep -qE 'urandom|random|console|exceptions:' \
    || die "5.9.9.F.3a: у rootkit_hidden_dir_dev нет ни исключения, ни упоминания штатных нод — /dev/urandom (7 строчных букв) продолжит давать critical по regex [a-z]{6,}, а это 10 из 12 срабатываний правила на №2.9.9.F.2"
echo "  ок: правило на месте, regex заякорен, штатные ноды учтены"

echo "--- преflight: 5.9.9.F.3b — privesc_suid_suspicious_path проверяет SUID/exec либо переименован (№132) ---"
grep -q 'id: privesc_suid_suspicious_path' rules/privesc.yaml \
    || die "5.9.9.F.3b: правило privesc_suid_suspicious_path исчезло из rules/privesc.yaml — удаление вместо сужения приёмкой волны не является"
# ВАЖНО: искать надо в ПРЕДИКАТЕ, а не в тексте правила. Описание правила
# буквально содержит слова «SUID binary was executed», и сторож, читающий
# тело целиком, давал ложный пропуск на неправленом дереве — то есть был бы
# критерием без достижимого FAIL, ровно тем классом (№123/№124), который
# чинила прошлая волна. rule_predicate() выбрасывает name:/description: и
# их свёрнутые продолжения, оставляя только условия и метаданные.
# ВАЖНО: искать надо в БЛОКЕ УСЛОВИЯ, а не в теле правила целиком. Проверено
# на неправленом дереве обоими исходами, и обе более грубые редакции этого
# сторожа давали ЛОЖНЫЙ ПРОПУСК: описание правила буквально содержит «SUID
# binary was executed», а tags: — слово `suid`. Сторож, читающий тело
# целиком, был бы критерием без достижимого FAIL — ровно тот класс
# (№123/№124), который чинила прошлая волна.
f3b_cond=$(rule_condition privesc_suid_suspicious_path rules/privesc.yaml)
f3b_meta=$(rule_meta privesc_suid_suspicious_path rules/privesc.yaml)
if echo "$f3b_cond" | grep -qiE 'suid|setuid|mode|exec|proc\.args'; then
    echo "  privesc_suid_suspicious_path: предикат получил условие на SUID/exec"
elif echo "$f3b_meta" | grep -qE 'severity:[[:space:]]*(warning|info)'; then
    echo "  privesc_suid_suspicious_path: предикат не выражен, правило понижено до warning (второй допустимый исход постановки)"
else
    die "5.9.9.F.3b: privesc_suid_suspicious_path остался critical и по-прежнему не проверяет ни бит SUID, ни факт exec — 37 критикалов при нуле истинных (находка №132), правка не в дереве"
fi
echo "$f3b_cond" | grep -qE '\^/tmp/' \
    || die "5.9.9.F.3b: regex privesc_suid_suspicious_path не заякорен (^) — правило продолжит матчить /tmp/ подстрокой в любом месте пути"
f3b_sigma=$(rule_condition sigma_binary_in_tmp_executed rules/sigma-linux.yaml)$(rule_meta sigma_binary_in_tmp_executed rules/sigma-linux.yaml)
[ -n "$f3b_sigma" ] \
    || die "5.9.9.F.3b: правило sigma_binary_in_tmp_executed исчезло из rules/sigma-linux.yaml — удаление вместо сужения приёмкой волны не является"
# proc\.args — это и есть проверка факта exec: поле заполняется коллектором
# ТОЛЬКО на execve/execveat (internal/collector/syscall.go), и именно на нём
# живёт правило-компаньон exec_from_tmp. Ревизия волны (2026-08-26): без
# этой альтернативы сторож падал на правленом дереве, то есть запрещал
# единственный исход, которым пункт вообще выразим.
echo "$f3b_sigma" | grep -qiE 'elf|exec|magic|mode|proc\.args|severity:[[:space:]]*info' \
    || die "5.9.9.F.3b: sigma_binary_in_tmp_executed по-прежнему голый prefix /tmp/ без проверки ELF и exec — правило с именем «ELF binary executed» срабатывает на создание каталога (находка №132)"
echo "  ок: оба правила семьи /tmp правлены"

echo "--- преflight: 5.9.9.F.3c/5.9.9.F.4a — признак песочницы systemd структурный, а не список comm, и покрывает двенадцать правил (№133/№141) ---"
# Ключевая проверка волны. Литеральный список comm НЕ чинит дефект: comm
# ребёнка равен (mandb), а не systemd, и следующий юнит даст (logrotate),
# (apt-daily), (fstrim) — ровно так не обобщилось исключение №111.
# 5.9.9.F.4a (№141): список расширен с исходных шести правил 3c до
# фактических двенадцати — вторая половина взята из архива отклонённого
# замера №2.9.9.F.3 поимённо.
f3c_hit=0
f3c_total=12
for r in container_escape_mount container_escape_chroot container_escape_unshare_user \
         container_escape_cap_sys_admin privesc_unshare_user_ns cis_5_2_1_privileged_container \
         proc_inject_memfd_create integrity_proc_self_exe_exec sigma_memfd_create_anonymous \
         rootkit_pam_module_added cred_shadow_read drift_new_library_in_system_dir; do
    body=$(for y in rules/*.yaml; do rule_predicate "$r" "$y"; done)
    [ -n "$body" ] || die "5.9.9.F.3c/5.9.9.F.4a: правило $r не найдено в rules/*.yaml — двенадцать правил пункта обязаны остаться на месте, удаление приёмкой не является"
    if echo "$body" | grep -qE 'ppid|systemd-private|namespace-dev|parent_comm'; then
        f3c_hit=$((f3c_hit + 1))
        echo "  $r: структурный признак песочницы присутствует"
    else
        echo "  $r: структурного признака НЕТ"
    fi
done
# Дробление пункта объявляется ДО правки (постановка). Здесь это означает:
# либо признак есть у всех двенадцати, либо переменная объявила дробление явно.
if [ "$f3c_hit" -lt "$f3c_total" ] && [ "${WAVE_F3C_SPLIT:-0}" != "1" ]; then
    die "5.9.9.F.3c/5.9.9.F.4a: структурный признак песочницы systemd есть только у $f3c_hit правил из $f3c_total, и дробление пункта НЕ объявлено (WAVE_F3C_SPLIT=1). Постановка требует объявлять дробление до правки, а не после FAIL — иначе замер измерит половину волны и назовёт это приёмкой"
fi
[ "$f3c_hit" -ge 1 ] \
    || die "5.9.9.F.3c/5.9.9.F.4a: ни у одного из двенадцати правил нет структурного признака песочницы — правка №133/№141 не в дереве вовсе, и idle-час снова даст три verdict=\"attack\" на старте любого sandboxed-юнита"
# Вторая половина пункта: pid 1 перестаёт ловить сам себя на /proc/1/*.
# Предикат тот же, что у №107 (self никогда не интересен ЭТОМУ правилу).
for r in container_escape_init_proc mitre_sandbox_detect_proc_read; do
    body=$(for y in rules/*.yaml; do rule_predicate "$r" "$y"; done)
    [ -n "$body" ] || die "5.9.9.F.3c: правило $r не найдено — вторая половина пункта без входа"
    echo "$body" | grep -qE 'ppid|pid|exceptions:' \
        || echo "  ВНИМАНИЕ: $r не различает чтение СВОЕГО /proc/1/* — pid 1 продолжит ловить сам себя (родня находки №107)"
done
echo "  ок: 5.9.9.F.3c/5.9.9.F.4a в дереве ($f3c_hit/$f3c_total правил со структурным признаком)"

echo "--- преflight: 5.9.9.F.3d — фаза idle проверяется раньше «наведено преflight'ом» (№134) ---"
# Ищется ПОРЯДОК ветвления, а не наличие признака: до правки in_induced
# стоял первым и поглощал idle целиком, потому что idle-час предшествует
# baseline по построению цепочки.
# Печать (диагностика для человека) обязана видеть ТЕ ЖЕ строки, что и
# проверка ниже: после правки 3d ветка induced существует в двух формах —
# составной `if [ -n "$phase_parts" ] && [ "$in_induced" -eq 1 ]` и одиночной
# `elif [ "$in_induced" -eq 1 ]`. Прежний шаблон с якорем ^ не матчил ни ту,
# ни другую, и «порядок веток» печатался БЕЗ induced вовсе — читателю
# казалось, что ветки нет в дереве.
awk '/&& \[ "\$in_induced" -eq 1 \]; then/{print NR": phase_parts+induced (составная)"} /^[[:space:]]*elif \[ "\$in_induced" -eq 1 \]; then/{print NR": induced (одиночная)"} /^[[:space:]]*elif \[ -n "\$phase_parts" \]; then/{print NR": phase_parts"} /^[[:space:]]*elif \[ -z "\$IDLE_METRICS_START" \]/{print NR": fallback"}' \
    $SETUP/attacks/run-gate.sh | sort -n | sed 's/^/  порядок веток: /'
# ПЕРВОЕ вхождение каждого, а не последнее: `if [ "$in_induced" -eq 1 ]`
# встречается дважды — ветка печати фазы и ветка счётчика ниже, — и awk,
# берущий последнее, сравнивал бы ветку счётчика с веткой печати и всегда
# отвечал «порядок верный».
if awk 'i==0 && /if \[ "\$in_induced" -eq 1 \]; then/{i=NR} p==0 && /elif \[ -n "\$phase_parts" \]; then/{p=NR} END{exit !(i>0 && p>0 && i<p)}' $SETUP/attacks/run-gate.sh; then
    die "5.9.9.F.3d: в run-gate.sh ветка in_induced по-прежнему стоит ПЕРЕД phase_parts — метка «наведено шагом преflight'а» продолжит поглощать фазу idle целиком (находка №134), и семь idle-FP пакета systemd уйдут в detection-baseline.txt как артефакты преflight-шага"
fi
echo "  ок: фаза idle проверяется раньше induced"

echo "--- преflight: 5.9.9.F.3e — три SKIP бухгалтерии починены (№135/№136/№137) ---"
# №135: текст fail() крит. 5.9.9.F.1d несёт свой id наравне с pass().
awk '/^[[:space:]]*fail "новый\(е\) актор\(ы\) idle-часа вне idle-actors.txt/{print}' $SETUP/attacks/run-gate.sh \
    | grep -q '5.9.9.F.1d, №115' \
    || die "5.9.9.F.3e/№135: текст fail() крит. 5.9.9.F.1d не несёт «5.9.9.F.1d, №115» — упавший критерий снова засчитается как неисполнившаяся ветка и оштрафует прогон дважды за один исход"
# №136: record_covered для 5.9.9.Fc вызывается ПОСЛЕ загрузки индекса.
if awk '/record_covered "окно журнала:"/{r=NR} /^CRITERIA_INDEX_FILE=/{c=NR} END{exit !(r>0 && c>0 && r<c)}' $SETUP/attacks/run-gate.sh; then
    die "5.9.9.F.3e/№136: record_covered \"окно журнала:\" по-прежнему вызывается ДО загрузки criteria-index.txt — на пустых массивах CRITERIA_SELF_* вызов является no-op по построению, и 5.9.9.Fc не покрывается никогда, каким бы ни был исход критерия"
fi
# №137: паттерн 5.9.9.F.2b в индексе взят с pass()/fail(), а не с echo.
f3e_pat=$(awk -F'\t' '$1=="5.9.9.F.2b"{print $3}' $SETUP/attacks/criteria-index.txt | head -1)
[ -n "$f3e_pat" ] || die "5.9.9.F.3e/№137: у пункта 5.9.9.F.2b нет строки в criteria-index.txt"
awk -v pat="$f3e_pat" '
        /^[[:space:]]*(pass|fail|warn|skip) / && index($0, pat) > 0 { found=1 }
        END { exit !found }' $SETUP/attacks/run-gate.sh \
    || die "5.9.9.F.3e/№137: паттерн 5.9.9.F.2b («$f3e_pat») не найден ни в одном вызове pass()/fail()/warn()/skip() — он снова взят со строки echo, через record_covered такие строки не проходят, и критерий останется в SKIP при любом исходе"
echo "  ок: все три дефекта бухгалтерии починены в дереве"

echo "--- преflight: 5.9.9.F.3f — каждый пункт волны заведён в criteria-index.txt (№138) ---"
f3f_missing=""
for wid in $WAVE_CRITERIA_IDS; do
    awk -F'\t' -v w="$wid" '!/^[[:space:]]*#/ && $1==w {found=1} END{exit !found}' $SETUP/attacks/criteria-index.txt \
        || f3f_missing="$f3f_missing $wid"
done
# Задним числом — два пункта прошлой волны, обнаруженные находкой №138.
for wid in 5.9.9.F.2c 5.9.9.F.2g; do
    awk -F'\t' -v w="$wid" '!/^[[:space:]]*#/ && $1==w {found=1} END{exit !found}' $SETUP/attacks/criteria-index.txt \
        || f3f_missing="$f3f_missing $wid(задним числом)"
done
if [ -n "$f3f_missing" ]; then
    die "5.9.9.F.3f/№138: пункты постановки без строки в criteria-index.txt:$f3f_missing. Старый сторож «непокрытых пунктов: 0» этого не видит по построению — он перебирает сам индекс. Пункт без строки нигде не проверяется, то есть исчезает та же дыра, которую закрывала 5.9.7h (№83)"
fi
echo "  ок: все $(echo $WAVE_CRITERIA_IDS | wc -w) пунктов волны + 5.9.9.F.2c/2g заведены в индексе"

echo "--- преflight: 5.9.9.F.3g — записи журнала (№139/№140) ---"
go test -count=1 ./internal/collector/ -run 'DNS|Truncat' >/dev/null 2>&1 \
    || echo "  ВНИМАНИЕ: юнит-тесты разбора DNS красные — пункт 3g (словарь причин, №140) под вопросом; на вердикт замера не влияет (P3)"
echo "  ок (P3, на вердикт замера не влияет)"

echo "--- преflight: 5.9.9.F.4e — exfil_archive_to_network_pipe несёт предикат архиватора (№145) ---"
grep -q 'id: exfil_archive_to_network_pipe' rules/exfiltration-extended.yaml \
    || die "5.9.9.F.4e: правило exfil_archive_to_network_pipe исчезло из rules/exfiltration-extended.yaml — удаление приёмкой не является"
# Ищется в ПРЕДИКАТЕ, а не в теле: description правила и до правки говорил
# «tar/zip/gzip», именно этим находка №145 и была — имя обещало предикат,
# которого не было. Сторож по телу дал бы ложный пропуск.
rule_predicate exfil_archive_to_network_pipe rules/exfiltration-extended.yaml | grep -qE 'parent_comm' \
    || die "5.9.9.F.4e: в условии exfil_archive_to_network_pipe нет proc.parent_comm — предикат архиватора не в дереве, правило по-прежнему алертит на любой execve сетевой утилиты (96 алертов, первое место по объёму на отклонённом №2.9.9.F.3)"
rule_predicate exfil_archive_to_network_pipe rules/exfiltration-extended.yaml | grep -qE '"tar"|\btar\b' \
    || die "5.9.9.F.4e: список архиваторов в предикате пуст или не содержит tar — сужение объявлено, но не выражено"
grep -q 'run_exfil_archive_parent_positive_control' $SETUP/attacks/run-all-attacks.sh \
    || die "5.9.9.F.4e: в манифесте атак нет run_exfil_archive_parent_positive_control — правка, уменьшающая число алертов, без позитивного контроля неотличима от ослепления (риск волны, названный заранее)"
grep -q 'run_exfil_archive_parent_positive_control' <(awk '/^full_run\(\)/,/^}/' $SETUP/attacks/run-all-attacks.sh) \
    || die "5.9.9.F.4e: run_exfil_archive_parent_positive_control определён, но не вызывается из full_run() — контроль, который не исполняется, величиной 10 не является"
echo "  ок: предикат архиватора в дереве, позитивный контроль подключён к full_run()"
echo "  ГРАНИЦА ПУНКТА (записана постановкой заранее): выражена только РОДИТЕЛЬСКАЯ половина"
echo "  (tar -> curl). Классический shell-пайп tar czf - | curl делает их БРАТЬЯМИ, и движок"
echo "  такой связи не хранит — величина 10 читается по родительской форме, sibling-форма"
echo "  остаётся невыполненной до отдельной stateful-фичи коррелятора (см. plan.md, 4e)."

echo "--- преflight: 5.9.9.F.5a — позитивный контроль exfil даёт comm=tar, а не comm интерпретатора (№152) ---"
grep -q 'run_exfil_archive_parent_positive_control' $SETUP/attacks/run-all-attacks.sh \
    || die "5.9.9.F.5a: run_exfil_archive_parent_positive_control пропал из run-all-attacks.sh"
grep -q 'comm_verified' $SETUP/attacks/run-all-attacks.sh \
    || die "5.9.9.F.5a: контроль не пишет поле comm_verified в манифест — сторож блока величины 10 не сможет отличить 'comm=tar подтверждён' от 'контроль подтвердил не то' (та же болезнь №152 — 0 неотличим от неисполнения)"
grep -q '/proc/self/comm' <(awk '/^run_exfil_archive_parent_positive_control\(\)/,/^}/' $SETUP/attacks/run-all-attacks.sh) \
    || die "5.9.9.F.5a: контроль не читает /proc/self/comm архиватора — доказательство comm=tar отсутствует, позитивный контроль остаётся недостоверным ровно как на №2.9.9.F.4"
echo "  ок: контроль читает /proc/self/comm архиватора и пишет comm_verified в манифест"

# 5.9.9.F.5k (№161): сторож выше (5.9.9.F.5a) проверял НАПИСАНИЕ — что в теле
# функции есть подстрока "/proc/self/comm". Это не ловит №161: было
# `cat /proc/self/comm > file`, cat — ВНЕШНИЙ форкнутый процесс, и
# /proc/self/comm внутри НЕГО — это comm самого cat (5/5 запусков), а не
# comm родителя-архиватора. Подстрока была на месте, сторож проходил,
# величина 10 всё равно оставалась без входа — «сторож, проверяющий
# написание, а не результат» (тот же класс, что №152, уровнем выше).
# Фикс: сторож исполняет ТУ ЖЕ конструкцию (bash-копия под именем "tar",
# `read`-builtin вместо `cat`) прямо здесь и падает по РЕЗУЛЬТАТУ, если
# напечатан не "tar".
echo "--- преflight: 5.9.9.F.5k — сторож 5a проверяет РЕЗУЛЬТАТ (comm=tar), а не подстроку исходника (№161) ---"
if [ -r /proc/self/comm ]; then
    _5k_dir=$(mktemp -d)
    _5k_bin="$_5k_dir/tar"
    _5k_bash="$(command -v bash)"
    if cp "$_5k_bash" "$_5k_bin" 2>/dev/null; then
        chmod +x "$_5k_bin"
        _5k_out="$_5k_dir/comm.txt"
        "$_5k_bin" -c "read -r c < /proc/self/comm; printf '%s' \"\$c\" > '$_5k_out' 2>/dev/null" >/dev/null 2>&1
        _5k_observed=$(cat "$_5k_out" 2>/dev/null)
        [ "$_5k_observed" = "tar" ] \
            || die "5.9.9.F.5k: та же конструкция, что использует run_exfil_archive_parent_positive_control (bash-копия под именем tar, read-builtin), на ЭТОЙ машине даёт comm='${_5k_observed:-<пусто>}', не 'tar' — сторож проверял написание исходника, не результат (№161); величина 10 при таком исходе обречена на FAIL(сторож) даже при исправном правиле"
        echo "  ок: конструкция сторожа исполнена на месте, comm='tar' подтверждён по результату"
    else
        die "5.9.9.F.5k: не удалось скопировать $_5k_bash для смысловой проверки сторожа — сторож не исполнился"
    fi
    rm -rf "$_5k_dir"
else
    echo "  SKIP: /proc недоступен на этой машине (не Linux) — смысловая проверка сторожа 5a требует живого /proc/self/comm, откладывается до стенда; проверки написания исходника (5.9.9.F.5a выше) остаются в силе"
fi
grep -q 'read -r c < /proc/self/comm' <(awk '/^run_exfil_archive_parent_positive_control\(\)/,/^}/' $SETUP/attacks/run-all-attacks.sh) \
    || die "5.9.9.F.5k: run_exfil_archive_parent_positive_control больше не читает /proc/self/comm через read-builtin — регрессия №161 (форк cat) могла вернуться незамеченной"
echo "  ок: контроль по-прежнему читает /proc/self/comm через read-builtin (не форкает cat)"

# 5.9.9.F.6d (№173): №2.9.9.F.5 дал Δ=0 при подтверждённом comm=tar — два
# кандидата остались: (1) bash exec'нул curl НА МЕСТЕ вместо форка, (2)
# единственный повтор съеден сэмплированием. Пайплайн обязан проверить, что
# ОБА кандидата сняты конструкцией контроля, а не только текстом постановки.
echo "--- преflight: 5.9.9.F.6d — N=20 повторов и гарантированный форк (№173) ---"
_6d_body=$(awk '/^run_exfil_archive_parent_positive_control\(\)/,/^}/' $SETUP/attacks/run-all-attacks.sh)
grep -q 'exfil_n_total=20' <<<"$_6d_body" \
    || die "5.9.9.F.6d: контроль не гоняет 20 повторов (exfil_n_total=20 не найден) — гипотеза «сэмплирование съело единственное событие» статистически не снята"
# 5.9.9.F.7a сдвинул хвост строки "-c": между вызовом $curl_bin и финальным
# builtin ':' встал ВТОРОЙ сторож (`printf '%s' "$?" > '$exec_rc_file'`), то
# есть после curl теперь ДВА ';'-разделённых звена, а не одно. Прежний
# шаблон требовал ':' сразу за ПЕРВЫМ ';' ([^;]*) и на правленой фикстуре
# падал жёстким стопом (предпрогон №2.9.9.F.7, 13:30 UTC) при полностью
# исправной конструкции. Смысл сторожа не меняется и не ослабляется:
#   [^;|]*;  — вызов $curl_bin завершается БЕЗУСЛОВНЫМ ';' (ни '||', ни '|'
#              до него не проходят — класс их исключает);
#   .*;[[:space:]]*:  — и он НЕ последняя команда строки: за ним, через ';',
#              стоит builtin-хвост ':', ради которого bash обязан узнать код
#              возврата, а значит форкнуть, а не exec-in-place.
grep -qE "'\\\$curl_bin'[^;|]*;.*;[[:space:]]*:" <<<"$_6d_body" \
    || die "5.9.9.F.6d: после вызова \$curl_bin нет безусловного (';', не '||') builtin-хвоста — bash по-прежнему вправе exec-in-place заменить свой образ curl'ом, гипотеза (1) не снята конструктивно"
grep -qE "\\\$curl_bin'[^;]*\\|\\|" <<<"$_6d_body" \
    && die "5.9.9.F.6d: вызов \$curl_bin по-прежнему завершается через '|| true' — старая форма, которую постановка №173 явно назвала недостаточной для исключения tail-call exec"
echo "  ок: контроль гоняет 20 повторов, вызов сетевой утилиты не последняя команда строки -c (гарантированный форк)"

# 5.9.9.F.7a (№176): два сторожа фикстуры. Оба — ПО ИСХОДНИКУ здесь и ПО
# РЕЗУЛЬТАТУ на самом прогоне (exec_verified в манифесте, величина 10 ниже).
# Разбор №176: ноль правила на №2.9.9.F.5/№2.9.9.F.6 был битой симлинкой
# ($true_bin = голое имя builtin'а "true" из `command -v`), execve падал с
# ENOENT ДО смены comm — событие с comm=curl не рождалось вовсе. Регрессия
# этой строки возвращает ложный продуктовый ноль, неотличимый от настоящего.
echo "--- преflight: 5.9.9.F.7a — фикстура контроля разрешает сетевую утилиту абсолютным путём (№176) ---"
_7a_body=$(awk '/^run_exfil_archive_parent_positive_control\(\)/,/^}/' $SETUP/attacks/run-all-attacks.sh)
grep -qE 'true_bin="?\$\(command -v true' <<<"$_7a_body" \
    && die "5.9.9.F.7a: run_exfil_archive_parent_positive_control снова берёт true_bin из \`command -v true\` — на bash это ИМЯ builtin'а без пути, ln -s создаёт битую относительную симлинку, execve curl_bin падает с ENOENT и правило получает ложный ноль (находка №176, стоила двух замеров)"
# 6.0g/№208: тот же запрет — на ВЕСЬ пайплайн, а не только на одну функцию
# run-all-attacks.sh. Замер 01.09 встал в окне атак ровно на этой
# конструкции, заведённой шагом 6.0g: сторож №176 её не видел, потому что
# смотрел в другой файл. Запрещается любое взятие пути до `true` из
# command -v/type -P (builtin отдаёт голое имя), где угодно в пайплайне.
# Комментарии ИСКЛЮЧАЮТСЯ явно: разбор дефекта выше цитирует запрещённую
# конструкцию дословно, и сторож, читающий комментарии как код, валил бы
# преflight на собственном объяснении (тот же класс, что 4540d53).
if grep -vE '^[[:space:]]*#' "$SETUP/run-6.0-pipeline.sh" | grep -nE '=\$\((command -v|type -P) true'; then
    die "6.0g/№208: в run-6.0-pipeline.sh снова берётся путь до \`true\` из command -v/type -P — на bash это builtin и путь пуст, cp/ln падает и шаг умирает через die (на замере 01.09 — уже ПОСЛЕ idle-часа, окно потеряно). Брать абсолютный путь перебором /usr/bin/true /bin/true с проверкой -f -x"
fi
echo "  ок: путь до true нигде в пайплайне не берётся из builtin-резолвера (№208)"
grep -q '/usr/bin/true' <<<"$_7a_body" \
    || die "5.9.9.F.7a: в контроле нет разрешения сетевой утилиты по абсолютному пути (/usr/bin/true|/bin/true с проверкой -x) — правка №176 откатилась"
grep -q 'exec_rc_file' <<<"$_7a_body" \
    || die "5.9.9.F.7a: в контроле нет сторожа по результату execve (exec_rc_file) — сторож 5.9.9.F.5k проверяет ТОЛЬКО comm архиватора и по построению не отличает битую фикстуру от продуктового нуля; величина 10 без второго сторожа снова становится неинтерпретируемой"
grep -q 'exec_verified: \$execok' <<<"$_7a_body" \
    || die "5.9.9.F.7a: контроль не пишет exec_verified в манифест — блок величины 10 ниже читает это поле и без него не сможет потребовать N из N по второму сторожу"
# Сторож по РЕЗУЛЬТАТУ, здесь и сейчас, тем же приёмом, что 5.9.9.F.5k выше:
# конструкция исполняется на ЭТОЙ машине, и преflight падает, если код
# возврата execve не 0 — то есть если фикстура сломана на этом стенде
# (нет /usr/bin/true, noexec на $TMPDIR), ДО траты 94 минут пайплайна.
_7a_dir=$(mktemp -d)
_7a_true=""
for _7a_c in /usr/bin/true /bin/true; do [ -x "$_7a_c" ] && { _7a_true="$_7a_c"; break; }; done
[ -n "$_7a_true" ] || die "5.9.9.F.7a: на этом стенде нет исполняемого /usr/bin/true или /bin/true — фикстура контроля 6d не соберётся, величина 10 будет нулём БЕЗ входа (ровно случай №176)"
ln -s "$_7a_true" "$_7a_dir/curl" 2>/dev/null || die "5.9.9.F.7a: не удалось создать симлинку фикстуры в $_7a_dir"
"${BASH:-bash}" -c "'$_7a_dir/curl' -s -o /dev/null http://127.0.0.1:1 >/dev/null 2>&1; printf '%s' \"\$?\" > '$_7a_dir/rc' 2>/dev/null; :" >/dev/null 2>&1
_7a_rc=$(cat "$_7a_dir/rc" 2>/dev/null)
rm -rf "$_7a_dir"
[ "$_7a_rc" = "0" ] \
    || die "5.9.9.F.7a ПРОВАЛЕН ПО РЕЗУЛЬТАТУ: execve сетевой утилиты через фикстуру дал код '${_7a_rc:-<пусто>}' вместо 0 (127 = нет файла/битая симлинка, 126 = не исполняется, напр. noexec на \$TMPDIR) — событие с comm=curl не родится, и величина 10 снова измерит фикстуру вместо продукта"
echo "  ок: сетевая утилита разрешена абсолютным путём, execve фикстуры исполнен на месте с кодом 0, exec_verified пишется в манифест"

# 5.9.9.F.8a/5.9.9.F.8b (№179/№180): сторожа волны 8. Обе правки — в
# измерителе и обе тривиально откатываются копированием старого файла на
# стенд, а цена отката — 94 минуты и повторение уже разобранного FAIL'а.
# Поэтому оба проверяются ДО прогона, по исходнику, как 7a выше.
echo "--- преflight: 5.9.9.F.8a — idle-actors.txt покрывает fwupd (№179) ---"
_8a_reg="$SETUP/attacks/idle-actors.txt"
[ -s "$_8a_reg" ] \
    || die "5.9.9.F.8a: idle-actors.txt отсутствует или пуст ($_8a_reg) — крит. 5.9.9.F.2d не с чем сверять, и замер повторит FAIL №2.9.9.F.7 вслепую"
for _8a_comm in 'fwupd' '(fwupd)' 'fwupdmgr' '(fwupdmgr)'; do
    awk -F'\t' -v c="$_8a_comm" '!/^[[:space:]]*(#|$)/ && $1==c {found=1} END{exit !found}' "$_8a_reg" \
        || die "5.9.9.F.8a: в idle-actors.txt нет строки '$_8a_comm' — реестр на стенде старее правки волны 8, и idle-час с таймером fwupd-refresh снова даст FAIL (находка №179, разобрана на №2.9.9.F.7)"
done
echo "  ок: все четыре строки fwupd/(fwupd)/fwupdmgr/(fwupdmgr) на месте"

echo "--- преflight: 5.9.9.F.8b — ветка классификации крит. 21 жива, а не только SKIP'ает (№180) ---"
# 6.0g (предпрогон 01.09): сторож искал литерал 'реплей 18/21', а волна 6.0f
# перенумеровала метки 18/21 -> 18/25 — сторож валил преflight на РАСХОЖДЕНИИ
# СО СВОИМ ЖЁСТКИМ ЗНАМЕНАТЕЛЕМ, а не на отсутствии реплея. Это ровно тот
# класс, что уже ронял волны на criteria-index.txt (перенумерация N/16 -> N/18):
# сторож обязан проверять НОМЕР реплея, знаменатель у него не предмет.
grep -qE -- '--- реплей 18/[0-9]+:' "$SETUP/attacks/replay-gate.sh" \
    || die "5.9.9.F.8b: в replay-gate.sh нет реплея 18/N — SKIP крит. 21 нельзя документировать в приёмке, пока ветка классификации не показана исполняющейся на архиве с флапом (иначе документируется «ветка мертва»)"
grep -qE '^5\.9\.9\.F\.8b'$'\t' "$SETUP/attacks/criteria-index.txt" \
    || die "5.9.9.F.8b: пункт 5.9.9.F.8b не заведён в criteria-index.txt — сторож 5.9.7h его не проверит, и реплей 18/21 можно будет удалить незаметно"
echo "  ок: реплей 18/21 на месте и заведён в индексе постановки"

echo "--- преflight: 5.9.9.F.4f — семейство drift правлено, базовая линия решена явно (№146) ---"
rule_predicate drift_exec_from_system_bin rules/drift-rules.yaml | grep -q 'proc.args' \
    || die "5.9.9.F.4f: drift_exec_from_system_bin по-прежнему не читает факт exec (нет proc.args в условии) — предикат op==open не означает исполнения, и правило остаётся первым местом по критикалам аптайма (44 на №2.9.9.F.2)"
rule_predicate drift_exec_from_system_bin rules/drift-rules.yaml | grep -qE 'event_type:[[:space:]]*syscall' \
    || die "5.9.9.F.4f: drift_exec_from_system_bin остался event_type: file — proc.args на файловом событии не заполняет НИ ОДИН коллектор (тот же дефект, которым был ослеплён sigma_binary_in_tmp_executed до ревизии 5.9.9.F.3)"
if grep -qE '^[[:space:]]*values:[[:space:]]*\[\][[:space:]]*$' rules/drift-rules.yaml; then
    die "5.9.9.F.4f: в rules/drift-rules.yaml остался пустой values: [] — «всегда истина» в предикате, и загрузчик 5.9.9.F.4g теперь ОТВЕРГНЕТ этот файл целиком (порядок пунктов волны: 4f раньше 4g)"
fi
echo "  ок: drift_exec_from_system_bin переведён на факт exec, пустых values: [] нет"

echo "--- преflight: 6.0a — profiler.drift_baseline включён, а не оставлен на дефолте (плановая точка входа волны 6.0) ---"
# Инверсия старого сторожа 5.9.9.F.4f: та волна сознательно выбрала (b)
# «оставить description-only, не включать baseline» именно потому, что
# доказательства закрытого learning ДО открытия idle-часа тогда не было.
# Волна 6.0 берёт вариант (a) и ПРЕДЪЯВЛЯЕТ это доказательство ниже (шаг
# [10/14], пауза считается до 3600с от AGENT_START_FILE, а не фиксированной
# константой) — поэтому здесь сторож требует ОБРАТНОГО: enabled НЕ true
# означает, что config-test.yaml откатился к состоянию волны 8, и вся
# перестройка порядка шагов ниже меряет пустое место.
if ! awk '/^profiler:/{p=1} p && /drift_baseline:/{d=1} d && /enabled:[[:space:]]*true/{print; exit}' $SETUP/config-test.yaml | grep -q true; then
    die "6.0a: в config-test.yaml НЕ включён profiler.drift_baseline (enabled: true отсутствует под profiler.drift_baseline) — волна 6.0 меняет решение 5.9.9.F.4f на противоположное, а без флага шесть правил класса drift снова алертят на каждое совпадение, и вся правка порядка шагов [5/14]..[11/14] ниже не имеет предмета"
fi
grep -q 'Class-wide baseline decision' rules/drift-rules.yaml \
    || die "6.0a: в rules/drift-rules.yaml нет записи о решении по базовой линии — без неё следующая сессия не увидит истории выбора (b)->(a)"
grep -q 'Wave 6, plan.md' rules/drift-rules.yaml \
    || die "6.0a: в rules/drift-rules.yaml нет записи о решении волны 6.0 — правка config-test.yaml включила baseline без объявленного в дереве решения"

# 6.0a (вторая половина, после разбора замера №6.0): печатать ВСЕ значения
# drift_baseline, а не только enabled. На №6.0 архив нёс один факт «enabled:
# true», и learning_period/min_samples/enforce_deadline_periods пришлось
# восстанавливать по арифметике T_seed+3600 из лога — величины, от которых
# прямо зависит, слепа нагрузка в окне замера или нет, в архиве отсутствовали.
DRIFT_LEARNING_PERIOD=$(awk '/^profiler:/{p=1} p && /drift_baseline:/{d=1} d && /^[[:space:]]*learning_period:/{print $2; exit}' $SETUP/config-test.yaml)
DRIFT_MIN_SAMPLES=$(awk '/^profiler:/{p=1} p && /drift_baseline:/{d=1} d && /^[[:space:]]*min_samples:/{print $2; exit}' $SETUP/config-test.yaml)
DRIFT_DEADLINE_PERIODS=$(awk '/^profiler:/{p=1} p && /drift_baseline:/{d=1} d && /^[[:space:]]*enforce_deadline_periods:/{print $2; exit}' $SETUP/config-test.yaml)
DRIFT_MAX_SIGS=$(awk '/^profiler:/{p=1} p && /drift_baseline:/{d=1} d && /^[[:space:]]*max_signatures_per_workload:/{print $2; exit}' $SETUP/config-test.yaml)
[ -n "$DRIFT_LEARNING_PERIOD" ] && [ -n "$DRIFT_MIN_SAMPLES" ] && [ -n "$DRIFT_DEADLINE_PERIODS" ] \
    || die "6.0a: в config-test.yaml не вычитаны learning_period/min_samples/enforce_deadline_periods под profiler.drift_baseline — шаг [10/14] считает по ним паузы, брать их из дефолтов кода молча нельзя (на №6.0 именно эти три величины отсутствовали в архиве)"
DRIFT_DEADLINE_SEC=$((DRIFT_LEARNING_PERIOD * DRIFT_DEADLINE_PERIODS))
echo "  ок: profiler.drift_baseline.enabled: true в config-test.yaml, решение волны 6.0 записано в rules/drift-rules.yaml"
echo "  drift_baseline: learning_period=${DRIFT_LEARNING_PERIOD}с min_samples=${DRIFT_MIN_SAMPLES} enforce_deadline_periods=${DRIFT_DEADLINE_PERIODS} (=${DRIFT_DEADLINE_SEC}с) max_signatures_per_workload=${DRIFT_MAX_SIGS:-<дефолт кода 256>}"

# Дедлайн обязан истекать ВНУТРИ пролога, иначе нагрузки, у которых не набрано
# min_samples, входят в idle-час в состоянии learning и там немы — на №6.0 это
# было 13 из 21, и ноль по счётчику был неотличим от успеха. Порог 3000с ниже —
# это длина пролога [5/14]..[11/14] с запасом (на №6.0 фактически 71 мин, после
# укорочения окон ожидается ~29 мин).
if [ "$DRIFT_DEADLINE_SEC" -gt 3000 ]; then
    die "6.0a: enforce_deadline_periods x learning_period = ${DRIFT_DEADLINE_SEC}с > 3000с — дедлайн не истечёт до открытия idle-часа, и нагрузки без min_samples будут слепы весь измеряемый час (замер №6.0: profiles=21 learning=13 stuck=13). Укоротить learning_period либо enforce_deadline_periods в config-test.yaml"
fi

# Сторожа ниже смотрят на КОД, а не на текст файла. Предпрогон 6.0b встал
# ЖЁСТКИМ СТОПОМ ровно на этом: негативный сторож `grep -q
# driftPathPrefixMaxDepth` сматчил СОБСТВЕННУЮ историческую запись в
# комментарии normalizeDriftPath («Wave 6.0 removed the depth truncation that
# used to sit here (driftPathPrefixMaxDepth = 2, ...)») и объявил, что
# усечение вернулось, хотя в коде его нет. Симметричная опасность у
# позитивных сторожей: имя, оставшееся только в комментарии, дало бы ложный
# PASS. Поэтому вход всем четырём — исходник со снятыми комментариями.
drift_code() { sed 's,//.*,,' "$1"; }

# Кап сигнатур — продуктовая половина правки 6.0: он заменил усечение пути по
# глубине, которое схлопывало /usr/bin/* в одну сигнатуру и делало позитивный
# контроль 6.0.3 непроходимым по конструкции.
grep -qE '^func normalizeDriftPath\(' internal/profiler/driftbaseline.go \
    || die "6.0a: в internal/profiler/driftbaseline.go нет normalizeDriftPath — правка сигнатуры дрейфа откатилась к normalizeDriftPathPrefix с усечением по глубине, и контроль 6.0.3 снова не сможет пройти ни при каком поведении базовой линии"
drift_code internal/profiler/driftbaseline.go | grep -q 'driftPathPrefixMaxDepth' \
    && die "6.0a: в internal/profiler/driftbaseline.go снова есть driftPathPrefixMaxDepth — усечение пути по глубине вернулось, /usr/bin/curl и /usr/bin/python3 опять одна сигнатура"
echo "  ок: сигнатура дрейфа без усечения по глубине (normalizeDriftPath), кардинальность ограничена капом max_signatures_per_workload"

# Вторая половина той же правки (2026-08-30). Обе проверяются по дереву, а не
# по бинарю: пайплайн собирает агента сам, и рассинхрон «правка в дереве есть,
# в собранном бинаре нет» ловится позже — контролем 6.0.3 и полом 16.5.
grep -qE '^var driftSyscallArgSpecs = map\[' internal/profiler/driftsyscallargs.go \
    || die "6.0a: нет internal/profiler/driftsyscallargs.go с driftSyscallArgSpecs — сигнатура syscall-правил снова вырождается в голый номер, и drift_dangerous_syscall будет нема весь прогон (замер №6.0: 416 подавлений, 0 алертов)"
drift_code internal/profiler/driftbaseline.go | grep -q '"already_reported"' \
    || die "6.0a: в internal/profiler/driftbaseline.go нет ветки already_reported — правка «сообщать один раз» откатилась, объём класса drift снова пропорционален частоте исполнения, и потолок 6.0.1 (<=100/ч) измеряет расписание cron, а не дрейф"
# Машинный гейт соответствия правил и таблицы аргументов. Дешевле поймать
# здесь, чем узнать из немого правила через 70 минут прогона.
go test ./internal/correlator/ -run TestDriftSyscallRulesHaveArgSpecs -count=1 >/dev/null 2>&1 \
    || die "6.0a: TestDriftSyscallRulesHaveArgSpecs не проходит — какой-то syscall в правиле класса drift не имеет записи в driftSyscallArgSpecs, его сигнатура схлопнута в одно значение на нагрузку. Запустить тест и прочитать имя правила и номер сисколла"
echo "  ок: syscall-сигнатуры различают аргументы (driftSyscallArgSpecs), дрейф сообщается один раз (already_reported)"

echo "--- преflight: 6.0d — правки по находкам №193…№198 (дополнительно к 6.0a) ---"
# Пункт 1/4: правила подмножества (б) — примитивы побега и захвата, для
# которых фаза learning новой нагрузки НЕ подавляет вовсе (находка №193б) —
# обязаны нести флаг drift_novel_workload: alert. Список зашит явно, а не
# по glob'у "container_escape_*": container_escape_init_proc_daemon
# существует под тем же префиксом, но это info-severity рулatable для
# самоинтроспекции штатных демонов (prometheus/grafana/cron/pgrep), а не
# примитив захвата — включать его в подмножество (б) означало бы алертить
# на каждый новый demon-под без всякой пользы.
DRIFT_NOVEL_WORKLOAD_RULES="container_escape_proc_write container_escape_init_proc drift_dangerous_syscall"
drift_novel_workload_flags=$(awk '
    /^  - id:/ {
        if (id != "") print id, (flag ? "1" : "0")
        id=$0; sub(/^  - id:[[:space:]]*"?/,"",id); sub(/"?[[:space:]]*$/,"",id)
        flag=0
        next
    }
    # Якорь обязателен: `drift_novel_workload: alert` в КОММЕНТАРИИ (а он там
    # есть — обе записи в container-escape.yaml ссылаются на drift_dangerous_syscall)
    # дал бы ложный PASS. Ровно этот класс дефекта остановил предпрогон 6.0b,
    # когда сторож сигнатуры дрейфа сматчил собственную историческую запись.
    /^[[:space:]]*drift_novel_workload:[[:space:]]*alert[[:space:]]*$/ { flag=1 }
    END { if (id != "") print id, (flag ? "1" : "0") }
' rules/container-escape.yaml rules/drift-rules.yaml)
for rid in $DRIFT_NOVEL_WORKLOAD_RULES; do
    rid_flag=$(echo "$drift_novel_workload_flags" | awk -v r="$rid" '$1==r{print $2}')
    [ "$rid_flag" = "1" ] \
        || die "6.0d: правило $rid из подмножества (б) (примитив побега/захвата, находка №193б) не несёт drift_novel_workload: alert (найдено: '${rid_flag:-правило не найдено в rules/}') — фаза learning новой нагрузки снова получит презумпцию невиновности на этом примитиве"
done
echo "  ок: все правила подмножества (б) ($DRIFT_NOVEL_WORKLOAD_RULES) несут drift_novel_workload: alert"
# Та же проверка, но через загрузчик правил, а не через awk: awk выше видит
# ТЕКСТ YAML, тест — то, что из него получил RuleEngine (класс после
# EffectiveClass, флаг после валидации). Расхождение между этими двумя
# ответами и есть интересный случай: правило, которое читается глазами как
# помеченное, но до движка доезжает без флага. Плюс отрицательная половина —
# container_escape_init_proc_daemon обязан ОСТАТЬСЯ вне подмножества.
go test ./internal/correlator/ -run 'TestDriftNovelWorkloadSubsetCarriesFlag|TestDriftNovelWorkloadDaemonVariantStaysOut' -count=1 >/dev/null 2>&1 \
    || die "6.0d: тесты подмножества (б) не проходят — запустить 'go test ./internal/correlator/ -run TestDriftNovelWorkload -v' и прочитать вывод: либо правило подмножества потеряло drift_novel_workload/class: drift, либо исключённый container_escape_init_proc_daemon его приобрёл"

# Пункт 5 плана 6.0d (находка №197) и пункт 6 (находка №198) — правки
# смотрят на КОД, тем же приёмом, что и сторожа 6.0a выше (комментарии
# вычищены, чтобы историческая запись о правке не сматчила сама себя).
grep -qE '^func stripPreExecCommParens\(' internal/profiler/workload.go \
    || die "6.0d: в internal/profiler/workload.go нет stripPreExecCommParens — находка №197 (расщепление нагрузки на pre-exec comm) не закрыта, WorkloadKeyFromEvent не нормализует (find)/find"
drift_code internal/profiler/workload.go | grep -q 'stripPreExecCommParens(internComm' \
    || die "6.0d: WorkloadKeyFromEvent в internal/profiler/workload.go не вызывает stripPreExecCommParens — функция существует, но не подключена к ключу нагрузки"
grep -qE '^func \(p \*DriftBaselineProfiler\) PromoteExpiredWorkloads\(' internal/profiler/driftbaseline.go \
    || die "6.0d: в internal/profiler/driftbaseline.go нет PromoteExpiredWorkloads — находка №198 (ленивый промоушен) не закрыта, дедлайн по-прежнему проверяется только внутри Observe()"
drift_code internal/profiler/driftbaseline.go | grep -q 'p.PromoteExpiredWorkloads()' \
    || die "6.0d: UpdateLearningGauge в internal/profiler/driftbaseline.go не вызывает PromoteExpiredWorkloads — периодический обход существует, но не запускает промоушен"
grep -qE '^func \(p \*DriftBaselineProfiler\) LearningOverdueWorkloads\(' internal/profiler/driftbaseline.go \
    || die "6.0d: в internal/profiler/driftbaseline.go нет LearningOverdueWorkloads — переопределение stuck_learning_workloads (находка №198) стёрло старый срез вместо того, чтобы вывести его отдельной серией"
go test ./internal/profiler/ -run 'TestWorkloadKeyFromEvent|TestDriftBaselineProfiler_PeriodicSweepPromotesWithoutFurtherEvents|TestDriftBaselineProfiler_StuckVsOverdueDiverge' -count=1 >/dev/null 2>&1 \
    || die "6.0d: тесты нормализации pre-exec comm и периодического промоушена не проходят — запустить 'go test ./internal/profiler/ -run TestWorkloadKeyFromEvent|TestDriftBaselineProfiler_PeriodicSweepPromotesWithoutFurtherEvents|TestDriftBaselineProfiler_StuckVsOverdueDiverge -v' и прочитать вывод"
echo "  ок: pre-exec comm нормализуется в ключе нагрузки (№197), промоушен по дедлайну больше не ленив (№198)"

# Пункт 3/4: критерий 6.0.1 (шаг 16.1 ниже) читает отсутствие строки
# drift_exec_from_system_bin в таблице 5.9.9.F.6b как 0/ч ТОЛЬКО когда сама
# таблица напечатана штатно — по её pass-строке в run-gate.sh (находка
# №195). Проверяется здесь, ЗАРАНЕЕ: если этот литерал в run-gate.sh
# переименуют, шаг 16.1 будет молча читать "таблица не напечатана" на
# каждом прогоне, и 6.0.1 перестанет засчитываться независимо от
# фактического объёма.
grep -qF 'объём правил за idle-час напечатан вместе со срезанным лимитером' $SETUP/attacks/run-gate.sh 2>/dev/null \
    || die "6.0d: строка-маркер таблицы 5.9.9.F.6b ('объём правил за idle-час напечатан вместе со срезанным лимитером') не найдена в run-gate.sh — критерий 6.0.1 (шаг 16.1, находка №195) не сможет отличить 'таблица не построена' от 'построена, объём 0/ч', и его вердикт станет недостоверным на каждом прогоне, а не только на этом"
echo "  ок: маркер таблицы 5.9.9.F.6b, на который опирается критерий 6.0.1, найден в run-gate.sh"

# Пункт 4/4: предпосылки контролей 6.0.6/6.0.7 (шаг 6.0e). Оба исполняются в
# окне атаки, на 90-й минуте прогона, и оба die'ят сам шаг. Отсутствие
# unshare(1) — не дефект продукта, а незаряженный стенд, и узнавать о нём
# через полтора часа означает выбросить весь замер: то же соображение, по
# которому преflight вообще существует.
command -v unshare >/dev/null 2>&1 \
    || die "6.0d: на стенде нет unshare(1) (util-linux) — контроль 6.0.6 (позитивный контроль на НОВУЮ нагрузку, находка №193) нечем исполнить, а он обязателен для закрытия волны. Поставить util-linux ДО прогона: apt-get install -y util-linux"
unshare --user --map-root-user --mount --propagation private -- /bin/true >/dev/null 2>&1 \
    || die "6.0d: 'unshare --user --map-root-user --mount' не отрабатывает на этом ядре/стенде — примитив контроля 6.0.6 недоступен (проверить kernel.unprivileged_userns_clone и что пайплайн запущен от root). Без исполнимого примитива 6.0.6 дал бы FAIL по среде, а не по детектору, и правка №193 была бы объявлена нерабочей ошибочно"
echo "  ок: примитив контроля 6.0.6 (unshare CLONE_NEWUSER + mount) исполним на этом стенде"

echo "--- преflight: 6.0f — приборный долг замера №6.0d и два продуктовых FP (п.9, дополнительно к 6.0d) ---"
# Пункт 1/4 (№199): 6.0.1 обязан читать собственную метрику (acc_v199_vol), а
# не таблицу 5.9.9.F.6b — регресс к таблице был бы находкой №195, повторённой
# ровно тем способом, которым она уже случалась (см. plan.md, «Поле величины
# 16.1 врёт»). acc_rl_cut/acc_rl_cutn/acc_rl_line остаются переменными ТОЛЬКО
# 6.0.2 (срез лимитера) — если они просочатся в блок 6.0.1, это и есть
# регресс, а не рефакторинг.
# Якорь — литерал самой строки вывода ("acc \"16.1\" \"6.0.1 —"), а не просто
# "16.1": этот же преflight-сторож НЕ должен матчить собственный исходный код
# ниже (та же ловушка, что заставила 6.0a чистить комментарии перед grep'ом
# сигнатуры дрейфа — иначе сторож находит себя, а не проверяемую строку).
_v199_line=$(grep -F 'acc "16.1" "6.0.1 —' "$SETUP/run-6.0-pipeline.sh")
[ -n "$_v199_line" ] \
    || die "преflight 6.0f/№199: не найдена сама строка вывода 6.0.1 (acc \"16.1\" \"6.0.1 —...\") — accumulation-блок переименован или удалён"
echo "$_v199_line" | grep -q 'acc_v199_vol' \
    || die "преflight 6.0f/№199: строка acc \"16.1\" не ссылается на acc_v199_vol — критерий 6.0.1 перестал читать собственную метрику, регресс к таблице 5.9.9.F.6b (находка №195, повторно)"
echo "$_v199_line" | grep -q 'acc_rl_cut' \
    && die "преflight 6.0f/№199: строка 6.0.1 ссылается на acc_rl_cut (срез лимитера таблицы 5.9.9.F.6b) — эта переменная принадлежит ТОЛЬКО 6.0.2, объём 6.0.1 обязан браться из собственной суммы alerts_total+alerts_filtered_total"
echo "  ок: 6.0.1 читает объём из собственной метрики (acc_v199_vol), не из таблицы 5.9.9.F.6b"
# Пункт 2/4 (№201/№170): в replay-gate.sh не меньше 21 реплея, знаменатель
# N/M один и тот же во всех метках, число заведённых меток совпадает с этим
# знаменателем, и литерал шага [1/14] этого пайплайна называет то же число —
# ровно тот класс расхождения, который находка №170 уже один раз поймала
# (перенумерация 16→18 задним числом разошлась с индексом). Якорь — заголовок
# "--- реплей N/M:" (с двоеточием), а не голое "реплей N/M": файл содержит
# постороннее совпадение той же формы ("реплей 4/4" — счётчик другой волны,
# 5.9.8e, никак не связанный с общей нумерацией реплеев этого гейта).
_replay_denoms=$(grep -oE -- '--- реплей [0-9]+/[0-9]+:' "$SETUP/attacks/replay-gate.sh" | grep -oE '/[0-9]+:$' | tr -d '/:' | sort -u)
[ "$(echo "$_replay_denoms" | wc -l | tr -d ' ')" -eq 1 ] \
    || die "преflight 6.0f/№201: replay-gate.sh смешивает разные знаменатели меток 'реплей N/M' ($_replay_denoms построчно) — перенумерация 18→21 прошла не до конца"
[ "$_replay_denoms" -ge 21 ] 2>/dev/null \
    || die "преflight 6.0f/№201: replay-gate.sh знает только реплеи с знаменателем $_replay_denoms (< 21) — три реплея постановки 6.0d (19 6.0.5, 20 6.0.1, 21 5.9.7e, находка №201) не заведены"
_replay_have=$(grep -oE -- '--- реплей [0-9]+/[0-9]+:' "$SETUP/attacks/replay-gate.sh" | awk '{print $3}' | sort -u | wc -l | tr -d ' ')
[ "$_replay_have" -eq "$_replay_denoms" ] \
    || die "преflight 6.0f/№201: replay-gate.sh обещает $_replay_denoms реплеев, но заведено только $_replay_have уникальных меток N/$_replay_denoms — реестр неполон"
grep -qF "replay-gate.sh на ПЯТНАДЦАТИ архивах, ${_replay_denoms} реплей" "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0f/№201: литерал шага [1/14] ('...реплей') не называет фактическое число реплеев replay-gate.sh ($_replay_denoms) — тот же класс расхождения текста и факта, что находка №207 нашла у заголовка 16.1"
echo "  ок: replay-gate.sh заведено $_replay_have/$_replay_denoms реплеев, знаменатель один и совпадает с литералом шага [1/14]"
# Пункт 5/6 (№203): подавление глобальной резервной базой обязано иметь
# СОБСТВЕННЫЙ reason, отличимый от "learning" — без этого механизм (а) не
# измерим ничем (находка №203). Проверяется в двух независимых местах: код
# профайлера (источник истины) и criteria-index.txt (регистрация, по которой
# run-gate.sh 5.9.7h ловит будущее исчезновение строки без единого прогона).
drift_code internal/profiler/driftbaseline.go | grep -q 'global_baseline_known' \
    || die "преflight 6.0f/№203: в internal/profiler/driftbaseline.go нет reason=\"global_baseline_known\" — подавление глобальным фоллбэком снова неотличимо от learning, механизм (а) снова не измерим ничем"
grep -qF 'global_baseline_known' "$SETUP/attacks/criteria-index.txt" \
    || die "преflight 6.0f/№203: criteria-index.txt не содержит global_baseline_known — регистр 5.9.7h не заметит будущее исчезновение reason из кода, разрез снова станет непроверяемым молча"
echo "  ок: reason=global_baseline_known заведён и в коде профайлера, и в criteria-index.txt"
# Пункт 4 (№200): оба правила, получившие сужающие предикаты, обязаны нести
# СВОЙ контроль в манифесте атак этого пайплайна — иначе правка правила без
# контроля есть заведение немого правила (тот же принцип, что держит
# WAVE_CRITERIA_IDS/criteria-index.txt в синхроне с постановкой).
grep -q '_impact_critical_count impact_raw_disk_write_from_container' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0f/№200: impact_raw_disk_write_from_container не несёт контроль в манифесте атак этого пайплайна — правка правила (сужение предиката) без контроля есть заведение немого правила"
# 6.0j/п.5 (№211): греп ЯКОРЕН на полный id. До правки он искал префикс
# `_impact_critical_count container_escape_host_device`, который матчится и
# на строку про _from_host, — то есть сторож, заведённый ради запрета немых
# правил, сам пропустил немое правило: волна 6.0f развела id на два, дала
# контроль только контейнерному, а этот греп объявил зелёными оба. Цена —
# два FAIL гейта замера №6.0f2. Правило проверяется для каждого id отдельно
# и своим типом контроля: контейнерный — негативным (критикалов нет),
# хостовой — ПОЗИТИВНЫМ (детект не потерян), потому что негативный контроль
# на warning-правиле не отличает «сужено» от «немо» по построению.
grep -qE '_impact_critical_count container_escape_host_device\)' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0f/№200: контейнерный id container_escape_host_device не несёт СВОЕГО негативного контроля в этом пайплайне (греп якорен на полный id: префиксное совпадение с _from_host запрещено правкой 6.0j/п.5) — разведение container/host без негативного контроля есть заведение немого правила"
grep -qE '_hd_count container_escape_host_device_from_host warning' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/№211: хостовой id container_escape_host_device_from_host не несёт ПОЗИТИВНОГО контроля (6.0.18, шаг 6.0l) — правило warning-уровня, и негативный 6.0.13 (считает только критикалы) о нём не утверждает ничего. Ровно так оно и было заведено немым волной 6.0f: два FAIL гейта №6.0f2 («потеряно 1 типов детекта» и «1 правило немо без строки в silent-rules.txt») — это его цена, и они воспроизведутся на любом прогоне своей волны, потому что new-rules.txt вычитает правило только на архивах СТАРШЕ даты заведения"
grep -q 'run_host_block_device_positive_control()' "$SETUP/attacks/run-all-attacks.sh" \
    || die "преflight 6.0j/№211: run_host_block_device_positive_control отсутствует в run-all-attacks.sh — вход хостового правила в СНИМОК прогона потерян. Состав детекта (крит. 6) и немые правила (крит. 5.9.4h) гейт считает по final-metrics-\$TIMESTAMP.txt, снятому в конце окна атак; шаги-контроли пайплайна (6.0c…6.0l) исполняются ПОСЛЕ него (находка №206), и их алерты в эти снимки не попадают вовсе. Без этого шага 6.0.18 доказал бы правило живым, а гейт всё равно дал бы оба FAIL замера №6.0f2"
calls_in_full_run run_host_block_device_positive_control \
    || die "преflight 6.0j/№211: run_host_block_device_positive_control определён, но не вызывается из full_run() — на замере он не исполнится ни разу, и оба FAIL гейта воспроизведутся"
grep -qF 'echo "--- 6.0l:' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/№211: шага с меткой 6.0l нет в пайплайне — критерий 6.0.18 негде исполнить, а репетиция [6/14] требует существования всех шести шагов-контролей"
rule_predicate container_escape_host_device_from_host rules/container-escape.yaml | grep -qE '^[[:space:]]*severity:[[:space:]]*warning[[:space:]]*$' \
    || die "преflight 6.0j/№211: container_escape_host_device_from_host больше не severity: warning — приём 6.0.18 («>= 1 warning при 0 критикалов по обоим id») тогда мерит не то правило, а разведение №200 отменено молча: хостовой случай снова критикал-first, и негативный 6.0.13 обязан был бы валиться на штатном dumpe2fs"
grep -qE '^[[:space:]]*-[[:space:]]*id:[[:space:]]*"?container_escape_host_device_from_host"?[[:space:]]*$' rules/container-escape.yaml \
    || die "преflight 6.0f/№200: новый id container_escape_host_device_from_host (хостовой случай разведения) не найден в rules/container-escape.yaml — правка №200 откатилась или переименовалась незаметно"
grep -qF 'container_escape_host_device_from_host' "$SETUP/attacks/detection-baseline.txt" \
    || die "преflight 6.0f/№200: container_escape_host_device_from_host не заведён в attacks/detection-baseline.txt — состав детекта разойдётся с базой на первом же прогоне"
echo "  ок: все ТРИ id №200 несут свой контроль поимённо (impact_raw_disk_write_from_container и container_escape_host_device — негативный 6.0.13; container_escape_host_device_from_host — вход в снимок прогона в окне атак + вердикт 6.0.18 на шаге 6.0l, severity=warning), греп якорен на полный id, все заведены в detection-baseline.txt"
# Пункт 6/7 (реплей-блокер правки №200): правило, заведённое волной, немо на
# КАЖДОМ архиве старше себя, и это валит ЖЁСТКИЙ СТОП №1 без единого
# регресса продукта (три реплея разошлись ровно так на 6.0f). Механизм —
# new-rules.txt, вычитающий такое правило из потерь ТОЛЬКО на прогонах
# старше даты заведения. Сторож против злоупотребления: каждый id реестра
# обязан существовать в дереве правил (иначе реестром прикрывают удалённое
# правило) и в detection-baseline.txt (иначе его нечего было бы терять), а
# сам гейт обязан этот реестр читать.
grep -q 'new-rules.txt' "$SETUP/attacks/run-gate.sh" \
    || die "преflight 6.0f/№200: run-gate.sh не читает new-rules.txt — правила, заведённые этой волной, снова станут «категорией (в) без объяснения» на архивах реплеев, и ЖЁСТКИЙ СТОП №1 встанет без регресса продукта"
while IFS=$'\t' read -r _nr_id _nr_date _nr_wave; do
    case "$_nr_id" in ''|\#*) continue ;; esac
    grep -qE "^[[:space:]]*-[[:space:]]*id:[[:space:]]*\"?${_nr_id}\"?[[:space:]]*$" rules/*.yaml \
        || die "преflight 6.0f/new-rules: id '$_nr_id' из new-rules.txt не существует в rules/*.yaml — реестром «моложе архива» прикрыто удалённое или переименованное правило, а не новое"
    grep -qF "$_nr_id" "$SETUP/attacks/detection-baseline.txt" \
        || die "преflight 6.0f/new-rules: id '$_nr_id' из new-rules.txt отсутствует в detection-baseline.txt — вычитать его из потерь нечего, запись бессмысленна и маскирует состав базы"
    echo "  ок: new-rules.txt/$_nr_id (заведено $_nr_date, $_nr_wave) существует в дереве правил и в detection-baseline.txt"
done < "$SETUP/attacks/new-rules.txt"
# Пункт 7/7 (№203): негативный контроль 6.0.11 обязан читать разрез ПО
# НАГРУЗКЕ, а не только счётчик подавлений. Метка нагрузки в
# ebpf_guard_drift_baseline_suppressed_total отсутствует ({rule_id, reason}),
# поэтому его прирост может дать любая чужая обучающаяся нагрузка — и пара
# «0 алертов И счётчик вырос» снова становится приборным нулём, засчитывать
# который постановка запрещает. Свидетель — samples нашего comm в
# /debug/state.
grep -q '_drift_g_samples' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0f/№203: шаг 6.0g не читает samples нагрузки из /debug/state (_drift_g_samples) — 6.0.11 снова засчитает ноль алертов по приросту счётчика, у которого нет метки нагрузки, то есть по чужому подавлению"
grep -q '_drift_g11_samples_after' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0f/№203: свидетель по нагрузке не участвует в вердикте 6.0.11 (нет _drift_g11_samples_after в проверке) — разрез прочитан, но не проверен"
echo "  ок: 6.0.11 требует прироста samples своей нагрузки, а не только счётчика без метки нагрузки"

echo "--- преflight: 6.0j — спуф argv[0] и немой proc.args в контролях (№209/№210, п.2 волны 6.0j) ---"
# Третий подряд замер, убитый шагом 6.0g конструкцией, которую до траты часа
# не проверял никто: №176 — `command -v true` в run-all-attacks.sh, №208 — она
# же в самом пайплайне, №209 — подмена argv[0] в контролях 6.0.11/6.0.12.
# Механика №209: коллектор сверяет comm с basename(argv[0])
# (commMatchesArgv0, internal/collector/syscall.go) и при несовпадении
# ОБНУЛЯЕТ event.ProcArgs — правило с `field: proc.args` не матчит вовсе, и
# контроль получает четыре нуля разом, неотличимых от продуктового молчания.
#
# Сторож 1/2. Подмена argv[0] законна ровно в одном месте пайплайна — в
# контроле 6.0.16 (шаг 6.0k), где она и есть ПРЕДМЕТ измерения. Везде ещё
# она запрещена. Разрешающий маркер — строка `# ARGV0-SPOOF-BY-DESIGN (№210)`
# не далее чем за 10 строк до конструкции. Комментарии исключены явно (тот же
# класс, что сторож №208 выше: разбор дефекта цитирует запрещённую
# конструкцию дословно, и сторож, читающий комментарии как код, валил бы
# преflight на собственном объяснении).
for _j_spoof_f in "$SETUP/run-6.0-pipeline.sh" "$SETUP/attacks/run-all-attacks.sh"; do
    [ -f "$_j_spoof_f" ] || die "преflight 6.0j/№210: файл $_j_spoof_f не найден — сторож подмены argv[0] нечем исполнить"
    _j_spoof_bad=$(awk '
        /ARGV0-SPOOF-BY-DESIGN/ { mark=NR }
        /^[[:space:]]*#/ { next }
        /exec[[:space:]]+-a[[:space:]]/ { if (mark == 0 || NR - mark > 10) printf "%s:%s\n", FILENAME, NR }
    ' "$_j_spoof_f")
    [ -z "$_j_spoof_bad" ] \
        || die "преflight 6.0j/№210: подмена argv[0] (флаг -a у встроенного exec) вне блока с маркером '# ARGV0-SPOOF-BY-DESIGN (№210)' — $_j_spoof_bad. Коллектор обнуляет proc.args при несовпадении comm с basename(argv[0]) (commMatchesArgv0), поэтому любое правило класса proc.args в таком контроле молчит по приборной причине, а шаг умирает уже ПОСЛЕ idle-часа (замеры №6.0f2 и №208). Либо звать реальный файл напрямую (имя файла = comm), либо, если подмена и есть предмет измерения, пометить блок маркером"
done
echo "  ок: подмена argv[0] нигде в пайплайне и в run-all-attacks.sh не стоит без маркера предмета измерения"
# Сторож 2/2, шире и важнее первого: всякий контроль, чей ПРИЁМ читает
# правило с `field: proc.args`, обязан печатать сам proc.args из полученного
# алерта. Без этого ноль контроля неотличим от обнулённого коллектором args —
# то есть от находки №209 в любом её будущем виде (не только под подменой
# argv[0]: тот же ноль даёт login-shell с argv[0]="-bash" и любой дроппер
# T1036.003). «Читает правило» определяется конструктивно: блок шага 6.0*
# содержит отбор алертов `rule_id=="<id>"` по правилу из списка ниже.
# «Печатает» — строка echo (не комментарий), содержащая proc.args.
# Список правил класса вычисляется из дерева правил, а не хардкодится:
# правило, получившее условие на proc.args завтра, попадает под сторож само.
_j_pa_ids=$(awk '
    /^[[:space:]]*-[[:space:]]*id:[[:space:]]*/ { id=$0; sub(/^[^:]*:[[:space:]]*/,"",id); gsub(/"/,"",id); sub(/[[:space:]]+$/,"",id); has=0; next }
    /^[[:space:]]*field:[[:space:]]*"?proc\.args"?[[:space:]]*$/ { if (id != "" && !has) { print id; has=1 } }
' rules/*.yaml | sort -u | tr '\n' ' ')
[ -n "${_j_pa_ids// /}" ] \
    || die "преflight 6.0j/№209: в rules/*.yaml не нашлось НИ ОДНОГО правила с условием на proc.args — сторож печати proc.args стал бы критерием без достижимого FAIL (класс №123/№124), а 71 условие этого класса на 01.09 существовало"
_j_pa_bad=$(awk -v ids="$_j_pa_ids" '
BEGIN { n=split(ids, a, " ") }
/^echo "--- / { emit(); step=""; body=""; if ($0 ~ /^echo "--- 6\.0[a-z]/) step=$0 }
step != "" { body = body "\n" $0 }
END { emit() }
function emit(   i,rid,prints,nl,L) {
  if (step == "") return
  rid=""
  for (i=1;i<=n;i++) if (a[i] != "" && index(body, "rule_id==\"" a[i] "\"") > 0) rid=a[i]
  if (rid == "") return
  prints=0
  nl=split(body, L, "\n")
  for (i=1;i<=nl;i++) if (L[i] ~ /echo/ && L[i] ~ /proc\.args/ && L[i] !~ /^[[:space:]]*#/) prints=1
  if (!prints) printf "%s (правило %s)\n", substr(step, 1, 60), rid
}
' "$SETUP/run-6.0-pipeline.sh")
[ -z "$_j_pa_bad" ] \
    || die "преflight 6.0j/№209: контроль читает правило класса proc.args, но не печатает proc.args из полученного алерта — $_j_pa_bad. Ноль такого контроля неотличим от proc.args, обнулённого коллектором (commMatchesArgv0), и стоит целого замера: именно так умер №6.0f2. Печатать поле details['proc.args'] последнего алерта своего rule_id (образец — _drift_g_args на шаге 6.0g)"
echo "  ок: все контроли, читающие правила класса proc.args, печатают proc.args из алерта (правил класса в дереве: $(echo "$_j_pa_ids" | wc -w | tr -d ' '))"
# Сторож 3/3 к п.1: proc.args обязан ДОЕЗЖАТЬ до алерта. Поле — часть правки
# 6.0j в корреляторе (procArgsAlertDetails): до неё Alert.Event был json:"-",
# а Details нёс только file.path/dns.qname, и печатать сторожу 2/2 было
# нечего. Откат правки делает оба сторожа выше бессмысленными молча.
grep -q 'func procArgsAlertDetails' internal/correlator/rules.go \
    || die "преflight 6.0j/№209: internal/correlator/rules.go не содержит procArgsAlertDetails — proc.args снова не доезжает до алерта (Alert.Event = json:\"-\"), и сторож печати proc.args проверяет вывод, которого физически неоткуда взять"
go test -count=1 ./internal/correlator/ -run 'TestProcArgsReachesAlertDetails' >/dev/null 2>&1 \
    || die "преflight 6.0j/№209: тест TestProcArgsReachesAlertDetails красный или отсутствует — контракт «алерт правила класса proc.args несёт сам proc.args» не закреплён, и его потеря не будет видна ничем до следующего убитого замера"
echo "  ок: proc.args доезжает до алерта (procArgsAlertDetails), контракт закреплён тестом"
# Сторож 4/6 (п.8 волны, долг п.2): ЯКОРЕНИЕ сторожа 2/2 на details.
# Сторож 2/2 выше считает контроль зрячим, если в блоке шага есть строка
# echo со словом proc.args. Обойти это можно одной строкой текста
# (`echo "  proc.args не читается"`) — то есть проверка «печатает величину»
# удовлетворяется печатью СЛОВА. Здесь требуется, чтобы такая строка печатала
# ВЕЛИЧИНУ, и чтобы величина эта происходила из алерта: в echo обязана быть
# подстановка ($… или $(…)), а имя, которое она зовёт, обязано быть определено
# в этом же файле телом, содержащим извлечение details["proc.args"].
_j_anchor_bad=$(awk '
/^echo "--- / { emit(); step=""; body=""; if ($0 ~ /^echo "--- 6\.0[a-z]/) step=$0 }
step != "" { body = body "\n" $0 }
END { emit() }
function emit(   i,nl,L,line,names,nn,j,nm,seen) {
  # Ни одной строки печати не найдено — это забота сторожа 2/2 выше, здесь
  # молчим: два сторожа на один и тот же дефект дали бы два разных вердикта.
  # Здесь проверяется ТОЛЬКО происхождение печатаемой величины, и достаточно
  # ОДНОЙ строки, которая сводится к алерту: контроль вправе печатать рядом и
  # пояснительные строки без подстановок.
  if (step == "") return
  if (index(body, "details[\"proc.args\"]") > 0) return   # извлечение прямо в блоке
  nl=split(body, L, "\n"); names=""; seen=0
  for (i=1;i<=nl;i++) {
    line=L[i]
    if (line !~ /echo/ || line !~ /proc\.args/ || line ~ /^[[:space:]]*#/) continue
    seen=1
    while (match(line, /\$\(?\{?[A-Za-z_][A-Za-z_0-9]*/)) {
      nm=substr(line, RSTART, RLENGTH); gsub(/[$({]/, "", nm)
      names=names " " nm
      line=substr(line, RSTART+RLENGTH)
    }
  }
  if (!seen) return
  nn=split(names, N, " ")
  for (j=1;j<=nn;j++) if (N[j] != "" && index(SRC_DETAILS, " " N[j] " ") > 0) return
  if (names == "") { printf "%s: строки печати proc.args без единой подстановки — печатается слово, а не величина\n", substr(step,1,60); return }
  printf "%s: печать proc.args не сводится к details[\"proc.args\"] (имена:%s)\n", substr(step,1,60), names
}
' SRC_DETAILS="$(awk '
    /^[_A-Za-z][_A-Za-z0-9]*\(\)[[:space:]]*\{/ { fn=$0; sub(/\(\).*/,"",fn); body="" }
    fn != "" { body = body $0 }
    /^\}/ { if (fn != "" && index(body, "details[\"proc.args\"]") > 0) printf " %s ", fn; fn="" }
' "$SETUP/run-6.0-pipeline.sh")" "$SETUP/run-6.0-pipeline.sh")
[ -z "$_j_anchor_bad" ] \
    || die "преflight 6.0j/№209 (п.8): печать proc.args в контроле не якорена на алерт — $_j_anchor_bad. Строка echo, содержащая слово proc.args, но не подставляющая величину из details[\"proc.args\"] полученного алерта, удовлетворяет сторожу 2/2 текстом и не доказывает ничего: ровно тот обход, из-за которого сторож заводился (образцы — _drift_g_args на шаге 6.0g и _drift_pc2_args на 6.0c)"
echo "  ок: печать proc.args в контролях сводится к details[\"proc.args\"] алерта, а не к слову в тексте"
# Сторож 5/6 (п.8 волны): реплеев в replay-gate.sh не меньше 25, и три
# новых заведены поимённо. Общий сторож №201 (выше, волна 6.0f) проверяет
# согласованность знаменателя с литералом шага [1/14] и не знает, СКОЛЬКО
# реплеев обязана иметь эта волна; без нижней границы п.7 можно было бы
# объявить исполненным, не заведя ни одного реплея.
_j_replay_denom=$(grep -oE -- '--- реплей [0-9]+/[0-9]+:' "$SETUP/attacks/replay-gate.sh" | grep -oE '/[0-9]+:$' | tr -d '/:' | sort -u | head -1)
[ "${_j_replay_denom:-0}" -ge 25 ] 2>/dev/null \
    || die "преflight 6.0j/п.7: в replay-gate.sh знаменатель меток реплеев = ${_j_replay_denom:-нет} (< 25) — три реплея волны 6.0j (23/25 new-rules.txt, 24/25 пол 6.0.1, 25/25 гигиена коллекта) не заведены, и ЖЁСТКИЙ СТОП №1 проверяет постановку прошлой волны"
for _j_rp in 'реплей 23/25' 'реплей 24/25' 'реплей 25/25'; do
    grep -qF -- "--- $_j_rp:" "$SETUP/attacks/replay-gate.sh" \
        || die "преflight 6.0j/п.7: в replay-gate.sh нет метки '--- $_j_rp:' — знаменатель перенумерован, а сам реплей не заведён (ровно тот класс расхождения текста и факта, что находка №170 поймала на перенумерации 16→18)"
    grep -qF -- "$_j_rp" "$SETUP/attacks/criteria-index.txt" \
        || die "преflight 6.0j/п.7: метка '$_j_rp' не заведена в criteria-index.txt — реплей можно будет удалить незаметно, сторож 5.9.7h его не хватится (память criteria-index-pins-replay-labels)"
done
echo "  ок: реплеев в replay-gate.sh $_j_replay_denom (>= 25), все три метки волны 6.0j заведены и зарегистрированы в criteria-index.txt"
# Сторож 6/6 (п.8 волны): пол величины 6.0.1 (реплей 24/25) существует в
# самом пайплайне. Реплей самодостаточен — он воспроизводит логику блока 16.1
# у себя, — поэтому удаление пола из пайплайна оставило бы реплей зелёным, а
# замер снова печатал бы ноль слепого детектора как успех.
grep -qF 'acc_v199_floor' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/п.7: в блоке 16.1 нет acc_v199_floor — пол величины 6.0.1 удалён, и нулевой объём снова засчитывается без свидетельства, что правило видело вход за тот же час (память drift-volume-criterion-needs-a-floor)"
grep -qF 'НЕ ЗАСЧИТЫВАЕТСЯ (ноль без пола)' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/п.7: в пайплайне нет ветки «ноль без пола» — пол посчитан, но на вердикт 6.0.1 не влияет, то есть печатается как наблюдение (та же форма, в которой условие «засчитывается вместе с полом 16.5» жило текстом и не проверялось)"
echo "  ок: пол величины 6.0.1 (acc_v199_floor) считается и входит в вердикт веткой «ноль без пола»"

echo "--- преflight: 6.0j/п.6 — артефакты аборта не выдают себя за свежие (№212) ---"
# Сторожа три, и все три — на СВОЙ файл, потому что каждый из них по
# отдельности пропускает находку №212 целиком:
#   уборка без метки аборта  — архив умершего прогона снова отличается от
#                              архива живого только тем, чего в нём нет;
#   метка без уборки         — метка прошлого аборта переживает следующий
#                              прогон и врёт про него;
#   обе без сверки TIMESTAMP — файл, написанный ЭТИМ прогоном про ЧУЖОЙ
#                              замер, проходит и уборку, и метку.
_j212_rm_line=$(grep -n '^rm -f /root/report-6.0.txt' "$SETUP/run-6.0-pipeline.sh" | head -1 | cut -d: -f1)
_j212_pf_line=$(grep -n '^echo "=== \[0/14\] преflight' "$SETUP/run-6.0-pipeline.sh" | head -1 | cut -d: -f1)
[ -n "$_j212_rm_line" ] && [ -n "$_j212_pf_line" ] && [ "$_j212_rm_line" -lt "$_j212_pf_line" ]     || die "преflight 6.0j/№212: пайплайн не убирает /root/*-6.0*.txt ДО преflight'а (строка уборки: ${_j212_rm_line:-нет}, строка [0/14]: ${_j212_pf_line:-нет}) — артефакты прошлого прогона снова доживут до коллекта. Так collect-6.0f2-aborted получил report-6.0.txt и gate-6.0.txt от прогона 30.08: они перезаписываются только на шагах [13/14]/[14/14], которых при аборте не бывает"
grep -q 'ABORTED-6.0.txt' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/№212: die() не пишет /root/ABORTED-6.0.txt — архив умершего прогона снова неотличим от архива успешного по составу файлов, и понять место смерти можно будет только чтением лога целиком"
grep -qF 'гигиена коллекта (№212) ПРОВАЛЕНА' "$SETUP/run-6.0-pipeline.sh" \
    || die "преflight 6.0j/№212: в пайплайне нет шага сверки TIMESTAMP артефактов с TIMESTAMP этого прогона — уборка на старте доказывает лишь «файл написан этим прогоном», а не «написан про этот прогон», и вторая половина находки №212 остаётся неизмеримой"
echo "  ок: уборка стоит до преflight'а (строка $_j212_rm_line < $_j212_pf_line), die() метит аборт, сверка TIMESTAMP коллекта заведена"


echo "--- преflight: 5.9.9.F.5g — drift_new_exec_critical переименовано и понижено (№154) ---"
# №154: правило дало 576/607 алертов и 576/577 критикалов idle-часа
# №2.9.9.F.4, из них 499 — пере-exec sshd на входящее ssh-соединение (см. блок
# «Числа для решений сняты» в plan.md, волна 5.9.9.F.5). Выбран вариант 2:
# rename + понижение до warning, critical зарезервирован за вариантом с
# drift_baseline (не включённым). Сторож ловит обе половины регрессии: старое
# имя не должно существовать в дереве, новое — обязано быть warning, не
# critical (иначе агент снова упирается в потолок per-rule лимитера 10/60с на
# каждом идентичном ssh-скане, находка №164/5.9.9.F.5n).
grep -q 'id: drift_new_exec_critical' rules/drift-rules.yaml \
    && die "5.9.9.F.5g: rules/drift-rules.yaml по-прежнему содержит старый id drift_new_exec_critical — переименование №154 откатилось, а detection-baseline.txt/background-rules.txt/этот пайплайн уже сверяются по новому имени drift_exec_from_system_bin"
grep -q 'id: drift_exec_from_system_bin' rules/drift-rules.yaml \
    || die "5.9.9.F.5g: rules/drift-rules.yaml не содержит drift_exec_from_system_bin — правило потеряно или переименовано иначе, чем зафиксировано в plan.md"
rule_predicate drift_exec_from_system_bin rules/drift-rules.yaml | grep -qE '^[[:space:]]*severity:[[:space:]]*warning[[:space:]]*$' \
    || die "5.9.9.F.5g ПРОВАЛЕН: drift_exec_from_system_bin не понижено до severity: warning — правило снова критикал-first на каждом ssh-скане стенда (499/607 idle-часа №2.9.9.F.4), величина 11 снова меряет потолок per-rule лимитера, а не drift"
echo "  ок: drift_new_exec_critical переименовано в drift_exec_from_system_bin, severity=warning"

echo "--- преflight: 5.9.9.F.5d/5.9.9.F.5j — коалесцирование фона обеими сторонами (№158/№160) ---"
# Обе половины 5.5d проверяются ОДНИМ прогоном, потому что поодиночке каждая
# ничего не доказывает: тест «cron-тики схлопываются» зелёный и у правки,
# которая просто доверяет всему подряд, а тест «атака из-под демона не
# схлопывается» зелёный и у полностью выключённого коалесцирования. Пункт
# считается исполненным, только если зелены обе стороны сразу.
#   5d (№158): cron-тик + собственный sh демона = один инцидент; xmrig в том
#              же дереве = по-прежнему два.
#   5j (№160): grafana за containerd-shim (усечённое на границе контейнера
#              дерево) = один инцидент вместо пяти строк на снимок; xmrig за
#              тем же шимом = два, и шим без записанной цепочки трастовым не
#              становится.
go test -count=1 ./internal/correlator/ \
        -run 'TestIncidentTracker_CronTick_CoalescesIntoOneIncident|TestIncidentTracker_AttackInDaemon_DoesNotCoalesce|TestIncidentTracker_ContainerizedDaemon_CoalescesThroughShim|TestIncidentTracker_AttackBehindShim_DoesNotCoalesce|TestIncidentTracker_ShimWithoutChain_StaysUntrustedRooted' >/dev/null 2>&1 \
    || die "5.9.9.F.5d/5.9.9.F.5j: тесты коалесцирования фона красные или отсутствуют — знаменатель критерия 9 (доля инцидентов на демонах) снова считает по одной строке на тик, и величина «< 20% на демонах» опять измеряет структурную константу, а не детект"
grep -q 'func (t \*IncidentTracker) trustedIncidentRoot' internal/correlator/incident.go \
    || die "5.9.9.F.5j: в internal/correlator/incident.go нет trustedIncidentRoot — сквозной просмотр через containerd-shim откатился, пять grafana-инцидентов на снимок вернулись"
grep -q 'containerd-shim' internal/correlator/incident.go \
    || die "5.9.9.F.5j: список containerSupervisorComms не содержит containerd-shim — усечённое на границе контейнера дерево снова читается как недоверенный корень"
echo "  ок: обе стороны 5d и все три стороны 5j зелёные"

echo "--- преflight: 5.9.9.F.4g — загрузчик отвергает пустой values: [] (№148) ---"
go test -count=1 ./internal/correlator/ -run 'TestRuleLoaderEmptyValuesList' >/dev/null 2>&1 \
    || die "5.9.9.F.4g: юнит-тест TestRuleLoaderEmptyValuesList красный или отсутствует — сторож загрузчика не в дереве"
# Не `./build/ebpf-guard rules check`: на этом шаге в build/ лежит ЕЩЁ СТАРЫЙ
# бинарь (пересборка — шаг [3/14]), а у старого загрузчика этой проверки нет,
# то есть зелёный ответ ничего не доказывал бы. Ищем сам дефект в наборе.
f4g_empty=$(grep -rn -E '^[[:space:]]*values:[[:space:]]*\[\][[:space:]]*$' rules/ || true)
[ -z "$f4g_empty" ] \
    || die "5.9.9.F.4g: в наборе rules/ остались пустые values: [] — после ужесточения загрузчика агент не поднимется с этим набором вовсе: $(echo "$f4g_empty" | tr '\n' ' ')"
echo "  ок: загрузчик отвергает пустой список, весь набор rules/ грузится"

echo "--- преflight: 5.9.9.F.4h — записи журнала: хопы различимы, порог DNS выше межвсплескового интервала (№149/№150) ---"
go test -count=1 ./internal/collector/ -run 'TestDropLogger_RecordDoesNotDuplicateCollectorKeyAndDistinguishesHops' >/dev/null 2>&1 \
    || die "5.9.9.F.4h/№149: юнит-тест различимости хопов красный или отсутствует — дубль ключа collector и неразличимые хопы fileaccess не закрыты"
dns_thr=$(awk '/^const dnsStaleThreshold/{print $NF; exit}' internal/collector/dns.go)
dns_thr_min=$(awk '/^const dnsStaleThreshold/{for(i=1;i<=NF;i++) if($i ~ /^[0-9]+$/) {print $i; exit}}' internal/collector/dns.go)
[ -n "$dns_thr_min" ] && [ "$dns_thr_min" -ge 6 ] 2>/dev/null \
    || die "5.9.9.F.4h/№150: dnsStaleThreshold = ${dns_thr_min:-?} мин — измеренный живьём межвсплесковый интервал тихого стенда 312с уже длиннее 5 минут, порог обязан быть выше него (иначе 59 пар WARN/recovered за idle-час, как на №2.9.9.F.3, и обязательная величина 12 недостижима)"
echo "  ок: хопы различимы юнит-тестом, dnsStaleThreshold = ${dns_thr_min} мин (> 312с наблюдённого интервала)"

echo "--- преflight: 5.9.9.F.4i — перенос волны 5.9.9.F.3 целиком ---"
# Пункт не имеет собственной правки кода по построению: он требует, чтобы все
# семь пунктов 5.9.9.F.3 остались в дереве и получили приёмку ЭТИМ замером.
# Их сторожа отработали выше; здесь проверяется то, чего у них нет, — что
# перенос объявлен там, где его читает бухгалтерия гейта.
f4i_missing=""
for wid in 5.9.9.F.3a 5.9.9.F.3b 5.9.9.F.3c 5.9.9.F.3d 5.9.9.F.3e 5.9.9.F.3f 5.9.9.F.3g; do
    case " $WAVE_CRITERIA_IDS " in *" $wid "*) ;; *) f4i_missing="$f4i_missing $wid" ;; esac
done
[ -z "$f4i_missing" ] \
    || die "5.9.9.F.4i: пункты 5.9.9.F.3 выпали из WAVE_CRITERIA_IDS:$f4i_missing — перенос волны объявлен постановкой, но её пункты не сверяются на этом замере, то есть 5.9.9.F.3 второй замер подряд не принимается ни одной величиной"
echo "  ок: все семь пунктов 5.9.9.F.3 сверяются этим замером наравне с пунктами 5.9.9.F.4"

echo "--- преflight: реестр idle-actors.txt заведён (5.9.9.F.2d, №118) ---"
[ -s "$SETUP/attacks/idle-actors.txt" ] \
    || die "5.9.9.F.2d: idle-actors.txt отсутствует или пуст — состав idle-часа не с чем сверять, критерий по НОВОМУ АКТОРУ без входа"
idle_actors_n=$(awk -F'\t' '!/^[[:space:]]*(#|$)/ && NF>=1 {print $1}' "$SETUP/attacks/idle-actors.txt" | sort -u | wc -l)
echo "  idle-actors.txt: $idle_actors_n различных comm (оба окна суток: утро 2.9.9.F + ночь 2.9.9.F.1)"
[ "$idle_actors_n" -ge 30 ] \
    || die "5.9.9.F.2d: в idle-actors.txt только $idle_actors_n акторов — реестр заведён из ОДНОГО окна суток, и первый же idle-час в другом часе даст FAIL реестром, а не находкой"

# 5.9.9.F.3, запрет постановки, названный явно: акторы пакета systemd
# 11:57:39 (находка №133) в реестр НЕ дописываются. Дописывание перевело бы
# FAIL замера №2.9.9.F.2 в PASS правкой реестра — то есть впитало бы
# реальный дефект детекта в сторожевой реестр и превратило крит. 5.9.9.F.2d
# из сторожа в узаконивание. Если правки 3a/3b/3c верны, эти акторы просто
# перестают порождать алерты и в состав idle-часа не попадают вовсе.
for banned in mandb '(mandb)' find '(find)' install '(install)'; do
    # find УЖЕ есть в реестре законно (утро 2.9.9.F, MOTD-цепочка) — его
    # проверяем только в скобочной форме, остальные в обеих.
    [ "$banned" = "find" ] && continue
    if awk -F'\t' -v b="$banned" '!/^[[:space:]]*#/ && $1==b {found=1} END{exit !found}' "$SETUP/attacks/idle-actors.txt"; then
        die "5.9.9.F.3: актор «$banned» дописан в idle-actors.txt. Постановка волны запрещает это явно: FAIL замера №2.9.9.F.2 вынесен крит. 5.9.9.F.2d на пакете systemd (находка №133), и перевод его в PASS правкой реестра — ровно то, что постановка 5.9.9.F.2 запретила («такой FAIL есть успех волны и в PASS правкой порога не переводится»). Чинить надо предикаты 3a/3b/3c, а не реестр"
    fi
done
echo "  ок: акторы пакета systemd в реестр не дописаны (FAIL чинится предикатом, не реестром)"

echo "--- преflight: юнит-тест 5.9.9.F.2g (дубль ключа collector в JSON, №127) ---"
go test -count=1 -v ./internal/collector/ -run 'TestMalformedLogger_RecordDoesNotDuplicateCollectorKey' 2>&1 | grep -E '^(=== RUN|--- |ok|FAIL)' | sed 's/^/  /'
go test -count=1 ./internal/collector/ -run 'TestMalformedLogger_RecordDoesNotDuplicateCollectorKey' >/dev/null 2>&1 \
    || die "5.9.9.F.2g: юнит-тест дубля ключа collector красный — запись malformed event record снова невалидна для строгих парсеров (находка №127)"

# Сторож 5.9.8a на уровне ИСХОДНИКА BPF: ключ dns_socket_map обязан быть
# процессным (tgid), а не потоковым. Проверяется здесь, а не только в
# контролях [7/14], потому что здесь это стоит секунду, а там — минуты.
echo "--- преflight: ключ dns_socket_map процессный, а не потоковый (5.9.8a) ---"
grep -q '__u32 tgid;' bpf/dns.bpf.c || die "5.9.8a: struct dns_socket_key не несёт поля tgid — правка №94 не в дереве, замер измерил бы старый ключ"
grep -q 'key.pid_tgid = bpf_get_current_pid_tgid();' bpf/dns.bpf.c \
    && die "5.9.8a: в bpf/dns.bpf.c остался потоковый ключ (key.pid_tgid = …) — правка №94 откачена частично"
echo "  ок: ключ строится из current_tgid()"

echo "--- преflight: реестры ---"
for f in dns-decode-reasons.txt detection-baseline.txt silent-rules.txt intentional-loss.txt criteria-index.txt dns-idle-fp.txt background-rules.txt idle-actors.txt; do
    if [ -f "$SETUP/attacks/$f" ]; then
        echo "  $f: $(grep -cv '^[[:space:]]*\(#\|$\)' "$SETUP/attacks/$f") значащих строк"
    else
        echo "  $f: ОТСУТСТВУЕТ — соответствующий критерий будет нечитаем"
    fi
done
[ -s "$SETUP/attacks/criteria-index.txt" ] \
    || die "criteria-index.txt отсутствует или пуст — run-gate.sh обрушится преflight'ом (exit 3), 5.9.7h не проверяем"

# 5.9.8h: WARN «база брошена» второй замер подряд означал, что сигнатура
# прошлого прогона осталась от прогона на АРХИВЕ (шаг [2/14] снимает её за
# собой, но старая могла дожить с прошлых сессий). Печатается явно.
ls -l "$SETUP/attacks/detection-baseline-diff-state.txt" 2>/dev/null | sed 's/^/  сигнатура прошлого прогона: /' \
    || echo "  сигнатуры прошлого прогона нет — предупреждение «база брошена» на этом замере невозможно по построению"

if command -v python3 >/dev/null 2>&1; then
    echo "  python3: $(python3 --version 2>&1) — 5.9.7a/5.9.7b/5.9.8a исполнимы"
else
    die "python3 не найден — контроль счётности (5.9.7a), run_ringbuf_overflow (5.9.7b) и оба контроля DNS (5.9.8a) без входа"
fi
command -v jq >/dev/null 2>&1 || die "jq не найден — гейт и разбивки по comm непроверяемы"

echo "  параметры замера: COUNTING_CONTROL_N=$COUNTING_CONTROL_N INDUCED_DROP_MAX_FILES=$INDUCED_DROP_MAX_FILES RINGBUF_OVERFLOW_N=$RINGBUF_OVERFLOW_N DNS_CROSS_THREAD_N=$DNS_CROSS_THREAD_N"
echo "  параметры волны 5.9.9.F.2: CPU_PRESSURE_MAX_FILES=$CPU_PRESSURE_MAX_FILES CPU_PRESSURE_MAX_REDUCE_WAIT=$CPU_PRESSURE_MAX_REDUCE_WAIT (min_dwell читается у агента, не задаётся здесь)"

grep -n -A7 '^enforcement:' "$SETUP/config-test.yaml" | sed 's/^/  конфиг enforcement: /'
grep -n 'track_write' "$SETUP/config-test.yaml" | sed 's/^/  конфиг file_ops: /'
grep -q 'track_write:[[:space:]]*true' "$SETUP/config-test.yaml" \
    || die "track_write выключен — rootkit_ssh_authorized_keys_modified (5.9.7e) немо по построению"
echo "преflight завершён в $(date -u +%H:%M:%S) UTC"

echo "=== [1/14] ЖЁСТКИЙ СТОП №1: replay-gate.sh на ПЯТНАДЦАТИ архивах, 25 реплей (5.9.7c…6.0j) ==="
# collect-2.9.5 — тождество умеет SKIP по отсутствующей левой части;
# collect-2.9.6 — сходится там, где сходилось, и новая формула фона проходит
# там, где старая валила; синтетическая потеря 1000 событий — тождество умеет
# падать; collect-2.9.7 (5.9.8e) — крит. 9 даёт 88.6/мин, а не SKIP;
# collect-2.9.8 (5.9.9a) — «база брошена» даёт ОБА исхода; collect-2.9.9
# (5.9.9.Fe) — вторая и третья ветки спасения фонового правила различаются;
# collect-2.9.9.F (5.9.9.F.1a/5.9.9.F.1c) — крит. 16 умеет PASS и FAIL, ноль
# web_sql_injection_files объясняется реестром.
#
# СЕДЬМОЙ архив, НОВОЕ на этом замере — collect-2.9.9.F.1. На нём стоят все
# четыре реплея волны 5.9.9.F.2, и он единственный, где это возможно: только
# рядом с ним лежат agent-start-*.txt (окно журнала крит. 17) и
# journal-agent-*.log (журнальные строки для крит. 5.9.4h), и только он
# вместе с collect-2.9.9.F покрывает ОБА окна суток для idle-actors.txt.
#
# У каждого из НОВЫХ реплеев (13/14 и 14/14) проверяется ОТРИЦАТЕЛЬНЫЙ исход, а не
# только положительный. Это прямое требование постановки волны: все её
# правки меняют вердикт гейта, и критерий, ставший зелёным потому, что
# разучился падать, вернул бы 0 и прошёл бы здесь незамеченным — ровно этим
# и была находка №124.
find_archive() {
    local name="$1" d
    for d in "/opt/ebpf-guard/server-logs/$name" "/root/$name" "/tmp/$name" "$SETUP/../../server-logs/$name"; do
        [ -d "$d/attacks" ] && { echo "$d"; return 0; }
    done
    return 1
}
C295_DIR="${REPLAY_C295_DIR:-$(find_archive collect-2.9.5 || true)}"
C296_DIR="${REPLAY_C296_DIR:-$(find_archive collect-2.9.6 || true)}"
C297_DIR="${REPLAY_C297_DIR:-$(find_archive collect-2.9.7 || true)}"
C298_DIR="${REPLAY_C298_DIR:-$(find_archive collect-2.9.8 || true)}"
C299_DIR="${REPLAY_C299_DIR:-$(find_archive collect-2.9.9 || true)}"
C299F_DIR="${REPLAY_C299F_DIR:-$(find_archive collect-2.9.9.F || true)}"
C299F1_DIR="${REPLAY_C299F1_DIR:-$(find_archive collect-2.9.9.F.1 || true)}"
C299F2_DIR="${REPLAY_C299F2_DIR:-$(find_archive collect-2.9.9.F.2 || true)}"
# 5.9.9.F.7b/7c завели реплеи 15/16 и 16/16, а те читают ДВА архива, которых
# в этом блоке не было: collect-2.9.4 (сторона FAIL крит. №68 и доля
# 2/20=10.0% крит. 9) и collect-2.9.9.F.6 (сторона PASS и доля 4/13=30.8%).
# Оба — позиционные аргументы $9 и $10 replay-gate.sh; без них скрипт брал
# СВОИ дефолты ($REPO_ROOT/server-logs/...), которых на стенде нет вовсе, и
# оба реплея печатали "не проверен" — предпрогон №2.9.9.F.7 (13:41 UTC) встал
# на этом ЖЁСТКИМ СТОПОМ №1. Ищутся тем же find_archive и точно так же
# обязательны: пропуск реплея — находка №85.
C294_DIR="${REPLAY_C294_DIR:-$(find_archive collect-2.9.4 || true)}"
C299F6_DIR="${REPLAY_C299F6_DIR:-$(find_archive collect-2.9.9.F.6 || true)}"
# 5.9.9.F.8a/5.9.9.F.8b (№179/№180) завели реплеи 17/21 и 18/21, а те читают
# ОДИННАДЦАТЫЙ архив — collect-2.9.9.F.7, которого в этом блоке не было:
# только его idle-час несёт fwupd/fwupdmgr (обе стороны строки реестра,
# 5.9.9.F.8a) и только он даёт сторону SKIP крит. 21 против стороны PASS на
# collect-2.9.9.F.2 (5.9.9.F.8b). Это позиционный аргумент $11 replay-gate.sh;
# без него скрипт берёт СВОЙ дефолт ($REPO_ROOT/server-logs/collect-2.9.9.F.7),
# которого на стенде нет вовсе, и оба реплея печатают «архив недоступен» —
# ровно тем встал предпрогон №2.9.9.F.7 на реплеях 15/16 и 16/16 (4d8d83e).
# Ищется тем же find_archive и точно так же обязателен: пропуск реплея —
# находка №85.
C299F7_DIR="${REPLAY_C299F7_DIR:-$(find_archive collect-2.9.9.F.7 || true)}"
# 6.0g (предпрогон 01.09): волна 6.0f завела реплеи 19/25..22/25 (6.0.5,
# 6.0.1, 5.9.7e/№194, 6.0.10), и они читают ДВЕНАДЦАТЫЙ и ТРИНАДЦАТЫЙ архивы —
# collect-6.0 и collect-6.0b, — которых в этом блоке не было. Это позиционные
# аргументы $12 и $13 replay-gate.sh; без них скрипт берёт СВОИ дефолты
# ($REPO_ROOT/server-logs/collect-6.0…), каталога server-logs на стенде нет
# вовсе, и все четыре реплея печатают [REPLAY-MISMATCH] «недоступен» —
# ЖЁСТКИЙ СТОП №1 без единого регресса продукта. Тот же дефект наследования
# пайплайна, что уже вставал на реплеях 15/16-16/16 (4d8d83e) и 17/18-18/18
# (07a4a3e), третий раз подряд. Ищутся тем же find_archive и точно так же
# обязательны: пропуск реплея — находка №85.
C60_DIR="${REPLAY_C60_DIR:-$(find_archive collect-6.0 || true)}"
C60B_DIR="${REPLAY_C60B_DIR:-$(find_archive collect-6.0b || true)}"
# 6.0j/п.7: реплеи 23/25..25/25 читают ЧЕТЫРНАДЦАТЫЙ и ПЯТНАДЦАТЫЙ архивы —
# collect-6.0f2-aborted и collect-6.0d. Позиционные аргументы $14 и $15
# replay-gate.sh; без них скрипт берёт свои дефолты ($REPO_ROOT/server-logs/…),
# каталога server-logs на стенде нет вовсе, и все три новых реплея печатают
# [REPLAY-MISMATCH] «недоступен» — ЖЁСТКИЙ СТОП №1 без единого регресса
# продукта. Тот же дефект наследования пайплайна, что уже вставал на реплеях
# 15/16-16/16 (4d8d83e), 17/18-18/18 (07a4a3e) и 19/22-22/22 (предпрогон
# 01.09), четвёртый раз подряд.
C60F2_DIR="${REPLAY_C60F2_DIR:-$(find_archive collect-6.0f2-aborted || true)}"
C60D_DIR="${REPLAY_C60D_DIR:-$(find_archive collect-6.0d || true)}"
echo "  архив 2.9.5: ${C295_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.6: ${C296_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.7: ${C297_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.8: ${C298_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9: ${C299_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9.F: ${C299F_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9.F.1: ${C299F1_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9.F.2: ${C299F2_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.4 (реплеи 15/18, 16/18): ${C294_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9.F.6 (реплеи 15/18, 16/18): ${C299F6_DIR:-НЕ НАЙДЕН}"
echo "  архив 2.9.9.F.7 (реплеи 17/21, 18/21): ${C299F7_DIR:-НЕ НАЙДЕН}"
echo "  архив 6.0 (реплей 19/25): ${C60_DIR:-НЕ НАЙДЕН}"
echo "  архив 6.0b (реплеи 19/25, 20/25, 21/25, 22/25): ${C60B_DIR:-НЕ НАЙДЕН}"
echo "  архив 6.0f2-aborted (реплеи 23/25, 24/25, 25/25): ${C60F2_DIR:-НЕ НАЙДЕН}"
echo "  архив 6.0d (реплеи 23/25, 25/25): ${C60D_DIR:-НЕ НАЙДЕН}"
if [ -z "$C295_DIR" ] || [ -z "$C296_DIR" ] || [ -z "$C297_DIR" ] || [ -z "$C298_DIR" ] || [ -z "$C299_DIR" ] || [ -z "$C299F_DIR" ] || [ -z "$C299F1_DIR" ] || [ -z "$C299F2_DIR" ] || [ -z "$C294_DIR" ] || [ -z "$C299F6_DIR" ] || [ -z "$C299F7_DIR" ] || [ -z "$C60_DIR" ] || [ -z "$C60B_DIR" ] || [ -z "$C60F2_DIR" ] || [ -z "$C60D_DIR" ]; then
    die "архивы collect-2.9.5…collect-2.9.9.F.2, collect-2.9.4, collect-2.9.9.F.6, collect-2.9.9.F.7, collect-6.0, collect-6.0b, collect-6.0f2-aborted, collect-6.0d найдены не все на стенде. Скопировать (например в /root/) либо задать REPLAY_C295_DIR…REPLAY_C299F2_DIR/REPLAY_C294_DIR/REPLAY_C299F6_DIR/REPLAY_C299F7_DIR/REPLAY_C60_DIR/REPLAY_C60B_DIR/REPLAY_C60F2_DIR/REPLAY_C60D_DIR. Пропуск реплея — это находка №85, повторённая пятнадцатый раз"
fi
# Реплеи 15/18 и 16/18 читают idle-час и attacks/ обоих новых архивов. Их
# отсутствие даёт не «реплей пропущен», а «реплей не проверил ничего» — то
# самое, чем предпрогон и встал; проверяется ЗДЕСЬ, до вызова, чтобы стоп
# назывался причиной, а не следствием.
[ -s "$C299F6_DIR/idle/alerts-end.json" ] \
    || die "реплей 15/18: $C299F6_DIR/idle/alerts-end.json отсутствует — сторона PASS крит. №68 (5.9.9.F.7b) непроверяема"
[ -s "$C294_DIR/idle/idle-2.9.4/alerts-end.json" ] \
    || die "реплей 15/18: $C294_DIR/idle/idle-2.9.4/alerts-end.json отсутствует — сторона FAIL крит. №68 (живой рецидив механизма) непроверяема"
for d in "$C294_DIR" "$C299F6_DIR"; do
    ls "$d"/attacks/baseline-state-*.json >/dev/null 2>&1 \
        || die "реплей 16/18: в $d/attacks нет baseline-state-*.json — офлайн-гейт по этому архиву не запустить, обе доли крит. 9 (5.9.9.F.7c) остались бы без входа"
done
# Реплеи 17/21 и 18/21 читают idle-час и attacks/ архива 2.9.9.F.7. Их
# отсутствие даёт не «реплей пропущен», а «реплей не проверил ничего»,
# поэтому проверяется ЗДЕСЬ, до вызова, тем же приёмом, что 15/18 и 16/18.
ls "$C299F7_DIR"/attacks/baseline-state-*.json >/dev/null 2>&1 \
    || die "реплеи 17/21 и 18/21: в $C299F7_DIR/attacks нет baseline-state-*.json — офлайн-гейт по архиву не запустить, ни строка реестра fwupd (5.9.9.F.8a), ни сторона SKIP крит. 21 (5.9.9.F.8b) не получат входа"
for f in idle/metrics-start.txt idle/metrics-end.txt idle/alerts-start.json idle/alerts-end.json; do
    [ -s "$C299F7_DIR/$f" ] \
        || die "реплей 17/21: $C299F7_DIR/$f отсутствует — idle-час с таймером fwupd-refresh не с чем сверять, и четыре строки реестра 5.9.9.F.8a остались бы правкой, сделанной руками и никем не воспроизводимой"
done
# Реплеи 9-12 читают не только attacks/, но и журнал с меткой старта агента
# рядом с архивом. Их отсутствие даёт не «реплей пропущен», а «реплей не
# проверил ничего», поэтому проверяется здесь, до вызова.
for f in journal-agent-2.9.9.F.1.log agent-start-2.9.9.F.1.txt; do
    [ -s "$C299F1_DIR/$f" ] \
        || die "реплеи 9/12 и 11/12: $C299F1_DIR/$f отсутствует — окно журнала крит. 17 и строка «no reachable nr» крит. 5.9.4h непроверяемы ни на чём другом"
done
for d in "$C299F_DIR" "$C299F1_DIR"; do
    for f in idle/metrics-start.txt idle/metrics-end.txt idle/alerts-start.json idle/alerts-end.json; do
        [ -s "$d/$f" ] \
            || die "реплей 10/12: $d/$f отсутствует — состав idle-часа не с чем сверять, реестр idle-actors.txt непроверяем на этом окне суток"
    done
done
# Реплеи 13/14 и 14/14 читают idle-час и журнал архива 2.9.9.F.2: без них
# 3d проверять не на чем (вход фазы idle — пакет systemd 11:57:39), а 3e
# не на чем проверять SKIP=0 (три SKIP есть только у этого архива).
for f in idle/metrics-start.txt idle/metrics-end.txt idle/alerts-start.json idle/alerts-end.json; do
    [ -s "$C299F2_DIR/$f" ] \
        || die "реплеи 13/14 и 14/14: $C299F2_DIR/$f отсутствует — пакет systemd 11:57:39 (вход фазы idle, №134) и состав idle-часа непроверяемы"
done
for f in journal-agent-2.9.9.F.2.log agent-start-2.9.9.F.2.txt; do
    [ -s "$C299F2_DIR/$f" ] \
        || die "реплей 14/14: $C299F2_DIR/$f отсутствует — SKIP=0 на архиве недостижим по построению (крит. 17 и крит. 5.9.4h останутся без входа), и вердикт 3e был бы вынесен по чужой причине"
done
# Реплеи 19/25..22/25 читают у архивов 6.0/6.0b не attacks/ вообще, а
# конкретные файлы: лог пайплайна (6.0.5), пару idle-метрик и gate-6.0.txt
# (6.0.1), attacks/baseline-state-*.json (5.9.7e и 6.0.10). Отсутствие любого
# даёт не «реплей пропущен», а «реплей не проверил ничего» — проверяется
# ЗДЕСЬ, до вызова, тем же приёмом, что 15/25..18/25.
[ -s "$C60_DIR/run-6.0-pipeline.log" ] \
    || die "реплей 19/25: $C60_DIR/run-6.0-pipeline.log отсутствует — сторона «НЕ ДОСТИГНУТО» решающего правила 6.0.5 (6.0.3 провален, №187) непроверяема"
[ -s "$C60B_DIR/run-6.0-pipeline.log" ] \
    || die "реплей 19/25: $C60B_DIR/run-6.0-pipeline.log отсутствует — сторона «ДОСТИГНУТО» решающего правила 6.0.5 непроверяема, и первый исход не доказывал бы ничего"
for f in idle/metrics-start.txt idle/metrics-end.txt gate-6.0.txt; do
    [ -s "$C60B_DIR/$f" ] \
        || die "реплей 20/25: $C60B_DIR/$f отсутствует — величина 6.0.1 (объём прямой дельтой двух метрик, №199) не с чем сверять"
done
[ -s "$C299F7_DIR/gate-2.9.9.F.7.txt" ] \
    || die "реплей 20/25: $C299F7_DIR/gate-2.9.9.F.7.txt отсутствует — сторона «НЕ ДОСТИГНУТО 577/ч» величины 6.0.1 непроверяема"
ls "$C60B_DIR"/attacks/baseline-state-*.json >/dev/null 2>&1 \
    || die "реплеи 21/25 и 22/25: в $C60B_DIR/attacks нет baseline-state-*.json — офлайн-гейт по архиву не запустить, ни ветка drift-suppression (5.9.7e/№194), ни 6.0.10 (контаминация idle-часа логином, №202) не получат входа"
for f in idle/metrics-start.txt idle/metrics-end.txt idle/alerts-start.json idle/alerts-end.json; do
    [ -s "$C60B_DIR/$f" ] \
        || die "реплей 22/25: $C60B_DIR/$f отсутствует — обе стороны 6.0.10 (чистый и контаминированный idle-час) остались бы без входа"
done
# Реплеи 23/25..25/25 (6.0j/п.7) читают у архивов 6.0f2-aborted и 6.0d свои
# файлы: снимки прогона в attacks/attack-results (у 6.0f2 они лежат ИМЕННО
# там, не в attacks/ — у аборта каталог не переименовывался), gate-6.0.txt
# (маркер таблицы 5.9.9.F.6b для 6.0.1 и источник TIMESTAMP для гигиены),
# пару idle-метрик (пол 6.0.1) и report-6.0.txt (вторая половина гигиены).
# Отсутствие любого даёт не «реплей пропущен», а «реплей не проверил ничего».
ls "$C60F2_DIR"/attacks/attack-results/baseline-state-*.json >/dev/null 2>&1 \
    || die "реплей 23/25: в $C60F2_DIR/attacks/attack-results нет baseline-state-*.json — офлайн-гейт по архиву аборта не запустить, и сторона «прогон = дате заведения» механизма new-rules.txt (оба FAIL замера №6.0f2) осталась бы без входа"
ls "$C60D_DIR"/attacks/baseline-state-*.json >/dev/null 2>&1 \
    || die "реплей 23/25: в $C60D_DIR/attacks нет baseline-state-*.json — сторона «архив старше даты заведения» непроверяема, и первый исход не доказывал бы ничего (вычитание, работающее всегда, ослепляет замер своей волны)"
for f in idle/metrics-start.txt idle/metrics-end.txt gate-6.0.txt report-6.0.txt; do
    [ -s "$C60F2_DIR/$f" ] \
        || die "реплеи 24/25 и 25/25: $C60F2_DIR/$f отсутствует — ни пол величины 6.0.1 (память drift-volume-criterion-needs-a-floor), ни отсечка по времени снимка (№212) не получат входа"
done
for f in gate-6.0.txt report-6.0.txt; do
    [ -s "$C60D_DIR/$f" ] \
        || die "реплей 25/25: $C60D_DIR/$f отсутствует — сторона PASS гигиены коллекта и подложенный чужой TIMESTAMP проверяются на этом архиве и больше ни на каком"
done
bash $SETUP/attacks/replay-gate.sh "$C295_DIR" "$C296_DIR" "$C297_DIR" "$C298_DIR" "$C299_DIR" "$C299F_DIR" "$C299F1_DIR" "$C299F2_DIR" "$C294_DIR" "$C299F6_DIR" "$C299F7_DIR" "$C60_DIR" "$C60B_DIR" "$C60F2_DIR" "$C60D_DIR" 2>&1 | tee /root/replay-6.0.txt
replay_rc=${PIPESTATUS[0]}
echo "  replay-gate вернул $replay_rc"
[ "$replay_rc" -eq 4 ] && die "replay-gate: неподходящий bash (находка №88) — цепочка зовёт старый интерпретатор"
[ "$replay_rc" -eq 0 ] \
    || die "REPLAY-GATE красный (код $replay_rc) — известные ответы на архивах не воспроизводятся. Риск №1 постановки материализовался: правки гейта 5.9.9.F.2a-2f меняют вердикт на уже снятых данных"

# --- реплеи 1-8: унаследованные, проверяются теми же строками -------------
grep -q '88\.6/мин' /root/replay-6.0.txt \
    || die "реплей 4/12 не напечатал 88.6/мин — крит. 9 на collect-2.9.7 не воспроизвёл известный ответ (5.9.8e, №90)"
grep -q 'повторный вызов за тот же замер молчит' /root/replay-6.0.txt \
    || die "реплей 5/12: повторный вызов гейта за тот же замер не промолчал — самонаведение №99 не починено (5.9.9a)"
grep -q 'умеет падать, а не только молчать (5.9.9a)' /root/replay-6.0.txt \
    || die "реплей 5/12: с подменённым TIMESTAMP WARN «база брошена» не напечатан — механизм 5.9.6f ослеплён правкой 5.9.9a"
grep -q 'выросло за idle-час' /root/replay-6.0.txt \
    || die "реплей 6/12: вторая ветка спасения фонового правила («выросло за idle-час») не напечатана (5.9.9.Fe)"
grep -q 'напечатаны разными формулировками' /root/replay-6.0.txt \
    || die "реплей 6/12: вторая и третья ветки спасения не различены на одном прогоне — ветка idle_prewindow_list не проверена (5.9.9.Fe, №111)"
# 5.9.9.F.2f (№126): текст реплея 7 изменён волной — к случаю добавлено само
# смещение в миллисекундах. Проверяется вместе со случаем, одной строкой:
# «случай 1 напечатан, а смещение потеряно» — это неисполнившийся 2f.
grep -q 'случай 1 (алерт старше регистрации корня), смещение -26мс напечатано' /root/replay-6.0.txt \
    || die "реплей 7/12: крит. 16 не вынес PASS со случаем 1 И смещением -26мс — либо классификация не отработала (проверить iso_to_epoch), либо 5.9.9.F.2f не печатает смещение (находка №126)"
grep -q 'критерий 16 умеет падать, а не только пропускать' /root/replay-6.0.txt \
    || die "реплей 7/12: с алертом за confirm_epoch крит. 16 НЕ упал — правка 5.9.9.F.1a ослепила критерий, что хуже находки №116 (тихо, а не шумно)"
grep -q 'ноль 5.9.9.F.1c объясняется печатью, а не допущением' /root/replay-6.0.txt \
    || die "реплей 8/12: нулевой web_sql_injection_files не отнесён реестром — приёмка 5.9.9.F.1c осталась бы допущением, а не проверкой"
grep -q 'ветка реестра различает объяснённый ноль и регресс детекта' /root/replay-6.0.txt \
    || die "реплей 8/12: крит. 6 не упал на правиле вне реестров — значит первый исход реплея 8 не доказывает ничего"

# --- реплеи 9-12: ВОЛНА 5.9.9.F.2, оба исхода у каждого -------------------
# 5.9.9.F.2c (№128): ветка 5.9.9.Fc («окно журнала не задано») до этой волны
# не исполнялась на пайплайне ни разу — её поломка была бы невидима.
grep -q 'без AGENT_START_FILE крит. 17 = SKIP «окно журнала не задано», вердикта нет' /root/replay-6.0.txt \
    || die "реплей 9/12: без AGENT_START_FILE крит. 17 вынес вердикт вместо SKIP — вернулась подстановка --boot, и предохранитель судился бы по чужим прогонам всего аптайма хоста (5.9.9.Fc, №110)"
grep -q 'оба исхода 5.9.9.Fc воспроизведены на одном архиве' /root/replay-6.0.txt \
    || die "реплей 9/12: с заданным AGENT_START_FILE крит. 17 не дал PASS — первый исход тогда доказывает только то, что критерий никогда ничего не выносит (5.9.9.F.2c, №128)"
# 5.9.9.F.2d (№118): три исхода, и третий обязателен — без него два PASS
# доказывали бы только то, что критерий не падает никогда.
[ "$(grep -c 'состав idle-часа целиком покрыт idle-actors.txt, новых акторов 0' /root/replay-6.0.txt)" -ge 2 ] \
    || die "реплей 10/12: idle-actors.txt покрыл меньше двух реальных окон суток — реестр подогнан под одно окно, и на замере даст FAIL реестром, а не находкой (5.9.9.F.2d, №118)"
grep -q 'вне idle-actors.txt — крит. FAIL и назван поимённо' /root/replay-6.0.txt \
    || die "реплей 10/12: синтетический актор вне реестра НЕ уронил критерий — сверка с idle-actors.txt зелёная на любом составе, то есть находка №118 не закрыта, а замаскирована"
# 5.9.9.F.2e (№122): оба исхода — деградация без journalctl и 11 правил с ним.
grep -q 'без journalctl крит. 5.9.4h деградирует к старому «0» текстом, не падает' /root/replay-6.0.txt \
    || die "реплей 11/12: без источника журнала крит. 5.9.4h не деградировал корректно — чтение журнала стало обязательным, и гейт упадёт там, где раньше честно молчал (5.9.9.F.2e)"
grep -q 'называет 11 правил категорией (а), «немых правил: 0» не печатается' /root/replay-6.0.txt \
    || die "реплей 11/12: с журналом крит. 5.9.4h не назвал 11 правил без достижимого nr — величина, которую агент печатает сам, снова никем не читается (находка №122)"
# 5.9.9.F.2a (№123/№124): замкнутое тождество обязано и сходиться, и падать.
grep -q 'считает замкнутым тождеством с симметричным ±1500 и даёт PASS на исправном прогоне' /root/replay-6.0.txt \
    || die "реплей 12/12: крит. 22 не пошёл замкнутым тождеством — либо formula=closed не применяется, либо выбран не тот маркер ringbuf-overflow-*.txt (ревизия волны, Р4)"
grep -q 'замкнутое тождество умеет падать' /root/replay-6.0.txt \
    || die "реплей 12/12: с заниженным на 5000 Δringbuf_full крит. 22 НЕ упал — допуск снова прячет потерю в кольце, находка №124 не закрыта"
# --- реплеи 13-14: ВОЛНА 5.9.9.F.3, оба исхода у каждого -------------------
# 5.9.9.F.3d (№134): фаза idle перестаёт поглощаться меткой «наведено шагом
# преflight'а». Вход — пакет systemd 11:57:39 архива 2.9.9.F.2: семь типов,
# помеченных там преflight'ом, обязаны получить метку idle. Отрицательный
# исход столь же обязателен: если ни один тип не остался induced, значит
# правка не переупорядочила ветки, а выключила четвёртую фазу целиком —
# это не починка №134, а откат 5.9.9d/№100.
grep -q 'фаза idle не поглощается меткой преflight' /root/replay-6.0.txt \
    || die "реплей 13/14: на collect-2.9.9.F.2 семь типов пакета systemd не получили метку idle — ветка in_induced по-прежнему поглощает idle целиком (находка №134), и idle-FP уйдут в detection-baseline.txt как артефакты преflight-шага"
grep -q 'четвёртая фаза сохранена' /root/replay-6.0.txt \
    || die "реплей 13/14: после правки НИ ОДИН тип не остался «наведено преflight'ом» — фаза 4 выключена целиком, а не переупорядочена. Это откат 5.9.9d (№100), а не починка №134: типы, наведённые контролями DNS вне окон, снова уйдут в «не определено»"
# 5.9.9.F.3e (№135/№136/№137): SKIP=0 на архиве БЕЗ правки самих критериев.
# Второй исход обязателен по той же причине, что у 12/12: механизм, который
# печатает 0 всегда, вернул бы 0 и здесь.
# Ревизия волны (2026-08-26): проверяется ИМЕННО ТРОЙКА пунктов, а не
# «SKIP=0» целиком. Офлайн-реплей идёт без агента и без attack-manifest.json,
# и его собственные SKIP'и (пустой токен, темп непроверяем, recall
# непроверяем) к волне отношения не имеют и сняты быть не могут по
# построению — критерий, названный «SKIP=0», а проверяющий тройку, был бы
# критерием, судящим не то, что называет. Величина приёмки №1 (SKIP=0/FAIL=0)
# по-прежнему имеет входом только полный гейт замера, шаг [13/14].
grep -q 'три неисполнившиеся ветки архива (5.9.9.Fc/5.9.9.F.1d/5.9.9.F.2b) исполняются без правки самих критериев' /root/replay-6.0.txt \
    || die "реплей 14/14: на архиве 2.9.9.F.2 хотя бы один из трёх пунктов (5.9.9.Fc/5.9.9.F.1d/5.9.9.F.2b) снова числится неисполнившимся — дефекты бухгалтерии №135/№136/№137 не сняты, и единственный SKIP замера №2.9.9.F.2 воспроизведётся на этом"
grep -q 'счётчик неисполнившихся веток умеет расти' /root/replay-6.0.txt \
    || die "реплей 14/14: с изъятой строкой индекса счётчик неисполнившихся веток НЕ вырос — 5.9.9e печатает 0 при любом составе, то есть SKIP=0 на этом замере не значит ничего (класс №124)"
# --- реплеи 15-16: ВОЛНА 5.9.9.F.7, обе стороны у каждого ----------------
grep -qF 'collect-2.9.9.F.6: крит. №68 = PASS' /root/replay-6.0.txt \
    || die "реплей 15/18: сторона PASS крит. №68 (collect-2.9.9.F.6, фон drift_exec_from_system_bin/sshd не считается за сигнатуру) не напечатана — сужение 5.9.9.F.7b либо не применилось, либо архив прочитан не тот"
grep -qF 'collect-2.9.4: крит. №68 = FAIL' /root/replay-6.0.txt \
    || die "реплей 15/18: сторона FAIL крит. №68 (collect-2.9.4, живой рецидив механизма) не напечатана — критерий сужен до немоты, и №68 больше не падает ни на чём (класс №124)"
grep -qF 'оба архива: крит. 9 печатает и долю по инцидентам, и долю по алертам' /root/replay-6.0.txt \
    || die "реплей 16/18: крит. 9 не напечатал обе доли (по инцидентам и по алертам) с честным SKIP — величина, ради которой волна 7 отказалась назначать порог, снова выносится вслепую"

# --- реплеи 17-18: ВОЛНА 5.9.9.F.8, обе стороны у каждого ----------------
# 5.9.9.F.8a (№179): строка реестра обязана быть проверена ОБЕИМИ сторонами
# на collect-2.9.9.F.7. Без отрицательного исхода первый доказывал бы только
# то, что крит. idle-actors.txt на этом архиве не падает ни при каком составе.
grep -q 'idle-час с fwupd целиком покрыт idle-actors.txt, новых акторов 0' /root/replay-6.0.txt \
    || die "реплей 17/21: реестр НЕ покрыл idle-час архива 2.9.9.F.7 — четыре строки 5.9.9.F.8a не работают, и idle-час этого замера повторит FAIL №2.9.9.F.7 вслепую"
grep -q 'без четырёх строк реестра крит. FAIL и fwupd/fwupdmgr названы поимённо' /root/replay-6.0.txt \
    || die "реплей 17/21: с вырезанными строками реестра критерий НЕ упал — сверка с idle-actors.txt зелёная на любом составе, то есть исход 1 не доказывает ничего (класс №124, ровно как №118)"
# 5.9.9.F.8b (№180): SKIP документируется в приёмке ТОЛЬКО после того, как
# ветка классификации показана исполняющейся на архиве с флапом.
grep -q 'ветка классификации исполняется и даёт PASS' /root/replay-6.0.txt \
    || die "реплей 18/21: на collect-2.9.9.F.2 (флап есть) ветка классификации крит. 21 не дала PASS — документировать SKIP в приёмке НЕЛЬЗЯ, иначе документируется «ветка мертва», а не «флап не наблюдался» (№180)"
grep -q 'на collect-2.9.9.F.7 (флапа нет) — SKIP' /root/replay-6.0.txt \
    || die "реплей 18/21: на collect-2.9.9.F.7 крит. 21 не дал SKIP при stale_transitions=0 — вычет по закрытому списку приёмки (acc_skip_doc21) описывает не тот исход, который гейт печатает на самом деле"
echo "реплей 18/21 пройден в $(date -u +%H:%M:%S) UTC"

echo "=== [2/14] ЖЁСТКИЙ СТОП №2: сверка criteria-index.txt (5.9.7h/5.9.8h) ==="
c296_ts=$(ls "$C296_DIR"/attacks/baseline-state-*.json 2>/dev/null | head -1 | sed 's/.*baseline-state-\(.*\)\.json/\1/')
[ -n "$c296_ts" ] || die "не удалось определить TIMESTAMP архива 2.9.6 для сверки criteria-index.txt"
# Побочный эффект run-gate.sh (detection-baseline-diff-state.txt, 5.9.6f)
# снимается здесь же: прогон на архиве не является «прошлым замером», иначе
# шаг [13/14] сравнит настоящий замер с сигнатурой архива и напечатает WARN
# «база брошена» третий замер подряд (5.9.8h).
DIFF_STATE="$SETUP/attacks/detection-baseline-diff-state.txt"
DIFF_BAK=""
if [ -f "$DIFF_STATE" ]; then DIFF_BAK=$(mktemp); cp "$DIFF_STATE" "$DIFF_BAK"; fi
ci_out=$(EBPF_GUARD_API="http://127.0.0.1:1" EBPF_GUARD_TOKEN="" \
    bash $SETUP/attacks/run-gate.sh "$C296_DIR/attacks" "$c296_ts" 2>&1 | head -8)
if [ -n "$DIFF_BAK" ]; then cp "$DIFF_BAK" "$DIFF_STATE"; rm -f "$DIFF_BAK"; else rm -f "$DIFF_STATE"; fi
echo "$ci_out" | sed 's/^/  /'
echo "$ci_out" | grep -q 'непокрытых пунктов постановки: 0' \
    || die "criteria-index.txt: у пункта постановки нет машинной печати в гейте (5.9.7h) — это находка №83, повторённая"
echo "сверка пройдена в $(date -u +%H:%M:%S) UTC"

echo "=== [3/14] make generate && make build (жёстко: 5.9.8a правит bpf/dns.bpf.c) ==="
cd /opt/ebpf-guard
make generate || die "make generate упал"
echo "--- generate: карты волны 5.9.6 живы в сгенерированных биндингах ---"
gen_maps_missing=0
for c in syscall network fileaccess privesc; do
    gf=$(ls internal/bpf/${c}_*_bpfe*.go 2>/dev/null | head -1)
    if [ -z "$gf" ]; then
        echo "  $c: сгенерированных биндингов нет — bpf2go не выдал объект"
        gen_maps_missing=1
        continue
    fi
    n=$(grep -c 'RingbufFullCounters\|EventsEmittedCounters' "$gf")
    echo "  $c ($gf): полей карт = $n"
    [ "$n" -eq 0 ] && gen_maps_missing=1
done
[ "$gen_maps_missing" -eq 0 ] || echo "ВНИМАНИЕ: карты 5.9.6 отсутствуют хотя бы в одном объекте — SMOKE-гейт [6/14] обязан это подтвердить красным"
# 5.9.8a: DNS-объект обязан быть ПЕРЕСОБРАН этим generate, а не взят с полки.
# Проверяется по факту существования свежего .o и биндинга с DnsSocketMap.
dns_gen=$(ls internal/bpf/dns_*_bpfe*.go 2>/dev/null | head -1)
[ -n "$dns_gen" ] || die "5.9.8a: сгенерированных биндингов DNS нет — bpf2go не выдал объект, правка ключа не попала бы в ядро"
grep -q 'DnsSocketMap' "$dns_gen" || die "5.9.8a: в $dns_gen нет DnsSocketMap — биндинг не соответствует правленому bpf/dns.bpf.c"
ls -l internal/bpf/dns_*_bpfe*.o 2>/dev/null | sed 's/^/  DNS-объект: /'
git status --porcelain internal/bpf/ | sed 's/^/  generate изменил: /'
make build || die "make build упал"
./build/ebpf-guard version 2>&1 | sed 's/^/  бинарь (после пересборки): /' || true
ls -l build/ebpf-guard | sed 's/^/  /'
echo "сборка завершена в $(date -u +%H:%M:%S) UTC"

echo "=== [4/14] риск №3 (5.9.4): отдельный короткий прогон P0-3 ДО замера ==="
cd $SETUP
OUT_DIR=$P0_OUT DURATION=120 INTERVAL=60 NO_RESTART=0 bash ./idle-run.sh
echo "P0-3 прогон завершён в $(date -u +%H:%M:%S) UTC"
grep -h "before:\|after:\|P0-3" $P0_OUT/idle-run.log

echo "=== [5/14] очистка стора + рестарт агента (уже с новым бинарём) ==="
systemctl stop ebpf-guard-test.service
rm -f /var/lib/ebpf-guard/test-events.db /var/lib/ebpf-guard/test-events.db-shm /var/lib/ebpf-guard/test-events.db-wal
# 5.9.9.F.4c (№147): раньше здесь стояло `echo 0 > observer-root-pid` — это и
# было дефектом: с этой строки и до idle-run.sh на шаге [11/14] дерево
# пайплайна оставалось НЕисключённым, хотя SMOKE/DNS/счётность/кольцо/
# CPU-давление/[9.6/14] — всё внутри аптайма, который меряет гейт. Файл на
# диске переживает рестарт сам, менять его не нужно; новый бинарь его
# переопрашивает при старте — шаг только переподтверждает подхват.
systemctl start ebpf-guard-test.service
echo "рестарт в $(date -u +%H:%M:%S) UTC"
register_pipeline_observer_root
date -u +"%Y-%m-%d %H:%M:%S" > /root/agent-start-6.0.txt
# Реестр исходов drift-контролей (6.0.3/6.0.6), из которого переопределённое
# решающее правило 6.0.5 читает вердикт (волна 6.0d, находка №196). Обнуляется
# ЗДЕСЬ, вместе с T0 агента: файл дописывается через >> и переживает прогон, а
# 6.0.5 требует контроль, исполненный ВНУТРИ окна замера. Без обнуления
# «6.0.3 PASS» прошлого прогона делал бы 6.0.5 зелёным на следующем — ровно та
# форма ложно-зелёного, которую волна 6.0d чинит в трёх других местах.
: > /root/drift-controls-6.0.txt
echo "# прогон от $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt
systemctl show ebpf-guard-test.service -p ExecMainStartTimestamp | sed 's/^/  /'

# 5.9.9.F.4c, сужено 5.9.9.F.5h/№151 (вариант 1 постановки: «исключение
# сужается до поллинга и не покрывает генераторы контролей»).
#
# До этой правки (предпрогон №2.9.9.F.6, находка №151, `585768a`) исключение
# СНИМАЛОСЬ ЦЕЛИКОМ на всё время [6/14]...[9.5/14] одним вызовом здесь —
# генераторы всех наведённых контролей ПОТОМКИ этого самого процесса, а
# фильтр 5.9.2g режет дерево В ЯДРЕ, до кольца, поэтому взведённое на весь
# участок исключение ослепляло бы канарейку счётности [8/14] (0 из N=10000
# вместо 10001), переполнение кольца [9/14], CPU-давление [9.7/14], три пары
# продуктовых контролей [9.6/14] и cred_proc_maps [9.5/14] разом — находка
# №57 на всех жёстких стопах волны сразу. Платой было то, что ЛЮБОЙ curl/jq
# этого пайплайна (fp_count/fp_alerts/cred_count/smoke_metrics и т.д.) внутри
# всего окна тоже оставался видим — 131 алерт (27.6% окна преflight'а на
# предпрогоне), 97.7% из которых пары (comm, rule_id) = (curl, ...)/(jq, ...).
#
# 5.9.9.F.5h возвращает регистрацию к состоянию ДО release (см. строку 1044
# выше — `register_pipeline_observer_root` уже вызван) и держит её взведённой
# по умолчанию через весь участок [6/14]...[9.5/14]. Единственные окна, где
# исключение снимается, — те, что каждый жёсткий стоп бракетирует САМ вокруг
# СВОЕГО генератора событий (`release_pipeline_observer_root` непосредственно
# перед действием, которое обязано быть видно ядру, `register_pipeline_observer_root`
# сразу после — до последующих `sleep`/fp_count/curl-проверок). Между такими
# окнами (ожидания, снятие «до»/«после» через API, cd/echo) исключение
# остаётся взведённым, и curl/jq пайплайна туда не попадают. Реализовано в:
# SMOKE-канарейка [6/14], оба контроля DNS [7/14] (внутри цикла попыток),
# контроль счётности [8/14], переполнение кольца [9/14], CPU-давление
# [9.7/14], все три пары [9.6/14] (обе половины каждой), cred_proc_maps и обе
# его негативные половины [9.5/14].
#
# Открытая граница (не закрыта этой правкой, названа явно): поллер агента,
# читающий observer-root-pid (cmd/ebpf-guard/main.go), тикает раз в 2с, и
# register/release здесь подтверждаются через /debug/state тем же циклом
# (до 7 попыток по 2с) — то есть у каждого бракета есть задержка порядка
# секунд на снятие и секунд на возврат. Toggle НИЖЕ этой гранулярности
# (вокруг отдельного curl-вызова) технически недостижим этим механизмом —
# поэтому бракеты стоят вокруг ДЕЙСТВИЯ генератора целиком (mkdir/unshare/
# chmod+exec/systemctl start/python3-канарейка/вызовы run-all-attacks.sh),
# а не вокруг каждого fp_count. Настоящее «поллер, а не пайплайн целиком» на
# уровне отдельного HTTP-вызова потребовало бы comm-фильтра на стороне BPF
# (bpf/common.h, observer_should_drop) — не сделано этой сессией (нет
# стенда/clang для проверки `make generate`, см. память bpf-gen-files-are-stubs).

echo "=== [6/14] SMOKE-гейт: коллекторы грузятся, поток не пуст, серии волны на месте ==="
SMOKE_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
SMOKE_API="http://${VPS_IP:-localhost}:19090"
smoke_fail=0

sleep 20
echo "--- smoke: журнал загрузки BPF ---"
smoke_journal=$(journalctl -u ebpf-guard-test.service --no-pager -n 400 2>/dev/null || true)
echo "$smoke_journal" | grep -iE 'verifier|failed to load|load program|permission denied|collector .* (started|failed)|watchdog started' | tail -20 | sed 's/^/  /'
if echo "$smoke_journal" | grep -qiE 'verifier|failed to load'; then
    echo "SMOKE FAIL: в журнале есть ошибка загрузки/верификатора"
    smoke_fail=1
fi

smoke_health=$(curl -s --max-time 10 -H "Authorization: Bearer $SMOKE_TOKEN" "$SMOKE_API/health" 2>/dev/null)
echo "  /health: $smoke_health"
echo "$smoke_health" | grep -q '"status"' || { echo "SMOKE FAIL: агент не отвечает на /health"; smoke_fail=1; }

smoke_metrics() { curl -s --max-time 10 -H "Authorization: Bearer $SMOKE_TOKEN" "$SMOKE_API/metrics" 2>/dev/null; }
# 5.9.9f (№103): ENVIRON, не -v — то же обоснование, что у run-gate.sh
# sum_metric_delta()/run-all-attacks.sh sum_metric(): -v запускает
# unescaped-sequence разбор строки, и \{ в паттерне печатал предупреждение
# "escape sequence `\{' treated as plain `{'" на stderr при каждом вызове.
# Эта копия smoke_sum() кочевала из run-2.9.6-pipeline.sh в 2.9.7 и в 2.9.8
# без правки — третья непочиненная копия одного и того же дефекта.
smoke_sum() { P="$1" awk -F'} ' '$0 ~ ENVIRON["P"] {s+=$2} END{printf "%.0f", s+0}'; }

smoke_before=$(smoke_metrics)
# 5.9.9.F.5h: канарейка сама эксполнена процессом-потомком пайплайна и
# считается по events_emitted_kernel_total — этот счётчик инкрементируется
# ПОСЛЕ observer_should_drop() (bpf/syscall.bpf.c), поэтому под исключением
# канарейка дала бы Δ=0 и ложный SMOKE FAIL. Бракет — только вокруг самого
# генератора, а до/после (smoke_metrics) остаются под исключением.
release_pipeline_observer_root
python3 -c "
import os
p='/tmp/ebpf-guard-smoke-canary'
open(p,'w').close()
for _ in range(20000):
    fd=os.open(p, os.O_RDONLY); os.close(fd)
" || echo "  smoke: генератор не отработал, полагаемся на фоновую активность"
sleep 8
register_pipeline_observer_root
smoke_after=$(smoke_metrics)
rm -f /tmp/ebpf-guard-smoke-canary

for c in syscall network fileaccess; do
    em_a=$(echo "$smoke_before" | smoke_sum "ebpf_guard_events_emitted_kernel_total\{collector=\"$c\"\}")
    em_b=$(echo "$smoke_after"  | smoke_sum "ebpf_guard_events_emitted_kernel_total\{collector=\"$c\"\}")
    rf_present=$(echo "$smoke_after" | grep -c "reason=\"ringbuf_full\".*collector=\"$c\"\|collector=\"$c\".*reason=\"ringbuf_full\"" || true)
    echo "  $c: emitted_kernel $em_a -> $em_b (Δ$((em_b - em_a))), серия ringbuf_full присутствует: $rf_present"
    if [ "$rf_present" -eq 0 ]; then
        echo "SMOKE FAIL: $c — серия events_dropped_total{reason=\"ringbuf_full\"} отсутствует (5.9.6a не доехала до /metrics)"
        smoke_fail=1
    fi
done

fa_a=$(echo "$smoke_before" | smoke_sum 'ebpf_guard_events_emitted_kernel_total\{collector="fileaccess"\}')
fa_b=$(echo "$smoke_after"  | smoke_sum 'ebpf_guard_events_emitted_kernel_total\{collector="fileaccess"\}')
ev_a=$(echo "$smoke_before" | smoke_sum '^ebpf_guard_events_total\{.*type="file"')
ev_b=$(echo "$smoke_after"  | smoke_sum '^ebpf_guard_events_total\{.*type="file"')
echo "  fileaccess: Δemitted_kernel=$((fa_b - fa_a)), Δevents_total{file}=$((ev_b - ev_a))"
[ "$((fa_b - fa_a))" -gt 0 ] || { echo "SMOKE FAIL: emitted_kernel{fileaccess} не вырос под заведомой нагрузкой"; smoke_fail=1; }
[ "$((ev_b - ev_a))" -gt 0 ] || { echo "SMOKE FAIL: events_total{type=file} не вырос — события не доходят до userspace"; smoke_fail=1; }

hb=$(echo "$smoke_after" | grep -c '^ebpf_guard_heartbeat_timestamp_seconds' || true)
echo "  watchdog: серий ebpf_guard_heartbeat_timestamp_seconds = $hb"
if [ "$hb" -eq 0 ]; then
    echo "SMOKE FAIL: heartbeat отсутствует — watchdog.Start не выполнен, bpf_lost_events_total останется нулём (5.9.7b недоказуем)"
    smoke_fail=1
fi

# 5.9.8b: канареечная серия материализована нулём в init() — её отсутствие
# означает старый бинарь, и крит. 20 молча свалился бы в путь с вычетом фона
# (тот же провал, что 5.9.8b и чинит), напечатав SKIP вместо вердикта.
canary_series=$(echo "$smoke_after" | grep -c '^ebpf_guard_counting_canary_total' || true)
echo "  5.9.8b: серий ebpf_guard_counting_canary_total = $canary_series (ожидается 2: events, dropped)"
if [ "$canary_series" -lt 2 ]; then
    echo "SMOKE FAIL: канареечная серия отсутствует или неполна — бинарь старее 5.9.8b, критерий 20 будет считать по старому пути с вычетом фона"
    smoke_fail=1
fi
# Та же логика для нового reason DNS (5.9.8a): материализован нулём в
# RegisterMetrics, отсутствует только у старого бинаря.
bad_header_series=$(echo "$smoke_after" | grep -c 'ebpf_guard_dns_decode_errors_total{reason="bad_header"}' || true)
echo "  5.9.8a: серия dns_decode_errors_total{reason=\"bad_header\"} присутствует: $bad_header_series"
if [ "$bad_header_series" -eq 0 ]; then
    echo "SMOKE FAIL: reason=bad_header отсутствует — бинарь старее 5.9.8a, второй заслон DNS не в прогоне"
    smoke_fail=1
fi

if [ "$smoke_fail" -ne 0 ]; then
    die "SMOKE-гейт красный. Полтора часа на прогон, который не сможет отличить исправную систему от ослепшей, тратить нельзя"
fi
echo "SMOKE OK: коллекторы живы, watchdog запущен, серии волны 5.9.8 на месте. $(date -u +%H:%M:%S) UTC"

echo "--- 6.0.19: репетиция механики ШЕСТИ шагов-контролей ДО idle-часа (№209, п.3 волны 6.0j) ---"
# Зачем. SMOKE_ONLY=1 покрывает шаги [1/14]…[6/14]; шаги контролей
# 6.0c/6.0e/6.0g/6.0h/6.0k/6.0l стоят ПОСЛЕ окна атак и не репетируются
# ничем — поэтому любая их поломка обнаруживается ценой целого замера. Так
# умерли три замера подряд, и все три раза на механике, а не на детекторе:
# №176 и №208 — `command -v true` (builtin, `cp` падал), №209 — подмена
# argv[0] (коллектор обнулял proc.args, и шаг получал приборный ноль).
#
# Что этот блок доказывает и чего НЕ доказывает. Доказывает механику: пути
# существуют, файлы кладутся и исполняются (проверка по РЕЗУЛЬТАТУ, а не по
# коду возврата), событие доезжает до агента, proc.args в алерте непуст.
# НЕ доказывает ни одного продуктового вердикта: ни подавления базовой
# линией, ни новизны сигнатуры, ни числа алертов на exec. Контроль, прошедший
# репетицию, всё ещё может честно провалиться на своём месте — и это
# правильный исход, а не дефект репетиции.
#
# Провал = стоп ЗДЕСЬ, до idle-часа, то есть даром теряется минута, а не час.
# Блок стоит внутри [6/14] сознательно: SMOKE_ONLY=1 доходит до [6/14] и
# выходит на [9.5/14], значит репетиция проверяется вообще без траты часа —
# в этом её единственный смысл, и приёмка волны требует такого прогона
# ОТДЕЛЬНО, до полного замера.
_reh_fail=0
_reh_note() { echo "  репетиция $1: $2"; }
_reh_bad()  { echo "  РЕПЕТИЦИЯ FAIL ($1): $2"; _reh_fail=1; }

# 0/7. Все шесть шагов-контролей обязаны существовать в этом файле. Репетиция
# несуществующего шага — ложно-зелёная: она напечатала бы «механика цела» про
# то, чего нет. Список закрыт и совпадает с постановкой волны 6.0j.
for _reh_step in 6.0c 6.0e 6.0g 6.0h 6.0k 6.0l; do
    grep -q "^echo \"--- $_reh_step:" "$SETUP/run-6.0-pipeline.sh" \
        || _reh_bad "$_reh_step" "шага с меткой $_reh_step нет в run-6.0-pipeline.sh — репетировать нечего, а приёмка волны требует всех шести (6.0l заводится п.5 волны 6.0j вместе с критерием 6.0.18)"
done

_reh_hex() { head -c 4 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n'; }
_reh_true=""
for _reh_cand in /usr/bin/touch /bin/touch; do
    if [ -f "$_reh_cand" ] && [ -x "$_reh_cand" ]; then _reh_true="$_reh_cand"; break; fi
done
[ -n "$_reh_true" ] || _reh_bad "общая" "ни /usr/bin/touch, ни /bin/touch не оказались исполняемым обычным файлом — примитив с наблюдаемым результатом собрать не из чего (находка №176: builtin брать нельзя)"
_reh_alerts_args() { # $1=comm -> proc.args последнего алерта drift_exec_from_system_bin под этим comm
    curl -s --max-time 15 -H "Authorization: Bearer $SMOKE_TOKEN" "$SMOKE_API/api/v1/alerts" 2>/dev/null \
        | jq -r --arg c "$1" '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm==$c)] | if length == 0 then "" else (sort_by(.timestamp) | .[-1].details["proc.args"] // "") end' 2>/dev/null \
        || echo ""
}
# Общий примитив: положить исполняемый файл с именем, равным comm, в каталог
# под /usr/local/bin/ и позвать его НАПРЯМУЮ с аргументом-сентинелом.
# Возвращает 0, только если сентинел действительно создан.
_reh_exec_probe() { # $1=каталог $2=comm -> печатает путь сентинела
    local dir="$1" comm="$2" bin="$1/$2" sent="/tmp/reh-ran-$2"
    mkdir -p "$dir" 2>/dev/null || return 1
    cp "$_reh_true" "$bin" 2>/dev/null || return 1
    chmod +x "$bin" 2>/dev/null || return 1
    [ -x "$bin" ] || return 1
    rm -f "$sent"
    "$bin" "$sent" >/dev/null 2>&1 || true
    [ -e "$sent" ] || return 1
    echo "$sent"
}

if [ "$_reh_fail" -eq 0 ]; then
release_pipeline_observer_root

# 1/7 (6.0c) и 3/7 (6.0g) — один и тот же примитив в трёх каталогах: обычный
# exec реального файла, имя которого равно comm, из-под /usr/local/bin/.
# Каталоги репетиции свои (`-reh-` в имени), с боевыми путями контролей не
# пересекаются: пересечение подсунуло бы 6.0.12 уже виденную сигнатуру.
_reh_c_comm="rehc-$(_reh_hex)"
_reh_c_dir="/usr/local/bin/reh-c-$_reh_c_comm"
_reh_c_sent=$(_reh_exec_probe "$_reh_c_dir" "$_reh_c_comm") \
    && _reh_note "6.0c" "механика цела: $_reh_c_dir/$_reh_c_comm исполнен, сентинел $_reh_c_sent создан" \
    || _reh_bad  "6.0c" "не удалось положить и исполнить $_reh_c_dir/$_reh_c_comm с наблюдаемым результатом (noexec на /usr/local? нет прав? cp взял не файл?) — на своём месте этот шаг умрёт ПОСЛЕ idle-часа"

_reh_g_comm="rehg-$(_reh_hex)"
_reh_g_seed="/usr/local/bin/reh-g-seed-$_reh_g_comm"
_reh_g_novel="/usr/local/bin/reh-g-novel-$_reh_g_comm"
_reh_g_ok=1
_reh_exec_probe "$_reh_g_seed"  "$_reh_g_comm" >/dev/null || _reh_g_ok=0
_reh_exec_probe "$_reh_g_novel" "$_reh_g_comm" >/dev/null || _reh_g_ok=0
if [ "$_reh_g_ok" -eq 1 ]; then
    _reh_note "6.0g" "механика цела: две различные сигнатуры под одним comm=$_reh_g_comm ($_reh_g_seed и $_reh_g_novel) исполнены, оба сентинела созданы"
else
    _reh_bad "6.0g" "не удалось исполнить обе сигнатуры под одним comm — ровно на этом шаге умерли замеры №208 и №6.0f2"
fi

register_pipeline_observer_root
sleep 20

# 2/7. Событие доезжает и proc.args в алерте НЕПУСТ. Это и есть находка №209
# в измеримом виде: обнулённый коллектором args даёт контролю приборный ноль,
# неотличимый от подавления базовой линией. Проверяется по алерту любого из
# двух exec'ов выше (правило drift_exec_from_system_bin, отбор по comm).
# Продуктовый вердикт здесь не выносится: не проверяется ни число алертов, ни
# причина подавления, ни новизна сигнатуры.
_reh_args_c=$(_reh_alerts_args "$_reh_c_comm")
_reh_args_g=$(_reh_alerts_args "$_reh_g_comm")
echo "  репетиция proc.args: comm=$_reh_c_comm -> '${_reh_args_c:-<пусто>}', comm=$_reh_g_comm -> '${_reh_args_g:-<пусто>}'"
if [ -z "$_reh_args_c" ] && [ -z "$_reh_args_g" ]; then
    _reh_bad "proc.args" "ни один из двух exec'ов не дал алерта drift_exec_from_system_bin с непустым proc.args. Читать в порядке: поле не доехало до алерта (бинарь старее правки 6.0j, correlator: procArgsAlertDetails); коллектор обнулил args (находка №209/№210 — смотреть ebpf_guard_proc_args_dropped_total); событие вообще не дошло (дерево измерителя не снято, exec срезан ядром). В любом из трёх случаев все контроли класса proc.args ПОСЛЕ idle-часа получат нули, и замер будет потерян так же, как №6.0f2"
fi
echo "  репетиция счётчиков слепоты: $(curl -s --max-time 15 -H "Authorization: Bearer $SMOKE_TOKEN" "$SMOKE_API/metrics" 2>/dev/null | grep '^ebpf_guard_proc_args_dropped_total' | tr '\n' ' ')"

# 4/7 (6.0e). Примитив побега целиком: unshare(2) + mount(MS_REC|MS_PRIVATE)
# из-под собственного comm. Репетируется именно исполнимость — на боевом шаге
# отсутствие util-linux даёт die уже после idle-часа.
_reh_e_src=$(command -v unshare 2>/dev/null || true)
if [ -z "$_reh_e_src" ] || [ ! -x "$_reh_e_src" ]; then
    _reh_bad "6.0e" "unshare(1) (util-linux) не найден исполняемым файлом — критерий 6.0.6 нечем исполнить, и это выяснится после idle-часа"
else
    _reh_e_comm="rehe-$(_reh_hex)"
    _reh_e_dir="/usr/local/bin/reh-e-$_reh_e_comm"
    _reh_e_sent="/tmp/reh-ran-$_reh_e_comm"
    mkdir -p "$_reh_e_dir" 2>/dev/null && cp "$_reh_e_src" "$_reh_e_dir/$_reh_e_comm" 2>/dev/null && chmod +x "$_reh_e_dir/$_reh_e_comm" 2>/dev/null || true
    rm -f "$_reh_e_sent"
    release_pipeline_observer_root
    "$_reh_e_dir/$_reh_e_comm" --user --map-root-user --mount --propagation private -- "$_reh_true" "$_reh_e_sent" >/dev/null 2>&1 || true
    register_pipeline_observer_root
    [ -e "$_reh_e_sent" ] \
        && _reh_note "6.0e" "механика цела: unshare(CLONE_NEWUSER|CLONE_NEWNS)+mount из-под comm=$_reh_e_comm отработал, сентинел создан" \
        || _reh_bad  "6.0e" "вызов unshare из копии $_reh_e_dir/$_reh_e_comm не создал сентинел — примитив не исполняется на этом ядре/стенде (userns запрещён sysctl? noexec?), и 6.0.6 получит ложный ноль ПОСЛЕ idle-часа"
    rm -rf "$_reh_e_dir"; rm -f "$_reh_e_sent"
fi

# 5/7 (6.0h) и 7/7 (6.0l). Оба шага стоят на одних и тех же трёх примитивах:
# dumpe2fs -h по блочному устройству (6.0.13 и 6.0.18), dd count=0 на него же
# (6.0.14) и sysctl -w текущим значением (6.0.15). Репетируется исполнимость
# и наличие устройства; вердикты (есть/нет критикалов, warning от хостового
# правила) не трогаются.
_reh_dev=""
for _reh_devc in /dev/vda1 /dev/sda1; do
    [ -b "$_reh_devc" ] && { _reh_dev="$_reh_devc"; break; }
done
if [ -z "$_reh_dev" ]; then
    _reh_bad "6.0h/6.0l" "ни /dev/vda1, ни /dev/sda1 не блочное устройство — примитив 6.0.13/6.0.14/6.0.18 нечем исполнить"
else
    [ "$_reh_dev" = "/dev/vda1" ] || _reh_bad "6.0h/6.0l" "шаги зовут /dev/vda1 жёстко, а на этом стенде блочным устройством оказалось $_reh_dev — вызов упадёт после idle-часа"
    if command -v dumpe2fs >/dev/null 2>&1; then
        release_pipeline_observer_root
        dumpe2fs -h "$_reh_dev" >/dev/null 2>&1 && _reh_dumpe_rc=0 || _reh_dumpe_rc=$?
        dd if=/dev/zero of="$_reh_dev" bs=512 count=0 >/dev/null 2>&1 && _reh_dd_rc=0 || _reh_dd_rc=$?
        register_pipeline_observer_root
        [ "${_reh_dumpe_rc:-1}" -eq 0 ] \
            && _reh_note "6.0h/6.0l" "механика цела: dumpe2fs -h $_reh_dev отработал (rc=0), dd count=0 rc=${_reh_dd_rc:-?}" \
            || _reh_bad  "6.0h/6.0l" "dumpe2fs -h $_reh_dev вернул rc=${_reh_dumpe_rc:-?} — примитив 6.0.13/6.0.18 не исполняется (не ext-раздел? нет прав?)"
    else
        _reh_bad "6.0h/6.0l" "dumpe2fs(8) (e2fsprogs) не установлен — 6.0.13 и 6.0.18 нечем исполнить"
    fi
fi
_reh_pidmax=$(cat /proc/sys/kernel/pid_max 2>/dev/null || echo "")
if [ -n "$_reh_pidmax" ] && command -v sysctl >/dev/null 2>&1; then
    _reh_note "6.0h" "механика цела: /proc/sys/kernel/pid_max читается ($_reh_pidmax), sysctl(8) на месте — 6.0.15 исполним"
else
    _reh_bad "6.0h" "/proc/sys/kernel/pid_max не читается либо нет sysctl(8) — 6.0.15 объявлен постановкой НЕ ИСПОЛНИМЫМ ровно в этом случае, и узнать это после idle-часа значит потерять замер"
fi

# 6/7 (6.0k). Подмена argv[0] — предмет измерения 6.0.16, поэтому репетируется
# ТОЛЬКО механика: подменённый вызов состоялся и реальный образ отработал
# (сентинел создан). proc.args этого вызова здесь СОЗНАТЕЛЬНО не проверяется:
# именно он и есть измеряемая величина 6.0.16, и проверить её тут значило бы
# вынести продуктовый вердикт до замера.
_reh_k_hex=$(_reh_hex)
_reh_k_comm="rehk-$_reh_k_hex"
_reh_k_dir="/usr/local/bin/reh-k-$_reh_k_hex"
_reh_k_spoofdir="/usr/local/bin/reh-k-seed-$_reh_k_hex"
_reh_k_sent="/tmp/reh-ran-$_reh_k_comm"
mkdir -p "$_reh_k_dir" "$_reh_k_spoofdir" 2>/dev/null || true
cp "$_reh_true" "$_reh_k_dir/$_reh_k_comm" 2>/dev/null && chmod +x "$_reh_k_dir/$_reh_k_comm" 2>/dev/null || true
rm -f "$_reh_k_sent"
release_pipeline_observer_root
# ARGV0-SPOOF-BY-DESIGN (№210)
# Второе и последнее место пайплайна с подменой argv[0]: репетиция того же
# примитива, что меряет 6.0.16 на шаге 6.0k. Маркер обязателен — преflight
# 6.0j/№210 запрещает конструкцию везде, кроме помеченных блоков.
bash -c "exec -a '$_reh_k_spoofdir/$_reh_k_hex' '$_reh_k_dir/$_reh_k_comm' '$_reh_k_sent'" >/dev/null 2>&1 || true
register_pipeline_observer_root
[ -e "$_reh_k_sent" ] \
    && _reh_note "6.0k" "механика цела: вызов с подменённым argv[0] состоялся, образ отработал (сентинел создан). proc.args этого вызова здесь не проверяется — это величина 6.0.16" \
    || _reh_bad  "6.0k" "подменённый вызов не создал сентинел — execve не состоялся (ENOENT/EACCES), и 6.0.16 после idle-часа дал бы ноль по приборной причине"
rm -rf "$_reh_k_dir" "$_reh_k_spoofdir"; rm -f "$_reh_k_sent"

rm -rf "$_reh_c_dir" "$_reh_g_seed" "$_reh_g_novel"
rm -f "/tmp/reh-ran-$_reh_c_comm" "/tmp/reh-ran-$_reh_g_comm"
fi

if [ "$_reh_fail" -ne 0 ]; then
    die "6.0.19 ПРОВАЛЕН: репетиция механики шагов-контролей красная (строки РЕПЕТИЦИЯ FAIL выше). Стоп ЗДЕСЬ и есть смысл критерия: три замера подряд умерли на механике контролей уже ПОСЛЕ отработавшего idle-часа (№176, №208, №209). Чинить названную механику и запускать заново — цена сейчас минута, после idle-часа это полтора часа и потерянное окно атак"
fi
echo "6.0.19 ДОСТИГНУТО $(date -u +%H:%M:%S) UTC: механика всех шести шагов-контролей отрепетирована до idle-часа (вердикты контролей этим НЕ предвосхищены)"

echo "=== [7/14] ЖЁСТКИЙ СТОП №4 (НОВЫЙ): оба контроля DNS ВНЕ окна замера (5.9.8a, запрет №6) ==="
# Риск №2 постановки: «0 long-label за idle-час» выглядит одинаково при
# починке и при полностью ослепшем DNS-коллекторе. Отсюда порядок: контроли
# в преflight, idle-час — потом. Слепой коллектор на idle-час не едет.
cd $SETUP/attacks
# 5.9.9g (находка №105, ЭТА ПРАВКА): шаг повторяем до трёх раз. На преflight'е
# №2.9.9 позитивный контроль дал Δdns=7 при N=8 и убил цепочку на 15-й минуте;
# три немедленных повтора подряд дали 8/8, а волна 5.9.9 не трогает ни
# bpf/dns.bpf.c, ни коллектор — то есть остановкой была потеря ОДНОГО UDP-пакета,
# а не ослепление. Различить их можно только повтором: ослепший коллектор даёт
# недосчёт КАЖДЫЙ раз, потерянный пакет — один раз из четырёх. Порог не ослаблен
# (последняя попытка обязана дать Δdns >= N ровно как раньше), ослаблена только
# цена единичного промаха. Повторяются лишь исходы «сценарий не воспроизведён»
# (в их формулировках и раньше стояло «повторить шаг»); Δdns > 0 у негатива —
# это находка №94, она валит цепочку с первой попытки без повторов.
DNS_CTL_ATTEMPTS="${DNS_CTL_ATTEMPTS:-3}"
dns_ctl_ok=0
for dns_try in $(seq 1 "$DNS_CTL_ATTEMPTS"); do
    echo "--- контроли DNS: попытка $dns_try из $DNS_CTL_ATTEMPTS ---"
    release_pipeline_observer_root
    bash ./run-all-attacks.sh --dns-fd-reuse-controls 2>&1 | tee /root/dns-controls-6.0-$dns_try.txt
    register_pipeline_observer_root
    dns_neg=$(ls -t $SETUP/attacks/attack-results/dns-negative-control-*.txt 2>/dev/null | head -1)
    dns_pos=$(ls -t $SETUP/attacks/attack-results/dns-positive-control-*.txt 2>/dev/null | head -1)
    [ -n "$dns_neg" ] || die "негативный контроль DNS не оставил маркера — 5.9.8a без входа"
    [ -n "$dns_pos" ] || die "позитивный контроль DNS не оставил маркера — 5.9.8a без входа"
    cat "$dns_neg" | sed 's/^/  негативный: /'
    cat "$dns_pos" | sed 's/^/  позитивный: /'
    grep -q '^skipped=1' "$dns_neg" && die "негативный контроль DNS пропущен харнессом — правка dns_socket_map не проверена (запрет №6)"
    grep -q '^skipped=1' "$dns_pos" && die "позитивный контроль DNS пропущен харнессом — правка dns_socket_map не проверена (запрет №6)"

    neg_xthread=$(awk -F= '$1=="cross_thread_close"{print $2+0}' "$dns_neg")
    neg_reused=$(awk -F= '$1=="reused_fd"{print $2+0}' "$dns_neg")
    neg_delta=$(awk -F= '$1=="events_dns_delta"{print $2+0}' "$dns_neg")
    pos_n=$(awk -F= '$1=="n"{print $2+0}' "$dns_pos")
    pos_delta=$(awk -F= '$1=="events_dns_delta"{print $2+0}' "$dns_pos")
    echo "  негативный: cross_thread_close=$neg_xthread reused_fd=$neg_reused Δdns=$neg_delta"
    echo "  позитивный: N=$pos_n Δdns=$pos_delta"

    # Негатив: Δdns > 0 — это сама находка №94, повтор её не исправит.
    [ "${neg_delta:-0}" -eq 0 ] || die "негативный контроль ПРОВАЛЕН: Δevents_total{type=dns}=$neg_delta > 0 — dns_socket_map всё ещё принимает переиспользованный fd за DNS, находка №94 не закрыта"
    # Генератор не отработал вовсе — повтор бессмыслен, вторая половина
    # запрета №6 осталась бы без входа при любом числе попыток.
    [ "${pos_n:-0}" -gt 0 ] || die "позитивный контроль: N=0 — генератор не отработал, вторая половина запрета №6 без входа"

    # Три исхода «сценарий не воспроизведён» — повторяемые.
    if [ "${neg_xthread:-0}" -ne 1 ]; then
        echo "ВНИМАНИЕ: попытка $dns_try: close() с чужого потока не удался — сценарий №94 не воспроизведён, повтор"
    elif [ "${neg_reused:-0}" -ne 1 ]; then
        echo "ВНИМАНИЕ: попытка $dns_try: fd не переиспользован (reused_fd=0) — сценарий №94 не воспроизведён, повтор"
    elif [ "${pos_delta:-0}" -lt "${pos_n:-0}" ]; then
        echo "ВНИМАНИЕ: попытка $dns_try: Δevents_total{type=dns}=$pos_delta < N=$pos_n — межпоточный резолв недосчитан, повтор (стабильный недосчёт остановит цепочку ниже)"
    else
        dns_ctl_ok=1
        [ "$dns_try" -gt 1 ] && echo "ВНИМАНИЕ: контроли DNS сошлись с попытки $dns_try, а не с первой — единичные промахи предыдущих попыток выше в логе"
        break
    fi
    sleep 10
done
[ "$dns_ctl_ok" -eq 1 ] \
    || die "контроли DNS не сошлись за $DNS_CTL_ATTEMPTS попыток (последняя: cross_thread_close=$neg_xthread reused_fd=$neg_reused N=$pos_n Δdns=$pos_delta) — недосчёт устойчив, это ослепление коллектора, а не потеря пакета (риск №2)"
echo "5.9.8a доказан живьём в $(date -u +%H:%M:%S) UTC: TLS по reused fd не даёт DNS-событий, межпоточный резолв даёт"

echo "=== [8/14] контроль счётности вне окна замера: канареечная серия оживает (5.9.8b) ==="
# Второй P0 волны после DNS. Без этого шага канареечная серия впервые
# считается только на минуте ~95 полного замера, внутри окна атак — то есть
# ошибка в ней (серия не растёт, префикс ловит лишнее) находилась бы там же,
# где и раньше находились все ошибки измерителя: после того, как час уже
# потрачен.
#
# ВЕРДИКТА ЗДЕСЬ НЕТ, и это осознанно: остаток считает ОДНА функция
# (counting_control_residual, run-gate.sh, 5.9.8c), переписывать её копию в
# пайплайне — ровно то, что 5.9.8c запретила. Проверяются только два
# инварианта, которым формула не нужна и которые ловят обе слепые ветки:
#   - null: канареечная серия строго 0 (иначе префикс ловит фон стенда);
#   - idle: канареечная серия выросла вообще (иначе счётчик мёртв, и крит. 20
#     на замере дал бы «остаток = -N» с диагнозом «непосчитанная потеря»).
# Маркеры пишутся со своим TIMESTAMP и в вердикт замера не попадают (секция
# 20 ищет их по таймстампу основного прогона) — запрет №3 соблюдён.
cd $SETUP/attacks
release_pipeline_observer_root
bash ./run-all-attacks.sh --counting-control 2>&1 | tee /root/counting-control-6.0.txt
register_pipeline_observer_root
# 5.9.9.F.2a (№123): режимов теперь два, а не три — drop удалён вместе с
# COUNTING_CONTROL_DROP_N. Маркер выбирается по ИМЕНИ (в имени лежит
# YYYYmmdd_HHMMSS), а не `ls -t` по mtime: тем же правилом, что теперь
# пользуется run-gate.sh, иначе пайплайн и гейт могли бы смотреть на разные
# марки одного и того же шага.
cc_null=$(ls -1 $SETUP/attacks/attack-results/counting-control-null-*.txt 2>/dev/null | LC_ALL=C sort | tail -1)
cc_idle=$(ls -1 $SETUP/attacks/attack-results/counting-control-idle-*.txt 2>/dev/null | LC_ALL=C sort | tail -1)
if ls $SETUP/attacks/attack-results/counting-control-drop-*.txt >/dev/null 2>&1; then
    echo "  ВНИМАНИЕ: в attack-results лежат маркеры counting-control-drop-* от прошлых замеров — режим удалён волной 5.9.9.F.2a, гейт их больше не читает"
fi
for m in "$cc_null" "$cc_idle"; do
    [ -n "$m" ] && { echo "  --- $(basename "$m")"; sed 's/^/    /' "$m"; }
done
[ -n "$cc_null" ] || die "контроль счётности: маркер null отсутствует — шаг не исполнен, 5.9.8b без входа"
[ -n "$cc_idle" ] || die "контроль счётности: маркер idle отсутствует — шаг не исполнен, 5.9.8b без входа"
grep -q '^skipped=1' "$cc_null" && die "контроль счётности пропущен харнессом (null) — python3 недоступен?"
grep -q '^skipped=1' "$cc_idle" && die "контроль счётности пропущен харнессом (idle)"

grep -q '^canary_sum=' "$cc_idle"     || die "5.9.8b: маркер без canary_sum — харнесс или бинарь старее 5.9.8b, крит. 20 на замере посчитает по старому пути с вычетом фона"
cc_null_canary=$(awk -F= '$1=="canary_sum"{print $2+0}' "$cc_null")
cc_idle_canary=$(awk -F= '$1=="canary_sum"{print $2+0}' "$cc_idle")
cc_idle_n=$(awk -F= '$1=="n"{print $2+0}' "$cc_idle")
echo "  null: канареечная серия=$cc_null_canary (обязана быть 0)"
echo "  idle: канареечная серия=$cc_idle_canary из N=$cc_idle_n"
[ "${cc_null_canary:-0}" -eq 0 ]     || die "5.9.8b ПРОВАЛЕН: канареечная серия=$cc_null_canary при N=0 — префикс /tmp/ebpf-guard-counting-canary- ловит события за пределами контроля счётности, крит. 20 будет врать в сторону завышения"
[ "${cc_idle_canary:-0}" -gt 0 ]     || die "5.9.8b ПРОВАЛЕН: канареечная серия=0 при N=$cc_idle_n — счётчик мёртв (RecordCountingCanary не вызывается либо FDPath пуст), крит. 20 на замере дал бы остаток -N с ложным диагнозом «непосчитанная потеря»"
# settle_reason проверяется здесь же — 5.9.8f судит его на замере, но
# «ceiling» на всех трёх маркерах означает дефект самого лупа, а не стенда,
# и чинить его дешевле сейчас, чем после idle-часа.
awk -F= '$1=="settle_reason"{print FILENAME": "$2}' "$cc_null" "$cc_idle" | sed 's/^/  5.9.8f: /'
echo "5.9.8b доказан живьём в $(date -u +%H:%M:%S) UTC: null=0, idle растёт"

echo "=== [9/14] ЖЁСТКИЙ СТОП №3: run_ringbuf_overflow ВНЕ окна замера (5.9.7b/5.9.8c) ==="
cd $SETUP/attacks
release_pipeline_observer_root
bash ./run-all-attacks.sh --ringbuf-overflow 2>&1 | tee /root/ringbuf-overflow-6.0.txt
register_pipeline_observer_root
rb_marker=$(ls -1 $SETUP/attacks/attack-results/ringbuf-overflow-*.txt 2>/dev/null | LC_ALL=C sort | tail -1)
[ -n "$rb_marker" ] || die "run_ringbuf_overflow не оставил маркера — шаг не исполнен, 5.9.7b без входа"
cat "$rb_marker" | sed 's/^/  /'
grep -q '^skipped=1' "$rb_marker" && die "run_ringbuf_overflow пропущен харнессом: $(awk -F= '$1=="skip_reason"{$1="";print substr($0,2)}' "$rb_marker")"
rb_full=$(awk -F= '$1=="ringbuf_full_delta"{print $2+0}' "$rb_marker")
rb_lost=$(awk -F= '$1=="bpf_lost_delta"{print $2+0}' "$rb_marker")
rb_canary=$(awk -F= '$1=="canary_sum"{print $2+0}' "$rb_marker")
rb_n=$(awk -F= '$1=="n"{print $2+0}' "$rb_marker")
echo "  ringbuf_full=$rb_full bpf_lost_events_total=$rb_lost канарейка=$rb_canary из N=$rb_n"
[ "${rb_full:-0}" -gt 0 ] \
    || die "ringbuf_full=0 даже с замороженным читателем — переполнение не воспроизведено (поднять RINGBUF_OVERFLOW_N)"
[ "${rb_full:-0}" -eq "${rb_lost:-0}" ] \
    || die "ringbuf_full=$rb_full != bpf_lost_events_total=$rb_lost — проводка watchdog (5.9.7b) не подтверждена живьём"
# 5.9.8c: сам вердикт (остаток той же формулой, что крит. 20) считает гейт в
# секции 22 — здесь только печатается вход, чтобы он лежал в логе замера, а
# не восстанавливался потом из маркера.
grep -q '^canary_sum=' "$rb_marker" \
    || echo "ВНИМАНИЕ: маркер без canary_sum — секция 22 посчитает по запасному пути с вычетом фона (5.9.8c не исполнена этим прогоном)"
echo "5.9.7b/5.9.8c доказан живьём в $(date -u +%H:%M:%S) UTC"

echo "=== [9.7/14] ЖЁСТКИЙ СТОП №5 (НОВЫЙ): наведённое CPU-давление с выдержкой ВНЕ окна замера (5.9.9.F.2b, №125) ==="
# Зачем шаг и почему он жёсткий. Критерий 14 («watchdog CPU-давления не
# флапает») три замера подряд давал SKIP: reduce=0 означал не «не флапает», а
# «давление ни разу не поднялось само за окно атак». Ждать, пока оно
# поднимется органически, — это ждать случайности; постановка волны требует
# НАВЕДЁННОГО давления с выдержкой. Шаг стоит ВНЕ окна замера, до baseline,
# рядом с контролями DNS/счётности и переполнением кольца (запрет №3).
#
# Почему стоп жёсткий, хотя сам по себе шаг ничего не детектирует: без его
# маркера крит. 14 остаётся SKIP, а обязательная величина приёмки №1
# (RUN-GATE: SKIP=0) — недостижима. Полтора часа замера, который заведомо не
# может выполнить свой первый пункт приёмки, тратить незачем — тот же довод,
# что у SMOKE-гейта [6/14].
#
# Что здесь НЕ проверяется: вердикт. Пару reduce↔recover судит крит. 14
# (run-gate.sh), читая ЭТОТ маркер; переписывать его логику здесь — ровно то,
# что 5.9.8c запретила для остатка счётности. Проверяются три инварианта,
# которым вердикт не нужен и которые ловят все три известные слепые ветки:
# шаг не пропущен, min_dwell прочитан у АГЕНТА (а не подставлен константой),
# нагрузка снята и не пережила шаг.
cd $SETUP/attacks
CPU_API="http://${VPS_IP:-localhost}:19090"
CPU_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
cpu_metric() { curl -s --max-time 10 -H "Authorization: Bearer $CPU_TOKEN" "$CPU_API/metrics" 2>/dev/null | awk -v m="$1" '$0 ~ "^"m"( |\\{)" {print $NF; exit}'; }

deg_before=$(cpu_metric ebpf_guard_cpu_degraded_fraction)
echo "  cpu_degraded_fraction до шага: ${deg_before:-n/a}"
release_pipeline_observer_root
EBPF_GUARD_API="$CPU_API" EBPF_GUARD_TOKEN="$CPU_TOKEN" \
    bash ./run-all-attacks.sh --cpu-pressure-control 2>&1 | tee /root/cpu-pressure-6.0.txt
register_pipeline_observer_root
cpu_marker=$(ls -1 $SETUP/attacks/attack-results/cpu-pressure-control-*.txt 2>/dev/null | LC_ALL=C sort | tail -1)
[ -n "$cpu_marker" ] || die "5.9.9.F.2b: run_cpu_pressure_control не оставил маркера — шаг не исполнен, крит. 14 останется в SKIP"
sed 's/^/  маркер: /' "$cpu_marker"
grep -q '^skipped=1' "$cpu_marker" \
    && die "5.9.9.F.2b: шаг пропущен харнессом: $(awk -F= '$1=="skip_reason"{$1="";print substr($0,2)}' "$cpu_marker"). Самая вероятная причина — журнальная строка агента 'adaptive load shedding enabled' недоступна (журнал урезан/сервис поднят раньше окна journalctl) либо разбор min_dwell разошёлся с форматом записи. Это дефект входа, а не детекта: крит. 14 без маркера даёт SKIP"

cpu_reduce=$(awk -F= '$1=="reduce"{print $2+0}' "$cpu_marker")
cpu_recover=$(awk -F= '$1=="recover"{print $2+0}' "$cpu_marker")
cpu_dwell=$(awk -F= '$1=="min_dwell_seconds"{print $2+0}' "$cpu_marker")
cpu_rwait=$(awk -F= '$1=="reduce_wait_seconds"{print $2+0}' "$cpu_marker")
cpu_cwait=$(awk -F= '$1=="recover_wait_seconds"{print $2+0}' "$cpu_marker")
cpu_fshed=$(awk -F= '$1=="file_shed_threshold_pct"{print $2}' "$cpu_marker")
cpu_ncpu=$(awk -F= '$1=="num_cpu"{print $2}' "$cpu_marker")
echo "  reduce=$cpu_reduce recover=$cpu_recover; ожидание reduce=${cpu_rwait}с recover=${cpu_cwait}с; min_dwell=${cpu_dwell}с (у агента), file_shed=${cpu_fshed} num_cpu=${cpu_ncpu}"

# (1) min_dwell прочитан у агента. Ноль означает, что разбор журнальной
# записи не сработал (её формат — ЧИСЛО НАНОСЕКУНД, slog.Duration в JSON), и
# шаг ждал бы recovered по константе — ровно то, что постановка запретила.
[ "${cpu_dwell:-0}" -gt 0 ] \
    || die "5.9.9.F.2b: min_dwell_seconds=0 в маркере — журнальная запись агента не разобрана, выдержка ждалась бы вслепую (постановка требует читать величину у агента, а не задавать константой)"
[ -n "$cpu_fshed" ] \
    || die "5.9.9.F.2b: пороги (file_shed/all_shed/recovery) не прочитаны у агента — крит. 14 напечатал бы зашитые «40/70/20» вместо реальных, то есть соврал бы про то, что именно сработало"

# (2) Давление поднялось. Ноль здесь — не «правило молчит», а «рычага нет»:
# генератор файловых событий не заставил агент тратить CPU выше file_shed.
[ "${cpu_reduce:-0}" -eq 1 ] \
    || die "5.9.9.F.2b ПРОВАЛЕН живьём: cpu_pressure_level не дошёл до file_shed за ${CPU_PRESSURE_MAX_REDUCE_WAIT}с непрерывного всплеска (reduce=0). Крит. 14 останется без входа. Поднимать CPU_PRESSURE_MAX_FILES/CPU_PRESSURE_MAX_REDUCE_WAIT — но сперва проверить, что file_shed=${cpu_fshed} pct одного ядра вообще достижим этим генератором на ${cpu_ncpu} ядрах"
# (3) Выдержка отработала: recovered пришёл за 2×min_dwell.
[ "${cpu_recover:-0}" -eq 1 ] \
    || die "5.9.9.F.2b ПРОВАЛЕН живьём: recovered не пришёл за 2×min_dwell=$((cpu_dwell * 2))с после снятия нагрузки (recover=0, ждали ${cpu_cwait}с). Либо нагрузка НЕ снята (проверить, не остались ли живые tar: pgrep -f ebpf-guard-cpu-pressure-filelist), либо watchdog не возвращается в normal — вторая половина крит. 14 («пара reduce↔recover закрыта») недоказуема"

# (4) Нагрузка не пережила шаг. Это не педантизм: шаг идёт ДО baseline, и
# осиротевший tar грузил бы стенд весь оставшийся замер, искажая КАЖДУЮ
# последующую величину, а не только свою (ревизия исполнения волны, Р3).
# ВНИМАНИЕ (находка №130, предпрогон №2.9.9.F.3): `pgrep -fc ... || echo 0`
# здесь не работал. procps-овский `pgrep -c` при нуле совпадений САМ печатает
# "0" и выходит с кодом 1 — то есть `|| echo 0` дописывал ВТОРОЙ ноль, в
# переменной оказывалось "0\n0", и `[ ... -ne 0 ]` падал с
# "integer expression expected" (код 2). `if` читает код 2 как «ложь», и
# инвариант Р3 молча пропускал что угодно, включая настоящий осиротевший tar.
# Код возврата не используется вовсе, а не-число — это «проверку выполнить не
# удалось», и оно обязано останавливать цепочку, а не превращаться в 0.
leftover_burst=$(pgrep -fc 'ebpf-guard-cpu-pressure-filelist' 2>/dev/null | head -1)
[ -n "$leftover_burst" ] || leftover_burst=0
case "$leftover_burst" in
    ''|*[!0-9]*)
        die "5.9.9.F.2b: счётчик живых процессов нагрузки не число ('$leftover_burst') — инвариант «нагрузка не пережила шаг» не проверен ничем (находка №130)" ;;
esac
echo "  живых процессов нагрузки после шага: $leftover_burst (обязан быть 0)"
if [ "$leftover_burst" -ne 0 ]; then
    pgrep -fa 'ebpf-guard-cpu-pressure-filelist' | sed 's/^/    /'
    pkill -f 'ebpf-guard-cpu-pressure-filelist' 2>/dev/null || true
    die "5.9.9.F.2b: после шага остались живые процессы нагрузки — они бы шли фоном через idle-час и окно атак. Убиты здесь, но замер начинать нельзя: стенд уже под искажённым фоном, перезапустить цепочку"
fi
deg_after=$(cpu_metric ebpf_guard_cpu_degraded_fraction)
lvl_after=$(cpu_metric ebpf_guard_cpu_pressure_level)
echo "  cpu_degraded_fraction после шага: ${deg_after:-n/a} (было ${deg_before:-n/a}), cpu_pressure_level=${lvl_after:-n/a}"
[ "${lvl_after:-0}" = "0" ] \
    || die "5.9.9.F.2b: cpu_pressure_level=${lvl_after} после шага — агент остался под шеддингом, idle-час и окно атак мерились бы урезанным сэмплингом"
# Доля кумулятивна с момента старта watcher-а, поэтому «0 за окно замера»
# ею не проверяется — эту половину несёт крит. 14 (естественных переходов в
# окне 0). Здесь печатается вклад САМОГО шага, чтобы на разборе крит. 5.9e
# (порог 0.2) было видно, сколько из доли внесено наведённым давлением, а
# сколько — прогоном.
awk -v a="${deg_before:-0}" -v b="${deg_after:-0}" 'BEGIN{printf "  вклад шага в cpu_degraded_fraction: +%.4f (крит. 5.9e судит итог по final-срезу, порог 0.2)\n", b-a}'
echo "5.9.9.F.2b доказан живьём в $(date -u +%H:%M:%S) UTC: reduce=1 recover=1, min_dwell=${cpu_dwell}с прочитан у агента, нагрузка снята"

echo "=== [9.6/14] ЖЁСТКИЙ СТОП №6 (НОВЫЙ): три пары контролей продуктовых правок ВНЕ окна замера (5.9.9.F.3a/3b/3c) ==="
# ГЛАВНЫЙ ШАГ ЭТОГО ЗАМЕРА. Все три правки волны УМЕНЬШАЮТ число алертов, и
# «правило сузилось» неотличимо от «правило ослепло» по любому счётчику —
# находка №57, повторённая волнами 5.9.7e, 5.9.8g, 5.9.9b, 5.9.9.Fa,
# 5.9.9.F.1b. Поэтому у каждого пункта здесь ДВЕ половины, и обе жёсткие:
#   позитивная — правило обязано остаться ненулевым на настоящем случае;
#   негативная — правило обязано перестать видеть то, ради чего правилось.
# Ноль на позитивной половине — это находка №57, а не успех волны, и полный
# замер объявил бы его регрессом детекта в крит. 6 ПОСЛЕ потраченного
# idle-часа и часа атак.
#
# Шаг стоит ВНЕ окна замера (запрет №3), рядом с контролями DNS, счётности и
# переполнением кольца, и исполняется на ОБОИХ режимах — и на предпрогоне, и
# на полном замере. Это осознанно и отличается от [9.5/14]: там контроль
# внутри full_run() читает крит. 7 по манифесту, а здесь входа в манифесте
# нет, и обязательная величина приёмки №2 («правила ненулевые НА позитивных
# контролях») иначе недостижима на полном замере вовсе.
#
# Следствие, названное заранее: после этого шага оба правленых правила
# получают ненулевой абсолют ДО открытия baseline, и секция 6 гейта пометит
# их «наведено шагом преflight'а». После правки 5.9.9.F.3d это ВЕРНО — они
# действительно сработали вне всех трёх измеряемых окон. Приёмка читает их
# абсолютом по стору, а не дельтой окна.
cd $SETUP/attacks
FP_API="http://${VPS_IP:-localhost}:19090"
FP_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
fp_alerts() { curl -s --max-time 20 -H "Authorization: Bearer $FP_TOKEN" "$FP_API/api/v1/alerts" 2>/dev/null; }
fp_count() { fp_alerts | jq --arg r "$1" '[.[]|select(.rule_id==$r)]|length' 2>/dev/null || echo 0; }

# Загруженность правил — ДО контролей. Без неё «0 за прогон» и «правило не
# загрузилось» неотличимы, и оба дали бы одинаково зелёный крит. 6 через
# реестры (находка №117: путь именно /api/v1/rules, голый /rules отдаёт 404).
fp_rules=$(curl -s --max-time 15 -H "Authorization: Bearer $FP_TOKEN" "$FP_API/api/v1/rules" 2>/dev/null)
fp_rules_n=$(echo "$fp_rules" | jq -e 'if type=="array" then length else empty end' 2>/dev/null) \
    || die "5.9.9.F.3: $FP_API/api/v1/rules не отдал JSON-массив (ответ: $(echo "$fp_rules" | head -c 200)) — это отказ API/токена, а не сужение правил; ни один контроль ниже без реестра не доказуем"
echo "  реестр правил агента: $fp_rules_n правил"
for r in rootkit_hidden_dir_dev privesc_suid_suspicious_path sigma_binary_in_tmp_executed \
         container_escape_mount container_escape_chroot container_escape_unshare_user \
         container_escape_cap_sys_admin privesc_unshare_user_ns cis_5_2_1_privileged_container \
         proc_inject_memfd_create integrity_proc_self_exe_exec sigma_memfd_create_anonymous \
         rootkit_pam_module_added cred_shadow_read drift_new_library_in_system_dir; do
    echo "$fp_rules" | jq -e --arg r "$r" '[.. | objects | select(.id? == $r)] | length > 0' >/dev/null 2>&1 \
        || die "5.9.9.F.3/5.9.9.F.4a: правило $r не найдено в /api/v1/rules — оно не загрузилось, и его ноль на приёмке означал бы битый YAML, а не сужение (проверить синтаксис правки)"
done
echo "  все пятнадцать правых правил загружены агентом (не битый YAML, включая шесть новых 5.9.9.F.4a/№141)"

# ---- 5.9.9.F.3a: rootkit_hidden_dir_dev ---------------------------------
# Позитив: настоящий скрытый каталог под /dev — ровно то, ради чего правило
# написано (T1564.001). Негатив: чтение /dev/urandom, которое дало 10 из 12
# критикалов правила на №2.9.9.F.2.
echo "--- 5.9.9.F.3a: пара контролей rootkit_hidden_dir_dev (№131) ---"
a_before=$(fp_count rootkit_hidden_dir_dev)
release_pipeline_observer_root
mkdir -p "/dev/.${FP_CONTROL_TAG}" 2>/dev/null || die "5.9.9.F.3a: не удалось создать /dev/.${FP_CONTROL_TAG} — позитивный контроль без входа (нужен root и rw на /dev)"
# Ревизия волны (2026-08-26): ОДНОГО mkdir мало, и это не придирка к
# контролю, а прямое следствие исполнения пункта 3a. Предикат «каталог
# создан» оказался невыразим (нет хука на mkdir/mkdirat — bpf/fileaccess.bpf.c
# видит только openat/read/write), поэтому правило переехало на «путь под
# /dev открыт». mkdir не порождает НИ ОДНОГО файлового события, то есть
# контроль в прежнем виде давал Δ=0 на исправном правиле и убивал замер
# сообщением «правило ослеплено». Скрытый путь под /dev поэтому ещё и
# ОТКРЫВАЕТСЯ — ровно то, что правило теперь обещает ловить.
: > "/dev/.${FP_CONTROL_TAG}-canary" 2>/dev/null \
    || die "5.9.9.F.3a: не удалось создать файл /dev/.${FP_CONTROL_TAG}-canary — позитивный контроль без входа (нужен root и rw на /dev)"
head -c 1 "/dev/.${FP_CONTROL_TAG}-canary" >/dev/null 2>&1 || true
register_pipeline_observer_root
sleep 20
a_pos=$(fp_count rootkit_hidden_dir_dev)
echo "  позитивный: скрытый каталог + открытие /dev/.${FP_CONTROL_TAG}-canary -> Δ=$((a_pos - a_before))"
rm -f "/dev/.${FP_CONTROL_TAG}-canary" 2>/dev/null || true
rmdir "/dev/.${FP_CONTROL_TAG}" 2>/dev/null || true
[ "$((a_pos - a_before))" -ge 1 ] \
    || die "5.9.9.F.3a ПРОВАЛЕН живьём: скрытый путь под /dev (каталог + открытый dot-файл) НЕ поднял rootkit_hidden_dir_dev (Δ=0). Якорь ^ вместе с исключением штатных нод ослепил правило целиком — это находка №57, а не сужение. Полный замер потратил бы полтора часа, чтобы напечатать это как «потеряно вне реестров» в крит. 6"
a_neg_before=$(fp_count rootkit_hidden_dir_dev)
release_pipeline_observer_root
for _ in $(seq 1 20); do head -c 32 /dev/urandom > /dev/null 2>&1; done
register_pipeline_observer_root
sleep 20
a_neg_after=$(fp_count rootkit_hidden_dir_dev)
echo "  негативный: 20 чтений /dev/urandom -> Δ=$((a_neg_after - a_neg_before))"
[ "$((a_neg_after - a_neg_before))" -eq 0 ] \
    || die "5.9.9.F.3a ПРОВАЛЕН: /dev/urandom всё ещё поднимает critical rootkit_hidden_dir_dev (Δ$((a_neg_after - a_neg_before))) — regex [a-z]{6,} по-прежнему покрывает штатные ноды либо агент крутит старые правила (проверить, что рестарт [5/14] подхватил новый rules/)"
echo "  5.9.9.F.3a: обе половины сошлись"

# ---- 5.9.9.F.3b: privesc_suid_suspicious_path / sigma_binary_in_tmp_executed
# Позитив: НАСТОЯЩИЙ SUID-бинарь, запущенный из /tmp, — ровно T1548.001.
# Негатив: обычный текстовый файл под /tmp, прочитанный обычным cat. Именно
# такой файл (список для tar шага 5.9.9.F.2b) дал 6 критикалов «SUID binary
# executed» на №2.9.9.F.2.
echo "--- 5.9.9.F.3b: пара контролей семьи /tmp (№132) ---"
b_before=$(fp_count privesc_suid_suspicious_path)
b_sigma_before=$(fp_count sigma_binary_in_tmp_executed)
fp_suid="/tmp/${FP_CONTROL_TAG}-suidcanary"
cp /bin/true "$fp_suid" 2>/dev/null || die "5.9.9.F.3b: не удалось подготовить SUID-канарейку в /tmp — позитивный контроль без входа"
chown root:root "$fp_suid" 2>/dev/null || true
chmod 4755 "$fp_suid" || die "5.9.9.F.3b: chmod 4755 не прошёл — без бита SUID позитивный контроль не проверяет ничего"
release_pipeline_observer_root
"$fp_suid" >/dev/null 2>&1 || true
register_pipeline_observer_root
sleep 20
b_pos=$(fp_count privesc_suid_suspicious_path)
b_sigma_pos=$(fp_count sigma_binary_in_tmp_executed)
echo "  позитивный: SUID-бинарь запущен из /tmp -> Δprivesc_suid=$((b_pos - b_before)) Δsigma_binary_in_tmp=$((b_sigma_pos - b_sigma_before))"
rm -f "$fp_suid"
[ "$((b_pos - b_before))" -ge 1 ] \
    || die "5.9.9.F.3b ПРОВАЛЕН живьём: настоящий SUID-бинарь, запущенный из /tmp, НЕ поднял privesc_suid_suspicious_path (Δ=0). Правило ослеплено, а не сужено (находка №57) — либо предикат SUID читает поле, которого коллектор не отдаёт, и тогда постановка требовала второго исхода (переименование с понижением severity), а не молчащего critical"
[ "$((b_sigma_pos - b_sigma_before))" -ge 1 ] \
    || echo "  ВНИМАНИЕ: sigma_binary_in_tmp_executed не поднялся на запуске ELF из /tmp (Δ=0) — если пункт закрыт переименованием, это ожидаемо; если проверкой ELF/exec, это ослепление"
b_neg_before=$(fp_count privesc_suid_suspicious_path)
b_neg_sigma_before=$(fp_count sigma_binary_in_tmp_executed)
fp_txt="/tmp/${FP_CONTROL_TAG}-filelist.txt"
printf 'harmless\n%s\n' "$FP_CONTROL_TAG" > "$fp_txt"
release_pipeline_observer_root
for _ in $(seq 1 10); do cat "$fp_txt" > /dev/null 2>&1; done
register_pipeline_observer_root
sleep 20
b_neg_after=$(fp_count privesc_suid_suspicious_path)
b_neg_sigma_after=$(fp_count sigma_binary_in_tmp_executed)
echo "  негативный: 10 чтений обычного .txt под /tmp -> Δprivesc_suid=$((b_neg_after - b_neg_before)) Δsigma_binary_in_tmp=$((b_neg_sigma_after - b_neg_sigma_before))"
rm -f "$fp_txt"
[ "$((b_neg_after - b_neg_before))" -eq 0 ] \
    || die "5.9.9.F.3b ПРОВАЛЕН: обычный текстовый файл под /tmp всё ещё поднимает critical privesc_suid_suspicious_path (Δ$((b_neg_after - b_neg_before))) — предикат SUID/exec не добавлен либо severity не понижена. Это ровно те 37 критикалов при нуле истинных, ради которых волна и собрана"
[ "$((b_neg_sigma_after - b_neg_sigma_before))" -eq 0 ] \
    || die "5.9.9.F.3b ПРОВАЛЕН: обычный .txt под /tmp всё ещё поднимает sigma_binary_in_tmp_executed (Δ$((b_neg_sigma_after - b_neg_sigma_before))) — правило с именем «ELF binary executed» по-прежнему голый prefix /tmp/"
echo "  5.9.9.F.3b: обе половины сошлись"

# ---- 5.9.9.F.3c: песочница systemd --------------------------------------
# 5.9.9.F.4b (№142/№143), два изменения относительно отклонённого замера
# №2.9.9.F.3:
#   1. Порядок половин перевёрнут — позитив первым. Провал негатива не
#      имеет права прятать проверку на ослепление (находка №143): именно
#      ослепление, а не ложный ноль негатива, главный риск всей троицы
#      3a/3b/3c и нового 4a.
#   2. Величина негатива больше не Δincident_confirmed_attack за окно —
#      эта глобальная дельта считает фон самого измерителя (находка №142:
#      субъектом отклонённого замера №2.9.9.F.3 оказался не man-db, а
#      инструментарий пайплайна; фон измерителя закрывается отдельно
#      пунктом 4c, смешивать два дефекта в одной величине запрещено
#      постановкой). Вместо неё — число incidents (/api/v1/incidents) с
#      verdict="attack", чей process_chain/comms содержит актора формы
#      "(...)" — считается по актору инцидента, а не глобально.
echo "--- 5.9.9.F.3c: пара контролей песочницы systemd, позитив первым (№133, №142/№143) ---"
fp_incidents() { curl -s --max-time 20 -H "Authorization: Bearer $FP_TOKEN" "$FP_API/api/v1/incidents?limit=500" 2>/dev/null; }
fp_sandbox_actor_attack_incidents() {
    fp_incidents | jq '[.[] | select(.verdict=="attack") | select( ((.process_chain // []) + (.comms // [])) | any(test("^\\(.*\\)$")) )] | length' 2>/dev/null || echo 0
}
c_rules="container_escape_mount container_escape_chroot container_escape_unshare_user container_escape_cap_sys_admin privesc_unshare_user_ns cis_5_2_1_privileged_container"

c_pos_before=0
for r in $c_rules; do c_pos_before=$((c_pos_before + $(fp_count "$r"))); done
# ppid этого процесса — bash пайплайна, не 1: сужение по признаку «ребёнок
# pid 1» не имеет права его погасить. Побег настоящий: новый user+mount ns.
release_pipeline_observer_root
unshare -Urm --propagation private /bin/true >/dev/null 2>&1 || true
register_pipeline_observer_root
sleep 20
c_pos_after=0
for r in $c_rules; do c_pos_after=$((c_pos_after + $(fp_count "$r"))); done
echo "  позитивный: unshare -Urm с ppid!=1 -> Δ(шесть правил побега)=$((c_pos_after - c_pos_before))"
[ "$((c_pos_after - c_pos_before))" -ge 1 ] \
    || die "5.9.9.F.3c ПРОВАЛЕН живьём: настоящий unshare -Urm из процесса с ppid!=1 НЕ поднял ни одного из шести правил (Δ=0). Сужение вышло за границу песочницы systemd и ослепило детект побега целиком — это находка №57 и одновременно нарушение запрета постановки («песочница systemd никогда не интересна» неверно: побег через unshare+mount существует)"
echo "  5.9.9.F.3c: позитивная половина сошлась (обязана исполняться первой — находка №143)"

c_sum_before=0
for r in $c_rules; do c_sum_before=$((c_sum_before + $(fp_count "$r"))); done
c_actor_inc_before=$(fp_sandbox_actor_attack_incidents)
fp_unit="${FP_SANDBOX_UNIT:-man-db.service}"
if systemctl list-unit-files "$fp_unit" >/dev/null 2>&1 && [ -n "$(systemctl list-unit-files --no-legend "$fp_unit" 2>/dev/null)" ]; then
    release_pipeline_observer_root
    systemctl start "$fp_unit" 2>&1 | sed 's/^/    /' || true
    register_pipeline_observer_root
    # Юнит одноразовый (Type=oneshot) — ждём и его работу, и корреляцию.
    sleep 45
    c_sum_after=0
    for r in $c_rules; do c_sum_after=$((c_sum_after + $(fp_count "$r"))); done
    c_actor_inc_after=$(fp_sandbox_actor_attack_incidents)
    echo "  негативный: systemctl start $fp_unit -> Δ(шесть правил побега)=$((c_sum_after - c_sum_before)) Δ(incidents verdict=attack с актором песочницы в process_chain/comms)=$((c_actor_inc_after - c_actor_inc_before))"
    fp_alerts | jq -r --arg t "$(date -u -d '-2 min' +%Y-%m-%dT%H:%M 2>/dev/null || echo zzz)" \
        '.[]|select(.timestamp >= $t)|"    свежий алерт: \(.rule_id) comm=\(.comm) pid=\(.pid)"' 2>/dev/null | tail -20
    [ "$((c_sum_after - c_sum_before))" -eq 0 ] \
        || die "5.9.9.F.3c ПРОВАЛЕН: старт sandboxed-юнита $fp_unit всё ещё поднимает правила побега из контейнера (Δ$((c_sum_after - c_sum_before))). Признак песочницы не структурный либо не покрыл форму comm '(unit)' — ровно так не обобщилось исключение по comm у находки №111. idle-час замера снова даст verdict=\"attack\" на pid 1, и обязательная величина приёмки №3 недостижима"
    [ "$((c_actor_inc_after - c_actor_inc_before))" -eq 0 ] \
        || die "5.9.9.F.3c ПРОВАЛЕН: старт $fp_unit всё ещё дал incident с verdict=attack, чей process_chain/comms содержит актора формы «(...)» (Δ$((c_actor_inc_after - c_actor_inc_before))) — шесть правил побега замолчали, но корреляция набирает score из оставшихся правил на том же акторе (sensitive_file_read, drift_*, rootkit_hidden_dir_dev). Пункт 3c закрыт наполовину. Если непустой Δ объясняется исключительно фоном самого пайплайна (находка №147, закрывается пунктом 4c) — это отдельная находка, а не провал этого контроля, и должна быть названа явно, а не молчаливо проигнорирована"
else
    die "5.9.9.F.3c: юнит $fp_unit не найден на стенде — негативный контроль без входа. Задать FP_SANDBOX_UNIT= настоящим sandboxed-юнитом (PrivateTmp/PrivateDevices), иначе пункт 3c не проверен ничем, а его ноль на idle-часе неотличим от тихого часа"
fi
echo "  5.9.9.F.3c: обе половины сошлись"

echo "5.9.9.F.3a/3b/3c доказаны живьём в $(date -u +%H:%M:%S) UTC: три правки сузились, ни одна не ослепла"

echo "=== [9.5/14] позитивный контроль cred_proc_maps_mass_read живьём (5.9.9.Fg, находка №112) ==="
# Только на предпрогоне. На полном замере шаг стоит ВНУТРИ full_run() (окно
# атак) — там его читает крит. 7, и второй прогон вне окна дал бы правилу
# ненулевой абсолют ДО idle-часа, то есть включил бы ветку спасения фонового
# правила чужой заслугой и замаскировал бы настоящий регресс в крит. 6.
#
# Смысл шага ровно тот же, что у контролей DNS в [7/14]: сужение
# cred_proc_maps_mass_read до numeric-PID (5.9.9.Fa) правит ПРАВИЛО, и
# «сработает ли оно на живом ядре» офлайн-реплеем не проверяется никак —
# юнит-тест судит матчер, а не путь ядро→коллектор→корреляция→стор.
if [ "${SMOKE_ONLY:-0}" = "1" ]; then
    cd $SETUP/attacks
    CRED_API="http://${VPS_IP:-localhost}:19090"
    CRED_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
    cred_alerts() { curl -s --max-time 15 -H "Authorization: Bearer $CRED_TOKEN" "$CRED_API/api/v1/alerts" 2>/dev/null; }
    cred_count() { cred_alerts | jq --arg r "$1" '[.[]|select(.rule_id==$r)]|length' 2>/dev/null || echo 0; }

    cred_before=$(cred_count cred_proc_maps_mass_read)
    dump_before=$(cred_count sigma_memory_proc_dump)
    echo "  до контроля: cred_proc_maps_mass_read=$cred_before sigma_memory_proc_dump=$dump_before"

    release_pipeline_observer_root
    EBPF_GUARD_API="$CRED_API" EBPF_GUARD_TOKEN="$CRED_TOKEN" \
        bash ./run-all-attacks.sh --cred-proc-maps-control 2>&1 | tee /root/cred-proc-maps-6.0.txt
    register_pipeline_observer_root
    cred_marker=$(ls -t $SETUP/attacks/attack-results/cred-proc-maps-control-*.txt 2>/dev/null | head -1)
    [ -n "$cred_marker" ] || die "5.9.9.Fa: позитивный контроль не оставил маркера — шаг не исполнен"
    sed 's/^/  маркер: /' "$cred_marker"
    grep -q '^skipped=1' "$cred_marker" && die "5.9.9.Fa: контроль пропущен харнессом: $(awk -F= '$1=="skip_reason"{$1="";print substr($0,2)}' "$cred_marker") — это дефект стенда, не детекта"
    grep -q '^done=1' "$cred_marker" || die "5.9.9.Fa: контроль не дочитал /proc/<pid>/maps (done!=1) — шаг не состоялся"

    # Порог правила — 5 за 10 с; корреляция и запись в стор идут асинхронно.
    sleep 20
    cred_after=$(cred_count cred_proc_maps_mass_read)
    dump_after=$(cred_count sigma_memory_proc_dump)
    echo "  после контроля: cred_proc_maps_mass_read=$cred_after (Δ$((cred_after - cred_before))) sigma_memory_proc_dump=$dump_after (Δ$((dump_after - dump_before)))"
    cred_alerts | jq -r '.[]|select(.rule_id=="cred_proc_maps_mass_read")|"    \(.rule_id) comm=\(.comm) pid=\(.pid) \(.message)"' 2>/dev/null | tail -5

    [ "$((cred_after - cred_before))" -ge 1 ] \
        || die "5.9.9.Fa ПРОВАЛЕН живьём: 8 чтений /proc/<pid>/maps процессом comm=credscrape не дали НИ ОДНОГО алерта cred_proc_maps_mass_read. Сужение до numeric-PID ослепило правило (находка №57) — полный замер объявил бы это регрессом детекта в крит. 6 после потраченного idle-часа"
    # 5.9.9.F.1b (находка №111): на волне 5.9.9.F этот же контроль для
    # sigma_memory_proc_dump был МЯГКИМ («ВНИМАНИЕ ... цепочку не
    # останавливает»), и это было верно ровно до 5.9.9.F.1b. После неё
    # правило потеряло /proc/[0-9]+/cmdline — то есть потеряло единственный
    # источник, который поднимал его на этом стенде без атаки (18 из 19
    # алертов №2.9.9.F: landscape-sysinfo и dbus-daemon). Теперь ЭТИ восемь
    # чтений /proc/<pid>/maps — единственный вход правила за весь прогон.
    # Ноль здесь означает не «отдельную находку», а ровно то, что постановка
    # назвала главным риском волны: правка неотличима от ослепления по
    # счётчику. Полный замер после этого объявил бы правило потерянным в
    # крит. 6 — после потраченного idle-часа и часа атак.
    [ "$((dump_after - dump_before))" -ge 1 ] \
        || die "5.9.9.F.1b ПРОВАЛЕН живьём: sigma_memory_proc_dump не поднялся на 8 чтениях чужого /proc/<pid>/maps (Δ=0). После снятия предиката cmdline это ЕДИНСТВЕННЫЙ вход правила на стенде — ноль означает ослепление (находка №57), а не тишину. Полный замер потратил бы 1.5 часа, чтобы напечатать это же как регресс детекта в крит. 6"
    echo "5.9.9.Fa/5.9.9.F.1b доказаны живьём в $(date -u +%H:%M:%S) UTC: оба правила видят чтение чужого /proc/<pid>/maps"
    rm -f /tmp/credscrape

    # --- Негативные контроли обеих правок волны 5.9.9.F.1 ------------------
    # Позитивная половина выше доказывает, что правила не ослепли. Негативная
    # половина ниже доказывает, что они СУЗИЛИСЬ — то есть что ожидаемые нули
    # приёмки (19 -> 1 и 10 -> 0) получены правкой условия, а не поломкой
    # загрузки правил. Без неё «0 за прогон» и «правило не загрузилось»
    # неотличимы, и оба дали бы одинаково зелёный крит. 6 через реестры.
    # Путь именно /api/v1/rules (internal/exporter/api.go:40). Голый /rules
    # отдаёт «404 page not found», и до 5.9.9.F.1d проверка ниже читала эту
    # строку как «правило не загрузилось» и валила смок с диагнозом «битый
    # YAML» при исправных правилах (находка №117).
    rules_json=$(curl -s --max-time 15 -H "Authorization: Bearer $CRED_TOKEN" "$CRED_API/api/v1/rules" 2>/dev/null)
    # Сначала — что ответ вообще реестр правил. Иначе любой отказ API
    # (404, пустое тело, отвалившийся токен) неотличим от «правило не
    # загрузилось», а именно на этом различии стоит весь смысл контроля.
    rules_total=$(echo "$rules_json" | jq -e 'if type=="array" then length else empty end' 2>/dev/null) \
        || die "5.9.9.F.1: $CRED_API/api/v1/rules не отдал JSON-массив правил (ответ: $(echo "$rules_json" | head -c 200)) — это отказ API/токена, а не сужение правил; негативные контроли ниже без реестра недоказуемы"
    [ "${rules_total:-0}" -gt 0 ] || die "5.9.9.F.1: реестр /api/v1/rules пуст — агент не загрузил ни одного правила"
    echo "  реестр правил агента: $rules_total правил"
    for r in sigma_memory_proc_dump web_sql_injection_files; do
        echo "$rules_json" | jq -e --arg r "$r" '[.. | objects | select(.id? == $r)] | length > 0' >/dev/null 2>&1 \
            || die "5.9.9.F.1: правило $r не найдено в /api/v1/rules — оно не загрузилось, и его ноль на приёмке означал бы битый YAML, а не сужение (проверить синтаксис правки)"
    done
    echo "  оба правленых правила загружены агентом (не битый YAML)"

    # Негативный контроль 5.9.9.F.1b: чтение чужого cmdline. До правки это
    # поднимало critical (landscape-sysinfo, dbus-daemon, 18 алертов за
    # №2.9.9.F), после — не обязано.
    cp /bin/cat /tmp/cmdlinescan 2>/dev/null || die "не удалось подготовить comm=cmdlinescan для негативного контроля 5.9.9.F.1b"
    dump_neg_before=$(cred_count sigma_memory_proc_dump)
    release_pipeline_observer_root
    for _ in $(seq 1 20); do /tmp/cmdlinescan /proc/1/cmdline > /dev/null 2>&1; done
    register_pipeline_observer_root
    sleep 20
    dump_neg_after=$(cred_count sigma_memory_proc_dump)
    echo "  негативный 5.9.9.F.1b: 20 чтений /proc/1/cmdline под comm=cmdlinescan -> Δsigma_memory_proc_dump=$((dump_neg_after - dump_neg_before))"
    [ "$((dump_neg_after - dump_neg_before))" -eq 0 ] \
        || die "5.9.9.F.1b ПРОВАЛЕН: чтение /proc/1/cmdline всё ещё поднимает sigma_memory_proc_dump (Δ$((dump_neg_after - dump_neg_before))) — предикат cmdline не убран либо агент крутит старые правила (проверить, что рестарт [5/14] подхватил новый rules/)"
    rm -f /tmp/cmdlinescan

    # Негативный контроль 5.9.9.F.1c: имена файлов с "--", "#", ";". Это
    # ровно те формы, что дали 10 критикалов на №2.9.9.F (session-файлы
    # systemd-logind и man-page git). Ни одна из них больше не SQL-инъекция.
    sql_neg_before=$(cred_count web_sql_injection_files)
    sql_dir=$(mktemp -d)
    release_pipeline_observer_root
    for f in 'git-mergetool--lib.1.gz' '.#114376ChHzY' 'report;final.csv' 'libfoo--dev_1.2.3.deb'; do
        printf 'x' > "$sql_dir/$f" 2>/dev/null && cat "$sql_dir/$f" > /dev/null 2>&1
    done
    register_pipeline_observer_root
    sleep 20
    sql_neg_after=$(cred_count web_sql_injection_files)
    echo "  негативный 5.9.9.F.1c: 4 имени файла с --/#/; -> Δweb_sql_injection_files=$((sql_neg_after - sql_neg_before))"
    [ "$((sql_neg_after - sql_neg_before))" -eq 0 ] \
        || die "5.9.9.F.1c ПРОВАЛЕН: имя файла с голым --/#/; всё ещё поднимает critical web_sql_injection_files (Δ$((sql_neg_after - sql_neg_before))) — паттерны не убраны либо агент крутит старые правила"
    rm -rf "$sql_dir"
    echo "5.9.9.F.1b/5.9.9.F.1c: негативные контроли пройдены в $(date -u +%H:%M:%S) UTC — сужение доказано, не поломка загрузки"
else
    echo "  пропущено: на полном замере шаг исполняется внутри full_run() (окно атак), крит. 7"
fi

# Наведённые контроли позади — дальше снова чистый инструментарий (пауза,
# idle-run.sh со своим, гораздо более узким корнем, гейт, отчёт). 5.9.9.F.5h:
# после последнего бракета выше (негативный контроль cred_proc_maps/SQL)
# исключение уже взведено — этот вызов избыточен по состоянию, оставлен как
# явная страховка (идемпотентен: тот же $$ снова, дешёвое переподтверждение)
# на случай, если SMOKE_ONLY=1 и блок [9.5/14] выше не исполнялся вовсе (тогда
# состояние после [9.6/14] — тоже уже "registered", но явный вызов здесь не
# полагается на это молча). Граница окна замера [11/14] снимает его ещё раз
# явно, как и требует 4c.
register_pipeline_observer_root

# SMOKE_ONLY=1 — короткий прогон «сборка + живые доказательства», без
# idle-часа и атак (~20 минут вместо ~2ч: наведённое CPU-давление добавляет
# к предпрогону до 3 минут ожидания reduce и до 2×min_dwell ожидания
# recovered). Именно здесь его место: всё, что выше, проверяется машинно и
# способно провалиться, а всё, что ниже, — это время.
#
# ПРЕДПРОГОН ОБЯЗАТЕЛЕН, и роль у него в этой волне третья по счёту, отличная
# от обеих предыдущих. На №2.9.9.F.1 он ловил ослепление продуктовых правок;
# на №2.9.9.F.2 — критерий, разучившийся падать; здесь обязаны исполниться
# ОБА класса сразу, потому что волна и продуктовая, и измерительная.
#
# Продуктовая половина — шаг [9.6/14], три пары контролей, каждая с жёстким
# стопом на ОБЕИХ половинах: позитивная (правило не ослепло) и негативная
# (правило сузилось). Это единственное место, где ослепление ловится ДО
# траты полутора часов; крит. 6 назвал бы его регрессом детекта после.
#
# Измерительная половина — шаг [1/14], реплеи 13/14 и 14/14: фаза idle не
# поглощается меткой преflight'а И четвёртая фаза при этом сохранена (3d);
# SKIP=0 достигается на архиве без правки самих критериев И счётчик
# неисполнившихся веток при этом умеет расти (3e). Второй исход у каждого
# обязателен: механизм, печатающий 0 всегда, вернул бы 0 и здесь — ровно
# этим была находка №124.
#
# Пункт волны, у которого отрицательный исход не исполнился, считается
# неисполненным, и цепочка останавливается там же.
#
# Приёмкой волны такой прогон НЕ является: величины 1, 3, 4, 6 приёмки
# (SKIP=0/FAIL=0, idle-час, реестр акторов, фазы прироста) имеют входом
# только idle-час и полный гейт.
if [ "${SMOKE_ONLY:-0}" = "1" ]; then
    echo "=== SMOKE_ONLY=1: сборка, SMOKE, РЕПЕТИЦИЯ МЕХАНИКИ ШЕСТИ ШАГОВ-КОНТРОЛЕЙ (6.0.19), оба контроля DNS, контроль счётности, переполнение кольца, наведённое CPU-давление (5.9.9.F.2b), ТРИ ПАРЫ КОНТРОЛЕЙ ПРОДУКТОВЫХ ПРАВОК (5.9.9.F.3a/3b/3c), позитивный контроль cred_proc_maps и пары 5.9.9.F.1b/5.9.9.F.1c пройдены ==="
    echo "=== 25/25 реплеев пройдены, включая четыре реплея волны 6.0f (19/25 6.0.5, 20/25 6.0.1, 21/25 5.9.7e, 22/25 6.0.10) и три новых реплея волны 6.0j (23/25 new-rules.txt обеими сторонами, 24/25 пол величины 6.0.1, 25/25 гигиена коллекта обеими половинами) ==="
    echo "=== idle-час, атаки и гейт НЕ запускались — это не приёмка волны 5.9.9.F.3 ==="
    echo "=== ПРЕДПРОГОН №6.0 ЗАВЕРШЁН $(date -u +%H:%M:%S) UTC ==="
    # 5.9.9.F.4c: предпрогон не доходит до idle-часа, поэтому границы окна
    # замера [11/14] не существует — регистрация снимается здесь же, чтобы
    # не оставлять observer-root-pid указывающим на процесс, который вот-вот
    # завершится.
    release_pipeline_observer_root
    touch /root/PIPELINE-6.0-DONE
    exit 0
fi

echo "=== [10/14] база дрейфа: посев known-сигнатуры, досыпание до 3600с от старта агента, доказанное закрытие learning (6.0, риск №1) ==="
# Старая пауза 660с (волна 8) достаточна, чтобы вывести SMOKE/DNS/кольцо за
# окно журнала idle-run, но НЕ достаточна, чтобы profiler.drift_baseline
# (learning_period=3600с, включённый преflight'ом 6.0a) успел закрыть
# обучение до открытия idle-часа — риск №1 постановки 6.0. Ниже — то самое
# доказательство, которое 5.9.9.F.4f требовал и не мог предъявить без
# живого прогона: known-сигнатура сеется собственным контролируемым
# бинарём (не зависит от угадывания реального трафика sshd/cron), а
# промежуток до открытия idle-часа считается от AGENT_START_FILE, а не
# берётся на веру константой.
DRIFT_PC_DIR=/usr/local/bin
DRIFT_PC_BIN="$DRIFT_PC_DIR/drift-pc"
DRIFT_PC_API="http://${VPS_IP:-localhost}:19090"
DRIFT_PC_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
cp /bin/true "$DRIFT_PC_BIN" 2>/dev/null || die "6.0b: не удалось подготовить $DRIFT_PC_BIN для посева known-сигнатуры базовой линии"
chmod +x "$DRIFT_PC_BIN"

echo "--- 6.0b: посев known-сигнатуры drift_exec_from_system_bin (min_samples=20) ---"
release_pipeline_observer_root
for _ in $(seq 1 25); do "$DRIFT_PC_BIN" >/dev/null 2>&1 || true; done
register_pipeline_observer_root
# T_seed — момент, с которого реально идёт отсчёт learning ДЛЯ ЭТОГО
# workload'а. driftbaseline.go:224 ставит prof.startedAt при СОЗДАНИИ профиля,
# то есть на ПЕРВОМ наблюдённом совпадении, а не на старте агента: workload
# comm=drift-pc до этой секунды не существовал. Отсчёт от T0 (agent-start)
# ниже сохранён — он держит своё обещание «idle-час открывается не раньше
# T0+3600с», — но промоушен в enforcing им НЕ обеспечивается.
drift_seed_epoch=$(date -u +%s)
echo "  посеяно 25 exec'ов $DRIFT_PC_BIN (comm=drift-pc) в $(date -u +%H:%M:%S) UTC — MinSamples=20 достигнут заведомо с запасом"
echo "  T_seed (создан профиль drift-pc)=$drift_seed_epoch — learning этого workload'а закроется не раньше T_seed+${DRIFT_LEARNING_PERIOD}с"

# Досыпание остатка до learning_period=3600с от AGENT_START_FILE. Если этот
# шаг сам стартовал позже T0+3600 (долгие предыдущие шаги), remaining <= 0
# и sleep не требуется — но это ЗАПИСЫВАЕТСЯ явно, не проглатывается тихо.
agent_start_epoch=$(date -u -d "$(cat /root/agent-start-6.0.txt)" +%s 2>/dev/null || date -u -j -f "%Y-%m-%d %H:%M:%S" "$(cat /root/agent-start-6.0.txt)" +%s 2>/dev/null)
[ -n "$agent_start_epoch" ] || die "6.0: не удалось разобрать /root/agent-start-6.0.txt ($(cat /root/agent-start-6.0.txt 2>/dev/null)) — без T0 остаток до learning_period=3600с не вычисляется, риск №1 постановки 6.0 не закрыт"
now_epoch=$(date -u +%s)
elapsed=$((now_epoch - agent_start_epoch))
# Целимся не в learning_period, а в ДЕДЛАЙН: к открытию idle-часа обучение
# должно быть закрыто у ВСЕХ нагрузок, включая те, что не набрали min_samples
# (их промоутит только ветка enforceDeadline). Замер №6.0 целился в
# learning_period=3600 и получил 13 stuck-нагрузок в измеряемом часе.
remaining=$((DRIFT_DEADLINE_SEC - elapsed))
echo "  T0 (агент поднят)=$(cat /root/agent-start-6.0.txt) UTC, прошло ${elapsed}с, до дедлайна T0+${DRIFT_DEADLINE_SEC}с осталось ${remaining}с"
if [ "$remaining" -gt 0 ]; then
    echo "  досыпаю ${remaining}с, чтобы открытие idle-часа было НЕ РАНЬШЕ T0+${DRIFT_DEADLINE_SEC}с ($(date -u +%H:%M:%S) UTC)"
    sleep "$remaining"
else
    echo "  ВНИМАНИЕ: до шага [10/14] уже прошло ${elapsed}с (>=${DRIFT_DEADLINE_SEC}с) без дополнительного сна — предыдущие шаги сами заняли дольше дедлайна; остаток отрицательный, это не ошибка, а более длинный прогон, чем обычно"
fi

# 660с наследия волны 8 остаются НЕ отменёнными: они всё ещё нужны, чтобы
# SMOKE/DNS/кольцо/CPU-давление точно вышли за окно журнала idle-run, и
# теперь это гарантированное МИНИМУМ, а не единственное ожидание.
sleep 660

echo "--- 6.0b (продолжение): контрольный exec той же known-сигнатуры, чтобы Observe() зафиксировал переход в enforcing ---"
# Промоушен learning->enforcing происходит ВНУТРИ Observe(), не по таймеру
# в фоне — событию нужно физически прийти ПОСЛЕ T0+3600с, чтобы agент
# увидел elapsed>=learning_period И sampleCount>=min_samples одновременно.
# Досыпание до T_seed+3600с. Без него шаг держался на невысказанном
# допущении «от рестарта [5/14] до посева проходит меньше 660с»: контрольный
# exec приходит в T0+learning_period+660, профиль создан в T0+d, его elapsed =
# learning_period+660-d, и условие elapsed>=learning_period верно ТОЛЬКО при
# d<=660. На замере №2.9.9.F.8 шаги
# [5/14]→[10/14] заняли d=520с — запас был 140с, а провал вылезал бы через
# ~75 минут прогона, на 6.0.4, уже после часа ожидания. Здесь допущение
# снято: ждём по T_seed, сколько бы ни занял участок выше.
drift_promo_target=$((drift_seed_epoch + DRIFT_LEARNING_PERIOD + 30))
drift_promo_wait=$((drift_promo_target - $(date -u +%s)))
if [ "$drift_promo_wait" -gt 0 ]; then
    echo "  до T_seed+${DRIFT_LEARNING_PERIOD}с осталось ${drift_promo_wait}с — досыпаю перед контрольным exec'ом"
    sleep "$drift_promo_wait"
else
    echo "  T_seed+${DRIFT_LEARNING_PERIOD}с уже прошёл ($((-drift_promo_wait))с назад) — досыпание не требуется"
fi
release_pipeline_observer_root
# Три exec'а, а не один: промоушен случается ВНУТРИ Observe(), поэтому нужен
# факт доставки события. Единственный exec, потерянный на сэмплировании или
# переполнении кольца, стоил бы всего прогона на 6.0.4.
for _ in 1 2 3; do "$DRIFT_PC_BIN" >/dev/null 2>&1 || true; sleep 1; done
sleep 20
register_pipeline_observer_root

echo "--- 6.0: состояние базовой линии на момент открытия idle-часа (критерий 6.0.4) ---"
drift_status_json=$(curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/status" 2>/dev/null)
drift_learning=$(echo "$drift_status_json" | jq -r '.health.drift_learning_workloads // empty' 2>/dev/null)
drift_stuck=$(echo "$drift_status_json" | jq -r '.health.drift_stuck_workloads // empty' 2>/dev/null)
drift_profiles=$(echo "$drift_status_json" | jq -r '.health.drift_profiles_active // empty' 2>/dev/null)
echo "  drift_learning_workloads=${drift_learning:-?} drift_stuck_workloads=${drift_stuck:-?} drift_profiles_active=${drift_profiles:-?} ($(date -u +%H:%M:%S) UTC)"
[ -n "$drift_profiles" ] && [ -n "$drift_learning" ] \
    || die "6.0.4: GET /api/v1/status не отдал health.drift_profiles_active/drift_learning_workloads — состояние базовой линии не напечатано, критерий 6.0.4 не засчитывается"
[ "${drift_profiles:-0}" -ge 1 ] \
    || die "6.0.4 ПРОВАЛЕН: drift_profiles_active=0 — ни один workload не выучен, включая наш собственный посев drift-pc; profiler.drift_baseline либо не подхвачен рестартом [5/14], либо посев выше не дошёл до коллектора"
[ "${drift_profiles:-0}" -gt "${drift_learning:-0}" ] \
    || die "6.0.4 ПРОВАЛЕН: ни один из $drift_profiles профилей не в enforcing (drift_learning_workloads=$drift_learning >= drift_profiles_active=$drift_profiles) — посев drift-pc должен был перейти в enforcing к этому моменту (T_seed+${DRIFT_LEARNING_PERIOD}с+30с, досыпание выше), напечатанное состояние не доказывает закрытие learning (риск №1 постановки 6.0)"

# Разрез по нагрузке (добавлен после разбора №6.0). Неравенство выше говорит
# лишь «какой-то профиль вышел из learning», а печаталось при этом «наш посев
# drift-pc в enforcing» — на №6.0 это разошлось: контроль 6.0.3 упал через 70
# минут, и die-сообщение вынуждено было перечислять две гипотезы, потому что
# различить их было нечем. Теперь состояние берётся поимённо.
drift_state_json=$(curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/debug/state" 2>/dev/null)
echo "$drift_state_json" | jq -e '.drift_baseline.workloads' >/dev/null 2>&1 \
    || die "6.0.4: GET /debug/state не отдал drift_baseline.workloads — разреза базовой линии по нагрузке нет, значит бинарь собран без правки наблюдаемости 6.0 (или drift_baseline выключен), и утверждение «наш посев в enforcing» опять недоказуемо"
# Число сигнатур на нагрузку — это ещё и ПРОГНОЗ будущего объёма алертов:
# после правки «сообщать один раз» поток дрейфа равен числу НОВЫХ сигнатур в
# час, а не частоте их исполнения, так что размер выученной базы и скорость
# роста reported говорят, чего ждать от 6.0.1, ДО того как час пройдёт.
echo "  состояние базовой линии по нагрузкам (state / сигнатур / сэмплов / сообщено / saturated):"
echo "$drift_state_json" | jq -r '.drift_baseline.workloads[] | "    \(.comm)\t\(.state)\tsig=\(.signatures)\tsamples=\(.samples)\treported=\(.reported)\tsat=\(.saturated)"'
# Постановка №6.0d называет это «неизвестным, названным до прогона», и
# требует читать его ПЕРВЫМ: глобальная резервная база (№193а) видит
# сигнатуры всех нагрузок сразу и упирается в max_signatures_per_workload
# раньше любой отдельной. Если она насытилась ДО открытия idle-часа,
# механизм (а) выродился в «алертить на всё незнакомое», и объём 6.0.8
# отражает насыщение, а не дрейф. Печатается величиной, а не порогом:
# запрет 5.9.6 (порог не назначается на том же замере, где величина
# впервые измерена) действует и здесь.
echo "  насыщение базовых линий на открытии idle-часа (6.0d): saturated_profiles=$(echo "$drift_state_json" | jq -r '.drift_baseline.saturated'), из них глобальная=$(echo "$drift_state_json" | jq -r '[.drift_baseline.workloads[] | select(.state=="global") | .saturated] | if length == 0 then "нет глобального профиля" else .[0] end'), сигнатур в глобальной=$(echo "$drift_state_json" | jq -r '[.drift_baseline.workloads[] | select(.state=="global") | .signatures] | if length == 0 then "-" else .[0] end') из ${DRIFT_MAX_SIGS:-256}"
drift_pc_state=$(echo "$drift_state_json" | jq -r '.drift_baseline.workloads[] | select(.comm=="drift-pc") | .state' 2>/dev/null | head -1)
[ -n "$drift_pc_state" ] \
    || die "6.0.4 ПРОВАЛЕН: в /debug/state нет нагрузки comm=drift-pc — посев [10/14] не дошёл до коллектора (или дерево измерителя его срезало), и контроль 6.0.3 ниже будет мерить пустое место"
[ "$drift_pc_state" = "enforcing" ] \
    || die "6.0.4 ПРОВАЛЕН: нагрузка comm=drift-pc в состоянии '$drift_pc_state', а не enforcing, к открытию idle-часа — досыпание до T_seed+${DRIFT_LEARNING_PERIOD}с своё обещание не выполнило; позитивный контроль 6.0.3 в окне атаки мерил бы обучение, а не базовую линию (риск №1 постановки 6.0)"
# Глобальная резервная база (№193а) появляется в том же списке отдельной
# строкой state=global и НЕ является нагрузкой: у неё нет ни дедлайна, ни
# промоушена. Считать её «нагрузкой вне enforcing» значило бы прибавлять
# ровно единицу к обеим величинам на каждом прогоне и сделать ряд
# несравнимым с «13 из 21» замера №6.0.
drift_stuck_state=$(echo "$drift_state_json" | jq -r '[.drift_baseline.workloads[] | select(.state!="enforcing" and .state!="global")] | length')
drift_wl_total=$(echo "$drift_state_json" | jq -r '[.drift_baseline.workloads[] | select(.state!="global")] | length')
echo "  нагрузок вне enforcing на открытии idle-часа: ${drift_stuck_state} из ${drift_wl_total} (замер №6.0: 13 из 21 — все они были слепы весь измеряемый час)"
echo "  разрез learning/stuck/overdue (6.0d, №198 — overdue промоутится обходом, а не следующим совпадением): $(echo "$drift_state_json" | jq -r '[.drift_baseline.workloads[] | select(.state!="enforcing" and .state!="global") | .state] | group_by(.) | map("\(.[0])=\(length)") | join(" ")')"

# Преflight 6.0d, пункт 2/4: наличие глобального профиля (№193а) в
# /debug/state. Тот же снимок уже снят для 6.0.4 выше — второй запрос не
# нужен. Без него правка №193 недоказуема живьём: код мог остаться
# закомментированным, а посев comm=drift-pc сам по себе не отличает
# "выучился по своей нагрузке" от "выучился ещё и в глобальной базе".
drift_global_state=$(echo "$drift_state_json" | jq -r '.drift_baseline.workloads[] | select(.comm=="*global*") | .state' 2>/dev/null | head -1)
[ "$drift_global_state" = "global" ] \
    || die "преflight 6.0d: в /debug/state нет записи comm=\"*global*\" state=\"global\" — глобальная резервная база (№193а) не подхватилась (либо per_workload: false, при котором глобальный профиль вырожден в единственный обычный, либо правка driftbaseline.go откатилась); правка (б) без (а) не закрывает находку №193 целиком, см. plan.md 6.0d п.4"
echo "  ок (преflight 6.0d): глобальная резервная база присутствует в /debug/state (comm=\"*global*\", state=global)"
# Критерий 6.0.9 (волна 6.0d, находка №197): расщепление нагрузки на pre-exec
# `comm` снято. Ядро в окне до execve отдаёт comm в обрамляющих скобках
# ("(find)"), и до правки такой процесс попадал в ОТДЕЛЬНЫЙ WorkloadKey — то
# есть выборка дробилась ровно на самом привилегированном участке, где
# процесс вот-вот станет тем, чем его выбрал стать атакующий.
# WorkloadKeyFromEvent теперь снимает скобки (только в КЛЮЧЕ; в алерте и
# событии comm остаётся сырым — сам факт «до execve» не теряется), поэтому в
# ЭТОЙ таблице, которая печатает именно ключи, скобок быть не должно ни у
# одной строки. Величина запоминается здесь и выносится вердиктом в приёмку
# (16.9): сама по себе она не повод убивать прогон перед idle-часом.
DRIFT_PAREN_COMMS=$(echo "$drift_state_json" | jq -r '.drift_baseline.workloads[] | .comm' 2>/dev/null | grep -E '^\(.*\)$' | sort -u | tr '\n' ' ')
if [ -n "${DRIFT_PAREN_COMMS// /}" ]; then
    echo "  6.0.9: comm В СКОБКАХ в таблице базовой линии: $DRIFT_PAREN_COMMS — stripPreExecCommParens не применяется к ключу нагрузки (находка №197 не закрыта)"
else
    echo "  6.0.9: comm в обрамляющих скобках в таблице базовой линии: нет ни одного — расщепление нагрузки на pre-exec comm снято (№197)"
fi
echo "6.0.4 доказан живьём: наш посев comm=drift-pc в состоянии enforcing к открытию idle-часа, установлено поимённо, а не по неравенству агрегатов"

echo "=== [11/14] idle-час, NO_RESTART=1 (5.9.1c) — сокращать нельзя ==="
# 5.9.9.F.4c (№147): граница окна замера — дерево ПАЙПЛАЙНА обнуляется
# явно здесь, ДО старта idle-run.sh, а не полагается на то, что
# idle-run.sh перезапишет файл своим $$ (это тоже произойдёт, но неявная
# зависимость от порядка записи — не гарантия: постановка 4c требует
# явного обнуления на границе, не переиспользования чужого побочного
# эффекта). idle-run.sh регистрирует СВОЙ, гораздо более узкий корень
# (только собственный поллинг curl) сразу вслед за этим.
release_pipeline_observer_root
# Час — не запас прочности: FP grafana наблюдался ровно один раз за idle-час
# (период резолва порядка часа, не измерен). Окно короче застало бы «0
# long-label» отсутствием, а не починкой — тот PASS отсутствием, который
# 5.9.6i запретила.
cd $SETUP
OUT_DIR=$IDLE_OUT DURATION=3600 INTERVAL=300 NO_RESTART=1 bash ./idle-run.sh
echo "idle завершён в $(date -u +%H:%M:%S) UTC"

echo "=== [12/14] атаки — без разрыва цепочки, сразу за idle, без ssh между ними ==="
export IDLE_METRICS_START=$IDLE_OUT/metrics-start.txt
export IDLE_STATE_END=$IDLE_OUT/state-end.json
cd $SETUP/attacks
bash ./run-all-attacks.sh || echo "run-all-attacks.sh вернул $? — гейт всё равно считаем"
echo "атаки завершены в $(date -u +%H:%M:%S) UTC"
ls -t $SETUP/attacks/attack-results/attack-window-*.txt 2>/dev/null | head -1 | xargs -r cat | sed 's/^/  окно атаки (5.9.7d): /'

echo "--- 6.0c: позитивный контроль базовой линии в окне атаки — заведомо новая сигнатура у УЖЕ enforcing workload (критерий 6.0.3) ---"
# Шаг [10/14] доказал, что comm=drift-pc перешёл в enforcing ДО открытия
# idle-часа. Здесь — тот самый вопрос постановки 6.0, ради которого весь
# посев затевался: правило живо для НОВОГО бинаря того же workload, а не
# просто перестало алертить вовсе. Тот же comm (basename "drift-pc",
# WorkloadKey совпадает с посевом [10/14]), другой полный путь под тем же
# префиксом /usr/local/bin/ условия правила — driftSignatureTarget для
# event_type: syscall теперь фолдит proc.args (правка internal/profiler/
# driftbaseline.go, найдена при проектировании этого самого контроля:
# раньше сигнатура syscall-события была ГОЛЫМ номером execve, одинаковым
# для любого бинаря — воркload, обучившийся один раз, глушил бы себя
# НАВСЕГДА для всех последующих бинарей, включая настоящую атаку).
# rule_id + comm, ДО/ПОСЛЕ, тем же приёмом, что cred_proc_maps_mass_read на
# шаге [9.5/14] — не message/pid-матчинг: rule.Description статичен для
# всех срабатываний правила (Alert.Message = rule.Description, rules.go),
# так что сообщение не несёт исполненный путь и не годится для отбора.
# Ожидаемое ДО = 0: и посев [10/14] (25 execов), и exec, зафиксировавший
# переход в enforcing, оба пришлись на learning-фазу и были подавлены
# Observe() ДО публикации в стор (учится -> return false раньше
# добавления в alerts-стор) — 6.0.3 в норме измеряет чистый переход 0->1.
DRIFT_PC2_DIR=/usr/local/bin/drift-pc-attack-window
mkdir -p "$DRIFT_PC2_DIR" 2>/dev/null || die "6.0c: не удалось создать $DRIFT_PC2_DIR"
DRIFT_PC2_BIN="$DRIFT_PC2_DIR/drift-pc"
cp /bin/true "$DRIFT_PC2_BIN" 2>/dev/null || die "6.0c: не удалось подготовить $DRIFT_PC2_BIN"
chmod +x "$DRIFT_PC2_BIN"
_drift_pc2_count() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm=="drift-pc")]|length' 2>/dev/null || echo 0
}
# 6.0j/№209 (сторож п.2 волны): контроль читает правило с `field: proc.args`,
# значит обязан печатать сам proc.args из полученного алерта. Иначе ноль
# контроля неотличим от proc.args, обнулённого коллектором (commMatchesArgv0),
# — то есть от приборного нуля, которым замер №6.0f2 убил шаг 6.0g.
_drift_pc2_args() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq -r '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm=="drift-pc")] | if length == 0 then "<алертов правила под comm=drift-pc нет>" else (sort_by(.timestamp) | .[-1].details["proc.args"] // "<поля нет в алерте>") end' 2>/dev/null \
        || echo "<не удалось прочитать /api/v1/alerts>"
}
_drift_pc2_before=$(_drift_pc2_count)
"$DRIFT_PC2_BIN" >/dev/null 2>&1 || true
sleep 20
_drift_pc2_after=$(_drift_pc2_count)
echo "  позитивный контроль: exec $DRIFT_PC2_BIN (comm=drift-pc, известный workload, новая сигнатура) -> drift_exec_from_system_bin{comm=drift-pc}: ${_drift_pc2_before:-0} -> ${_drift_pc2_after:-0} ($(date -u +%H:%M:%S) UTC)"
echo "  6.0.3 proc.args последнего алерта: $(_drift_pc2_args) (ожидается $DRIFT_PC2_BIN; сторож п.2 волны 6.0j/№209 — пустое или отсутствующее поле означает приборный ноль, а не подавление базовой линией)"
if [ "$((${_drift_pc2_after:-0} - ${_drift_pc2_before:-0}))" -lt 1 ]; then
    # Находка №196 (6.0d): исход 6.0.3 пишется в файл, переживающий отдельно
    # от gate-6.0.txt (создаётся позже, на шаге [11/14], этого контроля не
    # касается) — переопределённый пол 6.0.5 (ниже, "16.5") читает именно
    # его, и то же самое понадобится будущему офлайн-реплею на архиве: сам
    # die() ниже долговечен только если оператор запускал скрипт с
    # перенаправлением стдаута в сохранённый лог.
    echo "6.0.3 FAIL $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    die "6.0.3 ПРОВАЛЕН: exec нового бинаря $DRIFT_PC2_BIN тем же comm=drift-pc, что уже enforcing с шага [10/14], не дал ни одного нового срабатывания drift_exec_from_system_bin (было ${_drift_pc2_before:-0}, стало ${_drift_pc2_after:-0}) — либо базовая линия свернула правило в постоянную тишину для этого workload'а (регрессия сигнатуры syscall-события), либо посев [10/14] и контроль здесь разошлись комм-именами"
fi
echo "6.0.3 PASS $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.3 доказан живьём в $(date -u +%H:%M:%S) UTC: правило живо для новой сигнатуры уже enforcing workload'а"
rm -rf "$DRIFT_PC2_DIR" "$DRIFT_PC_BIN"

echo "--- 6.0e: контроли на НОВУЮ нагрузку — опасный примитив от невиданного comm (критерии 6.0.6 и 6.0.7) ---"
# Буква `d` пропущена так же и по той же причине, по которой её пропустила
# сама волна: `6.0d` — имя ВОЛНЫ, а этот файл грепается буквально (см. разбор
# в plan.md, «Почему волна названа 6.0d, а не 6.0c»). Завести шаг с именем
# волны значило бы создать вторую сущность с тем же именем в файле, по
# которому criteria-index.txt резолвит паттерны.
#
# Чем этот контроль ОТЛИЧАЕТСЯ от 6.0.3 выше и зачем нужен отдельно.
# 6.0.3 спрашивает: жива ли базовая линия для новой сигнатуры УЖЕ ОБУЧЕННОЙ
# нагрузки. Находка №193 — про противоположный случай: нагрузку, которой
# профайлер никогда не видел. До волны 6.0d фаза learning подавляла её
# совпадения БЕЗУСЛОВНО, то есть атакующий, пришедший под новым comm (а
# атака нова по определению), получал презумпцию невиновности ровно на тех
# примитивах, ради которых правило существует. 6.0.6 проверяет, что этой
# презумпции больше нет; 6.0.7 — что 6.0.6 доказывает НОВИЗНУ, а не просто
# факт вызова (иначе контроль прошёл бы и на сломанной базовой линии,
# которая алертит на всё подряд, — ровно то, чем 6.0.5 был непроходим до
# переопределения).
DRIFT_NW_COMM="dnw-$(head -c 4 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')"
# comm в ядре — TASK_COMM_LEN=16 с NUL, то есть 15 значащих символов;
# "dnw-" + 8 hex = 12, с запасом. Случайность на каждый прогон и есть
# гарантия «ранее не встречавшегося» comm: реестра прошлых comm нет и
# заводить его не нужно.
[ "${#DRIFT_NW_COMM}" -le 15 ] || die "6.0e: сгенерированный comm '$DRIFT_NW_COMM' длиннее 15 символов — ядро усечёт его, и отбор алертов по comm разойдётся с посевом"
DRIFT_NW_SRC=$(command -v unshare 2>/dev/null)
[ -n "$DRIFT_NW_SRC" ]     || die "6.0e: на стенде нет unshare(1) (util-linux) — контроль 6.0.6 нечем исполнить. Поставить util-linux; без него правка №193 не проверяется живьём и волна 6.0d не может быть закрыта (критерий 6.0.6 — обязательный, не наблюдение)"
DRIFT_NW_DIR=/usr/local/bin/drift-novel-workload
mkdir -p "$DRIFT_NW_DIR" 2>/dev/null || die "6.0e: не удалось создать $DRIFT_NW_DIR"
DRIFT_NW_BIN="$DRIFT_NW_DIR/$DRIFT_NW_COMM"
cp "$DRIFT_NW_SRC" "$DRIFT_NW_BIN" 2>/dev/null || die "6.0e: не удалось подготовить $DRIFT_NW_BIN из $DRIFT_NW_SRC"
chmod +x "$DRIFT_NW_BIN"

# Один вызов даёт ОБА примитива подмножества (б) от нашего comm:
#   unshare(CLONE_NEWUSER|CLONE_NEWNS) — сам unshare(2);
#   mount(..., MS_REC|MS_PRIVATE, ...) — util-linux делает его сам сразу
#   после unshare(2) при --mount (см. --propagation, дефолт private).
# Постановка называет вторым примитивом mount(MS_BIND). Взят MS_REC|MS_PRIVATE,
# а не MS_BIND, сознательно: MS_BIND через `unshare --mount=<файл>` оставляет
# ПЕРСИСТЕНТНЫЙ namespace, привязанный к файлу, и требует umount в откате —
# лишняя точка отказа внутри окна замера. Критерий 6.0.6 сформулирован на
# правиле drift_dangerous_syscall и на совпадении comm, а не на конкретном
# флаге mount: обе комбинации проходят через driftSyscallArgSpecs одинаково
# (165 -> mountFlagNames(a[3])) и обе новы для невиданной нагрузки. Отличие
# зафиксировано здесь, чтобы в архиве не пришлось гадать, почему в логе
# MS_PRIVATE, а в постановке MS_BIND.
_drift_nw_count() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq --arg c "$DRIFT_NW_COMM" '[.[]|select(.rule_id=="drift_dangerous_syscall" and .comm==$c)]|length' 2>/dev/null || echo 0
}
_drift_nw_limited() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_alerts_ratelimited_by_rule_total\{/ && /rule_id="drift_dangerous_syscall"/ { s += $NF } END { printf "%d", s+0 }'
}
_drift_nw_suppressed() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_drift_baseline_suppressed_total\{/ && /reason="already_reported"/ && /rule_id="drift_dangerous_syscall"/ { s += $NF } END { printf "%d", s+0 }'
}

# Сторож ложного нуля (память находки №101/«позитивный контроль по
# результату»). run-all-attacks.sh прямо перед этим шагом исполняет
# `unshare -U true` (позитивный контроль 5.9.9c) и весь блок container-escape,
# а drift_dangerous_syscall с волны 6.0d перестала быть немой — то есть
# per-rule лимитер (10 алертов/правило/60 с) может быть выбран ДО нашего
# вызова, и наш единственный алерт был бы срезан. Ноль по этой причине
# неотличим от нуля по причине «правка №193 не работает» — а стоит он
# целого замера. Поэтому: считаем срез лимитера тем же ДО/ПОСЛЕ, и при
# нулевом приросте алертов с НЕНУЛЕВЫМ приростом среза даём окну лимитера
# стечь (60 с + запас) и повторяем ОДИН раз. Повтор безопасен для 6.0.7
# ниже: он сравнивает с _drift_nw_after, то есть с состоянием после
# фактически зачтённой попытки, какой бы она ни была по счёту.
_drift_nw_attempt() {
    "$DRIFT_NW_BIN" --user --map-root-user --mount --propagation private -- /bin/true >/dev/null 2>&1 || true
    sleep 20
}
_drift_nw_before=$(_drift_nw_count)
_drift_nw_lim_before=$(_drift_nw_limited)
_drift_nw_attempt
_drift_nw_after=$(_drift_nw_count)
_drift_nw_lim_after=$(_drift_nw_limited)
echo "  6.0.6 позитивный контроль: $DRIFT_NW_BIN (comm=$DRIFT_NW_COMM — нагрузка, которой профайлер никогда не видел) unshare(CLONE_NEWUSER|CLONE_NEWNS)+mount(MS_REC|MS_PRIVATE) -> drift_dangerous_syscall{comm=$DRIFT_NW_COMM}: ${_drift_nw_before:-0} -> ${_drift_nw_after:-0}, срез лимитера правила ${_drift_nw_lim_before:-0} -> ${_drift_nw_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
if [ "$((${_drift_nw_after:-0} - ${_drift_nw_before:-0}))" -lt 1 ] \
   && [ "$(( ${_drift_nw_lim_after:-0} - ${_drift_nw_lim_before:-0} ))" -gt 0 ]; then
    echo "  6.0.6: ноль алертов ПРИ выросшем срезе лимитера (+$(( ${_drift_nw_lim_after:-0} - ${_drift_nw_lim_before:-0} ))) — это приборный ноль, а не вердикт о детекторе. Даём окну лимитера (60 с) стечь и повторяем один раз"
    sleep 70
    _drift_nw_before=$(_drift_nw_count)
    _drift_nw_lim_before=$(_drift_nw_limited)
    _drift_nw_attempt
    _drift_nw_after=$(_drift_nw_count)
    _drift_nw_lim_after=$(_drift_nw_limited)
    echo "  6.0.6 повтор после стекания окна лимитера: алертов ${_drift_nw_before:-0} -> ${_drift_nw_after:-0}, срез ${_drift_nw_lim_before:-0} -> ${_drift_nw_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
fi
if [ "$((${_drift_nw_after:-0} - ${_drift_nw_before:-0}))" -lt 1 ]; then
    echo "6.0.6 FAIL $(date -u +%FT%TZ) comm=$DRIFT_NW_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$DRIFT_NW_DIR"
    die "6.0.6 ПРОВАЛЕН: опасный примитив (unshare CLONE_NEWUSER + mount) от НИКОГДА не виденной нагрузки comm=$DRIFT_NW_COMM не дал ни одного алерта drift_dangerous_syscall (было ${_drift_nw_before:-0}, стало ${_drift_nw_after:-0}). Это ровно находка №193: фаза learning новой нагрузки по-прежнему подавляет примитив побега. Смотреть в порядке: (1) несёт ли drift_dangerous_syscall флаг drift_novel_workload: alert — преflight 6.0d это проверяет статически, значит проводка Rule -> Alert -> ObserveRule оборвалась в бинаре, а не в YAML; (2) есть ли в /debug/state запись comm=\"*global*\" (правка №193а); (3) дошло ли событие до движка вообще — 272/165 в kernel-allowlist (internal/bpf/sampling.go). Срез лимитера за эту попытку: +$(( ${_drift_nw_lim_after:-0} - ${_drift_nw_lim_before:-0} )) — если он ненулевой ПОСЛЕ повтора, причина приборная (лимитер), а не продуктовая"
fi
echo "6.0.6 PASS $(date -u +%FT%TZ) comm=$DRIFT_NW_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.6 доказан живьём в $(date -u +%H:%M:%S) UTC: новая нагрузка НЕ получила презумпцию невиновности на примитиве побега (находка №193 закрыта)"

# 6.0.7 — негативный контроль к 6.0.6. Тот же бинарь, тот же comm, тот же
# примитив, повторно. Без него 6.0.6 доказывал бы только «правило умеет
# срабатывать», что верно и для детектора, алертящего на КАЖДЫЙ вызов, —
# а тогда цена решения (б) была бы неограниченной, и объём 6.0.8 ниже мерил
# бы частоту исполнения, а не дрейф. Ожидание: 0 новых алертов, прирост
# уходит в suppressed_total{reason="already_reported"} (правка «сообщать
# один раз»).
_drift_nw_rep_before=$(_drift_nw_suppressed)
"$DRIFT_NW_BIN" --user --map-root-user --mount --propagation private -- /bin/true >/dev/null 2>&1 || true
sleep 20
_drift_nw_after2=$(_drift_nw_count)
_drift_nw_rep_after=$(_drift_nw_suppressed)
echo "  6.0.7 негативный контроль: повтор того же примитива тем же comm=$DRIFT_NW_COMM -> алертов ${_drift_nw_after:-0} -> ${_drift_nw_after2:-0}, already_reported ${_drift_nw_rep_before:-0} -> ${_drift_nw_rep_after:-0} ($(date -u +%H:%M:%S) UTC)"
if [ "$((${_drift_nw_after2:-0} - ${_drift_nw_after:-0}))" -ne 0 ]; then
    echo "6.0.7 FAIL $(date -u +%FT%TZ) comm=$DRIFT_NW_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$DRIFT_NW_DIR"
    die "6.0.7 ПРОВАЛЕН: повтор ТОГО ЖЕ примитива тем же comm=$DRIFT_NW_COMM дал $((${_drift_nw_after2:-0} - ${_drift_nw_after:-0})) новых алертов вместо 0 — 'сообщать один раз' не работает для подмножества drift_novel_workload, и 6.0.6 выше доказал факт вызова, а не его новизну. Цена решения (б) в этом случае пропорциональна частоте исполнения примитива, и величина 6.0.8 непригодна для назначения порога"
fi
echo "6.0.7 PASS $(date -u +%FT%TZ) comm=$DRIFT_NW_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.7 доказан живьём в $(date -u +%H:%M:%S) UTC: повторный вызов молчит — 6.0.6 доказывает новизну, а не факт вызова"
rm -rf "$DRIFT_NW_DIR"

echo "--- 6.0g: контроли механизма (а) — глобальный фоллбэк базовой линии (критерии 6.0.11 и 6.0.12, №203) ---"
# Буква f пропущена по той же причине, что и d выше: 6.0f — имя ВОЛНЫ, файл
# грепается буквально.
#
# Отличие от 6.0.6/6.0.7 выше: те контроли бьют по подмножеству (б)
# (drift_novel_workload: alert — три правила из ~600). Эти два бьют по
# механизму (а) — глобальному резервному фоллбэку (driftbaseline.go, поле
# `global`), который защищает ВСЕ правила класса drift без явного флага.
# Взято правило drift_exec_from_system_bin сознательно: у него флага (б)
# нет (rules/drift-rules.yaml), значит любое подавление здесь идёт через
# путь per-workload learning + global fallback, а не через обход learning.
#
# Сигнатура правила — "<nr>|<normalizeDriftPath(argv0)>" (driftSignatureTarget),
# а WorkloadKey.Comm — БАЗОВОЕ ИМЯ РЕАЛЬНОГО exec'нутого файла (ядро
# переписывает comm при execve на новый образ). Обоим критериям нужно одно:
# ОДНА нагрузка (один comm, невиданная на момент 6.0.11) и ДВЕ различные
# сигнатуры — одна посеянная и повторённая, вторая не встречавшаяся никогда.
#
# 6.0j/№209 (замер 01.09 умер здесь ПОСЛЕ idle-часа). До этой правки шаг
# добывал две сигнатуры под одним comm через
# `bash -c "exec -a '<argv0>' '<реальный_файл>'"` и называл расхождение
# argv[0] с именем образа «осью разъезда». Расхождение здесь не нужно ни
# одному из двух критериев — и именно оно их и убивало: в коллекторе на этой
# оси стоит сверка commMatchesArgv0 (internal/collector/syscall.go), которая
# при `basename(argv[0])`, не начинающемся с comm, ОБНУЛЯЕТ event.ProcArgs.
# Execve даёт две записи (sys_enter с comm вызывающего, sys_exit с comm
# нового образа), и под спуфом не проходила НИ ОДНА:
#     sys_enter  comm=bash            basename(argv0)=<hex>  -> не совпало
#     sys_exit   comm=dnw2-<hex>      basename(argv0)=<hex>  -> не совпало
# proc.args пуст -> drift_exec_from_system_bin (условие proc.args prefix) не
# матчит никогда -> все четыре нуля разом (алерты 0, счётчик 0, samples 0,
# нагрузки нет в /debug/state). Это приборный ноль, который постановка 6.0.11
# запрещает засчитывать, и первая из трёх формулировок её же die-сообщения.
# Механизм (а) при этом исправен (driftbaseline.go: learning + globalKnown ->
# reason="global_baseline_known"); ошибка была целиком в контроле.
#
# Спуф убран: контроль кладёт ДВА РЕАЛЬНЫХ ФАЙЛА с именем, равным comm, в два
# разных каталога под /usr/local/bin/ и зовёт их напрямую. comm у обоих один
# и тот же (имя файла), argv[0] равен полному пути (bash передаёт слово
# команды как argv[0] дословно) — сверка проходит на sys_exit-записи, а
# сигнатуры (normalizeDriftPath(argv0), с волны 6.0 путь не усекается по
# глубине) различны, потому что различны каталоги.
# Спуф argv[0] сам по себе остаётся предметом измерения — но своего,
# отдельного контроля 6.0.16 (шаг 6.0k), а не этого.
DRIFT_G_HEX=$(head -c 4 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')
DRIFT_G_COMM="dnw2-$DRIFT_G_HEX"
[ "${#DRIFT_G_COMM}" -le 15 ] || die "6.0g: сгенерированный comm '$DRIFT_G_COMM' длиннее 15 символов — ядро усечёт его, и отбор алертов по comm разойдётся с посевом"

# Два каталога, один и тот же базовый файл в обоих: имя файла = comm, полный
# путь = argv[0] = сигнатура. Каталог посева и каталог невиданной сигнатуры
# разведены, поэтому сигнатуры различны при одном comm.
DRIFT_G_SEEDDIR=/usr/local/bin/dnw2-seed
DRIFT_G_NOVELDIR=/usr/local/bin/dnw2-novel
mkdir -p "$DRIFT_G_SEEDDIR" 2>/dev/null || die "6.0g: не удалось создать $DRIFT_G_SEEDDIR"
mkdir -p "$DRIFT_G_NOVELDIR" 2>/dev/null || die "6.0g: не удалось создать $DRIFT_G_NOVELDIR"
DRIFT_G_SEEDBIN="$DRIFT_G_SEEDDIR/$DRIFT_G_COMM"
DRIFT_G_NOVELBIN="$DRIFT_G_NOVELDIR/$DRIFT_G_COMM"
# 6.0g/№208 (замер 01.09, стоп в окне атак): здесь стояло
# `DRIFT_G_TRUE=$(command -v true)`. На bash `true` — BUILTIN, и command -v
# отдаёт ГОЛОЕ ИМЯ без пути (`type -P true` пуст на этом же bash), поэтому
# `cp true …` падал, и шаг умирал через die ПОСЛЕ отработавшего idle-часа —
# замер терял окно целиком. Это буквально находка №176 (5.9.9.F.7a),
# стоившая двух замеров и разобранная в шапке этого же файла: сторож 7a
# запрещает конструкцию, но смотрит ТОЛЬКО в run-all-attacks.sh, а 6.0g
# завела её в самом пайплайне. Нужен абсолютный путь до РЕАЛЬНОГО файла.
DRIFT_G_TRUE=""
for _dg_cand in /usr/bin/true /bin/true; do
    if [ -f "$_dg_cand" ] && [ -x "$_dg_cand" ]; then DRIFT_G_TRUE="$_dg_cand"; break; fi
done
[ -n "$DRIFT_G_TRUE" ] \
    || die "6.0g: ни /usr/bin/true, ни /bin/true не оказались исполняемым обычным файлом — посев нагрузки нечем собрать, брать builtin нельзя (находка №176)"
for _dg_bin in "$DRIFT_G_SEEDBIN" "$DRIFT_G_NOVELBIN"; do
    cp "$DRIFT_G_TRUE" "$_dg_bin" 2>/dev/null || die "6.0g: не удалось подготовить $_dg_bin из $DRIFT_G_TRUE"
    chmod +x "$_dg_bin" || die "6.0g: не удалось сделать $_dg_bin исполняемым"
    [ -x "$_dg_bin" ] || die "6.0g: $_dg_bin не исполняем после chmod (noexec на /usr/local?) — execve упадёт с EACCES ДО смены comm, и оба критерия получат ложный ноль (класс находки №176)"
done
# argv[0] для 6.0.11 — путь, который сеется и затем переисполняется тем же
# comm ни разу не встречавшимся. "/usr/local/bin/" в префиксе обязателен —
# без него drift_exec_from_system_bin (proc.args prefix) не сматчит вовсе.
# argv[0] для 6.0.12 — путь, которого на хосте не было никогда: каталог создан
# этим шагом, hex случаен на каждый прогон.
DRIFT_G_SIG_ARGV0="$DRIFT_G_SEEDBIN"
DRIFT_G_NOVEL_ARGV0="$DRIFT_G_NOVELBIN"

_drift_g_count() { # $1=comm
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq --arg c "$1" '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm==$c)]|length' 2>/dev/null || echo 0
}
_drift_g_global_suppressed() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_drift_baseline_suppressed_total\{/ && /reason="global_baseline_known"/ && /rule_id="drift_exec_from_system_bin"/ { s += $NF } END { printf "%d", s+0 }'
}
_drift_g_limited() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_alerts_ratelimited_by_rule_total\{/ && /rule_id="drift_exec_from_system_bin"/ { s += $NF } END { printf "%d", s+0 }'
}
# Свидетель того, что правило сматчило ИМЕННО под нашим comm.
# ebpf_guard_drift_baseline_suppressed_total несёт только метки
# {rule_id, reason} — нагрузки в ней нет (driftbaseline.go, suppressedTotal).
# Значит прирост reason="global_baseline_known" по этому rule_id может дать
# ЛЮБАЯ ещё обучающаяся нагрузка стенда, а не наша: в паре «0 алертов И
# прирост счётчика >= 1» второе условие тогда выполняется чужими руками, и
# ноль снова становится неотличим от «правило вообще не сматчило» — ровно
# тот приборный ноль, который постановка запрещает засчитывать. Разрез по
# нагрузке даёт /debug/state: samples нашего workload'а растёт на каждый
# ObserveRule, пока профиль в learning (driftbaseline.go, prof.sampleCount++),
# а comm dnw2-<hex> синтетический и исполняется только этим шагом.
_drift_g_samples() { # $1=comm -> число сэмплов профиля этой нагрузки (0, если её нет)
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/debug/state" 2>/dev/null \
        | jq -r --arg c "$1" '[.drift_baseline.workloads[]? | select(.comm==$c) | .samples] | if length == 0 then 0 else .[0] end' 2>/dev/null || echo 0
}
# 6.0j/№209 (сторож п.2 волны): контроль, чей приём читает правило с
# `field: proc.args`, обязан ПЕЧАТАТЬ сам proc.args из полученного алерта.
# Без этого ноль контроля неотличим от proc.args, обнулённого коллектором
# (commMatchesArgv0), — то есть от находки №209 в любом её будущем виде.
# Поле приехало в алерт правкой 6.0j (correlator: procArgsAlertDetails);
# "<поля нет в алерте>" в выводе означает, что бинарь на стенде старее правки,
# и величины этого шага сняты не тем прибором.
_drift_g_args() { # $1=comm -> proc.args последнего алерта правила под этим comm
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq -r --arg c "$1" '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm==$c)] | if length == 0 then "<алертов правила под этим comm нет>" else (sort_by(.timestamp) | .[-1].details["proc.args"] // "<поля нет в алерте>") end' 2>/dev/null \
        || echo "<не удалось прочитать /api/v1/alerts>"
}
_drift_g_wl_line() { # $1=comm -> строка состояния нагрузки для диагностики
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/debug/state" 2>/dev/null \
        | jq -r --arg c "$1" '[.drift_baseline.workloads[]? | select(.comm==$c) | "state=\(.state) sig=\(.signatures) samples=\(.samples) reported=\(.reported) last_seen=\(.last_seen)"] | if length == 0 then "нагрузки нет в /debug/state" else .[0] end' 2>/dev/null || echo "нагрузки нет в /debug/state"
}

# Посев: $DRIFT_G_SEEDBIN исполняется НАПРЯМУЮ (argv[0] = полный путь до него,
# comm = имя файла). Дочерний процесс получает comm=$DRIFT_G_COMM, а сигнатура
# правила складывается из argv[0] — то есть уже на этом шаге и comm
# $DRIFT_G_COMM, и сигнатура $DRIFT_G_SIG_ARGV0 существуют. Это не портит
# 6.0.11: посев учит и per-workload профиль $DRIFT_G_COMM (который сам ещё
# в learning), и глобальный фоллбэк (учится на КАЖДОМ Observe(), до проверки
# prof.enforcing — driftbaseline.go). Второй exec ниже — ТЕМ ЖЕ comm, тем
# же argv[0] — проверяет не «новый comm», а именно то, что постановка
# требует: что штатный интервал спустя повтор уже известной глобально
# сигнатуры молчит. Комм совпадает с посевом по построению (один и тот же
# файл), поэтому «невиданный comm» в тексте волны — это невиданность на
# момент ПЕРВОГО исполнения, а не различие между посевом и проверкой.
"$DRIFT_G_SIG_ARGV0" >/dev/null 2>&1 || true
sleep 20
# Свидетель механики ДО вердикта: посев обязан был родить алерт (сигнатура
# новая, нагрузка новая) с НЕПУСТЫМ proc.args. Печатается, но не die'ит —
# вердикт 6.0.11 ниже, а die на посеве маскировал бы продуктовый разбор.
echo "  6.0g посев: argv[0]=$DRIFT_G_SIG_ARGV0 comm=$DRIFT_G_COMM -> proc.args в алерте: $(_drift_g_args "$DRIFT_G_COMM")"

_drift_g11_before=$(_drift_g_count "$DRIFT_G_COMM")
_drift_g11_global_before=$(_drift_g_global_suppressed)
_drift_g11_samples_before=$(_drift_g_samples "$DRIFT_G_COMM")
"$DRIFT_G_SIG_ARGV0" >/dev/null 2>&1 || true
sleep 20
_drift_g11_after=$(_drift_g_count "$DRIFT_G_COMM")
_drift_g11_global_after=$(_drift_g_global_suppressed)
_drift_g11_samples_after=$(_drift_g_samples "$DRIFT_G_COMM")
echo "  6.0.11 негативный контроль: повтор argv[0]=$DRIFT_G_SIG_ARGV0 под comm=$DRIFT_G_COMM -> drift_exec_from_system_bin{comm=$DRIFT_G_COMM}: ${_drift_g11_before:-0} -> ${_drift_g11_after:-0}, suppressed_total{reason=global_baseline_known}: ${_drift_g11_global_before:-0} -> ${_drift_g11_global_after:-0}, samples нагрузки в /debug/state: ${_drift_g11_samples_before:-0} -> ${_drift_g11_samples_after:-0} ($(date -u +%H:%M:%S) UTC)"
echo "  6.0.11 состояние нагрузки после повтора: $(_drift_g_wl_line "$DRIFT_G_COMM")"
echo "  6.0.11 proc.args последнего алерта правила под comm=$DRIFT_G_COMM: $(_drift_g_args "$DRIFT_G_COMM") (сторож п.2 волны 6.0j/№209: пустое или отсутствующее поле = приборный ноль, а не подавление)"
if [ "$((${_drift_g11_after:-0} - ${_drift_g11_before:-0}))" -ne 0 ] \
   || [ "$((${_drift_g11_global_after:-0} - ${_drift_g11_global_before:-0}))" -lt 1 ] \
   || [ "$((${_drift_g11_samples_after:-0} - ${_drift_g11_samples_before:-0}))" -lt 1 ]; then
    echo "6.0.11 FAIL $(date -u +%FT%TZ) comm=$DRIFT_G_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$DRIFT_G_SEEDDIR" "$DRIFT_G_NOVELDIR"
    die "6.0.11 ПРОВАЛЕН: ожидалось 0 новых алертов И прирост suppressed_total{reason=global_baseline_known} >= 1 И прирост samples нагрузки comm=$DRIFT_G_COMM >= 1 (постановка запрещает засчитывать нулевые алерты без прироста счётчика — неотличимо от 'правило вообще не сматчило'; сам счётчик меток нагрузки не несёт, поэтому его прирост мог прийти от чужой обучающейся нагрузки, и разрез по /debug/state — единственный свидетель, что сматчило именно наше исполнение). Получено: алертов $((${_drift_g11_after:-0} - ${_drift_g11_before:-0})), прирост счётчика $((${_drift_g11_global_after:-0} - ${_drift_g11_global_before:-0})), прирост samples $((${_drift_g11_samples_after:-0} - ${_drift_g11_samples_before:-0})), нагрузка: $(_drift_g_wl_line "$DRIFT_G_COMM"). Читать в порядке: нулевой прирост samples при нулевых алертах = событие не дошло до drift-базы вовсе (правило не сматчило / коллектор не отдал exec) — это приборный ноль, а не доказательство механизма (а); ненулевой прирост алертов = механизм (а) не подавляет знакомую глобально сигнатуру для нового workload'а (тяжесть №193 тогда целиком на подмножестве (б)); нулевой прирост счётчика при выросших samples = разрез reason=global_baseline_known не дошёл до бинаря либо подавление пошло другой веткой (профиль успел уйти в enforcing -> reason=baseline_known)"
fi
echo "6.0.11 PASS $(date -u +%FT%TZ) comm=$DRIFT_G_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.11 доказан живьём в $(date -u +%H:%M:%S) UTC: знакомая глобально сигнатура молчит для workload'а, который сам ещё в learning"

# 6.0.12 — позитивный контроль. ТОТ ЖЕ comm (та же реальная нагрузка,
# doказано выше как невиданная на момент 6.0.11), argv[0] — путь, которого
# на хосте не было никогда. Сторож ложного нуля — тот же, что у 6.0.6:
# срез лимитера читается ДО/ПОСЛЕ, при нулевом приросте алертов с ненулевым
# приростом среза окно лимитера (70с) сливается и попытка повторяется один раз.
_drift_g12_before=$(_drift_g_count "$DRIFT_G_COMM")
_drift_g12_lim_before=$(_drift_g_limited)
"$DRIFT_G_NOVEL_ARGV0" >/dev/null 2>&1 || true
sleep 20
_drift_g12_after=$(_drift_g_count "$DRIFT_G_COMM")
_drift_g12_lim_after=$(_drift_g_limited)
echo "  6.0.12 позитивный контроль: argv[0]=$DRIFT_G_NOVEL_ARGV0 (не встречалось на хосте никогда) под comm=$DRIFT_G_COMM -> drift_exec_from_system_bin{comm=$DRIFT_G_COMM}: ${_drift_g12_before:-0} -> ${_drift_g12_after:-0}, срез лимитера ${_drift_g12_lim_before:-0} -> ${_drift_g12_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
echo "  6.0.12 proc.args последнего алерта: $(_drift_g_args "$DRIFT_G_COMM") (ожидается $DRIFT_G_NOVEL_ARGV0; сторож п.2 волны 6.0j/№209)"
if [ "$((${_drift_g12_after:-0} - ${_drift_g12_before:-0}))" -lt 1 ] \
   && [ "$(( ${_drift_g12_lim_after:-0} - ${_drift_g12_lim_before:-0} ))" -gt 0 ]; then
    echo "  6.0.12: ноль алертов ПРИ выросшем срезе лимитера (+$(( ${_drift_g12_lim_after:-0} - ${_drift_g12_lim_before:-0} ))) — приборный ноль. Даём окну лимитера (60с) стечь и повторяем один раз"
    sleep 70
    _drift_g12_before=$(_drift_g_count "$DRIFT_G_COMM")
    _drift_g12_lim_before=$(_drift_g_limited)
    "$DRIFT_G_NOVEL_ARGV0" >/dev/null 2>&1 || true
    sleep 20
    _drift_g12_after=$(_drift_g_count "$DRIFT_G_COMM")
    _drift_g12_lim_after=$(_drift_g_limited)
    echo "  6.0.12 повтор после стекания окна лимитера: алертов ${_drift_g12_before:-0} -> ${_drift_g12_after:-0}, срез ${_drift_g12_lim_before:-0} -> ${_drift_g12_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
fi
_drift_g12_args=$(_drift_g_args "$DRIFT_G_COMM")
if [ "$((${_drift_g12_after:-0} - ${_drift_g12_before:-0}))" -ge 1 ] && [ "$_drift_g12_args" != "$DRIFT_G_NOVEL_ARGV0" ]; then
    echo "6.0.12 FAIL $(date -u +%FT%TZ) comm=$DRIFT_G_COMM args-mismatch" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$DRIFT_G_SEEDDIR" "$DRIFT_G_NOVELDIR"
    die "6.0.12 ПРОВАЛЕН ПО СВИДЕТЕЛЮ: алерты есть ($((${_drift_g12_after:-0} - ${_drift_g12_before:-0}))), но proc.args последнего из них — '$_drift_g12_args', а не посланный argv[0] '$DRIFT_G_NOVEL_ARGV0'. Читать в порядке: '<поля нет в алерте>' = бинарь на стенде старее правки 6.0j (correlator: procArgsAlertDetails) и величины этого шага сняты не тем прибором; '<алертов правила под этим comm нет>' при ненулевой дельте = дельта набрана не нашей нагрузкой (отбор по comm разъехался); чужой путь = алерт пришёл от другой сигнатуры, и 6.0.12 засчитал бы чужое срабатывание за своё"
fi
if [ "$((${_drift_g12_after:-0} - ${_drift_g12_before:-0}))" -lt 1 ]; then
    echo "6.0.12 FAIL $(date -u +%FT%TZ) comm=$DRIFT_G_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$DRIFT_G_SEEDDIR" "$DRIFT_G_NOVELDIR"
    die "6.0.12 ПРОВАЛЕН: сигнатура, которой не было на хосте никогда (argv[0]=$DRIFT_G_NOVEL_ARGV0), исполненная тем же невиданным comm=$DRIFT_G_COMM, не дала ни одного алерта drift_exec_from_system_bin (было ${_drift_g12_before:-0}, стало ${_drift_g12_after:-0}), срез лимитера за попытку: +$(( ${_drift_g12_lim_after:-0} - ${_drift_g12_lim_before:-0} )). Если срез ненулевой после повтора — причина приборная (лимитер), а не продуктовая; иначе 6.0.11 выше доказывал бы только 'правило молчит', а не 'правило умеет отличать известное от неизвестного'"
fi
echo "6.0.12 PASS $(date -u +%FT%TZ) comm=$DRIFT_G_COMM" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.12 доказан живьём в $(date -u +%H:%M:%S) UTC: незнакомая глобально сигнатура алертит от того же невиданного comm, что молчал на 6.0.11"
rm -rf "$DRIFT_G_SEEDDIR" "$DRIFT_G_NOVELDIR"

echo "--- 6.0h: позитивный контроль импакт-правил №200 и подмножества (б) на container_escape_proc_write (критерии 6.0.13/6.0.14/6.0.15, №200/№205) ---"
# 6.0.13 — негативный, по ОБОИМ правилам №200. dumpe2fs -h на смонтированное
# устройство раньше был false positive обоих: impact_raw_disk_write_from_container
# матчило на op=open/filename-регулярку без предиката на comm/тип операции;
# container_escape_host_device матчило на голый filename-регэксп без
# различения container/host. После правки: impact_raw_disk_write_from_container
# сужено до op=write ∧ comm в списке инструментов записи — dumpe2fs делает
# open(O_RDONLY), не матчит вовсе. container_escape_host_device разведено на
# container-случай (critical, тот же id) и host-случай (новый id, warning) —
# этот пайплайн исполняется НА ХОСТЕ (нет container.id/pod_name на событии),
# поэтому dumpe2fs здесь может поднять только новый warning-id, а критикал
# по container_escape_host_device остаётся ровно тем, что было ДО правки: 0.
_impact_critical_count() { # $1=rule_id
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq --arg r "$1" '[.[]|select(.rule_id==$r and .severity=="critical")]|length' 2>/dev/null || echo 0
}
_impact_neg_before1=$(_impact_critical_count impact_raw_disk_write_from_container)
_impact_neg_before2=$(_impact_critical_count container_escape_host_device)
dumpe2fs -h /dev/vda1 >/dev/null 2>&1 || true
sleep 15
_impact_neg_after1=$(_impact_critical_count impact_raw_disk_write_from_container)
_impact_neg_after2=$(_impact_critical_count container_escape_host_device)
echo "  6.0.13 негативный контроль: dumpe2fs -h /dev/vda1 -> impact_raw_disk_write_from_container критикалов: ${_impact_neg_before1:-0} -> ${_impact_neg_after1:-0}, container_escape_host_device критикалов: ${_impact_neg_before2:-0} -> ${_impact_neg_after2:-0} ($(date -u +%H:%M:%S) UTC)"
if [ "$((${_impact_neg_after1:-0} - ${_impact_neg_before1:-0}))" -ne 0 ] \
   || [ "$((${_impact_neg_after2:-0} - ${_impact_neg_before2:-0}))" -ne 0 ]; then
    die "6.0.13 ПРОВАЛЕН: dumpe2fs -h /dev/vda1 (read-only open, с хоста) подняло новых критикалов: impact_raw_disk_write_from_container +$((${_impact_neg_after1:-0} - ${_impact_neg_before1:-0})), container_escape_host_device +$((${_impact_neg_after2:-0} - ${_impact_neg_before2:-0})) — правка №200 не сузила хотя бы одно из двух правил, либо агент крутит старые правила (проверить рестарт [5/14]), либо container.id/k8s.pod ошибочно непусты на этом хосте (проверить enrichment)"
fi
echo "6.0.13 PASS $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.13 доказан живьём в $(date -u +%H:%M:%S) UTC: штатный dumpe2fs -h не поднимает критикал ни по одному из двух правил №200"

# 6.0.14 — позитивный: count=0 — устройство открывается на запись, ни один
# байт не пишется физически, откат не нужен по построению.
_impact_pos_before=$(_impact_critical_count impact_raw_disk_write_from_container)
dd if=/dev/zero of=/dev/vda1 bs=512 count=0 >/dev/null 2>&1 || true
sleep 15
_impact_pos_after=$(_impact_critical_count impact_raw_disk_write_from_container)
echo "  6.0.14 позитивный контроль: dd if=/dev/zero of=/dev/vda1 bs=512 count=0 -> impact_raw_disk_write_from_container критикалов: ${_impact_pos_before:-0} -> ${_impact_pos_after:-0} ($(date -u +%H:%M:%S) UTC)"
if [ "$((${_impact_pos_after:-0} - ${_impact_pos_before:-0}))" -lt 1 ]; then
    die "6.0.14 ПРОВАЛЕН: dd (comm=dd, op=write, count=0) на /dev/vda1 не подняло ни одного критикала impact_raw_disk_write_from_container (было ${_impact_pos_before:-0}, стало ${_impact_pos_after:-0}) — правка №200 сузила правило до немоты вместо сужения FP, находка №200 не закрыта"
fi
echo "6.0.14 PASS $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.14 доказан живьём в $(date -u +%H:%M:%S) UTC: dd на raw-устройство по-прежнему поднимает критикал"

# 6.0.15 — позитивный контроль подмножества (б) на container_escape_proc_write
# (№205, находка №193). sysctl -w того же значения — идемпотентно по
# построению, откат не нужен. comm=sysctl не входит в список исключений
# правила (systemd, systemd-sysctl, irqbalance).
_procwrite_count() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq '[.[]|select(.rule_id=="container_escape_proc_write")]|length' 2>/dev/null || echo 0
}
_procwrite_before=$(_procwrite_count)
_pid_max_current=$(cat /proc/sys/kernel/pid_max 2>/dev/null || echo "")
if [ -n "$_pid_max_current" ]; then
    sysctl -w kernel.pid_max="$_pid_max_current" >/dev/null 2>&1 || true
fi
sleep 15
_procwrite_after=$(_procwrite_count)
echo "  6.0.15 позитивный контроль: sysctl -w kernel.pid_max=$_pid_max_current -> container_escape_proc_write алертов: ${_procwrite_before:-0} -> ${_procwrite_after:-0} ($(date -u +%H:%M:%S) UTC)"
if [ -z "$_pid_max_current" ]; then
    die "6.0.15 НЕ ИСПОЛНИМ: /proc/sys/kernel/pid_max не читается на этом стенде — контроль нечем исполнить. Постановка требует либо 6.0.15 ДОСТИГНУТО, либо явный вывод container_escape_proc_write из подмножества (б) с записью причины в plan.md — третьего исхода нет"
fi
if [ "$((${_procwrite_after:-0} - ${_procwrite_before:-0}))" -lt 1 ]; then
    echo "6.0.15 FAIL $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    die "6.0.15 ПРОВАЛЕН: sysctl -w kernel.pid_max=<текущее значение> (comm=sysctl, op=write, filename=/proc/sys/kernel/pid_max) не подняло ни одного алерта container_escape_proc_write (было ${_procwrite_before:-0}, стало ${_procwrite_after:-0}) — проводка флага drift_novel_workload:alert на этом правиле мертва, находка №193 закрыта только на drift_dangerous_syscall"
fi
echo "6.0.15 PASS $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.15 доказан живьём в $(date -u +%H:%M:%S) UTC: sysctl -w поднимает container_escape_proc_write"

echo "--- 6.0k: контроли находки №210 — детект под спуфом argv[0] и ровно один алерт на обычный exec (критерии 6.0.16 и 6.0.17) ---"
# Буквы i и j пропущены: `6.0i` — метка шага-таблицы выше, `6.0j` — имя ВОЛНЫ,
# а файл грепается буквально (тот же разбор, что у пропущенных d и f).
#
# Что меряется. Находка №210: execve не требует, чтобы argv[0] называл образ,
# а коллектор до правки 6.0j решал «эта запись про новый образ или про
# вызывающего» ровно по совпадению comm с basename(argv[0])
# (commMatchesArgv0) и при несовпадении ОБНУЛЯЛ proc.args. Под это попадали
# весь класс правил `field: proc.args` (68 условий в дереве на 02.09),
# штатный login-shell (argv[0]="-bash", comm="bash") и маскирующийся дроппер
# T1036.003 — то есть техника, ради детекта которой правила и заведены,
# выключала детект целиком.
#
# Правка: `struct proc_args` несёт `exec_ts` (bpf_ktime_get_ns() в
# trace_sched_process_exec), и userspace прикрепляет argv тогда и только
# тогда, когда exec_ts СТАРШЕ метки самого события — то есть на записи
# sys_exit и не на записи sys_enter. Дискриминатор перестал зависеть от
# argv[0] вовсе. Резервный путь (/proc/PID/cmdline) метки времени не имеет и
# сохраняет старую эвристику; его слепота теперь измерима счётчиком
# ebpf_guard_proc_args_dropped_total{reason="argv0_mismatch"}.
#
# Пара контролей неразделима: 6.0.16 без 6.0.17 означал бы, что слепота снята
# ценой двойного алерта на каждый exec (ровно то, ради чего сверка
# commMatchesArgv0 вводилась), то есть обмен одного дефекта на другой.
#
# Оба контроля отбирают алерты ПО САМОМУ proc.args, а не по comm: под спуфом
# comm и argv[0] по построению разъезжаются, и отбор по comm мерил бы не то
# исполнение. Приём 6.0.17 («ровно 1») тем же отбором становится прямым: обе
# записи одного execve несут ОДИН И ТОТ ЖЕ argv, поэтому двойной алерт виден
# как 2, независимо от того, под каким comm приехал второй.
SP_TOUCH=""
for _sp_cand in /usr/bin/touch /bin/touch; do
    if [ -f "$_sp_cand" ] && [ -x "$_sp_cand" ]; then SP_TOUCH="$_sp_cand"; break; fi
done
[ -n "$SP_TOUCH" ] \
    || die "6.0k: ни /usr/bin/touch, ни /bin/touch не оказались исполняемым обычным файлом — примитив обоих контролей нечем собрать. Брать builtin нельзя (находка №176), и брать «true» тоже нельзя: у него нет наблюдаемого результата, а контроль без сторожа результата даёт ложный ноль при execve ENOENT (память «позитивный контроль по результату»)"
SP_WORKDIR=/usr/local/bin/sp-work
SP_SEEDDIR=/usr/local/bin/sp-seed
mkdir -p "$SP_WORKDIR" "$SP_SEEDDIR" 2>/dev/null || die "6.0k: не удалось создать $SP_WORKDIR/$SP_SEEDDIR"

_sp_count_args() { # $1=префикс proc.args -> число алертов правила с таким proc.args
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq --arg a "$1" '[.[]|select(.rule_id=="drift_exec_from_system_bin" and ((.details["proc.args"] // "") | startswith($a)))]|length' 2>/dev/null \
        || echo 0
}
_sp_args_of() { # $1=comm -> proc.args последнего алерта правила под этим comm (сторож п.2 волны 6.0j)
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq -r --arg c "$1" '[.[]|select(.rule_id=="drift_exec_from_system_bin" and .comm==$c)] | if length == 0 then "<алертов правила под этим comm нет>" else (sort_by(.timestamp) | .[-1].details["proc.args"] // "<поля нет в алерте>") end' 2>/dev/null \
        || echo "<не удалось прочитать /api/v1/alerts>"
}
_sp_limited() {
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_alerts_ratelimited_by_rule_total\{/ && /rule_id="drift_exec_from_system_bin"/ { s += $NF } END { printf "%d", s+0 }'
}
_sp_dropped() { # $1=reason -> ebpf_guard_proc_args_dropped_total{reason=...}
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk -v r="reason=\"$1\"" '/^ebpf_guard_proc_args_dropped_total\{/ && index($0, r) { s += $NF } END { printf "%d", s+0 }'
}

# --- 6.0.16: позитивный, закрывает №210 -------------------------------------
# Каждая попытка берёт СВЕЖИЙ hex: повтор той же сигнатуры после среза
# лимитера был бы подавлен базовой линией как already_reported, и ложный ноль
# сменился бы другим ложным нулём (память «потолок rate-limiter'а»).
_sp16_attempt() { # заполняет _sp16_{comm,spoof,sentinel,before,after,lim_before,lim_after}
    local hex; hex=$(head -c 4 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')
    _sp16_comm="sp-$hex"
    [ "${#_sp16_comm}" -le 15 ] || die "6.0k: сгенерированный comm '$_sp16_comm' длиннее 15 символов — ядро усечёт его"
    local bin="$SP_WORKDIR/$_sp16_comm"
    _sp16_spoof="$SP_SEEDDIR/$hex"
    _sp16_sentinel="/tmp/sp-ran-$hex"
    cp "$SP_TOUCH" "$bin" 2>/dev/null || die "6.0.16: не удалось подготовить $bin из $SP_TOUCH"
    chmod +x "$bin" || die "6.0.16: не удалось сделать $bin исполняемым"
    [ -x "$bin" ] || die "6.0.16: $bin не исполняем после chmod (noexec на /usr/local?) — execve упадёт с EACCES ДО смены comm, и контроль получит ложный ноль (класс находки №176)"
    rm -f "$_sp16_sentinel"
    _sp16_before=$(_sp_count_args "$_sp16_spoof")
    _sp16_lim_before=$(_sp_limited)
    # ARGV0-SPOOF-BY-DESIGN (№210)
    # Единственное место пайплайна, где подмена argv[0] разрешена преflight'ом
    # 6.0j/№210: здесь она и есть ПРЕДМЕТ измерения. argv[0] — путь в
    # $SP_SEEDDIR (префикс /usr/local/bin/ обязателен: без него правило с
    # `op: prefix` по proc.args не сматчит вовсе), исполняемый файл — другой,
    # в $SP_WORKDIR, и comm=$_sp16_comm равен его имени, а не basename(argv[0]).
    # До правки №210 commMatchesArgv0 обнулял бы proc.args на ОБЕИХ записях
    # execve, и контроль давал бы ровно ноль.
    bash -c "exec -a '$_sp16_spoof' '$bin' '$_sp16_sentinel'" >/dev/null 2>&1 || true
    # Сторож результата (память «позитивный контроль по результату»): без него
    # ENOENT/EACCES на execve выглядят как «детект не сработал».
    [ -e "$_sp16_sentinel" ] \
        || die "6.0.16 НЕ ИСПОЛНЕН: подменённый вызов не создал $_sp16_sentinel — сам execve не состоялся (ENOENT/EACCES/усечённый argv), и ноль алертов ниже был бы приборным. Проверить $bin и права на /usr/local/bin"
    sleep 20
    _sp16_after=$(_sp_count_args "$_sp16_spoof")
    _sp16_lim_after=$(_sp_limited)
    rm -f "$bin" "$_sp16_sentinel"
}
_sp16_dropped_before=$(_sp_dropped argv0_mismatch)
_sp16_attempt
echo "  6.0.16 позитивный контроль: argv[0]=$_sp16_spoof подменён у реального образа comm=$_sp16_comm -> алертов drift_exec_from_system_bin с этим proc.args: ${_sp16_before:-0} -> ${_sp16_after:-0}, срез лимитера ${_sp16_lim_before:-0} -> ${_sp16_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
if [ "$((${_sp16_after:-0} - ${_sp16_before:-0}))" -lt 1 ] \
   && [ "$(( ${_sp16_lim_after:-0} - ${_sp16_lim_before:-0} ))" -gt 0 ]; then
    echo "  6.0.16: ноль алертов ПРИ выросшем срезе лимитера (+$(( ${_sp16_lim_after:-0} - ${_sp16_lim_before:-0} ))) — приборный ноль. Даём окну лимитера (60с) стечь и повторяем один раз, со свежей сигнатурой"
    sleep 70
    _sp16_attempt
    echo "  6.0.16 повтор после стекания окна лимитера: argv[0]=$_sp16_spoof, алертов ${_sp16_before:-0} -> ${_sp16_after:-0}, срез ${_sp16_lim_before:-0} -> ${_sp16_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
fi
_sp16_args=$(_sp_args_of "$_sp16_comm")
echo "  6.0.16 proc.args последнего алерта под comm=$_sp16_comm: $_sp16_args (ожидается начало с $_sp16_spoof — сторож п.2 волны 6.0j/№209)"
echo "  6.0.16 счётчик слепоты резервного пути: ebpf_guard_proc_args_dropped_total{reason=\"argv0_mismatch\"} ${_sp16_dropped_before:-0} -> $(_sp_dropped argv0_mismatch), {reason=\"stale_exec\"} = $(_sp_dropped stale_exec)"
if [ "$((${_sp16_after:-0} - ${_sp16_before:-0}))" -lt 1 ]; then
    echo "6.0.16 FAIL $(date -u +%FT%TZ) comm=$_sp16_comm" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$SP_WORKDIR" "$SP_SEEDDIR"
    die "6.0.16 ПРОВАЛЕН: execve с подменённым argv[0]=$_sp16_spoof (реальный образ — другой файл, comm=$_sp16_comm) не дал ни одного алерта drift_exec_from_system_bin с этим proc.args (было ${_sp16_before:-0}, стало ${_sp16_after:-0}); сам вызов состоялся — сторож результата выше зелёный. Читать в порядке: срез лимитера за попытку +$(( ${_sp16_lim_after:-0} - ${_sp16_lim_before:-0} )) (ненулевой после повтора = причина приборная); прирост proc_args_dropped_total{reason=\"argv0_mismatch\"} = проводка идёт резервным путём (/proc/PID/cmdline, ядро без BTF), где эвристика argv[0] сохранена сознательно и слепота остаётся известным ограничением; прирост {reason=\"stale_exec\"} без алертов = exec_ts прикрепил argv не к той записи; ноль по обоим счётчикам и ноль алертов = правка №210 не в ядре, то есть `make generate` на шаге [3/14] собрал bpf/common.h без поля exec_ts, и контроль мерит старый бинарь"
fi
echo "6.0.16 PASS $(date -u +%FT%TZ) comm=$_sp16_comm" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.16 доказан живьём в $(date -u +%H:%M:%S) UTC: детект класса proc.args пережил подмену argv[0] (находка №210 закрыта)"

# --- 6.0.17: негативный, антирегресс ----------------------------------------
# Ровно один алерт на один обычный execve. Именно это обеспечивала сверка
# commMatchesArgv0, снятая правкой №210 с основного пути: без дискриминатора
# argv вызываемого приезжает и на запись sys_enter, и правило поднимается
# дважды за exec, второй раз — под comm вызывающего. Отбор по самому
# proc.args ловит обе записи, потому что argv у них общий.
_sp17_attempt() {
    local hex; hex=$(head -c 4 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')
    _sp17_comm="sp2-$hex"
    [ "${#_sp17_comm}" -le 15 ] || die "6.0k: сгенерированный comm '$_sp17_comm' длиннее 15 символов — ядро усечёт его"
    _sp17_dir="/usr/local/bin/sp-plain-$hex"
    mkdir -p "$_sp17_dir" 2>/dev/null || die "6.0.17: не удалось создать $_sp17_dir"
    _sp17_bin="$_sp17_dir/$_sp17_comm"
    _sp17_sentinel="/tmp/sp2-ran-$hex"
    cp "$SP_TOUCH" "$_sp17_bin" 2>/dev/null || die "6.0.17: не удалось подготовить $_sp17_bin из $SP_TOUCH"
    chmod +x "$_sp17_bin" || die "6.0.17: не удалось сделать $_sp17_bin исполняемым"
    [ -x "$_sp17_bin" ] || die "6.0.17: $_sp17_bin не исполняем после chmod (noexec на /usr/local?)"
    rm -f "$_sp17_sentinel"
    _sp17_before=$(_sp_count_args "$_sp17_bin")
    _sp17_lim_before=$(_sp_limited)
    "$_sp17_bin" "$_sp17_sentinel" >/dev/null 2>&1 || true
    [ -e "$_sp17_sentinel" ] \
        || die "6.0.17 НЕ ИСПОЛНЕН: обычный вызов не создал $_sp17_sentinel — execve не состоялся, и любое число алертов ниже относится не к нему"
    sleep 20
    _sp17_after=$(_sp_count_args "$_sp17_bin")
    _sp17_lim_after=$(_sp_limited)
    rm -rf "$_sp17_dir"
    rm -f "$_sp17_sentinel"
}
_sp17_attempt
echo "  6.0.17 негативный контроль: один обычный execve $_sp17_bin (comm=$_sp17_comm, невиданный каталог, argv[0] равен пути) -> алертов drift_exec_from_system_bin с этим proc.args: ${_sp17_before:-0} -> ${_sp17_after:-0}, срез лимитера ${_sp17_lim_before:-0} -> ${_sp17_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
echo "  6.0.17 proc.args последнего алерта под comm=$_sp17_comm: $(_sp_args_of "$_sp17_comm") (сторож п.2 волны 6.0j/№209)"
if [ "$((${_sp17_after:-0} - ${_sp17_before:-0}))" -eq 0 ] \
   || [ "$(( ${_sp17_lim_after:-0} - ${_sp17_lim_before:-0} ))" -gt 0 ]; then
    echo "  6.0.17: попытка непригодна для вердикта (ноль алертов либо ненулевой срез лимитера — «ровно 1» тогда может быть срезанной двойкой). Даём окну лимитера (60с) стечь и повторяем один раз, со свежей сигнатурой"
    sleep 70
    _sp17_attempt
    echo "  6.0.17 повтор: $_sp17_bin -> алертов ${_sp17_before:-0} -> ${_sp17_after:-0}, срез ${_sp17_lim_before:-0} -> ${_sp17_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
fi
if [ "$((${_sp17_after:-0} - ${_sp17_before:-0}))" -ne 1 ]; then
    echo "6.0.17 FAIL $(date -u +%FT%TZ) comm=$_sp17_comm" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    rm -rf "$SP_WORKDIR" "$SP_SEEDDIR"
    die "6.0.17 ПРОВАЛЕН: один execve $_sp17_bin дал $((${_sp17_after:-0} - ${_sp17_before:-0})) алертов drift_exec_from_system_bin с этим proc.args вместо ровно 1, срез лимитера за попытку +$(( ${_sp17_lim_after:-0} - ${_sp17_lim_before:-0} )). Читать так: 2 и больше = снятие сверки commMatchesArgv0 с основного пути вернуло алерт на записи sys_enter, то есть exec_ts прикрепляет argv к обеим записям (проверить, что bpf/common.h собран с полем exec_ts и что userspace сравнивает его с меткой события, а не с нулём) — слепота снята ценой двойного алерта на КАЖДЫЙ exec, и это обмен одного дефекта на другой, а не исправление; 0 при нулевом срезе лимитера = правило не сматчило вовсе, и 6.0.16 выше засчитан по чужому алерту"
fi
echo "6.0.17 PASS $(date -u +%FT%TZ) comm=$_sp17_comm" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.17 доказан живьём в $(date -u +%H:%M:%S) UTC: один exec — ровно один алерт, двойного срабатывания за execve нет"
rm -rf "$SP_WORKDIR" "$SP_SEEDDIR"

echo "--- 6.0l: позитивный контроль container_escape_host_device_from_host (критерий 6.0.18, №211) ---"
# Буква l — следующая свободная за k (i занята шагом-таблицей, j — именем
# ВОЛНЫ, а файл грепается буквально).
#
# Что меряется. Волна 6.0f развела container_escape_host_device на два
# правила: контейнерный случай (тот же id, critical) и хостовой (новый id
# container_escape_host_device_from_host, warning). Контроль получил только
# ПЕРВЫЙ: 6.0.13 негативный и считает исключительно КРИТИКАЛЫ обоих id,
# тогда как хостовое правило — warning, и ни один его алерт в вердикт 6.0.13
# не входит по построению. Правило было заведено без собственного контроля —
# ровно то «заведение немого правила», которое сторож преflight'а п.9 волны
# 6.0f и должен был запретить; он прошёл ложно-зелёным, потому что грепал
# префикс `_impact_critical_count container_escape_host_device`, матчащийся
# на контейнерное правило (сторож якорен на полный id правкой п.5 волны 6.0j).
#
# Цена немоты — два FAIL гейта замера №6.0f2: «состав детекта: потеряно 1
# типов вне intentional-loss.txt» и «1 правило немо за весь аптайм без строки
# в silent-rules.txt (категория (в))». Оба воспроизвелись бы и на этом
# прогоне: реестр new-rules.txt вычитает правило только на архивах СТАРШЕ
# даты заведения (20260901), а это прогон своей волны.
#
# Записи в silent-rules.txt НЕ заводится сознательно: она утверждала бы, что
# стенд не воспроизводит сценарий правила, а это ложь — сценарий
# воспроизводится ниже, в этом же пайплайне.
#
# Один примитив закрывает обе стороны разведения и совместим с 6.0.13:
# 6.0.13 утверждает «критикалов нет», 6.0.18 — «детект не потерян». Поэтому
# критикалы обоих id проверяются здесь ЕЩЁ РАЗ, на своём собственном
# примитиве: позитивный контроль, поднявший заодно критикал, означал бы, что
# разведение не состоялось, а не что детект жив.
_hd_dev=/dev/vda1
[ -b "$_hd_dev" ] \
    || die "6.0.18 НЕ ИСПОЛНИМ: $_hd_dev не блочное устройство — примитив контроля нечем исполнить. Репетиция [6/14] обязана была поймать это ДО idle-часа (сторож 6.0h/6.0l), и если прогон дошёл сюда, значит репетиция не покрывает того, что печатает (6.0.19 признаётся не покрывающей, см. постановку волны 6.0j)"
command -v dumpe2fs >/dev/null 2>&1 \
    || die "6.0.18 НЕ ИСПОЛНИМ: dumpe2fs(8) (e2fsprogs) не установлен — тот же примитив, что у 6.0.13, и та же претензия к репетиции [6/14]"
_hd_count() { # $1=rule_id, $2=severity -> число алертов правила этой строгости
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/api/v1/alerts" 2>/dev/null \
        | jq --arg r "$1" --arg s "$2" '[.[]|select(.rule_id==$r and .severity==$s)]|length' 2>/dev/null || echo 0
}
_hd_limited() { # срез лимитера по хостовому правилу (сторож ложного нуля)
    curl -s --max-time 15 -H "Authorization: Bearer $DRIFT_PC_TOKEN" "$DRIFT_PC_API/metrics" 2>/dev/null \
        | awk '/^ebpf_guard_alerts_ratelimited_by_rule_total\{/ && /rule_id="container_escape_host_device_from_host"/ { s += $NF } END { printf "%d", s+0 }'
}
# Сторож результата (память «позитивный контроль по результату», comm=tar
# 20/20 при execve ENOENT): без кода возврата самого dumpe2fs ноль алертов
# ниже неотличим от «устройство не открывалось вовсе» — не ext-раздел, нет
# прав, устройство занято. rc проверяется ДО того, как контроль посмотрит на
# алерты.
_hd18_attempt() { # заполняет _hd18_{warn_before,warn_after,c1_before,c1_after,c2_before,c2_after,lim_before,lim_after,rc}
    _hd18_warn_before=$(_hd_count container_escape_host_device_from_host warning)
    _hd18_c1_before=$(_hd_count container_escape_host_device critical)
    _hd18_c2_before=$(_hd_count container_escape_host_device_from_host critical)
    _hd18_lim_before=$(_hd_limited)
    dumpe2fs -h "$_hd_dev" >/dev/null 2>&1
    _hd18_rc=$?
    [ "$_hd18_rc" -eq 0 ] \
        || die "6.0.18 НЕ ИСПОЛНЕН: dumpe2fs -h $_hd_dev вернул rc=$_hd18_rc — устройство не было прочитано, и любое число алертов ниже относится не к этому вызову. Ноль здесь был бы приборным (класс находки №176), а не вердиктом о правиле"
    sleep 20
    _hd18_warn_after=$(_hd_count container_escape_host_device_from_host warning)
    _hd18_c1_after=$(_hd_count container_escape_host_device critical)
    _hd18_c2_after=$(_hd_count container_escape_host_device_from_host critical)
    _hd18_lim_after=$(_hd_limited)
}
_hd18_attempt
echo "  6.0.18 позитивный контроль: dumpe2fs -h $_hd_dev с хоста (rc=$_hd18_rc) -> container_escape_host_device_from_host warning: ${_hd18_warn_before:-0} -> ${_hd18_warn_after:-0}; критикалы container_escape_host_device: ${_hd18_c1_before:-0} -> ${_hd18_c1_after:-0}, container_escape_host_device_from_host: ${_hd18_c2_before:-0} -> ${_hd18_c2_after:-0}; срез лимитера ${_hd18_lim_before:-0} -> ${_hd18_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
# Сторож ложного нуля, общий с 6.0.6/6.0.12/6.0.16/6.0.17. Шаг стоит ПОСЛЕ
# окна атак, где лимитер уже мог набрать своё (память «контроль после атак и
# лимитер»): ноль при выросшем срезе — это срез, а не вердикт.
if [ "$(( ${_hd18_warn_after:-0} - ${_hd18_warn_before:-0} ))" -lt 1 ] \
   && [ "$(( ${_hd18_lim_after:-0} - ${_hd18_lim_before:-0} ))" -gt 0 ]; then
    echo "  6.0.18: ноль алертов ПРИ выросшем срезе лимитера (+$(( ${_hd18_lim_after:-0} - ${_hd18_lim_before:-0} ))) — приборный ноль. Даём окну лимитера (60с) стечь и повторяем один раз"
    sleep 70
    _hd18_attempt
    echo "  6.0.18 повтор после стекания окна лимитера: warning ${_hd18_warn_before:-0} -> ${_hd18_warn_after:-0}, срез ${_hd18_lim_before:-0} -> ${_hd18_lim_after:-0} ($(date -u +%H:%M:%S) UTC)"
fi
if [ "$(( ${_hd18_warn_after:-0} - ${_hd18_warn_before:-0} ))" -lt 1 ]; then
    echo "6.0.18 FAIL $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    die "6.0.18 ПРОВАЛЕН: dumpe2fs -h $_hd_dev с хоста (rc=0, устройство прочитано) не подняло ни одного алерта container_escape_host_device_from_host уровня warning (было ${_hd18_warn_before:-0}, стало ${_hd18_warn_after:-0}), срез лимитера за попытку +$(( ${_hd18_lim_after:-0} - ${_hd18_lim_before:-0} )). Читать в порядке: ненулевой срез после повтора = причина приборная; нулевой срез = хостовая половина разведения №200 нема продуктово, то есть волна 6.0f завела правило, которое не поднимается на СВОЁМ сценарии — проверить предикаты container.id/k8s.pod (op: eq, values: [\"\"]) против обогащения этого хоста и то, что агент крутит новые правила (рестарт [5/14]). Третьего исхода у 6.0.18 нет: правило без исполнившегося контроля возвращается в состояние, из-за которого волна 6.0j и заведена"
fi
# Вторая сторона разведения: тот же примитив не смеет поднять критикал НИ ПО
# ОДНОМУ из двух id. Это не дубль 6.0.13 (он мерил свой собственный вызов
# dumpe2fs на шаге 6.0h): здесь проверяется, что критикал не пришёл ИМЕННО
# от того вызова, который дал warning, — иначе «детект не потерян» было бы
# куплено ценой возврата ложного критикала, ради устранения которого №200 и
# разводило правило.
if [ "$(( ${_hd18_c1_after:-0} - ${_hd18_c1_before:-0} ))" -ne 0 ] \
   || [ "$(( ${_hd18_c2_after:-0} - ${_hd18_c2_before:-0} ))" -ne 0 ]; then
    echo "6.0.18 FAIL $(date -u +%FT%TZ) (критикал на позитивном примитиве)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
    die "6.0.18 ПРОВАЛЕН: тот же dumpe2fs -h $_hd_dev, что дал warning хостового правила, поднял и критикал: container_escape_host_device +$(( ${_hd18_c1_after:-0} - ${_hd18_c1_before:-0} )), container_escape_host_device_from_host +$(( ${_hd18_c2_after:-0} - ${_hd18_c2_before:-0} )). Разведение №200 не состоялось: хостовой случай снова критикал-first, и 6.0.13 на шаге 6.0h выше засчитан по случайности, а не по сужению. Правило _from_host обязано быть severity: warning (rules/container-escape.yaml), контейнерное — обязано требовать непустой container.id/k8s.pod"
fi
echo "6.0.18 PASS $(date -u +%FT%TZ)" >> /root/drift-controls-6.0.txt 2>/dev/null || true
echo "6.0.18 доказан живьём в $(date -u +%H:%M:%S) UTC: container_escape_host_device_from_host поднимается на своём сценарии (warning, без критикалов) — правило перестало быть немым, оба FAIL гейта №6.0f2 закрыты продуктом, а не реестром"

echo "--- 6.0i: окно атаки против времени drift-контролей, одной таблицей (№206, волна 6.0f/п.7) ---"
# Постановка 6.0d утверждала «6.0e стоит сразу за 6.0c, внутри окна атаки» —
# находка №206 (замер №6.0d) показала, что это не так: все контроли легли ЗА
# правой границей окна (last= в attack-window-*.txt), не внутри него. Вреда в
# этом нет — перенос контролей внутрь окна отклонён сознательно тем же
# пунктом постановки, иначе их алерты попали бы в числитель темпа атакующих
# и загрязнили бы величину, служащую базой сравнения с прогоном №4. Здесь
# правится не код детектора, а наблюдаемость самого прогона: расхождение
# печатается как факт таблицей, а не остаётся тем, что находит только
# постфактум-разбор логов.
_iso_to_epoch() { # $1=ISO8601 UTC (date -u +%FT%TZ)
    date -u -d "$1" +%s 2>/dev/null \
        || date -u -j -f "%Y-%m-%dT%H:%M:%SZ" "$1" +%s 2>/dev/null
}
_aw_file=$(ls -t $SETUP/attacks/attack-results/attack-window-*.txt 2>/dev/null | head -1)
_aw_first=""; _aw_last=""
if [ -n "$_aw_file" ] && [ -s "$_aw_file" ]; then
    _aw_first=$(grep -oE '^first=[0-9.]+' "$_aw_file" | cut -d= -f2)
    _aw_last=$(grep -oE '^last=[0-9.]+' "$_aw_file" | cut -d= -f2)
fi
echo "  граница окна атаки (5.9.7d): first=${_aw_first:-?} last=${_aw_last:-?}"
if [ -z "$_aw_last" ]; then
    echo "  таблица не построена: attack-window-*.txt отсутствует или без строки last= — сравнение невозможно, это наблюдательный, не обязательный пункт"
elif [ ! -s /root/drift-controls-6.0.txt ]; then
    echo "  таблица не построена: /root/drift-controls-6.0.txt пуст или отсутствует"
else
    _aw_last_i=${_aw_last%.*}
    echo "  контроль  результат  время_UTC             позиция относительно окна атаки"
    grep -E '^6\.0\.(3|6|7|11|12|13|14|15|16|17|18) (PASS|FAIL)' /root/drift-controls-6.0.txt | while read -r _cid _cres _cts _rest; do
        _cepoch=$(_iso_to_epoch "$_cts")
        _pos="? (метка времени не разобралась)"
        if [ -n "$_cepoch" ]; then
            if [ "$_cepoch" -le "$_aw_last_i" ]; then
                _pos="внутри окна атаки"
            else
                _pos="за правой границей (+$(( _cepoch - _aw_last_i ))с, №206)"
            fi
        fi
        printf '    %-9s %-9s %-21s %s\n' "$_cid" "$_cres" "$_cts" "$_pos"
    done
fi

# 5.9.9.F.4c (продолжение): окно замера ЗАКРЫТО (idle-час [11/14] + атаки
# [12/14] позади), а всё, что идёт дальше, — снова инструментарий: сам гейт
# (сотни вызовов curl/jq/grep/awk), блок приёмки и наблюдение [14.1/14].
# Без повторной регистрации эти вызовы попадают в СНИМОК аптайма, по которому
# считается обязательная величина 8 («доля алертов измерителя < 5%») — то
# есть измеритель снова мерил бы сам себя, только на другом конце прогона.
# Регистрация здесь не может «спрятать» ничего из измеряемого: baseline,
# idle-час и окно атак уже сняты idle-run.sh и run-all-attacks.sh.
register_pipeline_observer_root

echo "=== [13/14] гейт, один вызов ==="
export IDLE_METRICS_END=$IDLE_OUT/metrics-end.txt
export IDLE_ALERTS_END=$IDLE_OUT/alerts-end.json
export IDLE_ALERTS_START=$IDLE_OUT/alerts-start.json
# 5.9.9.F.5m (№163): пара снимков /api/v1/incidents, тем же приёмом, что
# IDLE_ALERTS_START/END — источник величины 8 ниже (акторы измерителя/сборки).
export IDLE_INCIDENTS_END=$IDLE_OUT/incidents-end.json
export IDLE_INCIDENTS_START=$IDLE_OUT/incidents-start.json
export AGENT_START_FILE=/root/agent-start-6.0.txt
bash ./run-gate.sh 2>&1 | tee /root/gate-6.0.txt
GATE_RC=${PIPESTATUS[0]}
echo "гейт вернул $GATE_RC"
# Пункты 1-14 постановки №6.0 не подлежат толкованию — вытаскиваем их
# строки отдельно, чтобы приёмка волны читалась без листания всего гейта.
echo "--- унаследованные величины (счётность, кольцо, DNS, темп, реестры) ---"
grep -E '=== (19|20|22)\.|5\.9\.8a\.|негативный|позитивный|канарейка|null:|idle:|ringbuf_full|bpf_lost_events_total|events_drain_offset|excluded\{observer_tree\}' \
    /root/gate-6.0.txt | sed 's/^/  /'
grep -E 'окно атаки, 5\.9\.7d|темп алертов|settle_reason|дерева измерителя|фон вне дерева|непокрытых пунктов|база брошена|потеряно вне реестров|dns\.qname|recall' \
    /root/gate-6.0.txt | sed 's/^/  /'

# --- ПРИЁМКА ВОЛНЫ 5.9.9.F.8: две величины постановки + регресс волн 5/6/7 --
#
# ВЕЛИЧИНЫ ВОЛНЫ 8 (их всего две, и обе — про гейт):
#   (1) величина 1 ниже: FAIL=0 и эффективный SKIP=0, где из SKIP вычитается
#       ЗАКРЫТЫЙ список из ДВУХ документированных пунктов — крит. 9
#       (5.9.9.F.7c) и крит. 21 (5.9.9.F.8b). Это единственная величина
#       замера №2.9.9.F.7, которая осталась не взятой, и единственное
#       условие входа в волну 6.
#   (4) величина 4 ниже: новых акторов вне idle-actors.txt = 0, с заранее
#       записанными исходами A/B по таймеру fwupd-refresh.
# Всё остальное в этом блоке — обязательный регресс волн 5.9.9.F.3…F.7,
# повторяется без правок. Ниже — унаследованный комментарий волны 7.
#
# Величины волны 7 по её постановке: (1) SKIP=0/FAIL=0 В ГЕЙТЕ — с явным
# вычетом документированного SKIP крит. 9 (решение 5.9.9.F.7c: порог не
# назначается угадыванием, честный SKIP остаётся честным); (2) механизм нуля
# exfil_archive_to_network_pipe назван и подтверждён ДВУМЯ сторожами N из N —
# величина 10 ниже; (3) критерий №68 с обеими сторонами — величина 13, живёт
# В ОТЧЁТЕ, не в гейте; (4) доля на демонах двумя числами — величина 14.
# Величина 15 — печать входа слепого окна (7d). Всё остальное ниже —
# обязательный регресс волн 5.9.9.F.5/5.9.9.F.6, повторяется без правок.
#
# --- унаследованный комментарий волны 5.9.9.F.3 ---
#
# Здесь НЕТ die ни у одной проверки, и это осознанно — но причина другая,
# чем на №2.9.9.F.2. Там все правки делали критерии строже, и FAIL был
# успехом волны. Здесь три правки продуктовые, и их живые доказательства уже
# отработали жёсткими стопами на шаге [9.6/14], ДО траты idle-часа. Всё, что
# может сказать этот блок, — величины по итогу; ослепление сюда дойти не
# может, оно остановлено выше.
echo ""
echo "=== ПРИЁМКА ВОЛНЫ 5.9.9.F.8 — две величины постановки + регресс волн 5/6/7 ==="
acc() { printf '  %-2s %s\n' "$1" "$2"; }
ACC_TOKEN="${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}"
ACC_API="http://${VPS_IP:-localhost}:19090"
acc_alerts=$(curl -s --max-time 20 -H "Authorization: Bearer $ACC_TOKEN" "$ACC_API/api/v1/alerts" 2>/dev/null)
acc_rule() { echo "$acc_alerts" | jq --arg r "$1" '[.[]|select(.rule_id==$r)]|length' 2>/dev/null || echo '?'; }
acc_rule_crit() { echo "$acc_alerts" | jq --arg r "$1" '[.[]|select(.rule_id==$r and .severity=="critical")]|length' 2>/dev/null || echo '?'; }

# (1) SKIP=0 И FAIL=0 В ГЕЙТЕ — перенесена с №2.9.9.F.2 неисполненной.
#
# 5.9.9.F.7c: постановка волны 7 требовала здесь SKIP=0 и одновременно
# разрешала крит. 9 дать SKIP — одновременно невыполнимо. Решение принято
# явно: величина 1 читается как «SKIP=0, НЕ СЧИТАЯ документированного SKIP
# крит. 9». Счётчик самого гейта при этом НЕ правился — правка счётчика была
# бы ровно тем «зелёным правкой прибора», от чего волна защищается; вычет
# делается здесь, в приёмке, поимённо и печатью обоих чисел.
# Граница величины: она про ГЕЙТ. Критерий №68 живёт в отчёте (сверх гейта),
# его исход — величина 13 ниже, в GATE_RC он не входит и никогда не входил.
acc_line=$(grep -E '^RUN-GATE: PASS=' /root/gate-6.0.txt | tail -1)
acc_skip=$(echo "$acc_line" | sed -E 's/.*SKIP=([0-9]+).*/\1/')
acc_verdict=$(grep -cE '^\[FAIL\]|\[0;31m\[FAIL\]' /root/gate-6.0.txt || true)
# Документированные SKIP: пока ровно один — крит. 9 (5.9.9.F.7c, порог не
# назначен на выборке 12-20 инцидентов). Список ЗАКРЫТЫЙ и поимённый: любой
# другой SKIP величину 1 валит, как валил до этой правки.
# 5.9.9.F.8b (№180): список документированных SKIP расширен ВТОРЫМ и
# последним пунктом — крит. 21 (stale_transitions=0). Он не «мягче» первого:
# ветка классификации показана исполняющейся офлайн (реплей 18/21, архив
# collect-2.9.9.F.2 с флапом даёт PASS), то есть документируется «флап не
# наблюдался в этом окне», а не «критерий мёртв». Причина отсутствия флапа
# названа и измерена: 5.9.9.F.4h подняла dnsStaleThreshold 5м -> 10м ВЫШЕ
# межвсплескового интервала тихого стенда (312с на №2.9.9.F.3), и величина 12
# ниже засчитывает «0 пар» как ДОСТИГНУТО. Без этой записи величина 1
# требовала бы «0 пар» и «флап наблюдался» одновременно.
# Список ОСТАЁТСЯ ЗАКРЫТЫМ и поимённым: ровно два пункта, любой третий SKIP
# величину 1 валит, как валил до этой правки.
acc_skip_doc9=$(grep -cE '\[SKIP\].*5\.9\.9\.F\.7c' /root/gate-6.0.txt || true)
acc_skip_doc21=$(grep -cE '\[SKIP\].*stale_transitions=0' /root/gate-6.0.txt || true)
acc_skip_doc=$(( ${acc_skip_doc9:-0} + ${acc_skip_doc21:-0} ))
acc_skip_eff=$(( ${acc_skip:-99} - ${acc_skip_doc:-0} ))
if [ "${acc_skip_eff}" = "0" ] && [ "$GATE_RC" -eq 0 ]; then
    acc "1." "SKIP=${acc_skip:-?} (из них документированных крит. 9: ${acc_skip_doc:-0}), эффективный SKIP=0 и FAIL=0 ДОСТИГНУТЫ — $acc_line"
    [ "${acc_skip_doc:-0}" -gt 0 ] 2>/dev/null \
        && acc "  " "вычет по закрытому списку (2 пункта): крит. 9 = ${acc_skip_doc9:-0} (5.9.9.F.7c — порог не назначен ни доле по инцидентам, ни доле по алертам), крит. 21 = ${acc_skip_doc21:-0} (5.9.9.F.8b — флап не наблюдался, ветка показана живой реплеем 18/21); счётчик гейта не правился"
else
    acc "1." "SKIP=${acc_skip:-?} (документированных: ${acc_skip_doc:-0}, эффективный ${acc_skip_eff}), вердикт гейта $GATE_RC, строк FAIL=$acc_verdict (ожидалось: эффективный SKIP=0 и FAIL=0) — $acc_line"
    grep -E '\[SKIP\]|\[FAIL\]' /root/gate-6.0.txt | sed 's/^/       /'
    grep -E 'чья ветка не исполнилась' /root/gate-6.0.txt | sed 's/^/       /'
fi

# (2) Оба правленых правила: 0 критикалов ВНЕ позитивных контролей и
# ненулевые НА них. Абсолют по стору, а не дельта окна: контроли шага
# [9.6/14] стоят до baseline, и дельта окна их не видит по построению.
acc_a=$(acc_rule rootkit_hidden_dir_dev);        acc_a_c=$(acc_rule_crit rootkit_hidden_dir_dev)
acc_b=$(acc_rule privesc_suid_suspicious_path);  acc_b_c=$(acc_rule_crit privesc_suid_suspicious_path)
acc_bs=$(acc_rule sigma_binary_in_tmp_executed)
acc "2." "правленые правила за аптайм: rootkit_hidden_dir_dev=$acc_a (critical $acc_a_c, было 12/12), privesc_suid_suspicious_path=$acc_b (critical $acc_b_c, было 37/37), sigma_binary_in_tmp_executed=$acc_bs"
acc "  " "ожидание: у каждого >=1 (позитивные контроли шага [9.6/14]) и НИ ОДНОГО срабатывания вне них. Состав поимённо:"
echo "$acc_alerts" | jq -r '.[]|select(.rule_id=="rootkit_hidden_dir_dev" or .rule_id=="privesc_suid_suspicious_path")|"       \(.rule_id) \(.severity) comm=\(.comm) \(.details["file.path"] // "")"' 2>/dev/null | sort | uniq -c | sort -rn | head -20
if [ "${acc_a:-0}" = "0" ] || [ "${acc_b:-0}" = "0" ]; then
    acc "  " "ВНИМАНИЕ: правило с нулём за весь аптайм при исполнившемся позитивном контроле — это находка №57 (ослепление), а не сужение. Проверить маркеры шага [9.6/14] в логе выше"
fi
if echo "$acc_alerts" | jq -e '[.[]|select(.rule_id=="rootkit_hidden_dir_dev" and (.details["file.path"] // "" | test("urandom|random|console")))]|length > 0' >/dev/null 2>&1; then
    acc "  " "ВНИМАНИЕ: rootkit_hidden_dir_dev снова сработал на штатной ноде /dev — правка 3a откачена либо агент крутит старые правила"
fi

# (3) verdict="attack" за idle-час = 0 ПРИ НЕПУСТОМ idle-часе. Ноль на тихом
# часе не засчитывается: он неотличим от отсутствия входа (запрет 5.9.6i,
# PASS отсутствием события).
acc "3." "idle-час (verdict=\"attack\" = 0 при непустом часе, 5.9.9.F.3c):"
grep -E 'verdict="attack" за idle-час|алертов за idle-час|состав промоушенов по comm|промоушенов verdict=attack в журнале|промоушенов в журнале за окно idle-часа \(оба вердикта' /root/gate-6.0.txt | sed 's/^/       /'
# 5.9.9.F.5b/№153: журнал агента — независимый источник состава промоушенов
# (см. run-gate.sh, "correlator: incident promoted"), а не только снимок
# алертов. Печатается отдельно, чтобы при FAIL было видно, каким источником
# назван актор — алертами или журналом.
grep -E 'по журналу \(5\.9\.9\.F\.5b\)' /root/gate-6.0.txt | sed 's/^/       /'
# 5.9.9.F.5l/№162, долг признанный 5.9.9.F.5b: восьмая строка блока приёмки —
# записей о промоушении в журнале (оба вердикта) сходится с дельтой
# incidents_total. Раньше журнал парсился в logfmt и не читался вовсе
# (см. run-gate.sh); теперь это jq по JSON-payload, и величина впервые имеет
# вход.
grep -E 'ДОСТИГНУТО \(5\.9\.9\.F\.5b/5\.9\.9\.F\.5l\)' /root/gate-6.0.txt | sed 's/^/       /'
acc_idle_alerts=$(grep -oE 'алертов за idle-час: [0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
acc_idle_att=$(grep -oE 'verdict="attack" за idle-час: [0-9]+ -> [0-9]+, дельта = [0-9-]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9-]+$')
if [ "${acc_idle_alerts:-0}" -eq 0 ] 2>/dev/null; then
    acc "  " "ВНИМАНИЕ: idle-час ПУСТ (0 алертов) — ноль по verdict=\"attack\" получен тишиной стенда, а не починкой 3c, и величиной приёмки НЕ является (запрет 5.9.6i). Замер обязан быть повторён в час, когда стартует хотя бы один sandboxed-юнит systemd"
elif [ "${acc_idle_att:-1}" = "0" ]; then
    acc "  " "ДОСТИГНУТО: verdict=\"attack\" = 0 при непустом idle-часе ($acc_idle_alerts алертов) — 3c закрыта величиной, которой нельзя достичь тишиной"
else
    acc "  " "НЕ ДОСТИГНУТО: verdict=\"attack\" за idle-час = ${acc_idle_att:-?} при $acc_idle_alerts алертах — состав промоушенов выше называет, кто именно; если это снова песочница systemd, пункт 3c закрыт наполовину"
fi

# (4) Новых акторов = 0 БЕЗ дописывания mandb/find/install в реестр.
# Второе проверяется преflight'ом жёстко; здесь печатается результат.
# ВЕЛИЧИНА ВОЛНЫ 8 (5.9.9.F.8a, №179). Реестр пополнен ЧЕТЫРЬМЯ строками
# (fwupd/(fwupd)/fwupdmgr/(fwupdmgr)) ДО этого замера, и строка проверена
# обеими сторонами офлайн (реплей 17/21). ОБРАТНАЯ СТОРОНА ЗАПИСАНА ЗАРАНЕЕ,
# до прогона, чтобы исход нельзя было прочесть задним числом в свою пользу:
#
#   Исход A — таймер fwupd-refresh попал в idle-час этого замера.
#     Ожидается: новых акторов 0 (реестр покрывает), крит. PASS, и величина 3
#     ниже снова даст verdict="attack" = 1 с root_comm=fwupd. Это НЕ регресс и
#     НЕ успех — это находка №179, повторённая живьём; она закрывается волной
#     6, а не здесь. Гейт при этом обязан быть зелёным.
#   Исход B — таймер в час не попал (суточный, попадание ~1 час из 24).
#     Ожидается: новых акторов 0 и verdict="attack" = 0. Ноль в исходе B
#     получен ОТСУТСТВИЕМ АКТОРА, а не снятием причины — читать его как
#     «величина 3 взята» ЗАПРЕЩЕНО, и блок печатает это прямо.
#
# Различаются исходы по составу алертов idle-часа, а не по вердикту: ниже
# печатается, был ли fwupd в часе вообще.
acc "4." "состав idle-часа против idle-actors.txt (5.9.9.F.2d/№118; реестр пополнен 5.9.9.F.8a, №179 — четыре строки fwupd, проверены реплеем 17/21):"
grep -E 'новые акторы idle-часа вне idle-actors|новых акторов 0|состав ВСЕХ новых алертов idle-часа' /root/gate-6.0.txt | sed 's/^/       /'
if grep -q 'новый(е) актор(ы) idle-часа вне idle-actors.txt' /root/gate-6.0.txt; then
    acc "  " "ВНИМАНИЕ: новые акторы есть. Если среди них mandb/find/install — правки 3a/3b/3c не сняли пакет systemd, и чинить это дописыванием в реестр ЗАПРЕЩЕНО постановкой. Если акторы другие — это новое окно суток, и оно пополняет реестр законно, отдельной записью в plan.md"
else
    acc "  " "ДОСТИГНУТО (5.9.9.F.8a): новых акторов вне реестра нет"
fi
# Какой из двух заранее записанных исходов наступил.
#
# ВАЖНО ПРО ИЗВЛЕЧЕНИЕ (урок №177): счёт привязан к БЛОКУ «состав ВСЕХ новых
# алертов idle-часа по comm», а не к файлу целиком. Свободный grep по
# gate-*.txt даёт на архиве №2.9.9.F.7 восемь совпадений вместо четырёх —
# строки fwupd попадаются ещё в блоке критикалов часа и в составе промоушенов,
# и напечатанное число читалось бы как «строк состава», не будучи им.
# Проверено против ТОЧНОГО формата печати run-gate.sh на архиве F.7:
# 4 строки состава, 20 алертов (fwupd 12, (fwupd) 2, fwupdmgr 3, (fwupdmgr) 3).
acc_fwupd_stat=$(awk '
    { gsub(/\033\[[0-9;]*m/, "") }
    /состав ВСЕХ новых алертов idle-часа по comm/ { inblk=1; next }
    inblk && /^[[:space:]]*(новые акторы|===|\[)/ { inblk=0 }
    inblk && match($0, /^[[:space:]]+\(?fwupd(mgr)?\)?: [0-9]+$/) {
        n++; split($0, a, ": "); alerts += a[2]
    }
    END { printf "%d %d", n+0, alerts+0 }' /root/gate-6.0.txt 2>/dev/null || echo "0 0")
acc_fwupd_lines=${acc_fwupd_stat%% *}
acc_fwupd_alerts=${acc_fwupd_stat##* }
if [ "${acc_fwupd_lines:-0}" -gt 0 ] 2>/dev/null; then
    acc "  " "ИСХОД A (записан заранее): таймер fwupd-refresh попал в idle-час — строк fwupd/fwupdmgr в составе часа: $acc_fwupd_lines, алертов: $acc_fwupd_alerts (на №2.9.9.F.7 было 4 и 20). Величина 3 ниже, если она даст verdict=\"attack\"=1 с root_comm=fwupd, повторяет находку №179 живьём; это ВХОД ВОЛНЫ 6, а не регресс волны 8"
else
    acc "  " "ИСХОД B (записан заранее): таймер fwupd-refresh в idle-час НЕ попал (суточный, попадание ~1 час из 24). Ноль величины 3 ниже получен ОТСУТСТВИЕМ АКТОРА, а не снятием причины — читать его как «величина 3 взята» ЗАПРЕЩЕНО; находка №179 остаётся открытой и непроверенной этим замером"
fi

# (5) Регресс правок волн 5.9.9.F/F.1 на месте.
acc_dump=$(acc_rule sigma_memory_proc_dump)
acc_sql=$(acc_rule web_sql_injection_files)
acc_cred=$(acc_rule cred_proc_maps_mass_read)
acc "5." "регресс прошлых волн: sigma_memory_proc_dump=$acc_dump (ожидается >=1), web_sql_injection_files=$acc_sql (ожидается 0), cred_proc_maps_mass_read=$acc_cred (ожидается >=1)"
[ "${acc_dump:-0}" = "0" ] && acc "  " "ВНИМАНИЕ: sigma_memory_proc_dump=0 — находка №57 на правке 5.9.9.F.1b"
[ "${acc_sql:-0}" != "0" ] && acc "  " "ВНИМАНИЕ: web_sql_injection_files=$acc_sql != 0 — правка 5.9.9.F.1c откачена"
[ "${acc_cred:-0}" = "0" ] && acc "  " "ВНИМАНИЕ: cred_proc_maps_mass_read=0 — находка №57 на правке 5.9.9.Fa"

# (6) 5.9.9.F.5c/№157: порог по СМЫСЛУ, не по константе 4, унаследованной
# с №2.9.9.F.2 (преflight этой волны вырос на пять жёстких стопов —
# константа больше ничего не защищает от). FAIL только если среди типов,
# напечатанных с меткой «наведено преflight-шагом» (то есть НЕ получивших
# композитную "phase+induced" метку — run-gate.sh:1113-1160), находится
# хотя бы один, чей рост НЕЗАВИСИМО подтверждается ростом
# ebpf_guard_alerts_total{rule_id=...} между IDLE_METRICS_START/END: если
# он растёт там — композитная метка была ОБЯЗАНА сработать (5.9.9.F.3d) и
# не сработала, то есть находка №134 вернулась. Идентична по данным
# add_idle_list из run-gate.sh, но вычисляется ЗАНОВО из тех же файлов
# снимков — это регресс-страховка на случай, если порядок веток в
# run-gate.sh снова переставят неверно, а не переиспользование того же
# результата под другим именем.
acc "6." "фазы прироста состава детекта (5.9.9.F.3d/№134, порог по смыслу — 5.9.9.F.5c/№157):"
grep -E 'добавлено по фазам|наведено шагом преflight' /root/gate-6.0.txt | head -14 | sed 's/^/       /'
acc_induced=$(grep -oE 'наведено преflight-шагом=[0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
acc_induced_ids=$(awk '/наведено шагом преflight.*вне измеряемых окон/{f=1; next} f && /^    \* /{sub(/^    \* /,""); print; next} f && !/^    \* /{exit}' /root/gate-6.0.txt)
acc_induced_absorbed=""
if [ -n "$acc_induced_ids" ] && [ -s "$IDLE_METRICS_START" ] && [ -s "$IDLE_METRICS_END" ]; then
    idle_grown_rules_5c=$(awk -F'[{}", ]+' -v metric="ebpf_guard_alerts_total" -v startfile="$IDLE_METRICS_START" '
        function rule_id(   i, rid) { rid=""; for (i=1;i<=NF;i++) { if ($i ~ /^rule_id=?$/) { rid=$(i+1); break } }; return rid }
        { gsub(/\r/, "") }
        index($0, metric "{") != 1 { next }
        { rid = rule_id(); if (rid == "") next
          if (FILENAME == startfile) { start[rid] += $NF; next }
          end[rid] += $NF; seen[rid] = 1 }
        END { for (r in seen) if (end[r] - (start[r]+0) > 0) print r }
    ' "$IDLE_METRICS_START" "$IDLE_METRICS_END" 2>/dev/null)
    while IFS= read -r rid; do
        [ -z "$rid" ] && continue
        if echo "$idle_grown_rules_5c" | grep -qx "$rid"; then
            acc_induced_absorbed="$acc_induced_absorbed$rid"$'\n'
        fi
    done <<< "$acc_induced_ids"
fi
acc_induced_absorbed=$(echo "$acc_induced_absorbed" | grep -v '^$' || true)
if [ -n "$acc_induced_absorbed" ]; then
    acc "  " "НЕ ДОСТИГНУТО: тип(ы) $(echo "$acc_induced_absorbed" | tr '\n' ' ') напечатаны с плоской меткой «наведено преflight-шагом», но независимо от gate.txt растут в ebpf_guard_alerts_total между IDLE_METRICS_START/END — композитная idle+induced метка обязана была сработать (5.9.9.F.3d) и не сработала. Находка №134 вернулась"
elif [ -n "$acc_induced_ids" ]; then
    acc "  " "ДОСТИГНУТО: наведено преflight-шагом=${acc_induced:-?} тип(ов) ($(echo "$acc_induced_ids" | tr '\n' ' ')), ни один независимо не растёт в idle-окне — поглощение idle меткой преflight'а не воспроизводится. Величина оценивается ПО СМЫСЛУ, а не порогом (5.9.9.F.5c/№157: число 4, унаследованное с №2.9.9.F.2, снято)"
else
    acc "  " "ДОСТИГНУТО: наведено преflight-шагом=0 — нечего поглощать по построению"
fi
acc "  " "ГРАНИЦА (5.9.9.F.5c): независимая проверка охватывает только idle-окно (IDLE_METRICS_START/END доступны пайплайну напрямую); окно атак опирается на собственный инвариант run-gate.sh (attack/idle/gap проверяются ДО induced, 5.9.9.F.3d) без второй, независимо вычисленной, копии — своих снимков baseline/final metrics у пайплайна нет"

# --- Новые величины волны 5.9.9.F.4: 7-12. Все пункты волны исполнены в
# дереве (4a-4h) плюс перенос 4i, поэтому печатаются ВСЕ шесть новых величин,
# а не подмножество. Величина без печати не является величиной приёмки —
# ровно так 5.9.9.F.2c/2g прошли замер незаведёнными (№138). ---

# (7) 5.9.9.F.4a/4b/№141/№142: ни одного инцидента verdict=attack, чья цепочка
# содержит актора вида (...) при ppid==1 — за ВЕСЬ аптайм (idle-час + окно
# атак). Считается по актору инцидента (пункт 4b), а не глобальной дельтой:
# ровно на этой подмене сторож №2.9.9.F.3 назвал субъектом man-db вместо фона
# самого измерителя.
acc_sandbox_inc=$(fp_sandbox_actor_attack_incidents 2>/dev/null || echo "?")
acc "7." "инцидентов verdict=attack с актором песочницы «(...)»/ppid==1 в цепочке (5.9.9.F.4a/4b): ${acc_sandbox_inc}"
if [ "${acc_sandbox_inc:-?}" = "0" ]; then
    acc "  " "ДОСТИГНУТО: 0 — двенадцать правил (5.9.9.F.4a) сняли класс актора целиком, и корреляция больше не набирает score на нём из остальных правил"
elif [ "${acc_sandbox_inc:-?}" = "?" ]; then
    acc "  " "SKIP: /api/v1/incidents недоступен — величина 7 не посчитана (не PASS)"
else
    acc "  " "НЕ ДОСТИГНУТО: ${acc_sandbox_inc} инцидент(ов) — состав:"
    fp_incidents 2>/dev/null | jq -r '.[]|select(.verdict=="attack")|select(((.process_chain // []) + (.comms // [])) | any(test("^\\(.*\\)$")))|"       incident \(.id // "-") comm=\(.comm // "-") rules=\((.rule_ids // []) | join(","))"' 2>/dev/null | head -10
    acc "  " "читать так: если правила инцидента — НЕ двенадцать правил 4a, класс актора поднимают ЕЩЁ какие-то правила, и список №141 неполон так же, как был неполон список 3c (это находка следующего замера, а не провал 4a); если правила ИЗ списка 4a — исключение не применилось, правка не в дереве или агент крутит старые правила"
fi

# (8) 5.9.9.F.4c/№147, пересчитано 5.9.9.F.5e/№155, ИСТОЧНИК ЗАМЕНЁН
# 5.9.9.F.5m/№163: доля от акторов измерителя и сборки СЧИТАЕТСЯ ПО ОКНАМ
# ОТДЕЛЬНО (преflight / idle-час / окно атак), а не одной цифрой за весь
# аптайм — это решение 5.9.9.F.5e не меняется. Меняется ЕДИНИЦА СЧЁТА:
# инциденты, а не алерты.
#
# РАЗВИЛКА 5.9.9.F.5m, выбор записан ДО правки: постановка предлагала два
# варианта — (1) довести колонку process_tree до SQLite-стора и до ответа
# /api/v1/alerts, (2) считать величину по инцидентам, у которых RootComm и
# ProcessChain уже есть сегодня (pkg/types/incident.go). Выбран **вариант
# 2**: он не трогает продукт (ни схему стора, ни сериализацию Alert — только
# offline-скрипты пайплайна) и не идёт на ту же грабли, на которую 5.9.9.F.5e
# уже наступил: `.process_tree` алерта — ЗАВОДИТСЯ engine'ом только когда
# сконфигурирован LineageTracker (pkg/types/event.go, комментарий у поля),
# то есть поле № 163 нашёл дважды пустым — и на алерте, и в сторе — по
# одной и той же причине; RootComm/ProcessChain у Incident заполняются
# отдельным путём (IncidentTracker) и НЕ зависят от LineageTracker.
#
# Подстановка `// "bash"` УБРАНА (прямое требование постановки): раньше
# `(.process_tree // [])[0].comm // "bash"` молча превращала «поля нет» в
# «корень — bash», то есть ЛЮБОЙ алерт без process_tree классифицировался
# как «дерево пайплайна/манифеста» без единого факта на это. Инцидент без
# root_comm (`.root_comm // ""` даёт пустую строку) НЕ проходит проверку
# «корень — интерпретатор», то есть по умолчанию считается НЕ-харнессом —
# безопасное направление ошибки (недосчитать harness хуже недостоверно, чем
# счесть продуктовый алерт фоном измерителя).
#
# Список harness-comm не изменился — поимённо из постановки волны: curl, jq,
# grep, go, ld, clang, llvm-strip, bpf2go, *.test, cmdlinescan.
acc_harness_comms='["curl","jq","grep","go","ld","clang","llvm-strip","bpf2go","cmdlinescan"]'
# ГРАНИЦА, унаследованная от 5.9.9.F.5e и НЕ снятая заменой источника:
# root_comm по-прежнему не отличает дерево пайплайна от дерева
# run-all-attacks.sh МЕЖДУ СОБОЙ — оба "bash script.sh", kernel даёт
# одинаковый comm="bash" на каждом уровне (тот же класс дефекта, что
# shebang-control-comm-is-interpreter.md, для уровня "оболочка"). Инциденты
# несут ProcessChain целиком (не только корень), но это не окно и не
# отличает манифест от пайплайна без имени скрипта в argv, которого comm не
# хранит. Открытый вопрос остаётся открытым; порог <5% по-прежнему
# применяется ТОЛЬКО к преflight-окну, где манифест ещё не запущен.
acc_harness_root_ok='((.root_comm // "") as $rc | ($rc == "bash" or $rc == "sh" or $rc == "dash"))'
acc_harness_filter="((.comm // \"\") as \$c | (\$hc | index(\$c)) or (\$c | test(\"\\\\.test\$\"))) and $acc_harness_root_ok"

acc_win_stats() {
    # $1 = incidents JSON (массив). Печатает "harness total pct" одной строкой.
    local json="$1" total harness pct
    total=$(echo "$json" | jq 'length' 2>/dev/null)
    harness=$(echo "$json" | jq --argjson hc "$acc_harness_comms" "[.[] | select($acc_harness_filter)] | length" 2>/dev/null)
    if [ "${total:-0}" -gt 0 ] 2>/dev/null; then
        pct=$(awk -v h="${harness:-0}" -v t="$total" 'BEGIN{printf "%.1f", 100*h/t}')
    else
        pct="n/a"
    fi
    echo "${harness:-?} ${total:-0} ${pct}"
}
acc_win_breakdown() {
    # $1 = incidents JSON. Состав по паре (comm, rule) — 5.9.9.F.5f, перенесено
    # на инциденты: rule_ids — МАССИВ (инцидент может нести несколько правил),
    # группировка идёт по (comm, каждое правило из rule_ids) через `[]`, а не
    # по единственному .rule_id (которого у инцидента нет).
    echo "$1" | jq --argjson hc "$acc_harness_comms" -r \
        "[.[] | select($acc_harness_filter)] | map(. as \$i | (\$i.rule_ids // [\"(пусто)\"])[] | {c: (\$i.comm // \"(пусто)\"), r: .}) | group_by([.c, .r]) | map({c: (.[0].c), r: (.[0].r), n: length}) | sort_by(-.n) | .[] | \"       \(.n)\t\(.c)\t\(.r)\"" \
        2>/dev/null | head -20
}

# Окно преflight'а: снимок IDLE_INCIDENTS_START (idle-run.sh пишет его ДО
# первого тика idle-часа, тем же вызовом api_multi, что alerts-start.json —
# 5.9.9.F.5m/№163). Взят как есть (все инциденты в файле), а не диффом от
# нулевой точки: агент перезапущен на [9/14], и допущение — что стор пуст на
# рестарте — не проверено живым замером (записано открытым вопросом ниже).
acc_pf_json='[]'
[ -s "$IDLE_INCIDENTS_START" ] && acc_pf_json=$(cat "$IDLE_INCIDENTS_START" 2>/dev/null || echo '[]')

# Окно idle-часа: новые по id инциденты между IDLE_INCIDENTS_START и
# IDLE_INCIDENTS_END — та же пара снимков, что величина 3 использует для
# алертов, но на инцидентах (5.9.9.F.5m).
acc_idle_json='[]'
acc_idle_have=0
if [ -s "$IDLE_INCIDENTS_START" ] && [ -s "$IDLE_INCIDENTS_END" ]; then
    acc_idle_json=$(jq -n --slurpfile a "$IDLE_INCIDENTS_START" --slurpfile b "$IDLE_INCIDENTS_END" \
        '($a[0]|map(.id)) as $seen | ($b[0]|map(select(.id as $i | ($seen|index($i))|not)))' 2>/dev/null)
    [ -n "$acc_idle_json" ] && acc_idle_have=1
fi

# Окно атак: новые по id инциденты между baseline-incidents-*.json и
# final-incidents-*.json последнего вызова run-all-attacks.sh — эта пара УЖЕ
# существует и пишется самим контролем (get_baseline_metrics/get_final_metrics,
# run-all-attacks.sh) на каждый TIMESTAMP, run-gate.sh уже читает
# final-incidents-$TIMESTAMP.json под именем final_incidents; здесь берётся та
# же пара, что и baseline-alerts/final-alerts у величины 8 до этого пункта —
# самый ПОЗДНИЙ по имени файл (в имени YYYYmmdd_HHMMSS, это вызов [12/14]).
acc_attack_dir="$SETUP/attacks/attack-results"
acc_attack_baseline_file=$(ls -1 "$acc_attack_dir"/baseline-incidents-*.json 2>/dev/null | LC_ALL=C sort | tail -1)
acc_attack_final_file=$(ls -1 "$acc_attack_dir"/final-incidents-*.json 2>/dev/null | LC_ALL=C sort | tail -1)
acc_attack_json='[]'
acc_attack_have=0
if [ -s "$acc_attack_baseline_file" ] && [ -s "$acc_attack_final_file" ]; then
    acc_attack_json=$(jq -n --slurpfile a "$acc_attack_baseline_file" --slurpfile b "$acc_attack_final_file" \
        '($a[0]|map(.id)) as $seen | ($b[0]|map(select(.id as $i | ($seen|index($i))|not)))' 2>/dev/null)
    [ -n "$acc_attack_json" ] && acc_attack_have=1
fi

read -r acc_pf_h acc_pf_t acc_pf_pct <<< "$(acc_win_stats "$acc_pf_json")"
acc "8." "доля ИНЦИДЕНТОВ от акторов измерителя и сборки, по окнам (5.9.9.F.4c/5.9.9.F.5e/5.9.9.F.5m/№147/№155/№163; единица счёта — инцидент, не алерт, см. РАЗВИЛКА выше)"
acc "  " "преflight: $acc_pf_h из $acc_pf_t (${acc_pf_pct}%) — единственное окно с порогом < 5% (было 55%/27.6% на отклонённом/предыдущем замерах, считались по алертам — цифры не сопоставимы напрямую с этой строкой)"
if [ "${acc_pf_t:-0}" -gt 0 ] 2>/dev/null; then
    if awk -v p="$acc_pf_pct" 'BEGIN{exit !(p < 5)}'; then
        acc "  " "ДОСТИГНУТО: преflight < 5%"
    else
        acc "  " "НЕ ДОСТИГНУТО: преflight >= 5% — состав по (comm, rule):"
        acc_win_breakdown "$acc_pf_json"
    fi
else
    acc "  " "SKIP: IDLE_INCIDENTS_START пуст или недоступен — преflight-доля не посчитана"
fi

if [ "$acc_idle_have" -eq 1 ]; then
    read -r acc_idle_h acc_idle_t acc_idle_pct <<< "$(acc_win_stats "$acc_idle_json")"
    acc "  " "idle-час: $acc_idle_h из $acc_idle_t (${acc_idle_pct}%) — наблюдение без порога (постановка 5.9.9.F.5e трогает только преflight); ненулевое здесь — атаки ещё не запущены, харнесс-comm может быть только утечкой поллинга idle-run.sh"
    [ "${acc_idle_h:-0}" -gt 0 ] 2>/dev/null && acc_win_breakdown "$acc_idle_json"
else
    acc "  " "idle-час: SKIP — IDLE_INCIDENTS_START/END недоступны, доля не посчитана"
fi

if [ "$acc_attack_have" -eq 1 ]; then
    read -r acc_atk_h acc_atk_t acc_atk_pct <<< "$(acc_win_stats "$acc_attack_json")"
    acc "  " "окно атак: $acc_atk_h из $acc_atk_t (${acc_atk_pct}%) — наблюдение без порога; ЧИСЛО НЕ ОЧИЩЕНО от кривой манифеста: curl/jq здесь могут быть как оркестровкой run-all-attacks.sh (настоящий фон), так и полезной нагрузкой атаки (lateral_tool_transfer_wget через curl и т.п.) — root_comm их не различает (оба дерева = bash, см. ГРАНИЦА выше), состав ниже — единственный способ разобрать это глазами"
    [ "${acc_atk_h:-0}" -gt 0 ] 2>/dev/null && acc_win_breakdown "$acc_attack_json"
else
    acc "  " "окно атак: SKIP — baseline/final-incidents-*.json последнего run-all-attacks.sh не найдены в $acc_attack_dir"
fi
# (8, "Учёт" п.2 постановки 4c) systemctl/journalctl говорят с pid 1 по
# dbus — pid 1 потомком дерева пайплайна не является ни при каком root_pid
# (config-test.yaml, комментарий 5.9.5f/находка №68), поэтому регистрация
# выше их не ловит по построению. Устранить эти вызовы из окна пайплайн не
# может (systemctl start/stop/show нужны шагу [5/14], journalctl — шагу
# [6/14], оба — преflight) — постановка требует напечатать остаток отдельной
# величиной наблюдения, а не списывать его молча на 4c. Считается по
# преflight-окну (acc_pf_json), а не по всему аптайму — pid1-акторы этих двух
# шагов физически не могут появиться в idle-часе/окне атак.
acc_pid1_actors='["systemd","systemd-logind","dbus-daemon","polkitd","journald","systemd-journal","systemd-udevd"]'
acc_pid1_alerts=$(echo "$acc_pf_json" | jq --argjson pc "$acc_pid1_actors" '[.[] | select((.comm // "") as $c | $pc | index($c))] | length' 2>/dev/null)
acc "  " "наблюдение без порога: инцидентов преflight'а от акторов, наведённых pid 1 (systemctl/journalctl самого пайплайна, дерево-исключение их не ловит) = ${acc_pid1_alerts:-0} (5.9.9.F.5m: acc_pf_json теперь инциденты, не алерты)"
acc_excl_obs=$(grep -oE 'excluded\{observer_tree\}[^:]*: [0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
if [ "${acc_excl_obs:-0}" -gt 0 ] 2>/dev/null; then
    acc "  " "ДОСТИГНУТО: events_excluded_total{reason=\"observer_tree\"} = $acc_excl_obs (не ноль — исключение действительно сработало, доля не упала по другой причине)"
else
    acc "  " "ВНИМАНИЕ: events_excluded_total{reason=\"observer_tree\"} = ${acc_excl_obs:-0} — если доля выше при этом упала, падение объяснить нечем (пункт 4c регистрации не сработал), значение пункта 8 под вопросом"
fi

# (9) 5.9.9.F.4d/№144: owasp_path_traversal + web_path_traversal_extended —
# 0 критикалов вне позитивного контроля, ненулевые НА нём. Абсолют по
# стору, тем же приёмом, что величина 2.
acc_pt1=$(acc_rule owasp_path_traversal); acc_pt1_c=$(acc_rule_crit owasp_path_traversal)
acc_pt2=$(acc_rule web_path_traversal_extended); acc_pt2_c=$(acc_rule_crit web_path_traversal_extended)
acc "9." "path traversal за аптайм (5.9.9.F.4d/№144): owasp_path_traversal=$acc_pt1 (critical $acc_pt1_c, было 18+7+3+1+1=30 ложных), web_path_traversal_extended=$acc_pt2 (critical $acc_pt2_c, было столько же ложных)"
echo "$acc_alerts" | jq -r '.[]|select(.rule_id=="owasp_path_traversal" or .rule_id=="web_path_traversal_extended")|"       \(.rule_id) \(.severity) comm=\(.comm)"' 2>/dev/null | sort | uniq -c | sort -rn | head -20
acc_pt_offcomm=$(echo "$acc_alerts" | jq '[.[]|select((.rule_id=="owasp_path_traversal" or .rule_id=="web_path_traversal_extended") and ((.comm // "") as $c | (["nginx","apache2","httpd","php-fpm","node","python","gunicorn","uwsgi","java","tomcat"] | index($c)) | not))] | length' 2>/dev/null)
if [ "${acc_pt_offcomm:-0}" != "0" ]; then
    acc "  " "ВНИМАНИЕ: $acc_pt_offcomm срабатывание(й) с comm вне списка веб-воркера — сужение (5.9.9.F.4d) неполно, правило грузит старую версию, либо в reports попал comm, который стоит добавить в список"
fi
# Маркер контроля читается из attack-manifest.json (category), туда его пишет
# run_path_traversal_positive_control — без этого «0 за аптайм» неотличим от
# «контроль не исполнился», и величина 9 не читается вовсе.
acc_pt_pos=$(jq '[.[]|select(.category=="path_traversal_positive_control")]|length' $SETUP/attacks/attack-manifest.json 2>/dev/null || echo 0)
acc "  " "маркеров позитивного контроля 5.9.9.F.4d в attack-manifest.json: ${acc_pt_pos:-0}"
if [ "${acc_pt1:-0}" = "0" ] && [ "${acc_pt2:-0}" = "0" ]; then
    if [ "${acc_pt_pos:-0}" = "0" ]; then
        acc "  " "ВНИМАНИЕ: оба правила = 0 за аптайм И контроль не исполнился (маркера нет) — ноль без входа, величина 9 НЕ засчитывается"
    else
        acc "  " "НЕ ДОСТИГНУТО: оба правила = 0 за аптайм ПРИ исполнившемся контроле — это находка №57 (ослепление), а не сужение 5.9.9.F.4d"
    fi
elif [ "${acc_pt_pos:-0}" != "0" ] && [ "${acc_pt_offcomm:-0}" = "0" ]; then
    acc "  " "ДОСТИГНУТО: срабатывания есть, все с comm веб-воркера, контроль исполнился"
fi

# (10) 5.9.9.F.4e/№145: exfil_archive_to_network_pipe. Негатив (одиночный
# curl без архиватора-родителя) исполняется десятками вызовов манифеста по
# построению; позитив — run_exfil_archive_parent_positive_control.
# ГРАНИЦА: правка выражает только РОДИТЕЛЬСКУЮ форму (tar -> curl). Дословная
# формулировка величины постановки («Δ≥1 на tar | curl») описывает
# sibling-форму классического пайпа, которой движок не видит вовсе — она
# остаётся невыполненной до stateful-корреляции братьев, и это записано
# заранее (plan.md, 4e), а не объясняется задним числом нулём в этой строке.
# РЕШЕНИЕ 5.9.9.F.5a, принятое до замера (plan.md, блок исполнения 5j/5a):
# из двух вариантов постановки выбран ПЕРВЫЙ — величина 10 переформулирована
# по родительской форме, и именно её измеряет эта строка. Второй вариант
# (stateful-корреляция братьев) — продуктовая работа в корреляторе, вынесена
# отдельной находкой №168 и в границу этой волны не входит; ноль на
# sibling-форме поэтому НЕ является исходом величины 10 ни в одну сторону.
acc_exfil=$(acc_rule exfil_archive_to_network_pipe)
# Маркер контроля лежит В МАНИФЕСТЕ (attack-manifest.json, category), а не
# отдельным файлом в attack-results/ — так его пишет
# run_exfil_archive_parent_positive_control. 5.9.9.F.5a/№152: маркер сам по
# себе больше не доказывает форму — контроль раньше исполнялся и писал
# маркер, создавая ПОДРАЖАТЕЛЯ comm=bash (интерпретатор шебанг-скрипта), а
# не comm=tar. Поле comm_verified — это то, что сторож самого контроля
# (/proc/self/comm) подтвердил ДО записи в манифест.
acc_exfil_pos=$(jq '[.[]|select(.category=="exfil_archive_parent_positive_control")]|length' $SETUP/attacks/attack-manifest.json 2>/dev/null || echo 0)
acc_exfil_comm_ok=$(jq '[.[]|select(.category=="exfil_archive_parent_positive_control" and .comm_verified==true)]|length' $SETUP/attacks/attack-manifest.json 2>/dev/null || echo 0)
# 5.9.9.F.7a/№176: ВТОРОЙ сторож — состоялся ли execve сетевой утилиты.
# Первый (comm_verified) говорит только про comm АРХИВАТОРА и на
# №2.9.9.F.5/№2.9.9.F.6 давал 20/20 при том, что события с comm=curl не
# рождалось вовсе (битая симлинка -> ENOENT). Ноль правила при exec_ok < N
# не является измерением продукта ни в одну сторону.
acc_exfil_exec_ok=$(jq '[.[]|select(.category=="exfil_archive_parent_positive_control" and .exec_verified==true)]|length' $SETUP/attacks/attack-manifest.json 2>/dev/null || echo 0)
acc_exfil_rcs=$(jq -r '[.[]|select(.category=="exfil_archive_parent_positive_control")|.exec_rc // "?"]|group_by(.)|map("\(.[0])×\(length)")|join(", ")' $SETUP/attacks/attack-manifest.json 2>/dev/null || echo '?')
acc "10." "exfil_archive_to_network_pipe за аптайм (5.9.9.F.7a/№176, было 5.9.9.F.6d/№173): $acc_exfil (96 на №2.9.9.F.3, 0 на №2.9.9.F.5 и №2.9.9.F.6 — ЛОЖНЫЙ ноль битой фикстуры, механизм назван №176), повторов позитивного контроля: $acc_exfil_pos, comm=tar подтверждён: $acc_exfil_comm_ok, execve сетевой утилиты успешен: $acc_exfil_exec_ok"
acc "  " "коды возврата execve по повторам (сторож 5.9.9.F.7a; 0=образ подменён, 127=нет файла/битая симлинка, 126=не исполняется): $acc_exfil_rcs"
echo "$acc_alerts" | jq -r '.[]|select(.rule_id=="exfil_archive_to_network_pipe")|"       comm=\(.comm) parent=\(.details["proc.parent_comm"] // "-")"' 2>/dev/null | sort | uniq -c | sort -rn | head -10
# 5.9.9.F.6d (№173): постановка требует ОДНОЗНАЧНЫЙ исход только при N≥20 и
# N из N подтверждённых comm=tar — частичное подтверждение (как и на
# №2.9.9.F.5 с N=1) величиной не является ни в одну сторону, это то же
# самое различие "0 без входа" vs "0 с доказанным входом", применённое к N.
if [ "${acc_exfil_pos:-0}" -lt 20 ] 2>/dev/null; then
    acc "  " "ВНИМАНИЕ: повторов контроля меньше 20 ($acc_exfil_pos) — величина 10 требует N≥20, при N<20 исход неотличим от недоисполнившегося контроля, НЕ засчитывается"
elif [ "${acc_exfil_comm_ok:-0}" != "${acc_exfil_pos:-0}" ]; then
    acc "  " "FAIL(сторож 5.9.9.F.5k/6d): $acc_exfil_comm_ok из $acc_exfil_pos повторов подтвердили comm=tar — постановка требует N ИЗ N, частичное подтверждение величину 10 не закрывает ни в одну сторону"
elif [ "${acc_exfil_exec_ok:-0}" != "${acc_exfil_pos:-0}" ]; then
    acc "  " "FAIL(сторож 5.9.9.F.7a): $acc_exfil_exec_ok из $acc_exfil_pos повторов дали успешный execve сетевой утилиты (коды: $acc_exfil_rcs) — событие с comm=curl рождается ТОЛЬКО на успешном execve, значит фикстура сломана на этом стенде, и любой исход правила (ноль или нет) измеряет фикстуру, а не продукт. Это ровно механизм №176, стоивший замеров №2.9.9.F.5 и №2.9.9.F.6"
elif [ "${acc_exfil:-0}" = "0" ]; then
    acc "  " "НЕ ДОСТИГНУТО ПРИ ОБОИХ ИСПРАВНЫХ СТОРОЖАХ — это НОВЫЙ, ещё не разобранный механизм: №176 (битая фикстура) снят по результату (exec_rc=0 на N из N), значит событие с comm=curl в ядре БЫЛО, родитель tar подтверждён, а правило всё равно молчит. Прежний текст развилки 6d ниже сохранён как история, но к этому исходу больше не применим: следующая волна разбирает путь события (BPF -> коллектор -> коррелятор), а не форму контроля."
    acc "  " "[история 6d] РАЗВИЛКА 6d ЗАКРЫТА В ПОЛЬЗУ ГИПОТЕЗЫ (1)/ослепления формой события: $acc_exfil_pos из $acc_exfil_pos повторов дали подтверждённый comm=tar (сэмплирование снято статистически, tail-call exec снят конструктивно — гарантированный форк, без '||'), а правило всё равно дало 0. Это ДОПУСТИМЫЙ исход постановки: заводится ПРОДУКТОВЫЙ пункт следующей волны — либо execve-событие начинает нести пост-exec comm вместе с parent_comm, либо правило переносится из detection-baseline.txt в intentional-loss.txt с этой причиной. Запись в silent-rules.txt по-прежнему ЗАПРЕЩЕНА постановкой."
else
    acc "  " "ДОСТИГНУТО: $acc_exfil_pos из $acc_exfil_pos повторов подтвердили comm=tar И успешный execve (оба сторожа N из N), правило дало $acc_exfil срабатывание(й) — родительская форма tar->curl поднимает правило, величина 10 закрыта; FAIL'ы «потеряно вне реестров» и «немо без объяснения» снимаются"
    # 5.9.9.F.7a: потолок per-rule лимитера — 10 алертов/правило/60с
    # ([[per-rule-rate-limit-ceiling]]). 20 повторов исполняются за секунды,
    # поэтому $acc_exfil СТРУКТУРНО не может дойти до 20: точечная проверка
    # 7a дала 12 при 20 исполненных повторах. Величина 10 сформулирована
    # как «> 0», а не «= N», и потолок её НЕ ломает — но число печатается
    # рядом, чтобы разрыв 20 vs $acc_exfil не читался как потеря детекта.
    if [ "${acc_exfil:-0}" -lt "${acc_exfil_pos:-0}" ] 2>/dev/null; then
        acc "  " "ГРАНИЦА (5.9.9.F.7a): алертов $acc_exfil при $acc_exfil_pos исполненных повторах — разрыв ожидаем и не является потерей детекта: потолок per-rule лимитера 10 алертов/60с, а повторы идут за секунды. Величина 10 требует > 0, не N из N (N из N требуют СТОРОЖА, а не алерты)"
    fi
fi

# (11) 5.9.9.F.4f/№146, переименовано и понижено 5.9.9.F.5g/№154:
# drift_exec_from_system_bin (был drift_new_exec_critical). Предикат
# переведён с op==open на факт exec, поэтому «0 на open() без exec»
# достигается по построению; смысл имеет ВТОРАЯ половина — ненулевое на
# настоящем exec из манифеста. Severity понижена critical -> warning
# (5.9.9.F.5g: 576/607 алертов и 576/577 критикалов idle-часа №2.9.9.F.4
# были этим правилом, 499 из них — пере-exec sshd на входящее ssh-соединение
# на публичном IP стенда, а не drift-сигнал; critical остаётся зарезервирован
# за вариантом с включённой profiler.drift_baseline, не реализованным этой
# сессией). acc_drift_c поэтому больше не измеряет "критикалы этого правила
# за аптайм" содержательно — он обязан быть 0 (или близко к нему) на любом
# исправном дереве, поскольку правило больше не critical; ненулевое значение
# здесь означает, что агент крутит СТАРУЮ версию правила (rename/severity не
# доехали), а не "правило сработало сильнее".
acc_drift=$(acc_rule drift_exec_from_system_bin); acc_drift_c=$(acc_rule_crit drift_exec_from_system_bin)
acc "11." "drift_exec_from_system_bin за аптайм (5.9.9.F.4f/№146, severity понижена 5.9.9.F.5g/№154): $acc_drift (critical $acc_drift_c — обязан быть 0 после rename, ненулевое значит старая версия правила)"
acc_drift_file_ev=$(echo "$acc_alerts" | jq '[.[]|select(.rule_id=="drift_exec_from_system_bin" and ((.details["file.path"] // "") != "") and ((.details["proc.args"] // "") == ""))]|length' 2>/dev/null)
if [ "${acc_drift_file_ev:-0}" != "0" ]; then
    acc "  " "ВНИМАНИЕ: ${acc_drift_file_ev} срабатывание(й) без proc.args — правило по-прежнему матчится на файловом событии, то есть агент крутит СТАРУЮ версию правила (правка 4f не доехала)"
fi
if [ "${acc_drift:-0}" = "0" ]; then
    acc "  " "ВНИМАНИЕ: 0 за весь аптайм при исполнившемся манифесте атак — правило ослеплено переводом на proc.args (argv[0] дропнутых бинарей манифеста, видимо, не абсолютный путь под /bin|/usr/bin), это находка №57, а не успех сужения"
else
    acc "  " "состав (кто исполнялся):"
    echo "$acc_alerts" | jq -r '.[]|select(.rule_id=="drift_exec_from_system_bin")|"       \(.severity)\tcomm=\(.comm)\t\(.details["proc.args"] // .details["file.path"] // "-")"' 2>/dev/null | sort | uniq -c | sort -rn | head -15
fi

# 5.9.9.F.6e (№164): постановка волны 6 требует, чтобы величина 11 была
# взята С ОБЕИХ СТОРОН — гейт уже печатает пару "объём/срезано" по правилу
# (секция 5.9.9.F.6b), приёмке остаётся процитировать её для ИМЕННО ЭТОГО
# правила. Объём, напечатанный без пары, по постановке волны 6 не
# засчитывается — drift_exec_from_system_bin упирался в потолок лимитера на
# №2.9.9.F.5 (859 опубликовано за аптайм при 713 срезанных за ОДИН idle-час),
# то есть без второго числа $acc_drift выше — величина лимитера, а не правила.
acc_drift_cut_line=$(grep -E 'drift_exec_from_system_bin[[:space:]]+стор' /root/gate-6.0.txt | tail -1)
acc_drift_cut=$(grep -oE 'срезано[[:space:]]+[0-9]+' <<<"$acc_drift_cut_line" | grep -oE '[0-9]+')
if [ -z "$acc_drift_cut_line" ]; then
    acc "  " "SKIP(5.9.9.F.6e): секция 5.9.9.F.6b гейта не напечатала drift_exec_from_system_bin (среза за idle-час нет либо метрики нет) — величина 11 не имеет второй половины, объём выше НЕ засчитывается волной 6"
else
    acc "  " "ВЗЯТО С ОБЕИХ СТОРОН (5.9.9.F.6e): $acc_drift_cut_line"
    if [ "${acc_drift_cut:-0}" -gt 0 ] 2>/dev/null; then
        acc "  " "срезано лимитером за idle-час: $acc_drift_cut — объём $acc_drift выше читается вместе с этим числом, а не отдельно"
    fi
fi

# (12) 5.9.9.F.4h/№150: 0 пар «dns: no new events» / «dns: collector
# recovered» за idle-час при живом DNS-детекте. Считается по счётчику
# stale_transitions (гейт печатает его дельту за прогон, крит. 5.9.6g) — тот
# же приём, что у самого гейта: журнал построчно здесь не парсится.
acc_stale=$(grep -oE 'stale_transitions за прогон: [0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
acc "12." "пар dns stale/recovered за прогон (5.9.9.F.4h/№150, порог поднят 5м -> 10м): ${acc_stale:-?}"
if [ "${acc_stale:-1}" = "0" ]; then
    acc "  " "ДОСТИГНУТО: 0 — порог выше межвсплескового интервала тихого стенда (312с наблюдённых на №2.9.9.F.3, где пар было 59)"
elif [ -z "$acc_stale" ]; then
    acc "  " "SKIP: гейт не напечатал stale_transitions — величина 12 не посчитана (не PASS)"
else
    acc "  " "НЕ ДОСТИГНУТО: ${acc_stale} — либо межвсплесковый интервал этого стенда длиннее 10 минут (тогда порог поднимается снова либо «тихо» и «слепо» разделяются двумя исходами, как предлагала постановка), либо коллектор ДЕЙСТВИТЕЛЬНО слеп: различать по крит. 2 гейта (events_total{dns} растёт между срезами или нет)"
fi
[ -f "$SETUP/attacks/dns-idle-fp.txt" ] && acc "  " "позитивный контроль DNS (5.9.8a) — исход в шаге [7/14] выше; ноль пар при КРАСНОМ контроле величиной не является"

# (13) 5.9.9.F.7b/№174: критерий №68 сужен до своей сигнатуры.
#
# ГРАНИЦА, названная явно (решение волны 7): критерий живёт в ОТЧЁТЕ
# (run-2.9.5-report.sh, п.10), а не в гейте — его FAIL не входит в GATE_RC и
# никогда не входил. Величина 1 выше — про гейт, эта — про отчёт; смешивать
# их нельзя, иначе «SKIP=0/FAIL=0 в гейте» начнёт молча означать разное.
# Отчёт собирается ПОСЛЕ этого блока (шаг [14/14]), поэтому здесь печатается
# только то, что величина 13 читается из /root/report-6.0.txt, и обе
# ветки уже взяты офлайн реплеем 15/16 (collect-2.9.9.F.6 -> PASS,
# collect-2.9.4 -> FAIL). Живой прогон обязан напечатать матожидание РЯДОМ с
# числом совпадений — иначе фон выводится из вердикта, а не виден числом.
acc "13." "критерий №68 (5.9.9.F.7b/№174) — в ОТЧЁТЕ, не в гейте: исход читается из /root/report-6.0.txt после шага [14/14]"
acc "  " "обе стороны взяты офлайн (реплей 15/16 replay-gate.sh): collect-2.9.9.F.6 -> PASS (3 совпадения фона, все drift_exec_from_system_bin/sshd, сигнатуры №68 — 0), collect-2.9.4 -> FAIL (22 совпадения сигнатуры на 11 из 13 срезов)"
acc "  " "живой замер обязан напечатать: новых idle-алертов, срезов, секунд с алертами, МАТОЖИДАНИЕ (секунд×срезов/длина_окна), совпадений по фону и отдельно по сигнатуре №68"

# (14) 5.9.9.F.7c/№175: доля на демонах — ДВЕ величины, порог явный либо SKIP.
# Числа печатает сам гейт (критерий 9); здесь они вытаскиваются в приёмку,
# чтобы обе читались рядом, а не порознь: после коалесцирования 5d доля по
# инцидентам говорит о коалесцировании, доля по алертам — об объёме, и
# подменять одну другой нельзя (ровно это и было дефектом порога волны 2).
acc_daem_inc=$(grep -E 'доля по инцидентам \(после коалесцирования' /root/gate-6.0.txt | tail -1 | sed 's/^[[:space:]]*//')
acc_daem_alr=$(grep -E 'доля по алертам \(объём' /root/gate-6.0.txt | tail -1 | sed 's/^[[:space:]]*//')
acc "14." "доля на демонах двумя числами (5.9.9.F.7c/№175):"
acc "  " "${acc_daem_inc:-НЕ НАПЕЧАТАНА гейтом — величина 14 НЕ засчитывается (критерий 9 не дошёл до счёта)}"
acc "  " "${acc_daem_alr:-НЕ НАПЕЧАТАНА гейтом — величина 14 НЕ засчитывается (вторая половина отсутствует)}"
if [ -n "$acc_daem_inc" ] && [ -n "$acc_daem_alr" ]; then
    acc "  " "ДОСТИГНУТО: обе величины напечатаны; порог не назначен ни одной — честный SKIP с записанной причиной (обоснования на 4 архивах нет: по инцидентам разброс 10.0-30.8%, по алертам 50.5-80.9% при старом пороге 20%). Этот SKIP документирован и вычтен в величине 1"
else
    acc "  " "НЕ ДОСТИГНУТО: критерий 9 не напечатал обе доли — величина 14 требует ОБЕ, одна другую не заменяет"
fi

# (15) 5.9.9.F.7d: слепое окно измерителя — печать входа, не правка.
# Порог <=5 НЕ тронут волной 7. Величина — наличие ВХОДА для разбора:
# pid/comm/смещение относительно confirm_epoch на каждый алерт случая 3.
# ppid печатается n/a честно и это ожидаемо: ни /api/v1/alerts, ни
# process_chain инцидентов (это []string имён comm) его структурно не несут.
# Живого случая 3 в архивах F.1…F.6 не встречалось — если и здесь его нет,
# величина закрывается исходом «случай 3 не наступил», а НЕ «печать не
# работает»: печать проверена офлайн реплеем 7/16 на collect-2.9.9.F.
acc_blind=$(grep -cE 'случай 3.*pid=|pid=[0-9]+ ppid=.* comm=.*смещение' /root/gate-6.0.txt || true)
acc_blind_line=$(grep -E 'дерево измерителя по случаю' /root/gate-6.0.txt | tail -1 | sed 's/^[[:space:]]*//')
acc "15." "слепое окно измерителя (5.9.9.F.7d, перенос 5.9.7g/5.9.8g/5.9.9.Fb): строк печати входа = ${acc_blind:-0}"
acc "  " "${acc_blind_line:-секция 16 гейта не напечатала классификацию случаев — величина 15 НЕ засчитывается}"
if [ "${acc_blind:-0}" -gt 0 ] 2>/dev/null; then
    acc "  " "ЖИВОЙ СЛУЧАЙ 3 ВПЕРВЫЕ ВЗЯТ: вход для разбора гонки «форк до подхвата, exec после» есть — следующая волна правит observer_tree_cache ПО ЭТИМ ЧИСЛАМ, а не по гипотезе. ppid=n/a ожидаем (структурно недоступен), при разборе брать bpftrace живьём"
else
    acc "  " "случай 3 не наступил на этом замере — величина 15 закрыта исходом «входа нет, потому что нет случая» (печать проверена офлайн реплеем 7/16 на collect-2.9.9.F); гипотеза гонки остаётся непроверенной за отсутствием входа, а НЕ за отсутствием печати"
fi

# (16) Четыре величины постановки 6.0 (plan.md, "### 6.0 Базовая линия
# дрейфа"), критерии 6.0.1..6.0.4. Величины 1..15 выше — унаследованный
# регресс волн 3/5/7/8, продолжает исполняться без правок; это первая
# запись, которая принадлежит именно волне 6.0.
#
# 6.0.1 ПЕРЕОПРЕДЕЛЁН находкой №199 (волна 6.0f). До этой правки объём читался
# из таблицы гейта 5.9.9.F.6b — но та таблица индексирована СРЕЗОМ лимитера
# (`for (r in cut)` в run-gate.sh), а не объёмом: правило, ни разу не упёршееся
# в лимитер, не попадает в неё вообще, независимо от того, сколько алертов
# опубликовало за idle-час. 6.0.1 теперь считает свою собственную дельту —
# сумму ebpf_guard_alerts_total и ebpf_guard_alerts_filtered_total по
# rule_id="drift_exec_from_system_bin" между IDLE_METRICS_START/END (те же
# снимки, что использует и F.6b, серии не пересекаются — см. комментарий
# самого гейта у 5.9.9.F.6b, №164). Таблица 5.9.9.F.6b остаётся источником
# ТОЛЬКО для 6.0.2 (срез лимитера) — второй половины величины.
_v199_sum_by_rule() { # $1=metric $2=rule_id $3=file
    local metric="$1" rule="$2" file="$3"
    [ -s "$file" ] || { echo ""; return; }
    awk -v m="$metric" -v r="rule_id=\"$rule\"" '
        $0 ~ "^"m"\\{" && index($0, r) { s += $NF; seen=1 } END { if (seen) printf "%d", s; else printf "" }
    ' "$file"
}
acc_v199_exp_start=""; acc_v199_exp_end=""; acc_v199_flt_start=""; acc_v199_flt_end=""
if [ -s "${IDLE_METRICS_START:-}" ] && [ -s "${IDLE_METRICS_END:-}" ]; then
    acc_v199_exp_start=$(_v199_sum_by_rule ebpf_guard_alerts_total drift_exec_from_system_bin "$IDLE_METRICS_START")
    acc_v199_exp_end=$(_v199_sum_by_rule ebpf_guard_alerts_total drift_exec_from_system_bin "$IDLE_METRICS_END")
    acc_v199_flt_start=$(_v199_sum_by_rule ebpf_guard_alerts_filtered_total drift_exec_from_system_bin "$IDLE_METRICS_START")
    acc_v199_flt_end=$(_v199_sum_by_rule ebpf_guard_alerts_filtered_total drift_exec_from_system_bin "$IDLE_METRICS_END")
fi
# Серия видна, если найдена хотя бы в одном из двух срезов (start ИЛИ end) —
# правило могло начать публиковать только к концу часа.
acc_v199_exp_seen=0; [ -n "$acc_v199_exp_start" ] || [ -n "$acc_v199_exp_end" ] && acc_v199_exp_seen=1
acc_v199_flt_seen=0; [ -n "$acc_v199_flt_start" ] || [ -n "$acc_v199_flt_end" ] && acc_v199_flt_seen=1
acc_v199_exp_delta=$(( ${acc_v199_exp_end:-0} - ${acc_v199_exp_start:-0} ))
acc_v199_flt_delta=$(( ${acc_v199_flt_end:-0} - ${acc_v199_flt_start:-0} ))
acc_v199_vol=$(( acc_v199_exp_delta + acc_v199_flt_delta ))
acc_v199_series_any=0; { [ "$acc_v199_exp_seen" -eq 1 ] || [ "$acc_v199_flt_seen" -eq 1 ]; } && acc_v199_series_any=1
# 6.0.2 (правил со срезом лимитера < 7) по-прежнему читает таблицу 5.9.9.F.6b
# — это её половина, не тронутая находкой №199.
acc_rl_line=$(grep -E '^[[:space:]]*drift_exec_from_system_bin[[:space:]]+стор' /root/gate-6.0.txt | tail -1)
acc_rl_cutn=$(grep -oE 'правил с ненулевым срезом за idle-час: [0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
acc_rl_cut=$(echo "$acc_rl_line" | grep -oE 'срезано[[:space:]]+[0-9]+' | grep -oE '[0-9]+')
# Находка №195 (сохранена): «таблица не построена» (снимки idle не сняты,
# метрика лимитера старее сборки) отличается от «правило дало 0 срабатываний»
# — 6.0.1 теперь различает это НЕ по таблице F.6b (у неё своя работа — срез
# лимитера для 6.0.2), а по наличию самих снимков IDLE_METRICS_START/END,
# которые ей и нужны напрямую.
acc_rl_table_ran=0
grep -qF 'объём правил за idle-час напечатан вместе со срезанным лимитером' /root/gate-6.0.txt \
    && acc_rl_table_ran=1
# 6.0j/п.7 (реплей 24/25): ПОЛ к этому потолку, машинной веткой, а не фразой в
# тексте вердикта. До этой правки 16.1 писал «засчитывается ТОЛЬКО вместе с
# 6.0.4 и полом 16.5» — условие, которое никто не проверял на самом прогоне:
# нулевой объём печатался как ДОСТИГНУТО и читался из архива как успех.
# Ноль под потолком берётся и исправным детектором (тихий час), и полностью
# слепым (замер №6.0: 0/ч при свёрнутой сигнатуре /usr/bin/*), и различить их
# по самому объёму нельзя по построению.
#
# Пол — свидетельство, что за ТОТ ЖЕ час правило видело вход: сумма
# anomalies_total (сработало) и suppressed_total всех reason (сматчило, но
# погашено базовой линией) по своему rule_id. На замере №6.0f2 пол выполнен
# с запасом (baseline_known 260 -> 887, +627) при объёме 0/ч — тот ноль
# означал тишину, а не слепоту, и это ровно то различение, которого 16.1 не
# делал. Пол применяется ТОЛЬКО к нулевому объёму: ненулевой объём сам по
# себе доказывает, что вход был.
#
# Пол 16.5 (6.0.5, решающее правило по drift-контролю) этим НЕ заменяется и
# не трогается: тот отвечает на вопрос «работает ли механизм в этом прогоне»
# и берётся из окна атак, этот — «видело ли правило вход в измеряемый час».
_v199_floor_sum() { # $1=rule_id $2=file -> anomalies+suppressed по правилу
    local rule="$1" file="$2"
    [ -s "$file" ] || { echo 0; return; }
    awk -v r="rule_id=\"$rule\"" '
        ($0 ~ /^ebpf_guard_drift_baseline_anomalies_total\{/ || $0 ~ /^ebpf_guard_drift_baseline_suppressed_total\{/) && index($0, r) { s += $NF }
        END { printf "%d", s+0 }
    ' "$file"
}
acc_v199_floor=""
if [ -s "${IDLE_METRICS_START:-}" ] && [ -s "${IDLE_METRICS_END:-}" ]; then
    acc_v199_floor=$(( $(_v199_floor_sum drift_exec_from_system_bin "$IDLE_METRICS_END") \
                     - $(_v199_floor_sum drift_exec_from_system_bin "$IDLE_METRICS_START") ))
fi
# №207 (волна 6.0f, п.8): заголовок и вердикт печатаются ОДНОЙ строкой, не
# двумя — до этой правки заголовок нёс независимо посчитанное текстовое поле
# ("НЕ НАПЕЧАТАН гейтом 5.9.9.F.6b"), а вердикт двумя строками ниже мог
# противоречить ему при беглом чтении архива (найдено на замере №6.0d:
# заголовок утверждал "НЕ НАПЕЧАТАН" при вердикте "ДОСТИГНУТО — объём 0/ч").
# Величина берётся из п.1 этой же волны (acc_v199_*, выше) — второго
# независимого источника для заголовка не существует.
if [ ! -s "${IDLE_METRICS_START:-}" ] || [ ! -s "${IDLE_METRICS_END:-}" ]; then
    acc_v199_verdict="НЕ ЗАСЧИТЫВАЕТСЯ: снимки idle/metrics-start.txt|metrics-end.txt недоступны — величине 6.0.1 не из чего считать собственную дельту (№199 читает эти снимки напрямую, не таблицу 5.9.9.F.6b)"
elif [ "$acc_rl_table_ran" -ne 1 ]; then
    acc_v199_verdict="НЕ ЗАСЧИТЫВАЕТСЯ: вторая половина величины потеряна — таблица 5.9.9.F.6b (срез лимитера, нужна 6.0.2) этим гейтом не напечатана (метрика лимитера отсутствует — сборка агента старее 5.9.9.F.5n)"
elif [ "$acc_v199_vol" -eq 0 ] && [ "${acc_v199_floor:-0}" -le 0 ]; then
    acc_v199_verdict="НЕ ЗАСЧИТЫВАЕТСЯ (ноль без пола): объём 0/ч при поле ${acc_v199_floor:-0} — за idle-час правило drift_exec_from_system_bin не дало НИ аномалии, НИ подавления базовой линией (anomalies_total + suppressed_total всех reason по этому rule_id). Такой ноль неотличим от слепоты детектора (замер №6.0: 0/ч при свёрнутой сигнатуре /usr/bin/*), и потолок <=100/ч по нему не берётся. Читать в порядке: базовая линия в состоянии enforcing (6.0.4, шаг [10/14])? правило вообще матчит (контроль 6.0.3/6.0.11)? сигнатура не свёрнута (6.0.9)?"
elif [ "$acc_v199_series_any" -eq 0 ]; then
    acc_v199_verdict="ДОСТИГНУТО — объём 0/ч: ни ebpf_guard_alerts_total, ни ebpf_guard_alerts_filtered_total не публиковали серию с rule_id=drift_exec_from_system_bin ни в одном из двух срезов idle-часа (правило не публиковало никогда за этот час). Засчитывается ТОЛЬКО вместе с 6.0.4 и полом 16.5"
elif [ "$acc_v199_vol" -le 100 ]; then
    acc_v199_verdict="ДОСТИГНУТО — засчитывается ТОЛЬКО вместе с 6.0.4 (enforcing напечатан на шаге [10/14]) И с полом 16.5 (класс drift дал за час хоть одну аномалию); сам по себе низкий объём неотличим ни от незакрывшегося обучения (риск №1), ни от свёрнутой сигнатуры (замер №6.0: объём 0 при 15071 совпадении)"
else
    acc_v199_verdict="НЕ ДОСТИГНУТО: объём $acc_v199_vol > 100/ч"
fi
acc "16.1" "6.0.1 — drift_exec_from_system_bin, объём за idle-час (порог <=100/ч, №199 — сумма своей метрики): ebpf_guard_alerts_total $acc_v199_exp_delta + ebpf_guard_alerts_filtered_total $acc_v199_flt_delta = ${acc_v199_vol} (было 577/ч на №2.9.9.F.7 без базовой линии), пол за тот же час (anomalies+suppressed по этому правилу) = ${acc_v199_floor:-не измерен} -> $acc_v199_verdict"
acc "16.2" "6.0.2 — правил со срезом лимитера за idle-час < 7 и drift_exec_from_system_bin среди них нет: правил со срезом = ${acc_rl_cutn:-?}, срезано у drift_exec_from_system_bin = ${acc_rl_cut:-0}"
if [ -n "$acc_rl_cutn" ] && [ "$acc_rl_cutn" -lt 7 ] 2>/dev/null && [ "${acc_rl_cut:-0}" -eq 0 ] 2>/dev/null; then
    acc "  " "ДОСТИГНУТО"
else
    acc "  " "НЕ ДОСТИГНУТО либо не напечатано"
fi
acc "16.3" "6.0.3 — позитивный контроль (шаг [12/14], comm=drift-pc, новая сигнатура у enforcing workload): смотреть 'позитивный контроль' выше по логу этого прогона; шаг die'ит сам, если контроль не прошёл — если приёмка дошла до этой строки, 6.0.3 ДОСТИГНУТО"
acc "16.4" "6.0.4 — состояние базовой линии на момент открытия idle-часа: смотреть 'состояние базовой линии' на шаге [10/14] этого лога; шаг die'ит сам при непечати или отсутствии enforcing — если приёмка дошла до этой строки, 6.0.4 ДОСТИГНУТО"

# 16.5 — пол к потолку 6.0.1, ПЕРЕОПРЕДЕЛЁН находкой №196 (волна 6.0d).
#
# 6.0.1 — потолок: «не больше 100 алертов за idle-час». На №6.0 он был взят
# с результатом 0, и ноль означал не работу механизма, а его слепоту: все
# пять правил класса drift молчали целиком, потому что сигнатура сворачивала
# /usr/bin/* в одну запись. Потолок, взятый сломанным детектором, выглядит
# в точности как потолок, взятый исправным, — поэтому величина 6.0.1 сама по
# себе неинформативна и с этого замера засчитывается ТОЛЬКО вместе с полом
# ниже.
#
# До волны 6.0d пол проверял ОБЪЁМ (anomalies_total > 0 за idle-час) —
# находка №196: это нефальсифицируемо в ту сторону, ради которой пол
# построен. Класс drift на idle-часе по определению видит только рутину;
# именно поэтому anomalies_total==0 на исправном детекторе неотличим от
# anomalies_total==0 на детекторе со свёрнутой сигнатурой (замер №6.0).
# Ноль не доказывает и не опровергает работоспособность механизма — это
# измеряет 6.0.8 (цена решения б), а не 6.0.5.
#
# Новое решающее правило: 6.0.5 ДОСТИГНУТО <=> в прогоне есть хотя бы один
# ПРОШЕДШИЙ drift-контроль (6.0.3 и/или 6.0.6), исполненный внутри окна
# замера — работу механизма доказывает контроль, поставленный намеренно,
# а не объём, который зависит от того, что случайно произошло на хосте.
# Оба контроля пишут свой исход в /root/drift-controls-6.0.txt, а не только
# в свой собственный echo (который живёт только в стдауте этого прогона).
# 6.0.3 (шаг 6.0c) исполняется РАНЬШЕ gate-6.0.txt (создаётся позже, на шаге
# [11/14], run-gate.sh перезаписывает его через tee без -a) — если бы контроль
# писал исход только в gate-6.0.txt, тот же tee его бы стёр. Отдельный файл
# переживает перезапись и читается одинаково живым гейтом этого прогона и
# будущим офлайн-реплеем на архиве.
#
# Объём (anomalies_total/baseline_known/learning/already_reported)
# печатается по-прежнему полностью — как измеряемая величина 6.0.8, а не как
# решающее правило.
_drift_sum() { # $1=metric $2=reason(опц.) $3=file
    local metric="$1" reason="$2" file="$3"
    [ -s "$file" ] || { echo 0; return; }
    if [ -n "$reason" ]; then
        awk -v m="$metric" -v r="reason=\"$reason\"" '$0 ~ "^"m"\\{" && index($0, r) { s += $NF } END { printf "%d", s+0 }' "$file"
    else
        awk -v m="$metric" '$0 ~ "^"m"\\{" { s += $NF } END { printf "%d", s+0 }' "$file"
    fi
}
if [ -s "$IDLE_METRICS_START" ] && [ -s "$IDLE_METRICS_END" ]; then
    _dm=ebpf_guard_drift_baseline
    acc_drift_anom=$(( $(_drift_sum "${_dm}_anomalies_total" "" "$IDLE_METRICS_END") - $(_drift_sum "${_dm}_anomalies_total" "" "$IDLE_METRICS_START") ))
    acc_drift_known=$(( $(_drift_sum "${_dm}_suppressed_total" baseline_known "$IDLE_METRICS_END") - $(_drift_sum "${_dm}_suppressed_total" baseline_known "$IDLE_METRICS_START") ))
    acc_drift_learn=$(( $(_drift_sum "${_dm}_suppressed_total" learning "$IDLE_METRICS_END") - $(_drift_sum "${_dm}_suppressed_total" learning "$IDLE_METRICS_START") ))
    acc_drift_rep=$(( $(_drift_sum "${_dm}_suppressed_total" already_reported "$IDLE_METRICS_END") - $(_drift_sum "${_dm}_suppressed_total" already_reported "$IDLE_METRICS_START") ))
    # Волна 6.0f, №203(а1): подавление глобальной резервной базой отделено от
    # подавления собственной ("learning" выше — это "никто ничего не знает",
    # а не "уже enforcing, но глобальный фоллбэк знает сигнатуру").
    acc_drift_global=$(( $(_drift_sum "${_dm}_suppressed_total" global_baseline_known "$IDLE_METRICS_END") - $(_drift_sum "${_dm}_suppressed_total" global_baseline_known "$IDLE_METRICS_START") ))
    acc "16.5" "6.0.1 (пол) — величина 6.0.8, справочно: класс drift за idle-час: аномалий $acc_drift_anom, подавлено baseline_known $acc_drift_known / learning $acc_drift_learn / already_reported $acc_drift_rep / global_baseline_known $acc_drift_global"
else
    acc "16.5" "6.0.1 (пол) — величина 6.0.8 недоступна: снимки idle/metrics-start.txt|metrics-end.txt недоступны, дельту класса drift за час считать не из чего (не блокирует решающее правило ниже — оно больше не читает объём)"
fi
# Решающее правило 6.0.5, напечатано текстом (№196: подмену правила должно
# быть видно в архиве, а не только в диффе скрипта).
echo "6.0.5 РЕШАЮЩЕЕ ПРАВИЛО (переопределено 6.0d, расширено 6.0f/№203): ДОСТИГНУТО <=> в прогоне есть хотя бы один прошедший drift-контроль (6.0.3 и/или 6.0.6 и/или 6.0.12) внутри окна замера; объём (16.5 выше) — величина 6.0.8, не пол"
acc_drift_ctrl_file=${DRIFT_CONTROLS_FILE:-/root/drift-controls-6.0.txt}
# Второй источник того же факта — лог прогона. Реестр выше появился только в
# волне 6.0d, а постановка №6.0d ТРЕБУЕТ реплея переопределённого 6.0.5 на
# архивах collect-6.0 (обязан дать НЕ ДОСТИГНУТО: контроль 6.0.3 там провален,
# пайплайн умер на нём) и collect-6.0b (обязан дать ДОСТИГНУТО): правило,
# которое не меняет вердикт на архивах в обе стороны, не решающее. В этих
# архивах реестра нет и быть не может, зато есть run-6.0-pipeline.log с
# исходной печатью шага 6.0c. Строки трассировки `set -x` отбрасываются: PS4
# по умолчанию "+ ", и без отбрасывания grep нашёл бы СВОЮ СОБСТВЕННУЮ
# трассу, напечатанную в тот же лог мгновением раньше (тот же класс дефекта,
# что уронил предпрогон 6.0b на сторожах сигнатуры дрейфа).
acc_drift_ctrl_log=${DRIFT_CONTROLS_LOG:-/root/run-6.0-pipeline.log}
acc_drift_ctrl_log_pass=0
if [ -f "$acc_drift_ctrl_log" ] && grep -v '^+' "$acc_drift_ctrl_log" | grep -qF '6.0.3 доказан живьём'; then
    acc_drift_ctrl_log_pass=1
fi
if [ -f "$acc_drift_ctrl_file" ] && grep -qE '^6\.0\.(3|6|12) PASS' "$acc_drift_ctrl_file" 2>/dev/null; then
    acc "  " "6.0.5 ДОСТИГНУТО: пройденный drift-контроль зафиксирован в $acc_drift_ctrl_file — $(grep -E '^6\.0\.(3|6|12) PASS' "$acc_drift_ctrl_file" | tr '\n' ' ')"
elif [ "$acc_drift_ctrl_log_pass" -eq 1 ]; then
    acc "  " "6.0.5 ДОСТИГНУТО: реестра drift-контролей нет (архив старее волны 6.0d), но контроль 6.0.3 напечатал 'доказан живьём' в $acc_drift_ctrl_log — механизм доказан контролем, а не объёмом"
elif [ -f "$acc_drift_ctrl_file" ] && grep -qE '^6\.0\.(3|6|12) FAIL' "$acc_drift_ctrl_file" 2>/dev/null; then
    acc "  " "6.0.5 НЕ ДОСТИГНУТО: $acc_drift_ctrl_file содержит только провалившиеся контроли — $(grep -E '^6\.0\.(3|6|12) FAIL' "$acc_drift_ctrl_file" | tr '\n' ' ')"
elif [ -f "$acc_drift_ctrl_log" ]; then
    acc "  " "6.0.5 НЕ ДОСТИГНУТО: ни реестр $acc_drift_ctrl_file, ни лог $acc_drift_ctrl_log не содержат ни одного прошедшего drift-контроля — контроль либо не исполнялся, либо провален (на collect-6.0 это ожидаемый исход: 6.0.3 провален по находке №187)"
else
    acc "  " "6.0.5 НЕ ЗАСЧИТЫВАЕТСЯ: ни $acc_drift_ctrl_file, ни $acc_drift_ctrl_log не найдены — исход drift-контролей нечем прочитать (это сбой сбора, а не значение величины)"
fi


# ── 16.6…16.9: четыре величины волны 6.0d ────────────────────────────────────
# Порядок правки соблюдён: эти печати заводятся ЗДЕСЬ, а строки 6.0.6…6.0.9
# в criteria-index.txt — только после них. Обратный порядок уронил бы преflight
# run-gate.sh (exit 3) на ВСЕХ архивах сразу, включая старые, — та же механика,
# что уронила его при перенумерации реплеев (находка №170).
acc "16.6" "6.0.6 — позитивный контроль на НОВУЮ нагрузку (шаг 6.0e, невиданный comm, unshare+mount): смотреть '6.0.6 позитивный контроль' выше по логу этого прогона; шаг die'ит сам, если контроль не прошёл — если приёмка дошла до этой строки, 6.0.6 ДОСТИГНУТО"
acc "16.7" "6.0.7 — негативный контроль к нему (повтор того же примитива тем же comm): смотреть '6.0.7 негативный контроль' выше по логу; шаг die'ит сам при ненулевом приросте — если приёмка дошла до этой строки, 6.0.7 ДОСТИГНУТО, и 6.0.6 доказывает новизну, а не факт вызова"

# 16.8 — ЦЕНА решения (б). Величина, НЕ критерий: порог на этом замере не
# назначается (запрет 5.9.6 — порог не назначается на том же замере, где
# величина впервые измерена). Считается по трём правилам подмножества (б) за
# idle-час: объём из дельты alerts_total (метрика без label comm — за него
# отвечает cardinality guard), разбивка по comm — из снимков стора idle-часа
# (alerts-start.json/alerts-end.json), отбором по id, а не по timestamp:
# id уникален, а на границе окна timestamp'ы совпадают с точностью до секунды.
acc_nw_rules="container_escape_proc_write container_escape_init_proc drift_dangerous_syscall"
acc_nw_total=0
acc_nw_per_rule=""
# Пустой путь скормил бы awk стандартный ввод, и приёмка повисла бы молча —
# поэтому обе границы проверяются одним -s ДО цикла, а не внутри него.
if [ -s "${IDLE_METRICS_START:-}" ] && [ -s "${IDLE_METRICS_END:-}" ]; then
    for _r in $acc_nw_rules; do
        _a=$(awk -v r="rule_id=\"$_r\"" '/^ebpf_guard_alerts_total\{/ && index($0, r) { s += $NF } END { printf "%d", s+0 }' "$IDLE_METRICS_START")
        _b=$(awk -v r="rule_id=\"$_r\"" '/^ebpf_guard_alerts_total\{/ && index($0, r) { s += $NF } END { printf "%d", s+0 }' "$IDLE_METRICS_END")
        _d=$(( ${_b:-0} - ${_a:-0} ))
        acc_nw_total=$(( acc_nw_total + _d ))
        acc_nw_per_rule="$acc_nw_per_rule $_r=$_d"
    done
else
    acc_nw_total="НЕ ИЗМЕРЕН"
    acc_nw_per_rule=" (снимки idle/metrics-start.txt|metrics-end.txt недоступны)"
fi
acc_nw_by_comm="снимки стора idle-часа недоступны"
if [ -s "$IDLE_OUT/alerts-start.json" ] && [ -s "$IDLE_OUT/alerts-end.json" ]; then
    acc_nw_by_comm=$(jq -r --slurpfile st "$IDLE_OUT/alerts-start.json" '
        ($st[0] | map(.id) | map({(.):true}) | add // {}) as $seen
        | map(select(.id as $i | ($seen[$i] // false) | not))
        | map(select(.rule_id == "container_escape_proc_write"
                  or .rule_id == "container_escape_init_proc"
                  or .rule_id == "drift_dangerous_syscall"))
        | group_by(.comm) | map("\(.[0].comm)=\(length)") | join(" ")
        | if . == "" then "новых алертов подмножества за час нет" else . end
    ' "$IDLE_OUT/alerts-end.json" 2>/dev/null || echo "разбор снимков стора не удался")
fi
acc "16.8" "6.0.8 — ЦЕНА решения (б), величина без порога (запрет 5.9.6): объём подмножества drift_novel_workload за idle-час = $acc_nw_total (по правилам:$acc_nw_per_rule)"
acc "  " "разбивка по comm (снимки стора idle-часа): $acc_nw_by_comm"
acc "  " "читать вместе с saturated_profiles на открытии часа (шаг [10/14]): если глобальная база насытилась ДО открытия, эта величина отражает насыщение, а не дрейф, и порог по ней назначать нельзя"

# 16.9 — прямая проверка правки №197 по таблице 6.0.4. DRIFT_PAREN_COMMS
# заполнена на шаге [10/14] того же процесса; в архиве та же величина
# напечатана строкой "6.0.9:" там же.
if [ -z "${DRIFT_PAREN_COMMS+x}" ]; then
    acc "16.9" "6.0.9 — расщепление нагрузок на pre-exec comm: НЕ ЗАСЧИТЫВАЕТСЯ — шаг [10/14] не дошёл до печати таблицы базовой линии, проверять нечего"
elif [ -n "${DRIFT_PAREN_COMMS// /}" ]; then
    acc "16.9" "6.0.9 — расщепление нагрузок на pre-exec comm НЕ СНЯТО: в таблице 6.0.4 есть comm в обрамляющих скобках ($DRIFT_PAREN_COMMS) — stripPreExecCommParens не доехал до ключа нагрузки (находка №197)"
else
    acc "16.9" "6.0.9 ДОСТИГНУТО — расщепление нагрузок снято: в таблице 6.0.4 нет ни одного comm в обрамляющих скобках (№197)"
fi

# 16.10 — 6.0.10 (№202, волна 6.0f): гигиена idle-часа как измеряемая
# величина, не смягчение 5.9.9.F.2d. Строка печатается гейтом безусловно,
# когда journalctl доступен и окно idle-часа определено (см. run-gate.sh);
# отсутствие строки — сбой сбора (нет journalctl/окна), а не «загрязнения не
# было». Третья формулировка (контаминация: время + акторы + доля motd)
# печатается гейтом отдельной строкой ТОЛЬКО при ненулевом значении.
acc_sshd_n=$(grep -oE 'успешных аутентификаций sshd за окно idle-часа \(6\.0\.10, №202\): [0-9]+' /root/gate-6.0.txt | tail -1 | grep -oE '[0-9]+$')
acc_sshd_third=$(grep -E '6\.0\.10 \(третья формулировка' /root/gate-6.0.txt | tail -1 | sed 's/^[[:space:]]*//')
acc "16.10" "6.0.10 — idle-час не загрязнён интерактивной sshd-сессией (успешных аутентификаций sshd = 0): ${acc_sshd_n:-НЕ ИЗМЕРЕН гейтом (journalctl недоступен либо окно не определено)}"
if [ -z "$acc_sshd_n" ]; then
    acc "  " "НЕ ЗАСЧИТЫВАЕТСЯ: journalctl недоступен на этом стенде либо окно idle-часа не определено по mtime срезов — это сбой сбора, а не значение величины"
elif [ "$acc_sshd_n" -eq 0 ] 2>/dev/null; then
    acc "  " "ДОСТИГНУТО — 0 успешных аутентификаций sshd за idle-окно, час пригоден для чтения величин 6.0.1/6.0.8 как измерения, а не ориентира"
else
    acc "  " "НЕ ДОСТИГНУТО: $acc_sshd_n успешных аутентификаций sshd за idle-окно — 5.9.9.F.2d остаётся FAIL/PASS по своему решению (не смягчается), но величины 6.0.1/6.0.8 этого прогона читать только как ориентир (регресс 5.9.9.F.2d при ненулевом 6.0.10 — не регресс детекта, см. plan.md)"
    acc "  " "${acc_sshd_third:-третья формулировка (час загрязнён логином в HH:MM:SS, новых акторов N, из них объяснимо motd-цепочкой M) НЕ НАПЕЧАТАНА гейтом — проверить run-gate.sh}"
fi

# 16.11-16.15 — волна 6.0f, пять новых drift/impact-контролей. Все пять
# `die`'ят сам шаг [12/14] на провале (см. секции 6.0g/6.0h выше), поэтому
# если исполнение дошло до этой строки, все пять уже ДОСТИГНУТО — акк-строки
# здесь только фиксируют исход в отчёте, решение принято выше по логу.
acc "16.11" "6.0.11 — негативный контроль механизма (а) (глобальный фоллбэк, №203): смотреть 'негативный контроль' на шаге 6.0g этого лога; шаг die'ит сам при 0 алертов без прироста suppressed_total{reason=global_baseline_known} — если приёмка дошла до этой строки, 6.0.11 ДОСТИГНУТО"
acc "16.12" "6.0.12 — позитивный контроль механизма (а): смотреть 'позитивный контроль' на шаге 6.0g этого лога; шаг die'ит сам при 0 алертов после повтора со стеканием лимитера — если приёмка дошла до этой строки, 6.0.12 ДОСТИГНУТО"
acc "16.13" "6.0.13 — негативный контроль FP №200 (dumpe2fs -h /dev/vda1): смотреть шаг 6.0h этого лога; шаг die'ит сам при ненулевом приросте критикалов — если приёмка дошла до этой строки, 6.0.13 ДОСТИГНУТО"
acc "16.14" "6.0.14 — позитивный контроль к нему (dd of=/dev/vda1 count=0): смотреть шаг 6.0h этого лога; шаг die'ит сам при 0 новых критикалов — если приёмка дошла до этой строки, 6.0.14 ДОСТИГНУТО"
acc "16.15" "6.0.15 — позитивный контроль подмножества (б) на container_escape_proc_write (sysctl -w kernel.pid_max=<текущее>): смотреть шаг 6.0h этого лога; шаг die'ит сам при 0 новых алертов — если приёмка дошла до этой строки, 6.0.15 ДОСТИГНУТО"

echo "=== конец приёмки волны 5.9.9.F.8 (величины 1/4) + регресс волн 5.9.9.F.3…F.7 (вердикт гейта: $GATE_RC) + приёмка волны 6.0 (величины 16.1-16.15) ==="
echo ""

echo "=== [14/14] сводка idle-части + отчёт сверх гейта ==="
cat $IDLE_OUT/SUMMARY.txt 2>/dev/null
# 5.9.9f (№104): REPORT_LABEL передаётся явно в обоих ветках — раньше
# run-2.9.5-report.sh печатал "ОТЧЁТ №2.9.5" литералом независимо от того,
# какой замер его в действительности вызвал (фолбэк использовался на
# №2.9.6…№2.9.8 тоже). REPORT_LABEL=6.0 чинит это для report-6.0.txt;
# если когда-нибудь появится собственный run-6.0-report.sh, ему тоже
# следует читать REPORT_LABEL, а не зашивать номер.
if [ -f "$SETUP/run-6.0-report.sh" ]; then
    IDLE_OUT=$IDLE_OUT AGENT_START_FILE=/root/agent-start-6.0.txt REPORT_LABEL=6.0 \
        bash $SETUP/run-6.0-report.sh 2>&1 | tee /root/report-6.0.txt
else
    echo "ВНИМАНИЕ: run-6.0-report.sh отсутствует — считаем отчётом (сверх гейта) фолбэком run-2.9.5-report.sh."
    echo "ВНИМАНИЕ: п.10 (idle-алерты на метках срезов) он посчитает, величины"
    echo "ВНИМАНИЕ: постановки №6.0 (пп.1-14) — нет; они только в гейте."
    IDLE_OUT=$IDLE_OUT AGENT_START_FILE=/root/agent-start-6.0.txt REPORT_LABEL=6.0 \
        bash $SETUP/run-2.9.5-report.sh 2>&1 | tee /root/report-6.0.txt
fi

echo "=== [14.1/14] наблюдение без порога: состав drift_exec_from_system_bin (долг «намеренно НЕ входит») ==="
# Пункт постановки замера, добавленный 2026-08-26 (см. plan.md, «Наблюдение без
# порога» в приёмке №2.9.9.F.3). drift_exec_from_system_bin — первое место по
# критикалам аптайма (44 на №2.9.9.F.2, больше, чем №131 и №132 вместе), и до
# сих пор он не находка только потому, что его состав никто не смотрел:
# правило дрейфа ОБЯЗАНО расти в окне атаки, и без разбора «сколько из 44
# пришло из окна атак, а сколько с фонового open() под /usr/bin» отличить
# законный рост от четвёртого экземпляра класса «правило шире своего имени»
# нечем. Шаг ничего не проверяет и НЕ влияет на вердикт: он печатает величину
# и складывает её в артефакт, чтобы волна 6 входила в разбор с числами, а не
# с «44 и первое место».
#
# Почему здесь, а не в run-gate.sh: у наблюдения нет порога, а всё, что гейт
# печатает через pass()/fail()/skip(), обязано иметь строку в
# criteria-index.txt и достижимый исход. Наблюдение без порога, заведённое
# критерием, стало бы либо вечным PASS (критерий без достижимого FAIL —
# №123/№124), либо SKIP-ом бухгалтерии (№135/№136/№137). Поэтому — шаг
# пайплайна, после гейта, на тех же снимках.
drift_out=/root/drift-composition-6.0.txt
{
    echo "=== состав drift_exec_from_system_bin за аптайм, замер №6.0, $(date -u +%Y-%m-%dT%H:%M:%SZ) ==="
    # FP_API/FP_TOKEN заданы шагом [9.6/14] в этом же shell; перевычисляются
    # на случай, если шаг был пропущен режимом прогона.
    FP_API="${FP_API:-http://${VPS_IP:-localhost}:19090}"
    FP_TOKEN="${FP_TOKEN:-${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}}"
    drift_json=$(curl -s --max-time 30 -H "Authorization: Bearer $FP_TOKEN" "$FP_API/api/v1/alerts" 2>/dev/null \
        | jq '[.[]|select(.rule_id=="drift_exec_from_system_bin")]' 2>/dev/null)
    if [ -z "$drift_json" ] || [ "$drift_json" = "null" ]; then
        echo "НЕ ПОЛУЧЕНО: /api/v1/alerts не отдал массив (токен/агент/jq). Наблюдение пропущено — на вердикт не влияет."
    else
        echo "-- записей в сторе: $(echo "$drift_json" | jq 'length')"
        echo "-- срабатываний с учётом дедупликации (сумма count): $(echo "$drift_json" | jq '[.[]|(.count // 1)]|add // 0')"
        echo "-- окно: $(echo "$drift_json" | jq -r '[.[].timestamp]|sort|(first // "-")+" .. "+(last // "-")')"
        echo "-- по severity:"
        echo "$drift_json" | jq -r 'group_by(.severity)[]|"     \(length)\t\(.[0].severity)"' | sort -rn
        echo "-- по comm (кто открывал):"
        echo "$drift_json" | jq -r 'group_by(.comm)[]|"     \(length)\t\(.[0].comm)"' | sort -rn
        echo "-- по file.path (что открывалось):"
        echo "$drift_json" | jq -r 'group_by(.details["file.path"])[]|"     \(length)\t\(.[0].details["file.path"] // "-")"' | sort -rn
        echo "-- пары comm × file.path (для разметки «окно атаки» против фона):"
        echo "$drift_json" | jq -r 'group_by([.comm, .details["file.path"]])[]|"     \(length)\t\(.[0].comm)\t\(.[0].details["file.path"] // "-")"' | sort -rn
        echo ""
        echo "КАК ЧИТАТЬ (postanovka 2026-08-26). Строки, чей comm — шаг манифеста атак"
        echo "(curl/wget/python3/nc/dropper из run-all-attacks.sh), — законный рост правила"
        echo "дрейфа в окне атаки. Строки, чей comm — фоновый демон стенда, а file.path —"
        echo "штатная утилита (/usr/bin/dpkg, /usr/bin/find, /usr/bin/mandb и т.п.), — тот же"
        echo "класс, что №131/№132: правило шире своего имени. Разметка и решение —"
        echo "волна 6, не этот замер. Порог здесь НЕ назначается (запрет 5.9.6)."
    fi
} 2>&1 | tee "$drift_out"
echo "  наблюдение сложено в $drift_out (собирается вместе с /root/report-6.0.txt)"

echo "=== [14.2/14] гигиена коллекта: чужих TIMESTAMP в артефактах нет (6.0j/п.6, №212) ==="
# Вторая половина п.6. Уборка на старте гарантирует, что каждый файл
# *-6.0*.txt написан ЭТИМ прогоном; эта проверка гарантирует, что каждый
# написан этим прогоном ПРО ЭТОТ ЖЕ ПРОГОН. Расходятся эти два утверждения
# ровно в том случае, ради которого п.6 и заведён: скрипт, взявший
# TIMESTAMP не от текущего замера (гейт и отчёт выбирают его сами — по
# последнему baseline-state-*.json), напишет свежий файл с чужой величиной
# внутри, и уборка этого не заметит.
#
# Источник истины — gate-6.0.txt: он написан шагом [13/14] этого прогона
# (файл удалён на старте, значит стал существовать здесь), и печатает
# "RUN-GATE: TIMESTAMP=...". Все прочие артефакты сверяются с ним.
DIE_HEADLINE="ЗАМЕР №6.0 ИСПОЛНЕН, но ПРИЁМКА ПРЕРВАНА ГИГИЕНОЙ КОЛЛЕКТА (№212)"
_hyg_run_ts=$(grep -aoE '^RUN-GATE: TIMESTAMP=[0-9_]+' /root/gate-6.0.txt 2>/dev/null | head -1 | cut -d= -f2)
if [ -z "$_hyg_run_ts" ]; then
    die "гигиена коллекта (№212): в /root/gate-6.0.txt нет строки 'RUN-GATE: TIMESTAMP=' — либо гейт [13/14] не исполнялся (тогда коллект не является архивом замера и обязан быть помечен как аборт), либо файл достался от чужого прогона, пережив уборку на старте. Оба случая — ровно та неотличимость архива аборта от архива замера, ради которой п.6 волны 6.0j и заведён"
fi
echo "  TIMESTAMP этого прогона (по gate-6.0.txt): $_hyg_run_ts"
_hyg_bad=""
for _hyg_f in /root/*-6.0.txt /root/dns-controls-6.0-*.txt; do
    [ -f "$_hyg_f" ] || continue
    for _hyg_ts in $(grep -aoE 'TIMESTAMP=[0-9]{8}_[0-9]{6}' "$_hyg_f" 2>/dev/null | cut -d= -f2 | sort -u); do
        [ "$_hyg_ts" = "$_hyg_run_ts" ] && continue
        _hyg_bad="$_hyg_bad $(basename "$_hyg_f"):$_hyg_ts"
    done
done
if [ -n "$_hyg_bad" ]; then
    die "гигиена коллекта (№212) ПРОВАЛЕНА: в артефактах прогона лежат файлы с ЧУЖИМ TIMESTAMP (ожидался $_hyg_run_ts):$_hyg_bad. Именно так архив collect-6.0f2-aborted нёс report-6.0.txt и gate-6.0.txt от прогона 30.08 рядом со свежими величинами 01.09. Уборка на старте здесь уже отработала — значит файл написан ЭТИМ прогоном, но про чужой замер: скрипт, его писавший, выбрал TIMESTAMP по последнему baseline-state-*.json, а не по своему прогону. Разбирать надо его, а не удалять файл"
fi
DIE_HEADLINE="ЗАМЕР №6.0 НЕ НАЧАТ"
# Однородность коллекта не доказывает его свежести: если чужой TIMESTAMP
# взяли ВСЕ артефакты разом (гейт не нашёл снимка этого прогона и выбрал
# последний по каталогу — ровно так пишется отчёт по чужому замеру), сверка
# выше зелена. Отсечка по времени: снимок, по которому считал гейт, обязан
# быть создан ПОСЛЕ начала этого прогона.
_hyg_res_dir=$(grep -aoE '^RUN-GATE: TIMESTAMP=[0-9_]+ RESULTS_DIR=.*' /root/gate-6.0.txt 2>/dev/null | head -1 | sed 's/.*RESULTS_DIR=//')
_hyg_state="$_hyg_res_dir/baseline-state-$_hyg_run_ts.json"
if [ -z "$_hyg_res_dir" ] || [ ! -f "$_hyg_state" ]; then
    echo "  ВНИМАНИЕ (№212): снимок baseline-state-$_hyg_run_ts.json не найден (RESULTS_DIR='${_hyg_res_dir:-не разобран}') — отсечка по времени не исполнена, свежесть коллекта держится только на однородности TIMESTAMP выше. Это ограничение, а не вердикт: гейт уже отработал на тех же снимках"
elif [ ! "$_hyg_state" -nt /root/PIPELINE-6.0-START ]; then
    die "гигиена коллекта (№212) ПРОВАЛЕНА: снимок $_hyg_state, по которому считал гейт, СТАРШЕ начала этого прогона (/root/PIPELINE-6.0-START) — весь коллект однороден, но относится к ЧУЖОМУ замеру: run-all-attacks.sh этого прогона своего снимка не оставил, а гейт и отчёт взяли последний по каталогу. Ровно этот случай сверка TIMESTAMP между файлами поймать не может по построению, потому что лгут все файлы сразу"
else
    echo "  снимок гейта baseline-state-$_hyg_run_ts.json создан после начала прогона — коллект свежий, а не только однородный"
fi
echo "  ок: все артефакты *-6.0*.txt относятся к TIMESTAMP=$_hyg_run_ts — коллект однороден, чужих вердиктов в нём нет"

echo "=== ПАЙПЛАЙН №6.0 ЗАВЕРШЁН $(date -u +%H:%M:%S) UTC, гейт=$GATE_RC ==="
touch /root/PIPELINE-6.0-DONE
